		["ravaged caravan"] = {
			name = "Ravaged Caravan",
			short = "On the northeastern shore of Stonebull Lake a Venture Company caravan lies burned on a mound, and black smoke still rises from the wreck.",
			full = "On the northeastern shore of Stonebull Lake a Venture Company caravan lies burned on a mound, and black smoke still rises from the wreck. It was carrying supplies to Supervisor Fizsprocket's mining operation when the tauren, who had seen goblins traveling all over Mulgore, attacked it. The goblins who survived stay with the wreck. They guard the smoldering cargo and drive off anyone who comes close.",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Caravan",
