		["red cloud mesa"] = {
			name = "Red Cloud Mesa",
			short = "Red Cloud Mesa rolls out as open plain on top of the high cliffs of southern Mulgore, known for its quiet beauty. Camp Narache stands in its northwest corner, the main training camp for the young of the tauren.",
			full = "Red Cloud Mesa rolls out as open plain on top of the high cliffs of southern Mulgore, known for its quiet beauty. Camp Narache stands in its northwest corner, the main training camp for the young of the tauren. They prove themselves here against the Bristleback quilboar, who hold Brambleblade Ravine to the northeast.",
