		["red rocks"] = {
			name = "Red Rocks",
			short = "Red sandstone rises in the northeast of Mulgore. The tauren send their most valiant dead here, to the Earth Mother and Sky Father, by cleansing flame.",
			full = "Red sandstone rises in the northeast of Mulgore. The tauren send their most valiant dead here, to the Earth Mother and Sky Father, by cleansing flame. Only warriors who helped found and defend Thunder Bluff, or gave their lives for their tribes and chieftains, are given this honor. Young braves also come to the stones to enter adulthood and listen for the blessings of their ancestors on the wind. Bristleback quilboar have lately broken in and fouled the holy ground, and the tauren of Thunder Bluff are furious.",
			source = "https://warcraft.wiki.gg/wiki/Red_Rocks",
