			short = "A path climbs to a high plateau northwest of Thunder Bluff and ends at a painted rock.",
			full = "A path climbs to a high plateau northwest of Thunder Bluff and ends at a painted rock. The Earthen Ring keeps its camp, Camp Gev'rek, on the summit, and its shaman watch over the plateau, where a handler tends a string of galestriders.\n\nA route runs between the plateau and the Valanaar Skydocks on Zephras Isle, and new arrivals to Azeroth come down here. A goblin entrepreneur, Brix Xizzix, waits to greet them. He offers to help them get set up for success, as long as they bring money.",
			source = "",
		},
		["stonebull lake"] = {
			name = "Stonebull Lake",
			short = "A long horseshoe of cool water wraps around three sides of Bloodhoof Village in central Mulgore. The fish are plentiful, and many hours go to casting lines into the lake.",
			full = "A long horseshoe of cool water wraps around three sides of Bloodhoof Village in central Mulgore. The fish are plentiful, and many hours go to casting lines into the lake. A bridge crosses it at the narrowest point, and the road over the bridge links Thunder Bluff to the village.",
			source = "https://warcraft.wiki.gg/wiki/Stonebull_Lake",
		},
		["thunderhorn water well"] = {
			name = "Thunderhorn Water Well",
			short = "In the open grass beside the north road between Thunder Bluff and Bloodhoof Village stands the Thunderhorn Water Well, one of three sacred wells of the tauren.",
			full = "In the open grass beside the north road between Thunder Bluff and Bloodhoof Village stands the Thunderhorn Water Well, one of three sacred wells of the tauren. The Venture Company has taken it to control the water supply.",
			source = "https://warcraft.wiki.gg/wiki/Thunderhorn_Water_Well",
		},
		["venture co mine"] = {
			name = "The Venture Co. Mine",
			short = "Mining rights in Mulgore were refused to the Venture Company, and the company dug anyway.",
			full = "Mining rights in Mulgore were refused to the Venture Company, and the company dug anyway. Its mine cuts into the eastern cliffs, and Supervisor Fizsprocket, the goblin in charge of the company's work in Mulgore, runs it from the main entrance. The tauren are angry at the intrusion.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Mine",
		},
		["wildmane water well"] = {
			name = "Wildmane Water Well",
			short = "North of Thunder Bluff lies the northernmost of the sacred water wells of the tauren, the Wildmane Water Well. The Venture Company has taken it as well.",
			full = "North of Thunder Bluff lies the northernmost of the sacred water wells of the tauren, the Wildmane Water Well. The Venture Company has taken it as well.",
			source = "https://warcraft.wiki.gg/wiki/Wildmane_Water_Well",
		},
		["windfury ridge"] = {
			name = "Windfury Ridge",
			short = "Harpies nest in the heights of Windfury Ridge, and they swoop down to kill or carry off anyone who strays near their nests. Wild cougars and wolves roam the hills around.",
			full = "Harpies nest in the heights of Windfury Ridge, and they swoop down to kill or carry off anyone who strays near their nests. Wild cougars and wolves roam the hills around. The tauren of Thunder Bluff still hunt the harpies, because their brilliant feathers decorate weddings and feasts.",
			source = "https://warcraft.wiki.gg/wiki/Windfury_Ridge",
		},
		["winterhoof water well"] = {
			name = "Winterhoof Water Well",
			short = "The Winterhoof Water Well lies at the edge of the Rolling Plains in southern Mulgore. Years after the Third War, the Venture Company seized it and poisoned its waters to choke off the tauren's supply.",
			full = "The Winterhoof Water Well lies at the edge of the Rolling Plains in southern Mulgore. Years after the Third War, the Venture Company seized it and poisoned its waters to choke off the tauren's supply. Mull Thunderhorn crafts totems to cleanse the taint, but the well is not yet pure.",
			source = "https://warcraft.wiki.gg/wiki/Winterhoof_Water_Well",
		},
	},
	-- The Barrens: 35 subzones
	[1413] = {
		["agamagor"] = {
			name = "Agama'gor",
			short = "The Bristleback quilboar hold a large settlement here, north of the road that runs west from Camp Taurajo. They dig blood shards out of the ground and carry them into battle as totems of strength and magic.",
			full = "The Bristleback quilboar hold a large settlement here, north of the road that runs west from Camp Taurajo. They dig blood shards out of the ground and carry them into battle as totems of strength and magic.",
			source = "https://warcraft.wiki.gg/wiki/Agama'gor",
		},
		["bael modan"] = {
			name = "Bael Modan",
			short = "The stone fortress of Bael'dun Keep rises beside the old village of the Stonespire tauren, and next to it the dwarves of Ironforge have opened a digsite.",
			full = "The stone fortress of Bael'dun Keep rises beside the old village of the Stonespire tauren, and next to it the dwarves of Ironforge have opened a digsite. Beneath the hill lies an ancient titan research complex. The dwarves are digging toward it, and its relics lie mostly unclaimed in the dark.\n\nThe dwarves dig with explosives, and the Stonespire held that ground holy. Most of the tribe was killed or driven off, and the old village is torn apart by digging machines. Gann Stonespire, a tauren who walks the roads nearby, tried to settle it by talking and got nowhere. He now seeks revenge.",
			source = "https://warcraft.wiki.gg/wiki/Bael_Modan",
		},
		["baeldun keep"] = {
			name = "Bael'dun Keep",
			short = "General Twinbraid, a cunning commander, rules the dwarven fortress that overlooks the Bael Modan digsite in the southern Barrens. The dwarves under him are hostile to the Horde.",
			full = "General Twinbraid, a cunning commander, rules the dwarven fortress that overlooks the Bael Modan digsite in the southern Barrens. The dwarves under him are hostile to the Horde. Bael'dun soldiers guard the keep, and it has flying machines of its own.",
			source = "https://warcraft.wiki.gg/wiki/Bael'dun_Keep",
		},
		["blackthorn ridge"] = {
			name = "Blackthorn Ridge",
			short = "Thorns crowd this valley just north of Razorfen Kraul, the quilboar capital, and Razormane quilboar hold the ground. On a hill at the northern end of the ridge an orc shaman named Brine has her camp.",
			full = "Thorns crowd this valley just north of Razorfen Kraul, the quilboar capital, and Razormane quilboar hold the ground. On a hill at the northern end of the ridge an orc shaman named Brine has her camp. She is an expert on the spirits and nature of water. Just below the camp lies a pool of notably clear and pure water.",
			source = "https://warcraft.wiki.gg/wiki/Blackthorn_Ridge",
		},
		["boulder lode mine"] = {
			name = "Boulder Lode Mine",
			short = "The Venture Company holds this mine in the northeast of the Barrens, and Boss Copperplug runs it.",
			full = "The Venture Company holds this mine in the northeast of the Barrens, and Boss Copperplug runs it. Copperplug was once the best engineer of the Tinkers' Union, until he went over to the Venture Company and took his best techniques with him.\n\nOrcish timbers and Horde banners still hang about the galleries, and the mine seems to have belonged to the Horde once.",
			source = "https://warcraft.wiki.gg/wiki/Boulder_Lode_Mine",
		},
		["bramblescar"] = {
			name = "Bramblescar",
			short = "A tribe of Razormane quilboar has its lair at Bramblescar. Across the road at Agama'gor the Bristleback tribe holds a settlement, and the two tribes are at war.",
			full = "A tribe of Razormane quilboar has its lair at Bramblescar. Across the road at Agama'gor the Bristleback tribe holds a settlement, and the two tribes are at war. The Razormane attack anyone who wanders close to their lair.",
			source = "https://warcraft.wiki.gg/wiki/Bramblescar",
		},
		["camp taurajo"] = {
			name = "Camp Taurajo",
			short = "Tauren keep an outpost here in the Barrens, near the mountain pass that leads into Mulgore. It has an inn for travelers coming out of the tauren homeland.",
			full = "Tauren keep an outpost here in the Barrens, near the mountain pass that leads into Mulgore. It has an inn for travelers coming out of the tauren homeland. The camp also holds a prisoner, the Razormane quilboar Mangletooth, whom the orcs and tauren captured and who awaits his execution.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Taurajo",
		},
		["crossroads"] = {
			name = "The Crossroads",
			short = "Two roads cross here, the Gold Road running north and south and the road that runs from Ratchet to the Stonetalon Mountains.",
			full = "Two roads cross here, the Gold Road running north and south and the road that runs from Ratchet to the Stonetalon Mountains. The Crossroads is the largest Horde town in the Barrens, with few lodgings and a great deal of trade, and traders shout their wares across the stalls.\n\nThork, an orc, leads its defense. Raptors once made off with a shipment of silver from the guard tower, the payroll meant for the guards. Just past the settlement lies a burial ground where the Horde pays respects to its dead.",
			source = "https://warcraft.wiki.gg/wiki/Crossroads",
		},
		["dreadmist den"] = {
			name = "Dreadmist Den",
			short = "Within Dreadmist Peak the Burning Blade keeps a den, shrouded in a dark red mist and an unending twilight. The cultists who live there worship demons, and the mist cloaks them.",
			full = "Within Dreadmist Peak the Burning Blade keeps a den, shrouded in a dark red mist and an unending twilight. The cultists who live there worship demons, and the mist cloaks them.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Den",
		},
		["dreadmist peak"] = {
			name = "Dreadmist Peak",
			short = "Northwest of the Crossroads, Dreadmist Peak climbs into a red fog. The mist thickens toward the summit and is all that remains of an ancient demonic curse.",
			full = "Northwest of the Crossroads, Dreadmist Peak climbs into a red fog. The mist thickens toward the summit and is all that remains of an ancient demonic curse. Burning Blade cultists make their home at the top.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Peak",
		},
		["dry hills"] = {
			name = "The Dry Hills",
			short = "Despite their name, the Dry Hills are among the greener parts of the Barrens. They lie in the far northwest corner, the foothills of the Stonetalon Mountains.",
			full = "Despite their name, the Dry Hills are among the greener parts of the Barrens. They lie in the far northwest corner, the foothills of the Stonetalon Mountains. Witchwing harpies hold them under Serena Bloodfeather and have lately raided the caravans on the northern Gold Road. An abandoned orcish watch tower and a few catapults stand in the middle of the hills.",
			source = "https://warcraft.wiki.gg/wiki/Dry_Hills",
		},
		["far watch post"] = {
			name = "Far Watch Post",
			short = "Just west of the bridge between Durotar and the Barrens, the Horde keeps a watch tower and a few catapults. An orc burrow stands beside them, and two peons tend a riding wolf pen a short way south.",
			full = "Just west of the bridge between Durotar and the Barrens, the Horde keeps a watch tower and a few catapults. An orc burrow stands beside them, and two peons tend a riding wolf pen a short way south. It is not a comfortable posting. Supply caravans depend on it, and it helps keep Durotar safe from the Alliance and the quilboar.",
			source = "https://warcraft.wiki.gg/wiki/Far_Watch_Post",
		},
		["field of giants"] = {
			name = "Field of Giants",
			short = "Herds of thunder lizards and kodo roam the Field of Giants, across the southernmost plains of the Barrens. The southern leg of the Gold Road runs through them, less well defended than the north.",
			full = "Herds of thunder lizards and kodo roam the Field of Giants, across the southernmost plains of the Barrens. The southern leg of the Gold Road runs through them, less well defended than the north. Its watch towers look abandoned.\n\nThe Horde has not given up the field. The wise shaman Brine lives on a ridge along its southern border. The tauren Gann Stonespire, whose tribe lost its village to the dwarves, seeks revenge here.",
			source = "https://warcraft.wiki.gg/wiki/Field_of_Giants",
		},
		["forgotten pools"] = {
			name = "The Forgotten Pools",
			short = "North of the western road out of the Crossroads lie the Forgotten Pools, the northernmost of the oases in the Barrens. Their shores are green, and turtles live in the water.",
			full = "North of the western road out of the Crossroads lie the Forgotten Pools, the northernmost of the oases in the Barrens. Their shores are green, and turtles live in the water. Kolkar centaurs patrol the pools alongside the wildlife.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Pools",
		},
		["fray island"] = {
			name = "Fray Island",
			short = "Warriors of every race and creed train on Fray Island, under a human named Klannoc Macleod. The island is small and arid, and lies off the eastern shore of the Barrens, south of Ratchet.",
			full = "Warriors of every race and creed train on Fray Island, under a human named Klannoc Macleod. The island is small and arid, and lies off the eastern shore of the Barrens, south of Ratchet. Fighters come here to meet one another and fight, with crowds of onlookers gathered around them.",
			source = "https://warcraft.wiki.gg/wiki/Fray_Island",
		},
		["gold road"] = {
			name = "Gold Road",
			short = "The long highway of the Barrens, the Gold Road, starts at the Mor'shan Rampart in the north and runs south across the land to a bridge that joins the northern half of the Barrens to the southern.",
			full = "The long highway of the Barrens, the Gold Road, starts at the Mor'shan Rampart in the north and runs south across the land to a bridge that joins the northern half of the Barrens to the southern. Past the bridge it is called the Southern Gold Road.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Road",
		},
		["groldom farm"] = {
			name = "Grol'dom Farm",
			short = "Kranal Fiss and his children raise pigs on Grol'dom Farm, one of the many orc farms that have sprung up since Orgrimmar was founded.",
			full = "Kranal Fiss and his children raise pigs on Grol'dom Farm, one of the many orc farms that have sprung up since Orgrimmar was founded. Razormane quilboar raid it constantly.",
			source = "https://warcraft.wiki.gg/wiki/Grol'dom_Farm",
		},
		["honors stand"] = {
			name = "Honor's Stand",
			short = "Burrows and watch towers, some of them badly damaged, guard the west road between the Crossroads and Sun Rock Retreat.",
			full = "Burrows and watch towers, some of them badly damaged, guard the west road between the Crossroads and Sun Rock Retreat. Many great battles between the Horde and its enemies were fought here, and the orcs posted at Honor's Stand know its proud, if short, history well. Barrens guards keep watch over the road, and of late Kolkar centaurs have attacked it.",
			source = "",
		},
		["lushwater oasis"] = {
			name = "Lushwater Oasis",
			short = "Lushwater Oasis lies just south of the Crossroads, one of the three major oases of the Barrens. Wild beasts come to its pools to drink, and Kolkar centaurs stalk between the trees, hunting them.",
			full = "Lushwater Oasis lies just south of the Crossroads, one of the three major oases of the Barrens. Wild beasts come to its pools to drink, and Kolkar centaurs stalk between the trees, hunting them.\n\nA cave mouth here opens into the Wailing Caverns, which are called accursed. The life energy in the oasis water is said to flow from them.",
			source = "https://warcraft.wiki.gg/wiki/Lushwater_Oasis",
		},
		["merchant coast"] = {
			name = "The Merchant Coast",
			short = "The Merchant Coast takes its name from the trade that passes along it, all of it through the thrifty hands of the goblins of Ratchet.",
			full = "The Merchant Coast takes its name from the trade that passes along it, all of it through the thrifty hands of the goblins of Ratchet. The goblin port stands on this shore, and Fray Island lies off it. The Southsea Freebooters hold the southern stretch of shore. Gazlowe, who leads Ratchet, has put a price on the head of Baron Longshore for piracy, and for leading ships of the Freebooters.",
			source = "https://warcraft.wiki.gg/wiki/Merchant_Coast",
		},
		["morshan base camp"] = {
			name = "Mor'shan Base Camp",
			short = "Mor'shan Base Camp stands just south of the border with Ashenvale, near the Mor'shan Rampart. It is one of the larger Horde settlements in the Barrens, and the base of the Warsong Outriders.",
			full = "Mor'shan Base Camp stands just south of the border with Ashenvale, near the Mor'shan Rampart. It is one of the larger Horde settlements in the Barrens, and the base of the Warsong Outriders.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Base_Camp",
		},
		["morshan rampart"] = {
			name = "The Mor'shan Rampart",
			short = "Where the Gold Road ends in the north, the Horde raised the Mor'shan Rampart to hold back the Alliance push out of Ashenvale. It is a makeshift defensive post, built around watch towers.",
			full = "Where the Gold Road ends in the north, the Horde raised the Mor'shan Rampart to hold back the Alliance push out of Ashenvale. It is a makeshift defensive post, built around watch towers. The orcs also use it as a launching point for raids on Astranaar, the night elf town to the north.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Rampart",
		},
		["northwatch hold"] = {
			name = "Northwatch Hold",
			short = "Survivors of the human expedition built Northwatch Hold right after the Battle of Mount Hyjal. It stood in land then thought neutral, and the orcs never trusted it.",
			full = "Survivors of the human expedition built Northwatch Hold right after the Battle of Mount Hyjal. It stood in land then thought neutral, and the orcs never trusted it. When Grand Admiral Daelin Proudmoore came to Kalimdor to root out the Horde, he made the hold his stronghold, and the orcs fought his Kul Tiran forces here and beat them.\n\nAfter Daelin died, the Theramore Guard took the hold back. Jaina Proudmoore did not like it, but she was pressed to keep it manned. Its walls block the coastal approach to Dustwallow Marsh from the north. Theramore marines garrison it, Captain Fairmount commands from the top of the central mage tower, and Cannoneers Smythe and Whessan keep the two scout towers.",
			source = "",
		},
		["raptor grounds"] = {
			name = "Raptor Grounds",
			short = "Sunscale raptors crowd a tiny valley in the southern Barrens, and they are odd among their kind. They show an unnatural intelligence.",
			full = "Sunscale raptors crowd a tiny valley in the southern Barrens, and they are odd among their kind. They show an unnatural intelligence. They build crude huts and make their own tools. Anything shiny, or merely out of the ordinary, draws them, and they have stolen many things from the Horde settlements nearby.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Grounds",
		},
		["ratchet"] = {
			name = "Ratchet",
			short = "Gazlowe was paid well by Warchief Thrall for the help he and his workers gave in raising Orgrimmar after the Third War. Some time after the city was finished, he founded Ratchet on the eastern shore of the Barrens.",
			full = "Gazlowe was paid well by Warchief Thrall for the help he and his workers gave in raising Orgrimmar after the Third War. Some time after the city was finished, he founded Ratchet on the eastern shore of the Barrens. Smugglers began it, and it filled with the rest of those whom other societies had cast out.\n\nIt is a goblin harbor now, and most of its trade runs through Booty Bay and Baron Revilgaz across the sea. A coven of warlocks lives in a tower above the town.",
			source = "https://warcraft.wiki.gg/wiki/Ratchet",
		},
		["razorfen kraul"] = {
			name = "Razorfen Kraul",
			short = "Ten thousand years ago, in the War of the Ancients, the demigod Agamaggan, a colossal boar, came forth to fight the Burning Legion. He fell, but his stand helped save the world from ruin.",
			full = "Ten thousand years ago, in the War of the Ancients, the demigod Agamaggan, a colossal boar, came forth to fight the Burning Legion. He fell, but his stand helped save the world from ruin. Where his blood soaked the earth, great thorned vines grew in time. The quilboar, held to be his mortal children, settled among the thorns and keep them sacred, and the heart of their thorn colonies is called the Razorfen.\n\nThis great mass of thorns at the far southern edge of the Barrens was conquered by an old crone, Charlga Razorflank. Under her rule its quilboar shamans strike at rival tribes and at Horde villages alike.",
			source = "",
		},
		["shrine of the fallen warrior"] = {
			name = "Shrine of the Fallen Warrior",
			short = "A short trail leads up a small hill west of the Crossroads to a shrine. It is a stone obelisk with the initials M K cut into its base.",
			full = "A short trail leads up a small hill west of the Crossroads to a shrine. It is a stone obelisk with the initials M K cut into its base. A spirit healer named Koiter stands in front.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Fallen_Warrior",
		},
		["sludge fen"] = {
			name = "The Sludge Fen",
			short = "A pool of crystal-blue water once lay here. Then the Venture Company built an oil rig on top of it and turned it into a mire of industrial waste.",
			full = "A pool of crystal-blue water once lay here. Then the Venture Company built an oil rig on top of it and turned it into a mire of industrial waste. Supervisor Lugwizzle, a goblin, runs the operation from the control room at the top of the rig.",
			source = "https://warcraft.wiki.gg/wiki/Sludge_Fen",
		},
		["southern barrens"] = {
			name = "Southern Barrens",
			short = "The southern Barrens are open plains, with Mulgore to the west, Dustwallow Marsh to the east and Thousand Needles to the south.",
			full = "The southern Barrens are open plains, with Mulgore to the west, Dustwallow Marsh to the east and Thousand Needles to the south. Kodo, zhevra, giraffes and thunderhawks roam the grass, and Darkmist spiders hunt here as well. In the far south the quilboar have claimed the land with their thorny settlements.",
			source = "",
		},
		["southern gold road"] = {
			name = "Southern Gold Road",
			short = "Trade caravans give the Southern Gold Road its name. It runs from the Great Lift at the southern end of the Barrens to the bridge joining the northern and southern halves of the land.",
			full = "Trade caravans give the Southern Gold Road its name. It runs from the Great Lift at the southern end of the Barrens to the bridge joining the northern and southern halves of the land. North of the bridge it is simply the Gold Road.\n\nTraders come along it from as far off as Gadgetzan in Tanaris, Auberdine in Darkshore and Nighthaven in the north.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Gold_Road",
		},
		["southfury river"] = {
			name = "Southfury River",
			short = "On the Barrens side the Southfury is the border with Durotar, and one of its three bridges carries the road across it from Durotar into the Barrens.",
			full = "On the Barrens side the Southfury is the border with Durotar, and one of its three bridges carries the road across it from Durotar into the Barrens. At its mouth the river spills over a cascading waterfall into the Great Sea, northeast of Ratchet.\n\nJust north of the western bridge to Orgrimmar there is one stretch of water where Ashenvale, Azshara, Durotar and the Barrens all meet.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["stagnant oasis"] = {
			name = "The Stagnant Oasis",
			short = "Kolkar centaurs camp on the fringes of the Stagnant Oasis, which lies between the Merchant Coast and the Gold Road. Lost Barrens kodo wander here, weakened and solitary, and far easier to hunt than the kodo of the south.",
			full = "Kolkar centaurs camp on the fringes of the Stagnant Oasis, which lies between the Merchant Coast and the Gold Road. Lost Barrens kodo wander here, weakened and solitary, and far easier to hunt than the kodo of the south. Deviate fish swim in the water, and oasis snapjaws live there too.",
			source = "https://warcraft.wiki.gg/wiki/Stagnant_Oasis",
		},
		["thorn hill"] = {
			name = "Thorn Hill",
			short = "Razormane quilboar hold Thorn Hill, a sizable settlement on the north face of a mountaintop between the Crossroads and Durotar.",
			full = "Razormane quilboar hold Thorn Hill, a sizable settlement on the north face of a mountaintop between the Crossroads and Durotar. Lately they have raided Horde caravans in the region, and the local guards are angry about it.",
			source = "https://warcraft.wiki.gg/wiki/Thorn_Hill",
		},
		["tidus stair"] = {
			name = "The Tidus Stair",
			short = "Broad terraces of stone rise above the coast southeast of Ratchet, stacked like a giant set of stairs that looks out over part of the Merchant Coast.",
			full = "Broad terraces of stone rise above the coast southeast of Ratchet, stacked like a giant set of stairs that looks out over part of the Merchant Coast. Two tauren, Islen Waterseer and Mahren Skyseer, sit on them to fish and to speak with the water spirits.",
			source = "https://warcraft.wiki.gg/wiki/Tidus_Stair",
		},
		["wailing caverns"] = {
			name = "Wailing Caverns",
			short = "The night elf druid Naralex found these caverns and named them for the mournful howls of wind and steam in the rock. Underground rivers run for miles beneath the savannah and bubble up as small oases across the Barrens.",
			full = "The night elf druid Naralex found these caverns and named them for the mournful howls of wind and steam in the rock. Underground rivers run for miles beneath the savannah and bubble up as small oases across the Barrens. From the front, the entrance looks vaguely like a snake skull.\n\nNaralex believed that joining those waters to the Emerald Dream would make the land green again. He went down with his loyal disciples and settled into meditation, letting the Dream reach Azeroth through his body. The Emerald Nightmare overwhelmed him instead. The waters were corrupted, the wildlife turned into deviate forms, and most of his disciples went insane and became the Druids of the Fang.",
			source = "https://warcraft.wiki.gg/wiki/Wailing_Caverns",
		},
	},
	-- Alterac Mountains: 8 subzones
	[1416] = {
		["city of dalaran"] = {
			name = "City of Dalaran",
			short = "The Kirin Tor have opened the great dome of magic they raised over the heart of Dalaran, and behind it the city is still under repair.",
			full = "The Kirin Tor have opened the great dome of magic they raised over the heart of Dalaran, and behind it the city is still under repair. The wizards who survived its destruction came back to rebuild, and the work is far from done.\n\nThe Skyborne of the High Order have found friends here. Archmage Ansirem Runeweaver labored to make the skycutter crossing between Dalaran and Zephras Isle safe, and mages of the city wait to receive the Skyborne when they arrive. They warn newcomers that the land beyond the city is far more dangerous than it looks.",
			source = "",
		},
		["dalaran"] = {
			name = "Dalaran",
			short = "Magi of the Arathorian Empire founded Dalaran after the Troll Wars, and it grew into a nation ruled by the Kirin Tor under the Council of Six.",
			full = "Magi of the Arathorian Empire founded Dalaran after the Troll Wars, and it grew into a nation ruled by the Kirin Tor under the Council of Six. Its Violet Citadel was the sanctum of those who studied the arcane, and no city outside Quel'Thalas held so great a concentration of magical power. Most human and high elven mages bowed to the sovereignty of the Kirin Tor.\n\nThe Scourge besieged the city, and the demon lord Archimonde destroyed it. The surviving wizards returned to rebuild the ruins, raised a vast dome of magic around the heart of their city, and fought the Forsaken while they worked.\n\nNow the dome has opened on a city under repair, with workers at their labor and Kirin Tor guards in the streets. Dalaran is wary of Horde and Alliance alike, but it has welcomed the Skyborne, elves from Zephras Isle above the clouds. Their High Order seeks to save the isle through the arcane with the Kirin Tor's help, and a skycutter ship sails between the isle and the city.",
			source = "https://warcraft.wiki.gg/wiki/Dalaran",
		},
		["dandreds fold"] = {
			name = "Dandred's Fold",
			short = "A small farm and manor stands at the western edge of the Uplands, where a harbor opens onto Lordamere Lake. Lord Aliden Perenolde lives here.",
			full = "A small farm and manor stands at the western edge of the Uplands, where a harbor opens onto Lordamere Lake. Lord Aliden Perenolde lives here. He is the eldest son of King Aiden Perenolde of Alterac and the last known leader of the Syndicate. He styles himself lord of the mountains and means to put the orcs back in chains.\n\nHis mistress Elysa lives with him, and Syndicate assassins and enforcers are quartered nearby.",
			source = "https://warcraft.wiki.gg/wiki/Dandred's_Fold",
		},
		["eventide"] = {
			pending = true,
			name = "The Eventide",
			short = "",
			full = "",
			source = "",
		},
		["lordamere internment camp"] = {
			name = "Lordamere Internment Camp",
			short = "The Lordamere Internment Camp stands on a hill overlooking Dalaran, the only internment camp in the Alterac Mountains.",
			full = "The Lordamere Internment Camp stands on a hill overlooking Dalaran, the only internment camp in the Alterac Mountains. Wizards of Dalaran hold it, and Warden Belamoore commands the garrison, though she gives more of her time to her studies than to her post.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Internment_Camp",
		},
		["old dalaran ruins"] = {
			name = "Old Dalaran Ruins",
			short = "Broken houses, barns, towers and walls lie scattered around the outskirts of Dalaran. Wizards of the Kirin Tor and their earth elementals patrol the ruined ground.",
			full = "Broken houses, barns, towers and walls lie scattered around the outskirts of Dalaran. Wizards of the Kirin Tor and their earth elementals patrol the ruined ground.",
			source = "",
		},
		["ruins of alterac"] = {
			name = "Ruins of Alterac",
			short = "King Aiden Perenolde of Alterac lost hope of a human victory in the Second War and made a pact with the Horde. The orcs could cross his lands unopposed, and he would be protected in return.",
			full = "King Aiden Perenolde of Alterac lost hope of a human victory in the Second War and made a pact with the Horde. The orcs could cross his lands unopposed, and he would be protected in return. Alteraci soldiers were found fighting beside the orcs, and a prison camp near the city held captive citizens of Dalaran. When the treason came out, the other human kingdoms marched on his city. King Terenas Menethil II of Lordaeron put it under martial law and imprisoned him.\n\nCrushridge ogres under the warlord Mug'thol live in the ruins now. The palace stands half whole, though the church and town hall are in ruins, and the gate is built much like the one at Stormwind. Wrecked meat wagons lie by the gate, and shattered ballistae litter the rubble.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Alterac",
		},
		["uplands"] = {
			name = "The Uplands",
			short = "These hills were the bread basket of the kingdom of Alterac. When the kingdom fell, the Syndicate took them over and pitched several camps here.",
			full = "These hills were the bread basket of the kingdom of Alterac. When the kingdom fell, the Syndicate took them over and pitched several camps here. Nowhere in the mountains are they stronger.\n\nBaron Vardus, once a noble of Alterac and now the Syndicate's quartermaster, is found in these camps.",
			source = "https://warcraft.wiki.gg/wiki/Uplands",
		},
	},
	-- Arathi Highlands: 19 subzones
	[1417] = {
		["boulderfist hall"] = {
			name = "Boulderfist Hall",
			short = "Kor'gresh Coldrage, an ogre mage and chief of the Boulderfist clan, holds the larger cave in this strongly fortified mound of the ogres.",
			full = "Kor'gresh Coldrage, an ogre mage and chief of the Boulderfist clan, holds the larger cave in this strongly fortified mound of the ogres. It stands in the south, near Thandol Span and Witherbark Village.",
			source = "https://warcraft.wiki.gg/wiki/Boulderfist_Hall",
		},
		["bouldergor"] = {
			name = "Boulder'gor",
			short = "A rough, broken hill rises north of Stromgarde Keep. Boulderfist ogres hold a mound on it, and Witherbark forest trolls loiter on its slopes beside them.",
			full = "A rough, broken hill rises north of Stromgarde Keep. Boulderfist ogres hold a mound on it, and Witherbark forest trolls loiter on its slopes beside them.",
			source = "https://warcraft.wiki.gg/wiki/Boulder'gor",
		},
		["circle of east binding"] = {
			name = "Circle of East Binding",
			short = "The Stone of East Binding stands in the east of Arathi Highlands, near Hammerfall, watched over by water elementals. It is one of four binding stones set across the highlands.",
			full = "The Stone of East Binding stands in the east of Arathi Highlands, near Hammerfall, watched over by water elementals. It is one of four binding stones set across the highlands.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_East_Binding",
		},
		["circle of inner binding"] = {
			name = "Circle of Inner Binding",
			short = "The strongest of the four binding stones lies here, in the south near Stromgarde Keep. Earth elementals guard the Stone of Inner Binding.",
			full = "The strongest of the four binding stones lies here, in the south near Stromgarde Keep. Earth elementals guard the Stone of Inner Binding.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Inner_Binding",
		},
		["circle of outer binding"] = {
			name = "Circle of Outer Binding",
			short = "Air elementals circle the Stone of Outer Binding at the middle of the highlands, near Refuge Pointe. It is one of four binding stones set across the highlands.",
			full = "Air elementals circle the Stone of Outer Binding at the middle of the highlands, near Refuge Pointe. It is one of four binding stones set across the highlands.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Outer_Binding",
		},
		["circle of west binding"] = {
			name = "Circle of West Binding",
			short = "Fire elementals guard the Stone of West Binding in the west of the highlands, near Thoradin's Wall. It is one of four binding stones set across the highlands.",
			full = "Fire elementals guard the Stone of West Binding in the west of the highlands, near Thoradin's Wall. It is one of four binding stones set across the highlands.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_West_Binding",
		},
		["dabyries farmstead"] = {
			name = "Dabyrie's Farmstead",
			short = "Kenata Dabyrie farms the north of Arathi Highlands with her children Fardel and Marcel. They are citizens of Stromgarde and loyal to the Alliance, and a militia guards their fields.",
			full = "Kenata Dabyrie farms the north of Arathi Highlands with her children Fardel and Marcel. They are citizens of Stromgarde and loyal to the Alliance, and a militia guards their fields. They came through the Third War and prospered. Stromgarde's cavalry, led by Lieutenant Valorcall, rides the road between the farm and Stromgarde Keep.",
			source = "https://warcraft.wiki.gg/wiki/Dabyrie's_Farmstead",
		},
		["drowned reef"] = {
			name = "The Drowned Reef",
			short = "A ruined elven city lies sunken beneath the bay on the southern shore, and the Daggerspine naga under Prince Nazjak have made it theirs.",
			full = "A ruined elven city lies sunken beneath the bay on the southern shore, and the Daggerspine naga under Prince Nazjak have made it theirs. The reef above has wrecked many ships, among them the Maiden's Folly and the Spirit of Silverpine.\n\nThe naga seem able to turn the tides of the bay. Crews who sail into Faldir's Cove thinking they have found a safe harbor are thrown onto the stones.",
			source = "https://warcraft.wiki.gg/wiki/Drowned_Reef",
		},
		["drywhisker gorge"] = {
			name = "Drywhisker Gorge",
			short = "A gorge cuts through the mountains of eastern Arathi Highlands, northeast of Hammerfall, and ends in a cave. Drywhisker kobolds live there, allies of the giants.",
			full = "A gorge cuts through the mountains of eastern Arathi Highlands, northeast of Hammerfall, and ends in a cave. Drywhisker kobolds live there, allies of the giants. Their diggers and surveyors work the gorge, and a geomancer named Flintdagger lives among them.",
			source = "https://warcraft.wiki.gg/wiki/Drywhisker_Gorge",
		},
		["faldirs cove"] = {
			name = "Faldir's Cove",
			short = "A strange tide met the Blackwater Raiders when they sailed three ships into this cove for an elven treasure, led by Captain Steelgut and Captain O'Breen.",
			full = "A strange tide met the Blackwater Raiders when they sailed three ships into this cove for an elven treasure, led by Captain Steelgut and Captain O'Breen. The naga guarding the sunken ruins offshore raised it, and two of the ships went down. Only the Harbinger reached the shore, and her crew is trapped in the bay.\n\nThe cove is named for Faldir, who is said to have marked this spot when he and his followers set out across the sea.",
			source = "https://warcraft.wiki.gg/wiki/Faldir's_Cove",
		},
		["goshek farm"] = {
			name = "Go'Shek Farm",
			short = "Primwell Skye, a veteran of the Second War, once held this farmstead. After the Third War, Forsaken and orcs from Hammerfall took it.",
			full = "Primwell Skye, a veteran of the Second War, once held this farmstead. After the Third War, Forsaken and orcs from Hammerfall took it. The orcs draw supplies from it for Hammerfall, and the Forsaken use it as a testing ground for alchemical experiments. Hammerfall Grunts guard the place.\n\nTwo Alliance agents, Quae and Kinelory, have come to find out what the Forsaken are brewing here.",
			source = "https://warcraft.wiki.gg/wiki/Go'Shek_Farm",
		},
		["hammerfall"] = {
			name = "Hammerfall",
			short = "Orgrim Doomhammer fell here. After the Second War the Alliance of Lordaeron kept captive orcs in one of its largest internment camps on this ground.",
			full = "Orgrim Doomhammer fell here. After the Second War the Alliance of Lordaeron kept captive orcs in one of its largest internment camps on this ground. Thrall and Doomhammer led the Horde to free them, and in the chaos a charging knight drove a lance through the Warchief from behind.\n\nAfter the Third War the Horde took the ruins as a forward base and named it Hammerfall in his honor. It became a refuge for those who felt they had no place in the world. Boulderfist ogres and Witherbark trolls have allied to wipe it out.",
			source = "https://warcraft.wiki.gg/wiki/Hammerfall",
		},
		["northfold manor"] = {
			name = "Northfold Manor",
			short = "A farm on the northwestern edge of the Arathi Highlands became a Syndicate outpost after the fall of Stromgarde. Syndicate highwaymen, mercenaries and pathstalkers hold the manor and its fields now.",
			full = "A farm on the northwestern edge of the Arathi Highlands became a Syndicate outpost after the fall of Stromgarde. Syndicate highwaymen, mercenaries and pathstalkers hold the manor and its fields now.",
			source = "https://warcraft.wiki.gg/wiki/Northfold_Manor",
		},
		["refuge pointe"] = {
			name = "Refuge Pointe",
			short = "When Stromgarde's capital fell in ruins after the Third War, most of its people fled south. The remnants of the army stayed behind, determined to win their land back, and they hold this outpost.",
			full = "When Stromgarde's capital fell in ruins after the Third War, most of its people fled south. The remnants of the army stayed behind, determined to win their land back, and they hold this outpost. From here the Alliance means to retake Stromgarde Keep and to secure the resources of the Highlands.\n\nStromgarde cavalrymen under Lieutenant Valorcall, the cavalry leader of the Stromic army, patrol the road to Stromgarde Keep.",
			source = "https://warcraft.wiki.gg/wiki/Refuge_Pointe",
		},
		["stromgarde keep"] = {
			name = "Stromgarde Keep",
			short = "Legend says King Thoradin saw a black wolf roaming this dry land and chose the spot for his capital.",
			full = "Legend says King Thoradin saw a black wolf roaming this dry land and chose the spot for his capital. With his sword, Strom'kar, he cut the boundaries of a city into the dirt, and his masons began to build Strom, seat of the first human kingdom.\n\nIn the Second War and after it, the city stood as a power among the Alliance of Lordaeron. Now it is sacked and divided three ways. The Syndicate holds the inner keep. Boulderfist ogres, helped by Witherbark trolls, hold the old mage district. Prince Galen Trollbane commands the last quarter from what remains of his army.",
			source = "https://warcraft.wiki.gg/wiki/Stromgarde_Keep",
		},
		["thandol span"] = {
			name = "Thandol Span",
			short = "Two great stone arches carry the road between the Wetlands of Khaz Modan and the Arathi Highlands.",
			full = "Two great stone arches carry the road between the Wetlands of Khaz Modan and the Arathi Highlands. The dwarves of Ironforge raised them after the War of the Three Hammers, to keep faith and trade with their Wildhammer cousins, and the Anvilmar family has guarded them for three generations. The bridges could bear the weight of whole armies and were the main road of trade between dwarves and humans. When the orcs lost the battle for Lordaeron, Anduin Lothar drove the Old Horde back into Khaz Modan across the Span.\n\nNow a Dark Iron attack has all but destroyed one bridge. The dwarves fight to hold the other and to retake the town of Dun Modr, and many have died.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thoradins wall"] = {
			name = "Thoradin's Wall",
			short = "Against the Amani trolls, King Thoradin ordered a great wall raised soon after he founded Strom, the capital of Arathor.",
			full = "Against the Amani trolls, King Thoradin ordered a great wall raised soon after he founded Strom, the capital of Arathor. For generations it stood watch over the border between the Arathi Highlands and Hillsbrad Foothills.\n\nMany centuries later it still stands, but heavily damaged, its stones broken and gaping wide.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["tower of arathor"] = {
			name = "The Tower of Arathor",
			short = "The Tower of Arathor stands in the former mage district of Stromgarde Keep and is named after the Empire of Arathor.",
			full = "The Tower of Arathor stands in the former mage district of Stromgarde Keep and is named after the Empire of Arathor.\n\nArchmage Trelane once studied in this tower. When the Syndicate and the Boulderfist ogres besieged Stromgarde, he tried to hold the tower and failed, and he fled the city. The ogres took the tower and the district around it, and the ogre mage Ruul Onestone now lives inside.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Arathor",
		},
		["witherbark village"] = {
			name = "Witherbark Village",
			short = "Around a small lake in the southeast of the Arathi Highlands sits the village of the Witherbark trolls. Behind it is a large cavern where the tribe's leaders are often found.",
			full = "Around a small lake in the southeast of the Arathi Highlands sits the village of the Witherbark trolls. Behind it is a large cavern where the tribe's leaders are often found.\n\nThe Witherbark have made a loose alliance with the nearby Boulderfist ogres against Stromgarde and Hammerfall. Together they hold a section of Stromgarde itself.",
			source = "https://warcraft.wiki.gg/wiki/Witherbark_Village",
		},
	},
	-- Badlands: 17 subzones
	[1418] = {
		["agmonds end"] = {
			name = "Agmond's End",
			short = "Prospector Agmond was in charge of the dwarf excavations in the Badlands, and this small dig in the south central part of the zone was the southernmost of them.",
			full = "Prospector Agmond was in charge of the dwarf excavations in the Badlands, and this small dig in the south central part of the zone was the southernmost of them. Troggs had infested the site, and Agmond met his end here. The dig stands abandoned, and it bears his name.",
			source = "https://warcraft.wiki.gg/wiki/Agmond's_End",
		},
		["angor fortress"] = {
			name = "Angor Fortress",
			short = "Angor Fortress is where the Dark Iron dwarves direct their work in the Badlands. From here they organize their exploration of Uldaman, and they mean to exploit it.",
			full = "Angor Fortress is where the Dark Iron dwarves direct their work in the Badlands. From here they organize their exploration of Uldaman, and they mean to exploit it. Ambassador Infernus, a fire elemental who serves Ragnaros, also lives in the keep and oversees the Shadowforge clan's digging.",
			source = "https://warcraft.wiki.gg/wiki/Angor_Fortress",
		},
		["apocryphans rest"] = {
			name = "Apocryphan's Rest",
			short = "The bones of Apocryphan's Rest sprawl across the Badlands south of Kargath, a vast draconic skeleton fallen and left to bleach in the dry heat.",
			full = "The bones of Apocryphan's Rest sprawl across the Badlands south of Kargath, a vast draconic skeleton fallen and left to bleach in the dry heat. A flock of hungry buzzards has taken over the bones and nests among the ribs.",
			source = "https://warcraft.wiki.gg/wiki/Apocryphan's_Rest",
		},
		["camp boff"] = {
			name = "Camp Boff",
			short = "Only three ogres guard Camp Boff, the southeastern of the four camps the Dustbelcher ogres keep in the Badlands.",
			full = "Only three ogres guard Camp Boff, the southeastern of the four camps the Dustbelcher ogres keep in the Badlands.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Boff",
		},
		["camp cagg"] = {
			name = "Camp Cagg",
			short = "Boss Tho'grun, a mercenary leader of the Dustbelcher ogres, walks a circuit between the tribe's camps with his bodyguards, and Camp Cagg is one of his stops.",
			full = "Boss Tho'grun, a mercenary leader of the Dustbelcher ogres, walks a circuit between the tribe's camps with his bodyguards, and Camp Cagg is one of his stops. Some of the Dustbelcher make their home here.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Cagg",
		},
		["camp kosh"] = {
			name = "Camp Kosh",
			short = "The ogres of Camp Kosh prey on the supply caravans that must cross the barren Badlands. It is the northernmost of the Dustbelcher camps.",
			full = "The ogres of Camp Kosh prey on the supply caravans that must cross the barren Badlands. It is the northernmost of the Dustbelcher camps.\n\nSigrun Ironhew and his dwarves were forced to leave the dig at Uldaman and had to abandon wagons and crates along the road. The ogres of Kosh plundered them, and took every weapon and all the food.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Kosh",
		},
		["camp wurg"] = {
			name = "Camp Wurg",
			short = "Some of the Dustbelcher ogres live at Camp Wurg in the northwest of the Badlands, and Boss Tho'grun's mercenary band stops here on its rounds.",
			full = "Some of the Dustbelcher ogres live at Camp Wurg in the northwest of the Badlands, and Boss Tho'grun's mercenary band stops here on its rounds.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Wurg",
		},
		["dustbelch grotto"] = {
			name = "Dustbelch Grotto",
			short = "In the southwestern Badlands rises a great mound of earth and stone, home of the Dustbelcher ogres. More of the tribe live in camps scattered across the cracked, sun-scorched land around it.",
			full = "In the southwestern Badlands rises a great mound of earth and stone, home of the Dustbelcher ogres. More of the tribe live in camps scattered across the cracked, sun-scorched land around it.",
			source = "https://warcraft.wiki.gg/wiki/Dustbelch_Grotto",
		},
		["dustbowl"] = {
			name = "The Dustbowl",
			short = "Cracked, dry ground spreads across the Dustbowl, a wide flat in the northwest of the Badlands. Coyotes range over it, buzzards circle above, and rock elementals stir among the stones.",
			full = "Cracked, dry ground spreads across the Dustbowl, a wide flat in the northwest of the Badlands. Coyotes range over it, buzzards circle above, and rock elementals stir among the stones. Only cacti and a few trees have found a way to grow here.\n\nCamp Wurg stands in the waste, one of the homes of the Dustbelcher ogres.",
			source = "https://warcraft.wiki.gg/wiki/Dustbowl",
		},
		["dustwind gulch"] = {
			name = "Dustwind Gulch",
			short = "Dustwind Gulch cuts through the dry, cracked ground of the Badlands, west of Lethlor Ravine. Stonevault troggs roam it, and rabid crag coyotes, ridge stalkers and starving buzzards hunt there.",
			full = "Dustwind Gulch cuts through the dry, cracked ground of the Badlands, west of Lethlor Ravine. Stonevault troggs roam it, and rabid crag coyotes, ridge stalkers and starving buzzards hunt there.",
			source = "https://warcraft.wiki.gg/wiki/Dustwind_Gulch",
		},
		["hammertoes digsite"] = {
			name = "Hammertoe's Digsite",
			short = "Hammertoe Grez, a dwarf, made this dig in the northern Badlands while he searched for lost titan artifacts with the historian Karnik.",
			full = "Hammertoe Grez, a dwarf, made this dig in the northern Badlands while he searched for lost titan artifacts with the historian Karnik. He has abandoned it. A gang of Dark Iron dwarves has taken it over, most likely part of the same force that has moved into Uldaman.",
			source = "https://warcraft.wiki.gg/wiki/Hammertoe's_Digsite",
		},
		["kargath"] = {
			name = "Kargath",
			short = "Kargath is the only outpost the Horde holds in Khaz Modan. It is named for Kargath Bladefist, chieftain of the Shattered Hand clan.",
			full = "Kargath is the only outpost the Horde holds in Khaz Modan. It is named for Kargath Bladefist, chieftain of the Shattered Hand clan.\n\nWarchief Thrall sent the Kargath Expeditionary Force here to explore the Badlands. Its scouts found Uldaman, a dig the dwarves value highly. The force's main aim is a road through the Searing Gorge to Blackrock Mountain, so the Horde can strike at Rend Blackhand, Warchief of the Dark Horde. On the way it ran into the Dark Iron dwarves, and the two sides are at war again.",
			source = "https://warcraft.wiki.gg/wiki/Kargath",
		},
		["lethlor ravine"] = {
			name = "Lethlor Ravine",
			short = "A wide, craggy valley runs through the eastern Badlands, and whelps and drakes of the black dragonflight roam it. Crystalline obelisks stand among the rocks.",
			full = "A wide, craggy valley runs through the eastern Badlands, and whelps and drakes of the black dragonflight roam it. Crystalline obelisks stand among the rocks.",
			source = "https://warcraft.wiki.gg/wiki/Lethlor_Ravine",
		},
		["makers terrace"] = {
			name = "The Maker's Terrace",
			short = "Dark Iron dwarves patrol the wide excavation of the Maker's Terrace, just outside the entrance to Uldaman. The earth has been cut back in wide swathes and left open to the sky.",
			full = "Dark Iron dwarves patrol the wide excavation of the Maker's Terrace, just outside the entrance to Uldaman. The earth has been cut back in wide swathes and left open to the sky.",
			source = "https://warcraft.wiki.gg/wiki/Maker's_Terrace",
		},
		["mirage flats"] = {
			name = "Mirage Flats",
			short = "Giant buzzards, ridge stalker patriarchs and rabid crag coyotes live on the Mirage Flats, east of Dustbelch Grotto.",
			full = "Giant buzzards, ridge stalker patriarchs and rabid crag coyotes live on the Mirage Flats, east of Dustbelch Grotto.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Flats",
		},
		["uldaman"] = {
			name = "Uldaman",
			short = "Legends say the titans made the troggs from stone, judged them a failure and locked them away in a vault under the earth. Then they tried again, and the dwarves were the result.",
			full = "Legends say the titans made the troggs from stone, judged them a failure and locked them away in a vault under the earth. Then they tried again, and the dwarves were the result. That vault is Uldaman.\n\nDwarves from Ironforge dug into it before the Third War and woke the troggs. Now the Dark Iron dwarves push inside, hoping to take the Discs of Norgannon, which record how the dwarves were made, for their master Ragnaros.",
			source = "https://warcraft.wiki.gg/wiki/Uldaman",
		},
		["valley of fangs"] = {
			name = "Valley of Fangs",
			short = "A small valley runs between two massive stone formations in the central Badlands. Wolves and cougars hunt there, and the way through is dangerous.",
			full = "A small valley runs between two massive stone formations in the central Badlands. Wolves and cougars hunt there, and the way through is dangerous. Martek the Exiled, Rigglefuzz and Jazzrik keep a camp in the valley.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Fangs",
		},
	},
	-- Blasted Lands: 9 subzones
	[1419] = {
		["altar of storms"] = {
			name = "Altar of Storms",
			short = "In the Second War the altars of storms were carved from the runestone at Caer Darrow and crowned with bronze figures.",
			full = "In the Second War the altars of storms were carved from the runestone at Caer Darrow and crowned with bronze figures. Dark and arcane power ran through those figures and twisted the stone's elven magic, and on the altars the ogre magi were given their spells. Even the rest of the Horde kept away from the cold stone. The elves knew their sacred runestone had been defiled, and they swore to destroy every altar in the Eastern Kingdoms.\n\nOnly a few altars remain. This one stands at the western edge of the Blasted Lands, and the Shadowsworn cult holds it now with its enforcers, warlocks and dreadweavers. Lady Sevine, an orc warlock who became a demon in the service of the dreadlord Razelikh, stands among them.",
			source = "",
		},
		["dark portal"] = {
			name = "The Dark Portal",
			short = "Medivh, a human mage in the grip of Sargeras, and the orc warlock Gul'dan tore a rift between Draenor and Azeroth in the Black Morass.",
			full = "Medivh, a human mage in the grip of Sargeras, and the orc warlock Gul'dan tore a rift between Draenor and Azeroth in the Black Morass. Through it came the Horde. At the end of the Second War, Archmage Khadgar and his magi destroyed the gateway to stop the orcs returning.\n\nThe stone arch that stands here now was raised when Ner'zhul reopened the rift. Hooded guardians hold swords on either side, and a stone serpent bares its fangs above. Lightning strikes the crater. The gate itself is still.",
			source = "https://warcraft.wiki.gg/wiki/Dark_Portal",
		},
		["dreadmaul hold"] = {
			name = "Dreadmaul Hold",
			short = "The Dreadmaul ogres keep their main camp at Dreadmaul Hold, an old fortress among the rocks of the Blasted Lands. Grol the Destroyer rules them here, and starving snickerfangs and scorpoks prowl the rocks around it.",
			full = "The Dreadmaul ogres keep their main camp at Dreadmaul Hold, an old fortress among the rocks of the Blasted Lands. Grol the Destroyer rules them here, and starving snickerfangs and scorpoks prowl the rocks around it.\n\nTwo bloodmages study the beasts of these lands nearby. They believe the energy released when the Dark Portal opened seeped into the creatures and forced them into their present, fearsome forms.",
			source = "",
		},
		["dreadmaul post"] = {
			name = "Dreadmaul Post",
			short = "The Dreadmaul ogres came to Azeroth from Draenor and never wandered far from the Dark Portal. This mound is theirs, and they keep a strong presence around it.",
			full = "The Dreadmaul ogres came to Azeroth from Draenor and never wandered far from the Dark Portal. This mound is theirs, and they keep a strong presence around it. The mages of Nethergarde Keep say they serve Lord Kazzak.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Post",
		},
		["garrison armory"] = {
			name = "Garrison Armory",
			short = "In the scarred ground of the Blasted Lands, Alliance miners work the Garrison Armory, wresting minerals from the earth for Nethergarde Keep.",
			full = "In the scarred ground of the Blasted Lands, Alliance miners work the Garrison Armory, wresting minerals from the earth for Nethergarde Keep. What they gather is shipped on to Stormwind, and in return the keep receives the other supplies it needs to endure in that blighted place.",
			source = "https://warcraft.wiki.gg/wiki/Garrison_Armory",
		},
		["nethergarde keep"] = {
			name = "Nethergarde Keep",
			short = "Nethergarde Keep stands on a high bluff above the only road into the Blasted Lands, its walls raised to watch the ruin of a gateway that no one wanted opened again.",
			full = "Nethergarde Keep stands on a high bluff above the only road into the Blasted Lands, its walls raised to watch the ruin of a gateway that no one wanted opened again. Archmage Khadgar called for it after the Second War, to make sure no second invasion came through the Dark Portal. Mages of Dalaran manned it and studied what the portal's energy had done to the soil and the beasts.\n\nDalaran was destroyed in the Third War, and the keep lives on caravans from Stormwind. Its mages and warriors fight ogres and demons every day, and they have little cheer left.",
			source = "https://warcraft.wiki.gg/wiki/Nethergarde_Keep",
		},
		["rise of the defiler"] = {
			name = "Rise of the Defiler",
			short = "Craggy mountains rise near the middle of the Blasted Lands, and a great demon lives among them. Razelikh the Defiler is a dreadlord, the most fearsome lieutenant of Lord Kazzak, who set him to secure the land.",
			full = "Craggy mountains rise near the middle of the Blasted Lands, and a great demon lives among them. Razelikh the Defiler is a dreadlord, the most fearsome lieutenant of Lord Kazzak, who set him to secure the land.",
			source = "https://warcraft.wiki.gg/wiki/Rise_of_the_Defiler",
		},
		["serpents coil"] = {
			name = "Serpent's Coil",
			short = "Burnt-out orcish buildings left from the Second War stand at the mouth of this winding cave system in the east.",
			full = "Burnt-out orcish buildings left from the Second War stand at the mouth of this winding cave system in the east. Cultists of the Shadowsworn worship a demon in the caves behind them, and Archmage Allistarj leads the cult from within.",
			source = "https://warcraft.wiki.gg/wiki/Serpent's_Coil",
		},
		["tainted scar"] = {
			name = "The Tainted Scar",
			short = "This stretch of the western Blasted Lands was once part of the Black Morass. The corruption of the Dark Portal left it waterless and treeless, the soil the color of blood, and demonic beasts prowl over it.",
			full = "This stretch of the western Blasted Lands was once part of the Black Morass. The corruption of the Dark Portal left it waterless and treeless, the soil the color of blood, and demonic beasts prowl over it.\n\nAfter the Burning Legion's defeat at Mount Hyjal, Lord Kazzak led much of its remaining force on Azeroth into the Scar and made it his own. He is there still, and the dreadlord Razelikh the Defiler serves him. An elderly human warlock, Daio the Decrepit, has settled at its altar. He performs rituals with the demons and trains recruits in the infernal arts.",
			source = "https://warcraft.wiki.gg/wiki/Tainted_Scar",
		},
	},
	-- Tirisfal Glades: 32 subzones
	[1420] = {
		["agamand family crypt"] = {
			name = "Agamand Family Crypt",
			short = "Just north of Agamand Mills lies the crypt where the Agamand family buried its dead. Captain Dargol, a Scourge commander, has made it his headquarters, the strongest point in the mills.",
			full = "Just north of Agamand Mills lies the crypt where the Agamand family buried its dead. Captain Dargol, a Scourge commander, has made it his headquarters, the strongest point in the mills. With necromancy he has raised the family's ancestors, every corpse and spirit within, to use against the Forsaken. The crypt is dark and dusty, and the vengeful dead attack anyone who enters unbidden.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Family_Crypt",
		},
		["agamand mills"] = {
			name = "Agamand Mills",
			short = "The windmills of Agamand stand in the highlands of northern Tirisfal Glades, and they once turned for a wealthy family. When the Scourge first entered the glades, Gregor Agamand would not leave.",
			full = "The windmills of Agamand stand in the highlands of northern Tirisfal Glades, and they once turned for a wealthy family. When the Scourge first entered the glades, Gregor Agamand would not leave. His family fortified the mills, stocked them well and persuaded their workers to stay and fight.\n\nThe defense failed from within. Devlin, the youngest son, sided with the Scourge, killed two watchmen and led undead through the breach to where the men slept. A third of the defenders died, and too few remained to hold. Then the plague took the whole family, and the Agamands walk their own mills as mindless dead. The Scourge now hold the place as an outpost.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Mills",
		},
		["balnir farmstead"] = {
			name = "Balnir Farmstead",
			short = "Northeast of the fallen capital of Lordaeron stands the ruined farm of the Balnir family, who bred the great white horses the royal house of Lordaeron rode.",
			full = "Northeast of the fallen capital of Lordaeron stands the ruined farm of the Balnir family, who bred the great white horses the royal house of Lordaeron rode. Scourge from the Plaguelands that slip across the border now shelter among the ruins. Snapdragons once tended in the garden still grow here.",
			source = "https://warcraft.wiki.gg/wiki/Balnir_Farmstead",
		},
		["bandarion keep"] = {
			name = "Bandarion Keep",
			short = "Bandarion Keep began as a hilltop outpost of Lordaeron's army, on a place called Northface Rock in western Tirisfal Glades.",
			full = "Bandarion Keep began as a hilltop outpost of Lordaeron's army, on a place called Northface Rock in western Tirisfal Glades. In the early days of the Forsaken, the Argent Dawn garrisoned it under Lord Maxwell Tyrosus, and Crushridge ogres laid siege to it, hoping to ransack the keep and eat the defenders. The Argent Dawn has since withdrawn to the Eastern Plaguelands. Paladins of Tyr's Watch under Danitha Morr hold the keep now, and it is named for Garek Bandarion, the first Forsaken paladin.",
			source = "",
		},
		["brightwater lake"] = {
			name = "Brightwater Lake",
			short = "The largest lake in Tirisfal Glades lies northeast of Brill. A free-willed lich named Gunther Arcanus lives on the big island at its center.",
			full = "The largest lake in Tirisfal Glades lies northeast of Brill. A free-willed lich named Gunther Arcanus lives on the big island at its center.",
			source = "https://warcraft.wiki.gg/wiki/Brightwater_Lake",
		},
		["brill"] = {
			name = "Brill",
			short = "Brill was an ordinary town of Lordaeron, held by the Barov family, with the Agamands keeping a manor of their own within its bounds.",
			full = "Brill was an ordinary town of Lordaeron, held by the Barov family, with the Agamands keeping a manor of their own within its bounds. Then Kel'Thuzad, still a living man, chose it to begin his experiments with the plague of undeath. They worked so well that he convinced the Lich King to launch the invasion before it was planned. The graveyard just outside the town was made to hold the many dead. Brill's defenders could not save the villagers and were driven out of the town. They joined Prince Arthas Menethil in his hunt for the source of the plague. The Forsaken have since rebuilt the town, and Magistrate Sevren governs it.",
			source = "https://warcraft.wiki.gg/wiki/Brill",
		},
		["brill town hall"] = {
			name = "Brill Town Hall",
			short = "The town hall is the most prominent building in Brill. From his podium, Magistrate Sevren leads the town and gives orders and tasks to the Forsaken who serve him.",
			full = "The town hall is the most prominent building in Brill. From his podium, Magistrate Sevren leads the town and gives orders and tasks to the Forsaken who serve him. Few town halls anywhere are run by the Forsaken, and this is one of them.",
			source = "https://warcraft.wiki.gg/wiki/Brill_Town_Hall",
		},
		["bulwark"] = {
			name = "The Bulwark",
			short = "High Executor Derrington commands the Bulwark, the last bastion the Forsaken hold against the Scourge to the east, where Tirisfal Glades meets the Western Plaguelands.",
			full = "High Executor Derrington commands the Bulwark, the last bastion the Forsaken hold against the Scourge to the east, where Tirisfal Glades meets the Western Plaguelands. Forsaken defenders and the Argent Dawn have teamed up to hold the border, and Derrington means to uproot the foothold the Scourge has made beyond it. A plaguemist hangs over the camp and tints the sky yellow-gray, as it does in the Western Plaguelands and nowhere else in Tirisfal Glades.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["cold hearth manor"] = {
			name = "Cold Hearth Manor",
			short = "Cold Hearth Manor was known for its warm atmosphere and bountiful crops. The Plague of Undeath killed everyone who lived or worked here, and the fields turned barren.",
			full = "Cold Hearth Manor was known for its warm atmosphere and bountiful crops. The Plague of Undeath killed everyone who lived or worked here, and the fields turned barren. Mindless Scourge zombies now infest them. The Forsaken hold the farmhouse beside the main road.",
			source = "https://warcraft.wiki.gg/wiki/Cold_Hearth_Manor",
		},
		["crusader outpost"] = {
			name = "Crusader Outpost",
			short = "A scout tower stands in the eastern hills of Tirisfal Glades, held by the Scarlet Crusade. From it the Crusaders watch the main road through the glades to the south.",
			full = "A scout tower stands in the eastern hills of Tirisfal Glades, held by the Scarlet Crusade. From it the Crusaders watch the main road through the glades to the south. They also use it to flank any force that tries to assault the Scarlet Monastery. Captain Vachon commands the tower.",
			source = "https://warcraft.wiki.gg/wiki/Crusader_Outpost",
		},
		["deathknell"] = {
			name = "Deathknell",
			short = "Every other Forsaken settlement kept the name it had as a human town. Deathknell was renamed, and no one knows why.",
			full = "Every other Forsaken settlement kept the name it had as a human town. Deathknell was renamed, and no one knows why. It lies in a well-guarded valley, and the newly risen Forsaken come down to it from the crypt where they first open their eyes.\n\nThe Scourge, whom the villagers call the Mindless Ones, hold the northern end of the valley and its forge, so the Forsaken have dug in around the church. Survival is a struggle, and gold is the scarcest thing of all. A gold mine to the northwest is overrun with spiders, and the villagers keep trying to clear it. Deathguard Elites watch the valley.\n\nNot every risen soul has lost the Light. In the church the paladin Aramis Hammerhand welcomes back those who still feel it and trains them.",
			source = "https://warcraft.wiki.gg/wiki/Deathknell",
		},
		["faols rest"] = {
			name = "Faol's Rest",
			short = "Archbishop Alonsus Faol, the much revered head of the Church of the Holy Light, was buried here in eastern Tirisfal Glades. He died some time before the Scourge came.",
			full = "Archbishop Alonsus Faol, the much revered head of the Church of the Holy Light, was buried here in eastern Tirisfal Glades. He died some time before the Scourge came.\n\nMourners visited the grave often in the days before the Plague of Undeath. Now it lies untended and mostly forgotten.",
			source = "https://warcraft.wiki.gg/wiki/Faol's_Rest",
		},
		["gallows end tavern"] = {
			name = "Gallows' End Tavern",
			short = "In Brill, the Forsaken run the only fully working tavern their people are known to keep. In its cellar a captured Scarlet Zealot and a dwarven mountaineer are held prisoner.",
			full = "In Brill, the Forsaken run the only fully working tavern their people are known to keep. In its cellar a captured Scarlet Zealot and a dwarven mountaineer are held prisoner.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_End_Tavern",
		},
		["garrens haunt"] = {
			name = "Garren's Haunt",
			short = "Garren's Haunt was once a bountiful farmstead in the north of Tirisfal Glades, with a farmhouse, a barn, a couple of silos and a wide field.",
			full = "Garren's Haunt was once a bountiful farmstead in the north of Tirisfal Glades, with a farmhouse, a barn, a couple of silos and a wide field. When the Scourge swept through Lordaeron, they murdered Garren and his family. The plague turned the land gray and lifeless.\n\nRot Hide gnolls now hold the farmhouse and barn under their leader, Maggot Eye. They attack anyone who comes close.",
			source = "https://warcraft.wiki.gg/wiki/Garren's_Haunt",
		},
		["gunthers retreat"] = {
			name = "Gunther's Retreat",
			short = "On an island in Brightwater Lake lives Gunther Arcanus, a free-willed lich. He keeps to the island, and his zombies attack anyone who comes near.",
			full = "On an island in Brightwater Lake lives Gunther Arcanus, a free-willed lich. He keeps to the island, and his zombies attack anyone who comes near.",
			source = "https://warcraft.wiki.gg/wiki/Gunther's_Retreat",
		},
		["kings alley"] = {
			name = "King's Alley",
			short = "The Baron holds King's Alley in the Ruins of Lordaeron. He calls out for fresh meat for the block.",
			full = "The Baron holds King's Alley in the Ruins of Lordaeron. He calls out for fresh meat for the block.",
			source = "",
		},
		["lordaeron graveyard"] = {
			name = "Lordaeron Graveyard",
			short = "Rath'mael haunts the Lordaeron Graveyard and pities the errant, unfortunate souls who wander in. Fallen berserkers keep the ground with him.",
			full = "Rath'mael haunts the Lordaeron Graveyard and pities the errant, unfortunate souls who wander in. Fallen berserkers keep the ground with him.",
			source = "",
		},
		["night webs hollow"] = {
			name = "Night Web's Hollow",
			short = "Spiders hold this small valley and the gold mine cut into it. Young Night Web Spiders wander the open hollow, and grown ones skitter through the mine and lurk in its webbed corners.",
			full = "Spiders hold this small valley and the gold mine cut into it. Young Night Web Spiders wander the open hollow, and grown ones skitter through the mine and lurk in its webbed corners.\n\nYoung Forsaken come to test themselves on the spiders outside before they venture deeper. In the deepest recess of the mine sits the Night Web Matriarch, the smallest of the spiders and the hardest to reach.",
			source = "https://warcraft.wiki.gg/wiki/Night_Web's_Hollow",
		},
		["nightmare vale"] = {
			name = "Nightmare Vale",
			short = "This wide valley was once green and full of forest animals. Now the trees have withered, and hungry darkhounds and huge vampire bats have eaten the wildlife.",
			full = "This wide valley was once green and full of forest animals. Now the trees have withered, and hungry darkhounds and huge vampire bats have eaten the wildlife. A rare white bat called Ressan the Needler hunts among them.",
			source = "https://warcraft.wiki.gg/wiki/Nightmare_Vale",
		},
		["north coast"] = {
			name = "The North Coast",
			short = "The beach along the northern edge of Tirisfal Glades looks out on the Great Sea. Ravenous murlocs and other sea creatures hold it.",
			full = "The beach along the northern edge of Tirisfal Glades looks out on the Great Sea. Ravenous murlocs and other sea creatures hold it.\n\nSince the Plague of Undeath, the coast has turned dark and cold. Dead sea creatures rot at the edge of the water.",
			source = "https://warcraft.wiki.gg/wiki/North_Coast",
		},
		["ruins of lordaeron"] = {
			name = "Ruins of Lordaeron",
			short = "Prince Arthas Menethil turned on his own people. He came home to Lordaeron at the head of an army and found his father, King Terenas, waiting in the throne room, and he killed him there.",
			full = "Prince Arthas Menethil turned on his own people. He came home to Lordaeron at the head of an army and found his father, King Terenas, waiting in the throne room, and he killed him there. Standing over the body, he proclaimed that the kingdom would fall and that from its ashes a new order would rise to shake the world. At his command the Scourge then marched in and slaughtered the city's people.\n\nThe palace of Lordaeron still stands above the Undercity, and the hour of the king's death is still heard there. Voices whisper in the courtyard, bells clang in the entryway, a cheer welcomes the prince, and a murmur rises from the throne room. The citizens of Lordaeron still haunt the courtyard, and those who can see the dead find them there.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
		["scarlet monastery"] = {
			name = "Scarlet Monastery",
			short = "The monastery in the northeast corner of Tirisfal Glades was once a cathedral of the Church of the Holy Light. It held great libraries and served as a seminary where paladins trained.",
			full = "The monastery in the northeast corner of Tirisfal Glades was once a cathedral of the Church of the Holy Light. It held great libraries and served as a seminary where paladins trained. Alexandros Mograine spent months here in his youth, praying and studying.\n\nAfter the Third War the Scarlet Crusade took it as their stronghold in the war on the Scourge and the Forsaken. They made it a military camp and a place to hold their prisoners. They are fanatics who hate every race but human and hold that any outsider may carry the plague. High Inquisitor Whitemane is the monastery's true master.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Monastery",
		},
		["scarlet watch post"] = {
			name = "Scarlet Watch Post",
			short = "Captain Melrache commands the scout tower north of the Scarlet Monastery. It stands in a remote place, and the Scarlet Crusade keeps it to stop its enemies from striking the monastery on its less defensible north side.",
			full = "Captain Melrache commands the scout tower north of the Scarlet Monastery. It stands in a remote place, and the Scarlet Crusade keeps it to stop its enemies from striking the monastery on its less defensible north side.\n\nIt is one of four Crusader outposts in Tirisfal Glades.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Watch_Post",
		},
		["shadow grave"] = {
			name = "Shadow Grave",
			short = "Newly risen Forsaken wake in this crypt, which stands at the top of a slope in the mountains of Tirisfal Glades. Deathguard Balteus and Deathguard Hansel stand guard here.",
			full = "Newly risen Forsaken wake in this crypt, which stands at the top of a slope in the mountains of Tirisfal Glades. Deathguard Balteus and Deathguard Hansel stand guard here. A worn path runs down from the entrance to Deathknell.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Grave",
		},
		["shadowvale"] = {
			name = "Shadowvale",
			short = "Ruined houses stand in the village of Shadowvale, and the Tarnished have moved into them. They are Forsaken paladins who could not settle into undeath.",
			full = "Ruined houses stand in the village of Shadowvale, and the Tarnished have moved into them. They are Forsaken paladins who could not settle into undeath. They kept the hatred they carried in life, and they turn it on their own kind. Commander Rudolph Gelhardt leads them.\n\nMindless undead also walk among the ruins.",
			source = "",
		},
		["solliden farmstead"] = {
			name = "Solliden Farmstead",
			short = "Farmer Solliden owns this pumpkin farm, and he is hostile to both the Horde and the Alliance.",
			full = "Farmer Solliden owns this pumpkin farm, and he is hostile to both the Horde and the Alliance. His people are among the few in northern Lordaeron the Plague of Undeath did not touch, and they still work their rows while the country around them has fallen.\n\nSettlers from Arathor began farming Tirisfal as their kingdom grew. Later, noble families from Strom bought up large plots the first settlers had cleared, Solliden among them.",
			source = "https://warcraft.wiki.gg/wiki/Solliden_Farmstead",
		},
		["stillwater pond"] = {
			name = "Stillwater Pond",
			short = "Before the plague, Stillwater Pond was a place for the living to be young.",
			full = "Before the plague, Stillwater Pond was a place for the living to be young. Families from the glades came to picnic on its banks, and children too small to brave the deeper waters of Brightwater Lake learned to swim here instead.\n\nThat water is gray now. The fish beneath the surface are only bones still swimming, as if no one told them to stop. Wandering undead and wild beasts pass along the shore, and the darkhound Bayne prowls the water's edge, feeding on whatever is unwary enough to linger.",
			source = "https://warcraft.wiki.gg/wiki/Stillwater_Pond",
		},
		["terrace of repose"] = {
			name = "Terrace of Repose",
			short = "North of the Scarlet Monastery entrance lies a small stretch of ground the Plague of Undeath has never reached.",
			full = "North of the Scarlet Monastery entrance lies a small stretch of ground the Plague of Undeath has never reached. The Scarlet Crusade grows green hedges here and keeps a fountain running with fresh water, while the water elsewhere in Tirisfal Glades has gone stagnant.",
			source = "https://warcraft.wiki.gg/wiki/Terrace_of_Repose",
		},
		["venomweb vale"] = {
			name = "Venomweb Vale",
			short = "A brood of poisonous spiders under the deadly Sri'skulk holds Venomweb Vale now, and they have given the valley its name.",
			full = "A brood of poisonous spiders under the deadly Sri'skulk holds Venomweb Vale now, and they have given the valley its name. Before they came the grass was green and the trees were healthy, and hunters found deer and rabbits here. Darkhounds roam the northern end.\n\nA rock of fool's gold in the vale marks the spot where Aegwynn once met with members of the Council of Tirisfal.",
			source = "https://warcraft.wiki.gg/wiki/Venomweb_Vale",
		},
		["whispering forest"] = {
			name = "Whispering Forest",
			short = "Northface Rock, a steep cliff, cuts the Whispering Forest off from the rest of Tirisfal Glades, high in the mountains of the west. Forsaken paladins of Tyr's Watch guard the forest from Bandarion Keep on the rock.",
			full = "Northface Rock, a steep cliff, cuts the Whispering Forest off from the rest of Tirisfal Glades, high in the mountains of the west. Forsaken paladins of Tyr's Watch guard the forest from Bandarion Keep on the rock. Vile Fin murlocs, driven out of the keep, have overrun the bluffs and the lake nearby, and rabid wolves hunt under the trees.\n\nAn undead threshadon called Blightsculler swims in the lake, and southwest of it lies the ruined village of Shadowvale. Near the middle of the wood, in a ring of great mushrooms, the ghost of a knight wanders, bound to the place by an oath.",
			source = "",
		},
		["whispering gardens"] = {
			name = "Whispering Gardens",
			short = "A great battle was fought on this hill south of the Scarlet Monastery entrance. On one side stood the men who became the Scarlet Crusade, on the other a host of the Scourge.",
			full = "A great battle was fought on this hill south of the Scarlet Monastery entrance. On one side stood the men who became the Scarlet Crusade, on the other a host of the Scourge. At twilight the spirits of the fallen can still be heard here as faint whispers. Scarlet magicians, preservers and scouts hold the ground now.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Gardens",
		},
		["whispering shore"] = {
			name = "Whispering Shore",
			short = "The water off the Whispering Shore is cold and dark, and the bounty that once drew fishermen to this stretch of coast is gone. A band of murlocs led by the fierce Muad has overrun it and falls on anyone who wanders near.",
			full = "The water off the Whispering Shore is cold and dark, and the bounty that once drew fishermen to this stretch of coast is gone. A band of murlocs led by the fierce Muad has overrun it and falls on anyone who wanders near.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Shore",
		},
	},
	-- Silverpine Forest: 22 subzones
	[1421] = {
		["ambermill"] = {
			name = "Ambermill",
			short = "Ambermill was a lumber town of little account until the Third War. Then the Scourge and the Burning Legion tore through the north, and the Kirin Tor of Dalaran, rebuilding their own city, found a use for it.",
			full = "Ambermill was a lumber town of little account until the Third War. Then the Scourge and the Burning Legion tore through the north, and the Kirin Tor of Dalaran, rebuilding their own city, found a use for it. The town sits on a dormant ley line that the wizards mean to wake. Their support makes Ambermill the one real source of human resistance in the forest, and the mills, the stables and the town hall are in Kirin Tor hands. The Forsaken fear losing their hold on Silverpine Forest.",
			source = "https://warcraft.wiki.gg/wiki/Ambermill",
		},
		["berens peril"] = {
			name = "Beren's Peril",
			short = "In the hills southwest of Ambermill, between the main road and the side road from the town, a band of undead hides at Beren's Peril, preparing an attack on the Sepulcher.",
			full = "In the hills southwest of Ambermill, between the main road and the side road from the town, a band of undead hides at Beren's Peril, preparing an attack on the Sepulcher. They are servants of the necromancer Thule Ravenclaw.",
			source = "https://warcraft.wiki.gg/wiki/Beren's_Peril",
		},
		["dawning isles"] = {
			name = "The Dawning Isles",
			short = "The Dawning Isles were once an idyllic set of low islets rising from the clear water of Lordamere Lake. The plague of undeath reached them, and their trees grew sickly.",
			full = "The Dawning Isles were once an idyllic set of low islets rising from the clear water of Lordamere Lake. The plague of undeath reached them, and their trees grew sickly. Murlocs roamed the shores, and now the Vile Fin murlocs, grown very numerous, hold the isles entirely.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Isles",
		},
		["dead field"] = {
			name = "The Dead Field",
			short = "Nobody knows who farmed the Dead Field. The farm in northern Silverpine Forest is abandoned and rotting, and the Rot Hide gnolls, servants of the Scourge, have made it a base.",
			full = "Nobody knows who farmed the Dead Field. The farm in northern Silverpine Forest is abandoned and rotting, and the Rot Hide gnolls, servants of the Scourge, have made it a base. Their numbers keep growing, which points to an attack in the making. The Forsaken have struck at the field again and again and failed each time. When the gnolls come under attack, the banshee Nightlash, who commands them, may rise among them.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Field",
		},
		["decrepit ferry"] = {
			name = "The Decrepit Ferry",
			short = "A ferry once ran from this shore to Fenris Isle, carrying goods and passengers for a small fee. The nearby farms sold part of their crops to the rich lord on the island and his family.",
			full = "A ferry once ran from this shore to Fenris Isle, carrying goods and passengers for a small fee. The nearby farms sold part of their crops to the rich lord on the island and his family. Then the Scourge invaded Lordaeron. The ferryman was murdered and the ferry destroyed. Ghouls, skeletons and Rot Hide gnolls now crowd the docks, and the ground is dangerous.",
			source = "https://warcraft.wiki.gg/wiki/Decrepit_Ferry",
		},
		["deep elem mine"] = {
			name = "Deep Elem Mine",
			short = "Arugal's magic has reached Deep Elem Mine, in the hills of central Silverpine Forest, and worgen of the Moonrage pack have made it their home.",
			full = "Arugal's magic has reached Deep Elem Mine, in the hills of central Silverpine Forest, and worgen of the Moonrage pack have made it their home. Gluttons and darksouls fill its shafts. They follow Grimson the Pale, the cunning foreman who once ran the mine.",
			source = "https://warcraft.wiki.gg/wiki/Deep_Elem_Mine",
		},
		["fenris isle"] = {
			name = "Fenris Isle",
			short = "Fenris Isle forms, with the Dawning Isles, a broken ring of dry land at the center of Lordamere Lake. It is a large island, and before the Third War it held Fenris Keep, a thriving military outpost of Lordaeron.",
			full = "Fenris Isle forms, with the Dawning Isles, a broken ring of dry land at the center of Lordamere Lake. It is a large island, and before the Third War it held Fenris Keep, a thriving military outpost of Lordaeron. When the Scourge took the country, everyone on the isle either fled or was murdered. The Rot Hide gnolls then took the keep as their base, and their treacherous master, Thule Ravenclaw, holds the whole island.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Isle",
		},
		["fenris keep"] = {
			name = "Fenris Keep",
			short = "Fenris Keep once housed a sizable part of Lordaeron's army. When the Scourge washed over the land, the keep did not escape.",
			full = "Fenris Keep once housed a sizable part of Lordaeron's army. When the Scourge washed over the land, the keep did not escape. Thule Ravenclaw, an ambitious young mage once of the Kirin Tor, sided with the Scourge and bent the local gnolls to his will, making them the Rot Hide. He is master of the keep, and his gnolls fall on anyone who comes near.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Keep",
		},
		["greymane wall"] = {
			name = "The Greymane Wall",
			short = "King Genn Greymane built this wall to cut Gilneas off from the world. He was tired of paying Gilnean taxes toward the orc internment camps, and tired of the quarrels among the kings of the Alliance of Lordaeron.",
			full = "King Genn Greymane built this wall to cut Gilneas off from the world. He was tired of paying Gilnean taxes toward the orc internment camps, and tired of the quarrels among the kings of the Alliance of Lordaeron. The wall is huge, with one great gate, and it kept the Scourge out of his kingdom. Refugees fleeing south from Lordaeron camp in its shadow. They are haggard and sick, and the gate stays shut to them.",
			source = "https://warcraft.wiki.gg/wiki/Greymane_Wall",
		},
		["ivar patch"] = {
			name = "The Ivar Patch",
			short = "Ivar's farm was a pleasant, prosperous place, and he employed many farmhands and servants. Then the plague of undeath came.",
			full = "Ivar's farm was a pleasant, prosperous place, and he employed many farmhands and servants. Then the plague of undeath came. Ivar, his family and every farmhand turned into rotting ghouls, and they fall on anyone who comes near. Ivar himself is known now as Ivar the Foul. A Forsaken scouting party was ambushed here, and Ivar wounded the deathstalker Quinn Yorick. Quinn and Rane Yorick hold out in Ivar's old house.",
			source = "https://warcraft.wiki.gg/wiki/Ivar_Patch",
		},
		["lordamere lake"] = {
			name = "Lordamere Lake",
			short = "Many human kingdoms prospered around Lordamere Lake in the days of the Alliance of Lordaeron. Lordaeron built its capital on the northern shore, and the lake very likely took its name from it.",
			full = "Many human kingdoms prospered around Lordamere Lake in the days of the Alliance of Lordaeron. Lordaeron built its capital on the northern shore, and the lake very likely took its name from it. Dalaran and Alterac stood nearby. That age is over, and the lake is now a border. It lies between the Forsaken lands of Tirisfal Glades and Silverpine Forest and the contested Alterac Mountains.\n\nAt its heart sits Fenris Isle, where Rot Hide gnolls hold an old keep of Lordaeron's army. East of it, the Vile Fin murlocs have overrun the small Dawning Isles.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Lake",
		},
		["maldens orchard"] = {
			name = "Malden's Orchard",
			short = "The trees of Malden's Orchard have gone dark and evergreen, and their fruit has not been picked in years. The orchard takes its name from its owner, who fled his home when the Scourge invaded Lordaeron.",
			full = "The trees of Malden's Orchard have gone dark and evergreen, and their fruit has not been picked in years. The orchard takes its name from its owner, who fled his home when the Scourge invaded Lordaeron.\n\nBlack worgs now den among the trees and around the orchard's single small cottage.",
			source = "https://warcraft.wiki.gg/wiki/Malden's_Orchard",
		},
		["north tides hollow"] = {
			name = "North Tide's Hollow",
			short = "North Tide's Hollow lies just north of the Sepulcher in Silverpine Forest. It is one of the many haunts of the Moonrage worgen, servants of Archmage Arugal.",
			full = "North Tide's Hollow lies just north of the Sepulcher in Silverpine Forest. It is one of the many haunts of the Moonrage worgen, servants of Archmage Arugal. Here they raise crude encampments with only the barest necessities for survival, shelter enough for creatures who live by tooth and strength.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Hollow",
		},
		["north tides run"] = {
			name = "North Tide's Run",
			short = "The northwestern shoreline of Silverpine Forest, where the beach meets the Great Sea, bears the name North Tide's Run. A derelict boat rests on the shore, the most prominent mark on this stretch of coast.",
			full = "The northwestern shoreline of Silverpine Forest, where the beach meets the Great Sea, bears the name North Tide's Run. A derelict boat rests on the shore, the most prominent mark on this stretch of coast. Corrupted water spirits haunt these waters. A fisherman, Killian Sanatha, keeps a campfire on the beach and sells fishing recipes, and a troll, Tiev Mordune, keeps to the shore.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Run",
		},
		["olsens farthing"] = {
			name = "Olsen's Farthing",
			short = "Olsen's Farthing was once a busy farmstead on the main trade road through Silverpine Forest. Now it lies in ruins.",
			full = "Olsen's Farthing was once a busy farmstead on the main trade road through Silverpine Forest. Now it lies in ruins. Undead under the command of Thule Ravenclaw hold the farm, skeletal raiders and ghouls he keeps as slaves, and they attack anyone who comes near.",
			source = "https://warcraft.wiki.gg/wiki/Olsen's_Farthing",
		},
		["pyrewood village"] = {
			name = "Pyrewood Village",
			short = "By day Pyrewood Village is a human settlement with a town hall, a blacksmith and a chapel. Its people lived through the coming of the Scourge, and they still sell cloth, leather and mail to travelers.",
			full = "By day Pyrewood Village is a human settlement with a town hall, a blacksmith and a chapel. Its people lived through the coming of the Scourge, and they still sell cloth, leather and mail to travelers.\n\nThen night falls. From Shadowfang Keep on the bluff above, Archmage Arugal has cursed the village. Every evening its people turn into Moonrage worgen and attack anyone near, whatever side they stand on. At dawn they wake human again.",
			source = "https://warcraft.wiki.gg/wiki/Pyrewood_Village",
		},
		["sepulcher"] = {
			name = "The Sepulcher",
			short = "The Sepulcher sits in the western hills above the Lordaeron coast. Once it was only a large graveyard beside the road that crosses Silverpine Forest, its crypts a resting place for the dead.",
			full = "The Sepulcher sits in the western hills above the Lordaeron coast. Once it was only a large graveyard beside the road that crosses Silverpine Forest, its crypts a resting place for the dead. Since the Third War the Forsaken have turned the old graveyard into their base in the region, a place built for the dead made to serve the undying.\n\nWorgen are to the south, the Scourge to the east, and the forces of the Kirin Tor to the southeast. Surrounded on nearly every side, the Forsaken hold one of the few places in the forest where the Horde can stand in safety.",
			source = "https://warcraft.wiki.gg/wiki/Sepulcher",
		},
		["shadowfang keep"] = {
			name = "Shadowfang Keep",
			short = "Baron Silverlaine once held this keep on a high bluff above Pyrewood Village. When the Scourge swept over Lordaeron, Archmage Arugal summoned the worgen against the counsel of the Kirin Tor.",
			full = "Baron Silverlaine once held this keep on a high bluff above Pyrewood Village. When the Scourge swept over Lordaeron, Archmage Arugal summoned the worgen against the counsel of the Kirin Tor.\n\nThe worgen cut down the Scourge, then besieged the keep and killed the Baron. Arugal, mad with guilt, took the worgen as his children and withdrew inside. He renamed the place Shadowfang Keep. He is said to be there still, guarded by his great pet Fenrus and haunted by the Baron's ghost.",
			source = "https://warcraft.wiki.gg/wiki/Shadowfang_Keep",
		},
		["shining strand"] = {
			name = "The Shining Strand",
			short = "A long shoreline of Lordamere Lake runs from the capital city of Lordaeron in the north to the rough hills that divide Silverpine Forest from the Alterac Mountains.",
			full = "A long shoreline of Lordamere Lake runs from the capital city of Lordaeron in the north to the rough hills that divide Silverpine Forest from the Alterac Mountains. This is the Shining Strand.\n\nThe Vile Fin murlocs have several settlements along it, and travelers who do not know the shore find it dangerous.",
			source = "https://warcraft.wiki.gg/wiki/Shining_Strand",
		},
		["skittering dark"] = {
			name = "The Skittering Dark",
			short = "Spiders have taken over the Skittering Dark, an abandoned mine near the northwestern coast of Silverpine Forest.",
			full = "Spiders have taken over the Skittering Dark, an abandoned mine near the northwestern coast of Silverpine Forest. Moss stalkers crawl through the mine and the ground around its mouth, mist creepers lurk in the woods just east of it, and giant grizzled bears hunt among them. A rare spider, Krethis Shadowspinner, sometimes prowls nearby.",
			source = "https://warcraft.wiki.gg/wiki/Skittering_Dark",
		},
		["south tides run"] = {
			name = "South Tide's Run",
			short = "The southwestern coast of Silverpine Forest, where the land meets the Great Sea, is called South Tide's Run.",
			full = "The southwestern coast of Silverpine Forest, where the land meets the Great Sea, is called South Tide's Run.",
			source = "https://warcraft.wiki.gg/wiki/South_Tide's_Run",
		},
		["valgans field"] = {
			name = "Valgan's Field",
			short = "Valgan's Field was a wheat farm, and it takes its name from the man who owned it. When the Scourge arrived in Silverpine Forest he was either killed or forced to flee.",
			full = "Valgan's Field was a wheat farm, and it takes its name from the man who owned it. When the Scourge arrived in Silverpine Forest he was either killed or forced to flee. From the fields there was a fine view of Lordamere Lake.\n\nNow it is one of the desolate farms in the north of the forest, west of the Shining Strand, and feral Moonrage worgen roam the empty farm.",
			source = "https://warcraft.wiki.gg/wiki/Valgan's_Field",
		},
	},
	-- Western Plaguelands: 17 subzones
	[1422] = {
		["bulwark"] = {
			name = "The Bulwark",
			short = "After the fall of Lordaeron, Uther the Lightbringer made a camp here for the survivors, on the border where Tirisfal Glades meets the Western Plaguelands.",
			full = "After the fall of Lordaeron, Uther the Lightbringer made a camp here for the survivors, on the border where Tirisfal Glades meets the Western Plaguelands. Now the Forsaken hold the ground against the Scourge, and Argent Dawn soldiers stand with them.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["caer darrow"] = {
			name = "Caer Darrow",
			short = "Humans built the fortress of Caer Darrow long ago, and an ancient high elven runestone was set within it.",
			full = "Humans built the fortress of Caer Darrow long ago, and an ancient high elven runestone was set within it. In the Second War the Horde invaded the island, sacked the keep and hewed the runestone into the pieces from which the Altars of Storms were made. Gul'dan used them to instill magic into his ogre allies.\n\nThe keep was restored after the war and became the manor of House Barov. In the years before the Third War the Barovs grew greedy and bitter and wanted to keep their fortune and land beyond their own lifespan. Kel'Thuzad, leader of the Cult of the Damned, offered a way. Beneath the manor the catacombs became Scholomance, a school of necromancy, and the family's servants were used to test the plague of undeath. Within six months a sickness broke loose and killed everyone on the island. Their spirits remain, each bound to relive the last thing it knew. Two girls still race each other by the fountain, and a baker still sells his bread.",
			source = "https://warcraft.wiki.gg/wiki/Caer_Darrow",
		},
		["chillwind camp"] = {
			name = "Chillwind Camp",
			short = "Chillwind Camp stands at the southern entrance to the Western Plaguelands, where the road comes down from the Alterac Mountains, and it is the last safe ground for Alliance travelers.",
			full = "Chillwind Camp stands at the southern entrance to the Western Plaguelands, where the road comes down from the Alterac Mountains, and it is the last safe ground for Alliance travelers. A small contingent of the Argent Dawn keeps it. With only a few troops and specialists, the Dawn leans on mercenaries and fights a guerrilla war against the Scourge at Andorhal and the plague cauldrons. Commander Ashlam Valorfist is here too, sent by the Kingdom of Stormwind and its allies to counter the Scourge.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Camp",
		},
		["dalsons tears"] = {
			name = "Dalson's Tears",
			short = "Dalson's Orchard once bore fruit for the family that gave it its name. Now the Scourge hold the farm.",
			full = "Dalson's Orchard once bore fruit for the family that gave it its name. Now the Scourge hold the farm. A plague cauldron squats in the field and breathes out disease, and blighted zombies, rotting cadavers and skeletal terrors guard it.",
			source = "https://warcraft.wiki.gg/wiki/Dalson's_Tears",
		},
		["darrowmere lake"] = {
			name = "Darrowmere Lake",
			short = "Darrowmere is one of the largest lakes in the Eastern Kingdoms and among the most symbolic places of the fallen kingdom of Lordaeron.",
			full = "Darrowmere is one of the largest lakes in the Eastern Kingdoms and among the most symbolic places of the fallen kingdom of Lordaeron. The Thondroril River is joined to it in the north and the Darrowmere River in the south. In the middle lies the island town of Caer Darrow, where the House of Barov once lived. It is abandoned now. Beneath it is Scholomance, where the Cult of the Damned works among its undead.",
			source = "https://warcraft.wiki.gg/wiki/Darrowmere_Lake",
		},
		["felstone field"] = {
			name = "Felstone Field",
			short = "Felstone Field once fed the living. The Scourge overran it and set a cauldron in the middle of the field, and vapor thick with disease has poured out of it ever since.",
			full = "Felstone Field once fed the living. The Scourge overran it and set a cauldron in the middle of the field, and vapor thick with disease has poured out of it ever since. Skeletal sorcerers, skeletal flayers and slavering ghouls guard it. A party of the Scarlet Crusade is here too, and it takes vengeance on the living and the dead alike. In the house at the northeastern corner of the field, Janice Felstone is still at home.",
			source = "https://warcraft.wiki.gg/wiki/Felstone_Field",
		},
		["gahrrons withering"] = {
			name = "Gahrron's Withering",
			short = "The farm at the eastern edge of the Western Plaguelands once belonged to Gahrron, and in its better days it was called Gahrron's Quickening.",
			full = "The farm at the eastern edge of the Western Plaguelands once belonged to Gahrron, and in its better days it was called Gahrron's Quickening. Nothing grows there now. The Scourge took the field and raised a cauldron in the middle of it, and haunting visions, wailing deaths and hungering wraiths guard it, drifting over the ruined rows.",
			source = "https://warcraft.wiki.gg/wiki/Gahrron's_Withering",
		},
		["hearthglen"] = {
			name = "Hearthglen",
			short = "The Horde never took Hearthglen in the Second War, and the Scourge did not take it either, though its people had just baked bread from plagued grain out of Andorhal when the dead came.",
			full = "The Horde never took Hearthglen in the Second War, and the Scourge did not take it either, though its people had just baked bread from plagued grain out of Andorhal when the dead came. Its walls enclose a town hall, a mage tower, a lumber mill, stables, a mine and Mardenholde Keep, from which the region was governed. Now the Scarlet Crusade holds the town and the keep, and its soldiers strike out from behind the walls against the Scourge.",
			source = "https://warcraft.wiki.gg/wiki/Hearthglen",
		},
		["mardenholde keep"] = {
			name = "Mardenholde Keep",
			short = "Tirion Fordring was lord of Mardenholde Keep until he was excommunicated, and his son Taelan took the keep after him.",
			full = "Tirion Fordring was lord of Mardenholde Keep until he was excommunicated, and his son Taelan took the keep after him. Taelan is Highlord of the Scarlet Crusade now, and the keep is the Crusade's headquarters in the Western Plaguelands.\n\nIn Tirion's day Mardenholde was the center of commerce and trade for the principality of Hearthglen. A few years before the Third War it filled with dignitaries from the nations of the Alliance, passing through Hearthglen on secret diplomatic errands.",
			source = "https://warcraft.wiki.gg/wiki/Mardenholde_Keep",
		},
		["northridge lumber camp"] = {
			name = "Northridge Lumber Camp",
			short = "The Scarlet Crusade runs the lumber mill here, in the northern Western Plaguelands close to Hearthglen. The timber it cuts is a supply the Crusade prizes.",
			full = "The Scarlet Crusade runs the lumber mill here, in the northern Western Plaguelands close to Hearthglen. The timber it cuts is a supply the Crusade prizes. Before the Third War the mill was run by the family of Nathaniel Dumah.",
			source = "https://warcraft.wiki.gg/wiki/Northridge_Lumber_Camp",
		},
		["ruins of andorhal"] = {
			name = "Ruins of Andorhal",
			short = "Andorhal was the granary of northern Lordaeron. Its grain went out to the towns of the north, and the necromancer Kel'Thuzad and his Cult of the Damned infected it with the Plague of Undeath before it left.",
			full = "Andorhal was the granary of northern Lordaeron. Its grain went out to the towns of the north, and the necromancer Kel'Thuzad and his Cult of the Damned infected it with the Plague of Undeath before it left.\n\nWhen the Scourge came for the city, its desperate defenders set it ablaze so that the Scourge could not raise more warriors from the dead. Now it lies in ruin. Ghouls drag themselves between the fallen stones, skeletons stand sentinel where guards once did, banshees cry over the ruins and abominations lumber through the wreckage of homes. The lich Araj the Summoner holds the city as his base and oversees the plague cauldrons across the Western Plaguelands.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Andorhal",
		},
		["scholomance"] = {
			name = "Scholomance",
			short = "The House of Barov kept its manor on this rise above Caer Darrow.",
			full = "The House of Barov kept its manor on this rise above Caer Darrow. To keep its fortune beyond death, the family gave the manor and its crypts to Kel'Thuzad and his Cult of the Damned in exchange for the Lich King's blessing of immortality.\n\nThe cult made the crypts a school of necromancy, and the Barovs remain as undead monsters. The lich Ras Frostwhisper rules over the site and guards it for the Scourge, while the mortal necromancer Darkmaster Gandling serves as its headmaster.",
			source = "https://warcraft.wiki.gg/wiki/Scholomance",
		},
		["sorrow hill"] = {
			name = "Sorrow Hill",
			short = "In peaceful years Sorrow Hill was where Andorhal buried its dead, rich and poor alike. When the plague came and the Scourge raided without end, the graves multiplied faster than anyone could mark them.",
			full = "In peaceful years Sorrow Hill was where Andorhal buried its dead, rich and poor alike. When the plague came and the Scourge raided without end, the graves multiplied faster than anyone could mark them. Hurried mounds still cover the ground where defenders fell. At last the survivors stopped burying and burned their dead in a mass grave south of the cemetery, afraid of what the plague would make of them. When Prince Arthas Menethil struck down Uther the Lightbringer, a great tomb was raised on the hill and the paladin's torn body laid within it.\n\nEven so, the plague cauldrons raised the dead of the hill. Soldiers and townsfolk stand guard over their own graves.",
			source = "https://warcraft.wiki.gg/wiki/Sorrow_Hill",
		},
		["thondroril river"] = {
			name = "Thondroril River",
			short = "The Thondroril River marks the line between the Western and Eastern Plaguelands. It runs south into Darrowmere Lake and goes on below it as the Darrowmere River.",
			full = "The Thondroril River marks the line between the Western and Eastern Plaguelands. It runs south into Darrowmere Lake and goes on below it as the Darrowmere River. Maggots, vampire bats, plaguebears and spiders crowd its banks.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["uthers tomb"] = {
			name = "Uther's Tomb",
			short = "Uther's Tomb stands at Sorrow Hill, the one place in the Western Plaguelands where the Light still holds against the dying of the land.",
			full = "Uther's Tomb stands at Sorrow Hill, the one place in the Western Plaguelands where the Light still holds against the dying of the land.\n\nUther the Lightbringer once held Andorhal against the Scourge, standing beside Sage Truthbearer and Ballador the Bright with the Knights of the Silver Hand at his back. Arthas Menethil ended that stand. He brought his undead army against the city and cut down Truthbearer, Ballador and Uther himself.\n\nUther's own soldiers gathered up his body, carried it south of Andorhal's ruins and raised a great tomb over it. His headstone shows him as he was in life, a tome of the Light in one hand and his warhammer in the other. High Priest Thel'danis keeps the tomb as its caretaker and guardian, and the grave is sacred to those who follow the Light.",
			source = "https://warcraft.wiki.gg/wiki/Uther's_Tomb",
		},
		["weeping cave"] = {
			name = "The Weeping Cave",
			short = "The Weeping Cave opens in the northeastern part of the Western Plaguelands, just west of the Thondroril River. Bog beasts and oozes fill its hollows, with rotting behemoths and decaying horrors shambling in the dark.",
			full = "The Weeping Cave opens in the northeastern part of the Western Plaguelands, just west of the Thondroril River. Bog beasts and oozes fill its hollows, with rotting behemoths and decaying horrors shambling in the dark. A rare elemental called the Husk lurks among them.",
			source = "https://warcraft.wiki.gg/wiki/Weeping_Cave",
		},
		["writhing haunt"] = {
			name = "The Writhing Haunt",
			short = "Crops once grew in the furrows of the Writhing Haunt, tended for the sustenance of the living. The Scourge took the fields and set at their center a great cauldron, which has not stopped its work since.",
			full = "Crops once grew in the furrows of the Writhing Haunt, tended for the sustenance of the living. The Scourge took the fields and set at their center a great cauldron, which has not stopped its work since. A constant spew of disease-filled vapor rolls out across the rows.\n\nRotting ghouls, freezing ghouls and fetid zombies stand watch over it, bound to the place as its wardens. In one of the farm's houses lies Mulgris Deepriver, a tauren druid who came to these lands to heal what the plague had done to nature. He is dying.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Haunt",
		},
	},
	-- Eastern Plaguelands: 28 subzones
	[1423] = {
		["blackwood lake"] = {
			name = "Blackwood Lake",
			short = "A town called Blackwood once stood on this shore, home to Grand Marshal Othmar Garithos, who ruled it as baron. Nothing of it remains but the name.",
			full = "A town called Blackwood once stood on this shore, home to Grand Marshal Othmar Garithos, who ruled it as baron. Nothing of it remains but the name.\n\nThe water is foul now, and corrupted water elementals coil through it.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Lake",
		},
		["browman mill"] = {
			name = "Browman Mill",
			short = "Skeletons, banshees and abominations crowd Browman Mill, a haunted lumber mill just north of Light's Hope Chapel.",
			full = "Skeletons, banshees and abominations crowd Browman Mill, a haunted lumber mill just north of Light's Hope Chapel.",
			source = "https://warcraft.wiki.gg/wiki/Browman_Mill",
		},
		["corins crossing"] = {
			name = "Corin's Crossing",
			short = "Corin's Crossing sits where the roads to Andorhal, Darrowshire, Stratholme and Tyr's Hand meet, between the Infectis Scar and Lake Mereldar.",
			full = "Corin's Crossing sits where the roads to Andorhal, Darrowshire, Stratholme and Tyr's Hand meet, between the Infectis Scar and Lake Mereldar. Its town hall and blacksmith still stand among the ruins, but the Scourge fills the streets to the brim. Tutors and summoners of the Cult of the Damned work there, and banshees shriek through the ruins.\n\nAmong the dead move things that cannot be seen at all, the Unseen Servants, and nothing creeps past them unnoticed.",
			source = "https://warcraft.wiki.gg/wiki/Corin's_Crossing",
		},
		["crown guard tower"] = {
			name = "Crown Guard Tower",
			short = "Lordaeron raised scout towers like this one to watch its borders and spot enemies from far off. When the Scourge swept through the kingdom, Crown Guard Tower was destroyed.",
			full = "Lordaeron raised scout towers like this one to watch its borders and spot enemies from far off. When the Scourge swept through the kingdom, Crown Guard Tower was destroyed. It stands in ruins now.\n\nThe Horde and the Alliance both contest the broken tower, each hoping to use it to fortify itself in Lordaeron.",
			source = "https://warcraft.wiki.gg/wiki/Crown_Guard_Tower",
		},
		["darrowshire"] = {
			name = "Darrowshire",
			short = "Darrowshire lies in the southern hills of the Eastern Plaguelands. In the Third War the Scourge fell on it, and its defenders were slaughtered.",
			full = "Darrowshire lies in the southern hills of the Eastern Plaguelands. In the Third War the Scourge fell on it, and its defenders were slaughtered.\n\nThey rose again as ghouls, their spirits trapped in rotting flesh, and serve the Scourge. Darrowshire lies silent and in ruins now, a place where only ghosts and memories remain, and the ghost of Pamela Redpath, a little girl, still lingers there.",
			source = "https://warcraft.wiki.gg/wiki/Darrowshire",
		},
		["eastwall gate"] = {
			name = "Eastwall Gate",
			short = "Eastwall Gate is a side way into Stratholme. It opens straight onto Elder's Square, beside the Alonsus Chapel, where the first paladins of the Silver Hand were ordained before the Second War.",
			full = "Eastwall Gate is a side way into Stratholme. It opens straight onto Elder's Square, beside the Alonsus Chapel, where the first paladins of the Silver Hand were ordained before the Second War.\n\nBeyond the gate the Scarlet Crusade and the Scourge fight over the city.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Gate",
		},
		["eastwall tower"] = {
			name = "Eastwall Tower",
			short = "Eastwall Tower stands near Light's Hope Chapel, a scout tower of Lordaeron's. The Scourge invasion destroyed it, and only ruins are left to watch the dead land.",
			full = "Eastwall Tower stands near Light's Hope Chapel, a scout tower of Lordaeron's. The Scourge invasion destroyed it, and only ruins are left to watch the dead land.\n\nThe Horde and the Alliance both fight over the ruin, each wanting to hold ground in Lordaeron from it.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Tower",
		},
		["fungal vale"] = {
			name = "The Fungal Vale",
			short = "North of the Marris Stead and the Crown Guard Tower lies the Fungal Vale, ground gone dark purple beneath a murky haze.",
			full = "North of the Marris Stead and the Crown Guard Tower lies the Fungal Vale, ground gone dark purple beneath a murky haze. The Plague of Undeath has taken one of its deepest holds here, and the Scourge and the Cult of the Damned move freely through the corruption.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Vale",
		},
		["infectis scar"] = {
			name = "The Infectis Scar",
			short = "The Infectis Scar is a deep gorge in the blighted earth near Corin's Crossing.",
			full = "The Infectis Scar is a deep gorge in the blighted earth near Corin's Crossing.\n\nOozes of living decay and rotting sludge crawl along its floor, and spectral corpses and spectral marauders drift among them.",
			source = "https://warcraft.wiki.gg/wiki/Infectis_Scar",
		},
		["lake mereldar"] = {
			name = "Lake Mereldar",
			short = "Corrupted water elementals move through Lake Mereldar, a large lake south of Corin's Crossing whose water the plague has polluted.",
			full = "Corrupted water elementals move through Lake Mereldar, a large lake south of Corin's Crossing whose water the plague has polluted. On the shore stand the ruins of an old house, and a shack and ferry that belonged to a farm.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mereldar",
		},
		["lights hope chapel"] = {
			name = "Light's Hope Chapel",
			short = "Among the oldest and most revered holy sites of the Church of the Holy Light, Light's Hope Chapel stands on the slopes of the mountains in the east of the region.",
			full = "Among the oldest and most revered holy sites of the Church of the Holy Light, Light's Hope Chapel stands on the slopes of the mountains in the east of the region. A small camp of the Argent Dawn holds it now, and the Dawn takes fighters of every race and counts both the Alliance and the Horde as allies.\n\nInside, Commander Eligor Dawnbringer of the Brotherhood of the Light keeps the peace between the Dawn and the Scarlet Crusade. He has met Scarlet envoys here to plan against Kel'Thuzad and the Scourge.",
			source = "https://warcraft.wiki.gg/wiki/Light's_Hope_Chapel",
		},
		["marris stead"] = {
			name = "The Marris Stead",
			short = "The Marris Stead stands on a small ridge beside the main road, the long-time homestead of Nathanos Marris. His cousin Stephon lived here for a while, and Lady Sylvanas Windrunner sometimes visited.",
			full = "The Marris Stead stands on a small ridge beside the main road, the long-time homestead of Nathanos Marris. His cousin Stephon lived here for a while, and Lady Sylvanas Windrunner sometimes visited.\n\nNathanos was killed when the Scourge swept over Lordaeron, then freed by Sylvanas. Now one of the Forsaken, he has come home at her order, with his blighthounds. He recruits Horde soldiers to fight the Scourge and the Scarlet Crusade.",
			source = "https://warcraft.wiki.gg/wiki/Marris_Stead",
		},
		["mazraalor"] = {
			name = "Mazra'Alor",
			short = "Forest troll shadow hunters of the Mossflayer tribe hold Mazra'Alor, the great ziggurat at the heart of Zul'Mashar. Zul'Mashar is home to Warlord Thresh'jin and Zul'Brin Warpbranch.",
			full = "Forest troll shadow hunters of the Mossflayer tribe hold Mazra'Alor, the great ziggurat at the heart of Zul'Mashar. Zul'Mashar is home to Warlord Thresh'jin and Zul'Brin Warpbranch.",
			source = "https://warcraft.wiki.gg/wiki/Mazra'Alor",
		},
		["northdale"] = {
			name = "Northdale",
			short = "Banshees and unseen, eyeless watchers haunt the wrecked houses of Northdale, a destroyed town north of Light's Hope Chapel and southeast of the entrance to Quel'Thalas.",
			full = "Banshees and unseen, eyeless watchers haunt the wrecked houses of Northdale, a destroyed town north of Light's Hope Chapel and southeast of the entrance to Quel'Thalas. The lake nearby is full of corrupted water elementals.",
			source = "https://warcraft.wiki.gg/wiki/Northdale",
		},
		["northpass tower"] = {
			name = "Northpass Tower",
			short = "Northpass Tower stands farthest north of the watchtowers in the Eastern Plaguelands, marking the road toward Quel'Thalas.",
			full = "Northpass Tower stands farthest north of the watchtowers in the Eastern Plaguelands, marking the road toward Quel'Thalas. The Scourge swept through Lordaeron, and the tower wears its scars still.",
			source = "https://warcraft.wiki.gg/wiki/Northpass_Tower",
		},
		["noxious glade"] = {
			name = "The Noxious Glade",
			short = "The air in the Noxious Glade hangs thick and sickly green, and the ground is stained dark purple.",
			full = "The air in the Noxious Glade hangs thick and sickly green, and the ground is stained dark purple. The glade lies up a hill north of Light's Hope Chapel, and the blight has fouled it worse than the rest of the Plaguelands. The Scourge has built a plague cauldron and a slaughterhouse here, and its creatures move through the poisoned ground.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Glade",
		},
		["pestilent scar"] = {
			name = "Pestilent Scar",
			short = "A deep gorge scars the blighted earth of the Eastern Plaguelands. It looks to be a natural one, perhaps a lake that dried up when the Plague of Undeath struck.",
			full = "A deep gorge scars the blighted earth of the Eastern Plaguelands. It looks to be a natural one, perhaps a lake that dried up when the Plague of Undeath struck. Oozes still live in its depths.",
			source = "https://warcraft.wiki.gg/wiki/Pestilent_Scar",
		},
		["plaguewood"] = {
			name = "Plaguewood",
			short = "South of Stratholme, this wood was called Greenwood before the plague. It stood green and untroubled, a woodland much like Elwynn Forest, with a small village near the arch at its entrance.",
			full = "South of Stratholme, this wood was called Greenwood before the plague. It stood green and untroubled, a woodland much like Elwynn Forest, with a small village near the arch at its entrance. When Kel'Thuzad began his work, poisoned grain from Andorhal reached the village. Sergeant Morigan, a Lordaeronian soldier from there, was the first to see that something was wrong. Prince Arthas crossed the woodland on his way to Stratholme.\n\nWhat was left afterward was not a forest anymore. The soil went spongy underfoot, and mushrooms and toadstools swelled to the size of trees, towering over what remained of the old woodland. They breathe out a dark brown gas not unlike the fumes of the Scourge's plague cauldrons. No one can say whether the fungus simply grows in poisoned ground or the Scourge grows it to spread its sickness. The wood took the name Plaguewood from this change.",
			source = "https://warcraft.wiki.gg/wiki/Plaguewood",
		},
		["quellithien lodge"] = {
			name = "Quel'Lithien Lodge",
			short = "Many travelers once stopped at Quel'Lithien Lodge, a Farstrider camp near the entrance to Quel'Thalas. It was one of two major gatherings of high elves in Lordaeron.",
			full = "Many travelers once stopped at Quel'Lithien Lodge, a Farstrider camp near the entrance to Quel'Thalas. It was one of two major gatherings of high elves in Lordaeron.\n\nBy the Second War, Ranger Lord Hawkspear led the hunters here. The Scourge's invasion of Quel'Thalas brought the lodge hard times, and rangers under him still hold it, with Aurora Skycaller and Kriss Goldenlight among them.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Lithien_Lodge",
		},
		["scarlet base camp"] = {
			name = "Scarlet Base Camp",
			short = "The Scarlet Base Camp is a small fortification of barricades on the east bank of Lake Mereldar, not far from Tyr's Hand. Scarlet warders, clerics and enchanters keep it for the Crusade.",
			full = "The Scarlet Base Camp is a small fortification of barricades on the east bank of Lake Mereldar, not far from Tyr's Hand. Scarlet warders, clerics and enchanters keep it for the Crusade.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Base_Camp",
		},
		["scarlet basilica"] = {
			name = "The Scarlet Basilica",
			short = "The high seat of the Scarlet Crusade's religious power is the Scarlet Basilica, a great cathedral in Tyr's Hand, where Crusader Lord Valdelmar is found.",
			full = "The high seat of the Scarlet Crusade's religious power is the Scarlet Basilica, a great cathedral in Tyr's Hand, where Crusader Lord Valdelmar is found. It stands close to Tyr's Hand Abbey and has ties to the Scarlet Monastery far off in Tirisfal Glades. The building is much like the Cathedral of Light in Stormwind.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Basilica",
		},
		["stratholme"] = {
			name = "Stratholme",
			short = "Stratholme's ruin began with grain. Shipments from Andorhal, infected by the Cult of the Damned, were baked into bread and eaten by a populace who never knew they were dying.",
			full = "Stratholme's ruin began with grain. Shipments from Andorhal, infected by the Cult of the Damned, were baked into bread and eaten by a populace who never knew they were dying. Prince Arthas Menethil arrived with Uther the Lightbringer and Jaina Proudmoore to find the plague already spreading. Arthas believed the only way to keep the city from becoming a Scourge stronghold was to purge it, and he ordered the plagued citizens killed. Uther and Jaina thought it madness and refused. Arthas went on with his own soldiers. Fire swept the streets, and almost every soul in Stratholme was massacred. The dreadlord Mal'Ganis, whom Arthas had come to kill, escaped the slaughter.\n\nThe undead moved in, and the city became the Scourge's capital in Lordaeron. Stratholme burns still. The Scarlet Crusade under Grand Crusader Dathrohan holds one half of the ruin, the Scourge under Baron Rivendare the other, and the two sides fight without pause.",
			source = "https://warcraft.wiki.gg/wiki/Stratholme",
		},
		["terrordale"] = {
			name = "Terrordale",
			short = "Terrordale is a small town in the northwest corner of the Eastern Plaguelands.",
			full = "Terrordale is a small town in the northwest corner of the Eastern Plaguelands. It sits on the edge of the Plaguewood and is a ghost town now: only the Scourge and plagued animals roam it, apart from the merchant Augustus the Touched and the ghost hunter Egan. Before the Scourge came, Augustus had a great business and bought and sold everything, and he still trades with anyone who passes.",
			source = "https://warcraft.wiki.gg/wiki/Terrordale",
		},
		["terrorweb tunnel"] = {
			name = "Terrorweb Tunnel",
			short = "Crypt fiends fill the Terrorweb Tunnel, a long, winding passage through the mountain that runs from Terrordale in the north to the Thondroril River in the south.",
			full = "Crypt fiends fill the Terrorweb Tunnel, a long, winding passage through the mountain that runs from Terrordale in the north to the Thondroril River in the south. Now and then a Nerubian Overseer, far more powerful than the rest, stalks its length. Tirion Fordring stands at the tunnel's mouth by the river.",
			source = "https://warcraft.wiki.gg/wiki/Terrorweb_Tunnel",
		},
		["thondroril river"] = {
			name = "Thondroril River",
			short = "Tirion Fordring, one of the first paladins of the Silver Hand, keeps to the eastern side of the Thondroril River, near a ruined farmhouse.",
			full = "Tirion Fordring, one of the first paladins of the Silver Hand, keeps to the eastern side of the Thondroril River, near a ruined farmhouse. The river marks the line between the Western and Eastern Plaguelands. It rises in the north and runs south into Darrowmere Lake, and below the lake it goes on as the Darrowmere River.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["tyrs hand"] = {
			name = "Tyr's Hand",
			short = "Crusader Lord Valdelmar holds Tyr's Hand for the Scarlet Crusade against the Scourge, one of the last strongholds of the living in Lordaeron.",
			full = "Crusader Lord Valdelmar holds Tyr's Hand for the Scarlet Crusade against the Scourge, one of the last strongholds of the living in Lordaeron. Churches fill the fortified city, which the Church of the Holy Light counts among its oldest and most revered holy sites. The Scarlet Basilica and the fortified abbey stand among them, and the walls are heavy. The city sends supplies and reinforcements to other Scarlet strongholds, while couriers fight their way in from Stratholme with daily reports. The land around it is in better shape than the rest of the Plaguelands, though the trees still decay.",
			source = "https://warcraft.wiki.gg/wiki/Tyr's_Hand",
		},
		["undercroft"] = {
			name = "The Undercroft",
			short = "Undead trolls of the Mossflayer tribe have made a crypt in the southwest of the Eastern Plaguelands their den, zombies and unliving Mossflayers alike.",
			full = "Undead trolls of the Mossflayer tribe have made a crypt in the southwest of the Eastern Plaguelands their den, zombies and unliving Mossflayers alike. Zaeldarr the Outcast, a dire troll risen from the dead, leads them. From time to time his band raids the Argent Dawn's grave pit at Light's Hope Chapel and carries the bodies back to the Undercroft.",
			source = "https://warcraft.wiki.gg/wiki/Undercroft",
		},
		["zulmashar"] = {
			name = "Zul'Mashar",
			short = "The Mossflayers, a small tribe of forest trolls, once ruled from Zul'Mashar.",
			full = "The Mossflayers, a small tribe of forest trolls, once ruled from Zul'Mashar. Long fighting with the humans of Lordaeron threw their land into disarray, and the trolls retook parts of it before the plague of undeath arrived and did more damage still. The city is a shadow of its former glory.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Mashar",
		},
	},
	-- Hillsbrad Foothills: 25 subzones
	[1424] = {
		["azurelode mine"] = {
			name = "Azurelode Mine",
			short = "Iron comes out of this mine for the armories of the Alliance. Miners from Hillsbrad Fields work it under Foreman Bonds, and guards stand watch to protect them.",
			full = "Iron comes out of this mine for the armories of the Alliance. Miners from Hillsbrad Fields work it under Foreman Bonds, and guards stand watch to protect them. The mine lies in the southwest of the Foothills, south of the fields.",
			source = "https://warcraft.wiki.gg/wiki/Azurelode_Mine",
		},
		["chillwind point"] = {
			name = "Chillwind Point",
			short = "Cold wind pours down the ravine here from the Plaguelands, and the rise takes its name from it. The pass once belonged to the kingdom of Lordaeron.",
			full = "Cold wind pours down the ravine here from the Plaguelands, and the rise takes its name from it. The pass once belonged to the kingdom of Lordaeron. An ancient troll ruin crowns the hill. A jungle troll shaman, Bath'rah the Windwatcher, has made the ruin his home and lives there as a hermit. He is a skilled weaponcrafter.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Point",
		},
		["corrahns dagger"] = {
			name = "Corrahn's Dagger",
			short = "Outlaws of the Syndicate hold this hill. They are human criminals led by nobles of the fallen kingdom of Alterac, and they are enemies of the Alliance and the Horde alike.",
			full = "Outlaws of the Syndicate hold this hill. They are human criminals led by nobles of the fallen kingdom of Alterac, and they are enemies of the Alliance and the Horde alike.",
			source = "https://warcraft.wiki.gg/wiki/Corrahn's_Dagger",
		},
		["crushridge hold"] = {
			name = "Crushridge Hold",
			short = "Near the ruins of Alterac, a cave in an earthen mound shelters a large number of Crushridge ogres, and more of them camp around it.",
			full = "Near the ruins of Alterac, a cave in an earthen mound shelters a large number of Crushridge ogres, and more of them camp around it. The kingdom of Alterac had made a pact with the Horde in the Second War, and the other human kingdoms struck its capital for the treason. Most of the people fled. Now the ogres hold the empty ruins.",
			source = "https://warcraft.wiki.gg/wiki/Crushridge_Hold",
		},
		["darrow hill"] = {
			name = "Darrow Hill",
			short = "Darrow Hill lies in the northern Hillsbrad Foothills, beneath the Headland.",
			full = "Darrow Hill lies in the northern Hillsbrad Foothills, beneath the Headland. Mountain lions and stags range its open fields, and within the Foothill Caverns yetis have made their den, among veins of Alterac granite that run through the rock.",
			source = "https://warcraft.wiki.gg/wiki/Darrow_Hill",
		},
		["dun garok"] = {
			name = "Dun Garok",
			short = "Dwarves hold this keep in the southeastern hills, under Captain Ironhill. They guard the humans of Hillsbrad and watch over the Azurelode Mine.",
			full = "Dwarves hold this keep in the southeastern hills, under Captain Ironhill. They guard the humans of Hillsbrad and watch over the Azurelode Mine. The Forsaken hate having them so close and want them dead.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Garok",
		},
		["durnholde keep"] = {
			name = "Durnholde Keep",
			short = "In the Second War, Orgrim Doomhammer himself raided Durnholde Keep to free the troll warlord Zul'jin from its cells.",
			full = "In the Second War, Orgrim Doomhammer himself raided Durnholde Keep to free the troll warlord Zul'jin from its cells. Afterward it became the command center of the orc internment camps, ruled by Lieutenant General Aedelas Blackmoore, a self-absorbed drunkard. Blackmoore found an orc infant among the bodies of his murdered parents, named him Thrall and raised him here as a slave and gladiator.\n\nThrall escaped, freed the orcs of the camps, and came back to lay siege to Durnholde. He killed Blackmoore in single combat and called on the spirit of the earth to level the fortress.\n\nThe keep lies in ruins now, east of Tarren Mill. It once held inner barracks, a mage tower and an arena. The Syndicate holds it as its base in the Foothills, and from here its outlaws steal horses and shipments from Southshore.",
			source = "https://warcraft.wiki.gg/wiki/Durnholde_Keep",
		},
		["eastern strand"] = {
			name = "Eastern Strand",
			short = "The Eastern Strand runs along the southeastern coast of the Hillsbrad Foothills, its counterpart lying further west along the same shore.",
			full = "The Eastern Strand runs along the southeastern coast of the Hillsbrad Foothills, its counterpart lying further west along the same shore. This stretch of sand belongs to the Daggerspine naga, who hold the beaches and the shallow water beyond them.",
			source = "https://warcraft.wiki.gg/wiki/Eastern_Strand",
		},
		["gallows corner"] = {
			name = "Gallows' Corner",
			short = "At Gallows' Corner, where the roads meet in the Alterac Mountains near the Ruins of Alterac, a scout tower stands broken and empty.",
			full = "At Gallows' Corner, where the roads meet in the Alterac Mountains near the Ruins of Alterac, a scout tower stands broken and empty. Crushridge ogres now hold the crossing, prowling the stones around the tower's remains, and nothing else stirs there.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_Corner",
		},
		["gavins naze"] = {
			name = "Gavin's Naze",
			short = "Mountain lions roam this hill, and the rare Araga is sometimes among them.",
			full = "Mountain lions roam this hill, and the rare Araga is sometimes among them.\n\nDwarven battleguards of the Stormpike Guard watch the tunnel here that leads into Alterac Valley, where their clan fights the Frostwolf orcs. Sergeant Durgen Stormpike keeps watch with them and has no kind word for the Frostwolves.",
			source = "https://warcraft.wiki.gg/wiki/Gavin's_Naze",
		},
		["growless cave"] = {
			name = "Growless Cave",
			short = "Deep in this cave in the Alterac Mountains stands the Flame of Uzel, an old ceremonial pyre. Mountain yetis shelter in the cave around it, and a yeti named Skhowl is often found just outside its mouth.",
			full = "Deep in this cave in the Alterac Mountains stands the Flame of Uzel, an old ceremonial pyre. Mountain yetis shelter in the cave around it, and a yeti named Skhowl is often found just outside its mouth.",
			source = "https://warcraft.wiki.gg/wiki/Growless_Cave",
		},
		["headland"] = {
			name = "The Headland",
			short = "A mountain lion with a slight mane and a striped tail rests on the cliffside of the Headland. She is Araga, and no other cat in the hills looks like her.",
			full = "A mountain lion with a slight mane and a striped tail rests on the cliffside of the Headland. She is Araga, and no other cat in the hills looks like her.\n\nDwarves of the Stormpike Guard keep a post here, close to the way into Alterac Valley, where their clan is at open war with the Frostwolf orcs. Lieutenant Haggerdin enlists recruits for the Guard.",
			source = "https://warcraft.wiki.gg/wiki/Headland",
		},
		["hillsbrad fields"] = {
			name = "Hillsbrad Fields",
			short = "Apple orchards and pumpkin patches cover the fields of Hillsbrad, with cattle grazing between them, and the harvest feeds all of Hillsbrad Foothills.",
			full = "Apple orchards and pumpkin patches cover the fields of Hillsbrad, with cattle grazing between them, and the harvest feeds all of Hillsbrad Foothills. Orgrim Doomhammer had the town destroyed in the Second War as a gruesome example, and the news spread through the human kingdoms. It was rebuilt after the war.\n\nHillsbrad and Southshore are the only parts of former Lordaeron the Third War did not leave completely devastated, and neither joined the Scarlet Crusade. Their guards still wear the tabard of Lordaeron. Magistrate Burnside governs from the town hall, aided by the Council of Hillsbrad and the clerk Horrace Whitesteed.\n\nThe Forsaken at Tarren Mill under High Executor Darthalia threaten the farms. The farmers answer with ambushes, armed by the blacksmith Verringtan and his apprentices.",
			source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Fields",
		},
		["misty shore"] = {
			name = "Misty Shore",
			short = "The Misty Shore runs along Lordamere Lake, between Dandred's Fold and Dalaran. Turtles move slowly through its shallows.",
			full = "The Misty Shore runs along Lordamere Lake, between Dandred's Fold and Dalaran. Turtles move slowly through its shallows.\n\nTwo humans allied with the Scarlet Crusade hold this shore, falling on any who come too near.\n\nAcross the water, the Dawning Isles can be seen, with the eerie Fenris Keep in the distance.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Shore",
		},
		["nethander stead"] = {
			name = "Nethander Stead",
			short = "Nethander Stead lies just east of Southshore, its fields abandoned and overrun by Mudsnout gnolls, the only place their tribe is found.",
			full = "Nethander Stead lies just east of Southshore, its fields abandoned and overrun by Mudsnout gnolls, the only place their tribe is found. Giant white mushrooms called Mudsnout Blossoms grow wild there.",
			source = "https://warcraft.wiki.gg/wiki/Nethander_Stead",
		},
		["purgation isle"] = {
			name = "Purgation Isle",
			short = "A towering spiral of rock rises from the water south of the Hillsbrad shore, with a cemetery on its top and the ruins of a scout tower.",
			full = "A towering spiral of rock rises from the water south of the Hillsbrad shore, with a cemetery on its top and the ruins of a scout tower. Before the First War the island belonged to Kul Tiras.\n\nDozens of condemned human and dwarf spirits haunt it, paladins and priests, monks and mages, who cannot find rest.",
			source = "https://warcraft.wiki.gg/wiki/Purgation_Isle",
		},
		["ravenholdt manor"] = {
			name = "Ravenholdt Manor",
			short = "Lord Jorach Ravenholdt leads his Assassin's League from this hidden manor in the Alterac Mountains. A narrow path climbs to it from a plateau, twisting through the mountains and a small cave.",
			full = "Lord Jorach Ravenholdt leads his Assassin's League from this hidden manor in the Alterac Mountains. A narrow path climbs to it from a plateau, twisting through the mountains and a small cave. The League takes in only those of extraordinary skill, and a stranger who leaves without a blade in the back or poison in the veins has done well.\n\nFor years the League has fought the Syndicate. Its agents steal Syndicate emblems, since a member who loses his emblem is dealt with by his own side.",
			source = "https://warcraft.wiki.gg/wiki/Ravenholdt_Manor",
		},
		["slaughter hollow"] = {
			name = "Slaughter Hollow",
			short = "The Crushridge ogres make their home in Slaughter Hollow, an ogre mound set deep in the Alterac Mountains.",
			full = "The Crushridge ogres make their home in Slaughter Hollow, an ogre mound set deep in the Alterac Mountains.\n\nA captured gnome, Rizz Loosebolt, is kept in a cage among them. He begs anyone who passes not to let the ogres eat him, and trades engineering supplies through the bars.",
			source = "https://warcraft.wiki.gg/wiki/Slaughter_Hollow",
		},
		["soferas naze"] = {
			name = "Sofera's Naze",
			short = "The Syndicate holds this hill above Hillsbrad. Its footpads and thieves camp here, and some of them have been at the Southshore stout.",
			full = "The Syndicate holds this hill above Hillsbrad. Its footpads and thieves camp here, and some of them have been at the Southshore stout.",
			source = "https://warcraft.wiki.gg/wiki/Sofera's_Naze",
		},
		["southpoint tower"] = {
			name = "Southpoint Tower",
			short = "The Forsaken Deathstalker Lesh keeps watch from this ruined scout tower at the far western edge of Hillsbrad Foothills, just south of the road to Silverpine Forest.",
			full = "The Forsaken Deathstalker Lesh keeps watch from this ruined scout tower at the far western edge of Hillsbrad Foothills, just south of the road to Silverpine Forest. She spies on the Alliance activity in the area.",
			source = "https://warcraft.wiki.gg/wiki/Southpoint_Tower",
		},
		["southshore"] = {
			name = "Southshore",
			short = "Southshore was a simple fishing village when the boats arrived, thousands of them, carrying the survivors of Stormwind after the Horde destroyed their kingdom in the First War.",
			full = "Southshore was a simple fishing village when the boats arrived, thousands of them, carrying the survivors of Stormwind after the Horde destroyed their kingdom in the First War. They settled near the village and swore loyalty to the new Alliance. In the Second War the town grew into a busy military port, its waters rich in the oil the Horde wanted. The Horde took it anyway, and Orgrim Doomhammer anchored his fleet in the harbor. The Alliance rebuilt Southshore after the war.\n\nAt the start of the Third War, Thrall's orcs crept into the town by night and stole its ships to sail for Kalimdor.\n\nNow Southshore is a quiet port, one of the few places left in Lordaeron where humans still hold to the Alliance. Survivors of the Third War have made their homes here, and some of them once served as knights of the Silver Hand or mages of the Kirin Tor. Its guards walk the streets, and the Forsaken of Tarren Mill live not far to the north.",
			source = "",
		},
		["strahnbrad"] = {
			name = "Strahnbrad",
			short = "Strahnbrad stands on the northeastern foothills of the Alterac Mountains, a ghost town with an abandoned town hall and blacksmith.",
			full = "Strahnbrad stands on the northeastern foothills of the Alterac Mountains, a ghost town with an abandoned town hall and blacksmith. It once belonged to the Kingdom of Alterac, and after the Second War it passed to Lordaeron.\n\nShortly before the Third War, Blackrock orcs raided it, taking slaves to sacrifice to the Burning Legion. Only a handful of footmen guarded the town, but it got word to the Knights of the Silver Hand. Uther the Lightbringer went after the orc camp, and Prince Arthas Menethil rode to hold the town. The raid had begun when he arrived and many villagers died, but Arthas and the surviving defenders routed the orcs and killed the Slave Master who led them.\n\nNow the Syndicate holds the town as its main base.",
			source = "https://warcraft.wiki.gg/wiki/Strahnbrad",
		},
		["tarren mill"] = {
			name = "Tarren Mill",
			short = "Early in the Second War, high elven archers from Silvermoon came south to see the orc threat. They were ambushed in the grasslands near Tarren Mill and taken to a nearby prison camp.",
			full = "Early in the Second War, high elven archers from Silvermoon came south to see the orc threat. They were ambushed in the grasslands near Tarren Mill and taken to a nearby prison camp. King Terenas sent Alliance soldiers, who freed them. The Council of Silvermoon then committed the armies of Quel'Thalas to the Alliance of Lordaeron.\n\nThe Forsaken hold the town now. A church, a few houses and withered orchards stand in disrepair. From here they make war on the Alliance towns of Southshore and Dun Garok. The ground between Tarren Mill and Southshore is infamous for constant battle.",
			source = "https://warcraft.wiki.gg/wiki/Tarren_Mill",
		},
		["thoradins wall"] = {
			name = "Thoradin's Wall",
			short = "Soon after the kingdom of Arathor was founded and Strom became its capital, King Thoradin ordered a great wall built to shield humanity from the Amani trolls.",
			full = "Soon after the kingdom of Arathor was founded and Strom became its capital, King Thoradin ordered a great wall built to shield humanity from the Amani trolls. It runs between Hillsbrad Foothills and the Arathi Highlands.\n\nAfter many centuries the wall is heavily damaged and in ruins.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["western strand"] = {
			name = "Western Strand",
			short = "The Western Strand lies on the southwest coast of Hillsbrad Foothills. Torn Fin murlocs have raised small camps along its shore, and Andy Murgole patrols the area.",
			full = "The Western Strand lies on the southwest coast of Hillsbrad Foothills. Torn Fin murlocs have raised small camps along its shore, and Andy Murgole patrols the area.",
			source = "https://warcraft.wiki.gg/wiki/Western_Strand",
		},
	},
	-- The Hinterlands: 21 subzones
	[1425] = {
		["aerie peak"] = {
			name = "Aerie Peak",
			short = "The Wildhammers went home to Grim Batol after the War of the Three Hammers and found the fortress tainted by the death of Modgud. They could not live there.",
			full = "The Wildhammers went home to Grim Batol after the War of the Three Hammers and found the fortress tainted by the death of Modgud. They could not live there. Having fought the Dark Iron dwarves in the tunnels, they would not burrow into stone again, and built Aerie Peak on the outside of a mountain instead.\n\nA great gryphon aviary crests its middle, and the Wildhammer keep stands at the far end.",
			source = "https://warcraft.wiki.gg/wiki/Aerie_Peak",
		},
		["agolwatha"] = {
			name = "Agol'watha",
			short = "Agol'watha was raised as a temple of the Amani Empire, and the empire is gone. Green sludges and jade oozes have overrun it, crawling through its ruined courts.",
			full = "Agol'watha was raised as a temple of the Amani Empire, and the empire is gone. Green sludges and jade oozes have overrun it, crawling through its ruined courts.",
			source = "https://warcraft.wiki.gg/wiki/Agol'watha",
		},
		["altar of zul"] = {
			name = "The Altar of Zul",
			short = "The Vilebranch forest trolls keep an altar here. It is one of the ancient bastions of the Amani, and the Vilebranch, strongest of the three troll tribes of the Hinterlands, hold it along with Jintha'Alor.",
			full = "The Vilebranch forest trolls keep an altar here. It is one of the ancient bastions of the Amani, and the Vilebranch, strongest of the three troll tribes of the Hinterlands, hold it along with Jintha'Alor. Qiaga the Keeper stands at its top.",
			source = "https://warcraft.wiki.gg/wiki/Altar_of_Zul",
		},
		["bogens ledge"] = {
			name = "Bogen's Ledge",
			short = "Bogen's Ledge is a cave in the southwestern Hinterlands. Vicious owlbeasts prowl around it.",
			full = "Bogen's Ledge is a cave in the southwestern Hinterlands. Vicious owlbeasts prowl around it.",
			source = "https://warcraft.wiki.gg/wiki/Bogen's_Ledge",
		},
		["creeping ruin"] = {
			name = "The Creeping Ruin",
			short = "Forest trolls built the Creeping Ruin, and hostile slimes have overrun what they left. They creep through the broken stone.",
			full = "Forest trolls built the Creeping Ruin, and hostile slimes have overrun what they left. They creep through the broken stone.",
			source = "https://warcraft.wiki.gg/wiki/Creeping_Ruin",
		},
		["featherbeards hovel"] = {
			name = "Featherbeard's Hovel",
			short = "A small house stands next to Aerie Peak, the home of Featherbeard.",
			full = "A small house stands next to Aerie Peak, the home of Featherbeard.",
			source = "https://warcraft.wiki.gg/wiki/Featherbeard's_Hovel",
		},
		["hiriwatha"] = {
			name = "Hiri'watha",
			short = "Witherbark forest trolls live among the old ruins of Hiri'watha, south of Quel'Danil Lodge. When emissaries of the Horde came to the Hinterlands, the Witherbark refused them outright.",
			full = "Witherbark forest trolls live among the old ruins of Hiri'watha, south of Quel'Danil Lodge. When emissaries of the Horde came to the Hinterlands, the Witherbark refused them outright. Zul'arek Hatefowler, a Witherbark troll, is sometimes seen there.",
			source = "https://warcraft.wiki.gg/wiki/Hiri'watha",
		},
		["jinthaalor"] = {
			name = "Jintha'Alor",
			short = "Trolls of the Amani Empire raised Jintha'Alor and named it for Jintha, one of their ancient leaders. Among forest troll cities only Zul'Aman is larger.",
			full = "Trolls of the Amani Empire raised Jintha'Alor and named it for Jintha, one of their ancient leaders. Among forest troll cities only Zul'Aman is larger. The Vilebranch hold it now and use its tiers as a fortress for sacrifice.\n\nVile Priestess Hexx rules here in the name of Hakkar the Soulflayer. The Vilebranch prey on the weaker Revantusk to feed him. Elder Torntusk was taken in one raid and is held in the city still, and his guard captain, Huntsman Malkhor, was killed, his remains thrown to the wolves and oozes within the walls.",
			source = "https://warcraft.wiki.gg/wiki/Jintha'Alor",
		},
		["martsirt"] = {
			pending = true,
			name = "Martsirt",
			short = "",
			full = "",
			source = "",
		},
		["overlook cliffs"] = {
			name = "The Overlook Cliffs",
			short = "The great river that runs through the Hinterlands ends at the Overlook Cliffs, pouring over the edge in one massive waterfall where the mountains give way to the eastern shoreline.",
			full = "The great river that runs through the Hinterlands ends at the Overlook Cliffs, pouring over the edge in one massive waterfall where the mountains give way to the eastern shoreline. The cliffs are steep and deceptively high, and many travelers have misjudged the drop and fallen to their deaths.",
			source = "https://warcraft.wiki.gg/wiki/Overlook_Cliffs",
		},
		["plaguemist ravine"] = {
			name = "Plaguemist Ravine",
			short = "A mist hangs over Plaguemist Ravine, a narrow pathway that runs north through the mountains toward Caer Darrow in the Western Plaguelands.",
			full = "A mist hangs over Plaguemist Ravine, a narrow pathway that runs north through the mountains toward Caer Darrow in the Western Plaguelands. The entrance lies in the woods west of Quel'Danil Lodge. The ravine takes its name from the sickly mist that fouls this one path and stands in sharp contrast to the clean freshness of the rest of the Hinterlands. No one lives in it.",
			source = "https://warcraft.wiki.gg/wiki/Plaguemist_Ravine",
		},
		["queldanil lodge"] = {
			name = "Quel'Danil Lodge",
			short = "The Highvale elves keep this lodge as their base near Aerie Peak. It is the larger of the two great gatherings of high elves left in Lordaeron, and one of the last high elven settlements.",
			full = "The Highvale elves keep this lodge as their base near Aerie Peak. It is the larger of the two great gatherings of high elves left in Lordaeron, and one of the last high elven settlements.\n\nAfter the Third War the lodge became a center of communication. Highvale ambassadors reached out to the other peoples of the Alliance and shared what they knew of the Witherbark trolls. The elves later allied with the Wildhammer dwarves, which angered the Revantusk trolls.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Danil_Lodge",
		},
		["revantusk village"] = {
			name = "Revantusk Village",
			short = "When the Second War broke the Old Horde, many forest trolls deserted their orc allies without a moment's hesitation. The Revantusk kept some loyalty to the Horde.",
			full = "When the Second War broke the Old Horde, many forest trolls deserted their orc allies without a moment's hesitation. The Revantusk kept some loyalty to the Horde. They were too few to free the captive orcs, who in any case seemed uninterested in freedom, and other forest trolls attacked them for it. The tribe moved to the coast of the Hinterlands, hoping to avoid notice, and built this village.\n\nIn time they learned that Thrall had gathered a new Horde and led his people back to their shamanistic traditions. They sent their fastest runners to him, and the two made a pact of friendship. Other forest trolls call the Revantusk weaklings and enemies, and the Revantusk call them traitors to the new Horde.",
			source = "https://warcraft.wiki.gg/wiki/Revantusk_Village",
		},
		["seradane"] = {
			name = "Seradane",
			short = "A great circular portal stands in the northeastern Hinterlands, one of four entrances to the Emerald Dream. Green dragons made this forest their home, among them the drakes Rothos and Dreamtracker.",
			full = "A great circular portal stands in the northeastern Hinterlands, one of four entrances to the Emerald Dream. Green dragons made this forest their home, among them the drakes Rothos and Dreamtracker.\n\nGreen dragonspawn keep most of the woods. A Verdantine Oracle leads each group, with Verdantine Boughguards and Tree Warders beside it. The skull of an unknown dragon rests on a hill north of the portal.",
			source = "https://warcraft.wiki.gg/wiki/Seradane",
		},
		["shadraalor"] = {
			name = "Shadra'Alor",
			short = "The Witherbark tribe keeps its main settlement at Shadra'Alor, among old temples that the forest trolls of the Amani Empire raised. The Witherbark worship the loa Shadra here.",
			full = "The Witherbark tribe keeps its main settlement at Shadra'Alor, among old temples that the forest trolls of the Amani Empire raised. The Witherbark worship the loa Shadra here.",
			source = "https://warcraft.wiki.gg/wiki/Shadra'Alor",
		},
		["shaolwatha"] = {
			name = "Shaol'watha",
			short = "Little remains of Shaol'watha, an old forest troll temple in the northeastern Hinterlands.",
			full = "Little remains of Shaol'watha, an old forest troll temple in the northeastern Hinterlands.",
			source = "https://warcraft.wiki.gg/wiki/Shaol'watha",
		},
		["shindiggers camp"] = {
			name = "Shindigger's Camp",
			short = "Rhapsody Shindigger, a dwarf fond of drink, keeps his small camp in the Hinterlands alongside the high elf Gilveradin Sunchaser, an odd pairing.",
			full = "Rhapsody Shindigger, a dwarf fond of drink, keeps his small camp in the Hinterlands alongside the high elf Gilveradin Sunchaser, an odd pairing.",
			source = "https://warcraft.wiki.gg/wiki/Shindigger's_Camp",
		},
		["skulk rock"] = {
			name = "Skulk Rock",
			short = "During the Second War the Old Horde made a base in this forest troll ruin, until the Alliance of Lordaeron drove them out.",
			full = "During the Second War the Old Horde made a base in this forest troll ruin, until the Alliance of Lordaeron drove them out.\n\nSlimes have overrun the ruin since. A cave here is one of the few places where Ghost Mushrooms still grow.",
			source = "https://warcraft.wiki.gg/wiki/Skulk_Rock",
		},
		["valorwind lake"] = {
			name = "Valorwind Lake",
			short = "Northeast of Shadra'Alor lies Valorwind Lake, a small and quiet body of water. Its waters seem unremarkable, yet it is the only known place where the Violet Tragan, a mysterious mushroom, grows.",
			full = "Northeast of Shadra'Alor lies Valorwind Lake, a small and quiet body of water. Its waters seem unremarkable, yet it is the only known place where the Violet Tragan, a mysterious mushroom, grows.",
			source = "https://warcraft.wiki.gg/wiki/Valorwind_Lake",
		},
		["wildhammer keep"] = {
			name = "Wildhammer Keep",
			short = "At one end of Aerie Peak, opposite the great gryphon aviary, stands the keep of the Wildhammer dwarves. Falstad Wildhammer, their High Thane, rules from the top of the peak.",
			full = "At one end of Aerie Peak, opposite the great gryphon aviary, stands the keep of the Wildhammer dwarves. Falstad Wildhammer, their High Thane, rules from the top of the peak.\n\nMost dwarves cut their halls into the mountain. The Wildhammers build in the open air, a habit they took from the horror of the underground battles they fought against the Dark Iron dwarves.",
			source = "https://warcraft.wiki.gg/wiki/Wildhammer_Keep",
		},
		["zunwatha"] = {
			name = "Zun'watha",
			short = "Among the old ruins of Zun'watha the Witherbark trolls have settled. Scalpers and zealots of the tribe keep watch among the stones.",
			full = "Among the old ruins of Zun'watha the Witherbark trolls have settled. Scalpers and zealots of the tribe keep watch among the stones.",
			source = "https://warcraft.wiki.gg/wiki/Zun'watha",
		},
	},
	-- Dun Morogh: 25 subzones
	[1426] = {
		["amberstill ranch"] = {
			name = "Amberstill Ranch",
			short = "The Amberstill dwarves keep mountain rams, the kind dwarves ride, at their ranch off the road to Loch Modan, north of Gol'Bolar Quarry.",
			full = "The Amberstill dwarves keep mountain rams, the kind dwarves ride, at their ranch off the road to Loch Modan, north of Gol'Bolar Quarry. Young Yarlyn Amberstill looks after a pen of snowshoe rabbits. A wendigo named Vagash stalks the herd, and Rudra Amberstill wants it driven off.",
			source = "https://warcraft.wiki.gg/wiki/Amberstill_Ranch",
		},
		["anvilmar"] = {
			name = "Anvilmar",
			short = "In Coldridge Valley stands Anvilmar, the first town of any size in the north of the valley. A hall built around a great forge is at its center.",
			full = "In Coldridge Valley stands Anvilmar, the first town of any size in the north of the valley. A hall built around a great forge is at its center.",
			source = "https://warcraft.wiki.gg/wiki/Anvilmar",
		},
		["brewnall village"] = {
			name = "Brewnall Village",
			short = "The Barleybrew family has made its home in Brewnall Village, in Chill Breeze Valley near Gnomeregan.",
			full = "The Barleybrew family has made its home in Brewnall Village, in Chill Breeze Valley near Gnomeregan. Rejold Barleybrew leads their search for the best recipe for ale, and the family works to improve the old dwarven art of brewing. They send their young out to guard the village from wild animals and to hunt for rare ingredients for the ultimate ale.\n\nThe village is more a camp than a settlement. It answers to Ironforge, though it sits in gnomish country.",
			source = "https://warcraft.wiki.gg/wiki/Brewnall_Village",
		},
		["chill breeze valley"] = {
			name = "Chill Breeze Valley",
			short = "Blood shows on the snow in the north and south arms of Chill Breeze Valley. Large stains spread across the white, and torn animal carcasses lie where they were dropped.",
			full = "Blood shows on the snow in the north and south arms of Chill Breeze Valley. Large stains spread across the white, and torn animal carcasses lie where they were dropped. Few people walk these branches. Hunters go after the beasts responsible, hoping to end their threat to the dwarven lands, and many do not come back. A dangerous wendigo lairs in one of the caves.\n\nThe east and west arm is easier going. It runs between Gnomeregan and Kharanos, and young dwarves and gnomes pass along it often.",
			source = "https://warcraft.wiki.gg/wiki/Chill_Breeze_Valley",
		},
		["coldridge pass"] = {
			name = "Coldridge Pass",
			short = "Troggs have overrun Coldridge Pass, the tunnel that joins Coldridge Valley to the rest of Dun Morogh.",
			full = "Troggs have overrun Coldridge Pass, the tunnel that joins Coldridge Valley to the rest of Dun Morogh. Dwarven recruits come through in a trickle on their way to the frontier town of Kharanos, and they must cut a path through the troggs or run past them.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Pass",
		},
		["coldridge valley"] = {
			name = "Coldridge Valley",
			short = "Cut off in the southwestern corner of Dun Morogh, Coldridge Valley lies under thick snow. Its only way out is the tunnel of Coldridge Pass to the northeast.",
			full = "Cut off in the southwestern corner of Dun Morogh, Coldridge Valley lies under thick snow. Its only way out is the tunnel of Coldridge Pass to the northeast. Dwarven mountaineers keep guard here, though troggs and Frostmane trolls trouble the valley.\n\nThe troggs have turned up all over the hills to the southeast and around the frozen lake, and the trolls keep mostly to a cave in the south.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Valley",
		},
		["frostmane hold"] = {
			name = "Frostmane Hold",
			short = "Frostmane Hold stands on the western edge of Dun Morogh's cold mountains, south of Gnomeregan, a scatter of buildings knit to a cave system driven into the mountainside.",
			full = "Frostmane Hold stands on the western edge of Dun Morogh's cold mountains, south of Gnomeregan, a scatter of buildings knit to a cave system driven into the mountainside. It is the base camp of the Frostmane ice trolls, who hold the ground with headhunters and hideskinners guarding every approach.",
			source = "https://warcraft.wiki.gg/wiki/Frostmane_Hold",
		},
		["gates of ironforge"] = {
			name = "Gates of Ironforge",
			short = "The Gates of Ironforge are a grand sight, visible from far across Dun Morogh. They stand at the head of the great ramp that climbs north to the mountain, and they open into Ironforge itself.",
			full = "The Gates of Ironforge are a grand sight, visible from far across Dun Morogh. They stand at the head of the great ramp that climbs north to the mountain, and they open into Ironforge itself. Just inside, a huge statue of High King Modimus Anvilmar stands guard.\n\nHe was the last king of the united dwarves, a ruler of justice and wisdom, known for his diplomacy with the three great dwarven clans. When he died of old age, before his eldest son could be crowned, those clans went to war with one another.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
		["gnomeregan"] = {
			name = "Gnomeregan",
			short = "The gnomes built Gnomeregan underground, in the foothills of Dun Morogh, and filled it with iron and invention. During the Third War, mutant troggs infested the city.",
			full = "The gnomes built Gnomeregan underground, in the foothills of Dun Morogh, and filled it with iron and invention. During the Third War, mutant troggs infested the city. In a desperate attempt to destroy them, High Tinker Gelbin Mekkatorque ordered the waste tanks vented and filled the halls with radiation. The gnomes sheltered from the fumes and waited for the troggs to die or flee. The troggs sickened, but they kept coming. Nearly four in five gnomes died within days, and the survivors fled to Ironforge. Others were twisted into leper gnomes, mindless and cruel.\n\nSicco Thermaplugg, once Mekkatorque's trusted advisor, was driven mad by the poison. He now rules the ruined halls as a techno-overlord over troggs and leper gnomes.",
			source = "https://warcraft.wiki.gg/wiki/Gnomeregan",
		},
		["golbolar quarry"] = {
			name = "Gol'Bolar Quarry",
			short = "In the southeast of Dun Morogh, dwarves keep a small mining camp beside Gol'Bolar Quarry, a large dig site. Troggs have overrun the excavation and the mine below, and the miners hold only the camp.",
			full = "In the southeast of Dun Morogh, dwarves keep a small mining camp beside Gol'Bolar Quarry, a large dig site. Troggs have overrun the excavation and the mine below, and the miners hold only the camp.",
			source = "https://warcraft.wiki.gg/wiki/Gol'Bolar_Quarry",
		},
		["grizzled den"] = {
			name = "The Grizzled Den",
			short = "The wendigos of the Grizzled Den do not scatter when strangers come. They flock together, breathe frost, and drive intruders back out of this large cave system just southwest of Kharanos.",
			full = "The wendigos of the Grizzled Den do not scatter when strangers come. They flock together, breathe frost, and drive intruders back out of this large cave system just southwest of Kharanos. Hunters go in after their manes, which are prized for seat covers. Copper veins run through the rock, and a tougher wendigo lairs at the back.",
			source = "https://warcraft.wiki.gg/wiki/Grizzled_Den",
		},
		["helms bed lake"] = {
			name = "Helm's Bed Lake",
			short = "Ice covers most of Helm's Bed Lake, but one hole is kept open so that fresh water can be drawn. The ice is safe to cross. The shore is not, because wild animals and stray troggs roam around it.",
			full = "Ice covers most of Helm's Bed Lake, but one hole is kept open so that fresh water can be drawn. The ice is safe to cross. The shore is not, because wild animals and stray troggs roam around it.\n\nSouth of the lake, Dark Iron dwarves have taken an abandoned building, and they strike at anyone who comes too near.",
			source = "https://warcraft.wiki.gg/wiki/Helm's_Bed_Lake",
		},
		["iceflow lake"] = {
			name = "Iceflow Lake",
			short = "Iceflow Lake freezes hard in the cold of Dun Morogh, but the dwarves of Brewnall Village keep one hole cut through the ice, drawing fresh water and fish from beneath the frozen surface.",
			full = "Iceflow Lake freezes hard in the cold of Dun Morogh, but the dwarves of Brewnall Village keep one hole cut through the ice, drawing fresh water and fish from beneath the frozen surface.\n\nOut toward the lake's center rise a pair of islands, best left alone. A pack of ravenous wolves has claimed them, running under a worg named Timber, and their presence keeps the islands empty of all but the beasts that hold them.",
			source = "https://warcraft.wiki.gg/wiki/Iceflow_Lake",
		},
		["ironbands compound"] = {
			name = "Ironband's Compound",
			short = "South of Helm's Bed Lake, Ironband's Compound stands as a foothold for Dark Iron dwarves, who strike at anyone who strays too near.",
			full = "South of Helm's Bed Lake, Ironband's Compound stands as a foothold for Dark Iron dwarves, who strike at anyone who strays too near. It once belonged to Sturgy Ironband, a master blacksmith who taught his craft there, until a band of Dark Irons attacked it and killed everyone inside.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Compound",
		},
		["ironforge submarine facility"] = {
			pending = true,
			name = "Ironforge Submarine Facility",
			short = "",
			full = "",
			source = "",
		},
		["kharanos"] = {
			name = "Kharanos",
			short = "Kharanos sits among the mountain peaks of Dun Morogh, a bustling little town ringed by wintry wilds.",
			full = "Kharanos sits among the mountain peaks of Dun Morogh, a bustling little town ringed by wintry wilds. A large forge burns here, a gnomish workshop clatters away, and the Thunderbrew Distillery pours some of the best ale in the world. Behind the charm, Kharanos is a hub of military activity, defending against every threat the wilds send.\n\nA large cavern full of fierce wendigo lies directly to the west. To the northwest, Frostmane trolls have rooted themselves on top of Shimmer Ridge, watching the town below, and Senir Whitebeard is set on driving them out.",
			source = "https://warcraft.wiki.gg/wiki/Kharanos",
		},
		["misty pine refuge"] = {
			name = "Misty Pine Refuge",
			short = "Misty Pine Refuge is a small outpost of the Argent Dawn in central Dun Morogh. Father Gavin is the only agent of the order stationed there.",
			full = "Misty Pine Refuge is a small outpost of the Argent Dawn in central Dun Morogh. Father Gavin is the only agent of the order stationed there.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Pine_Refuge",
		},
		["north gate outpost"] = {
			name = "North Gate Outpost",
			short = "The northeasternmost settlement the dwarves have built in Dun Morogh stands in the middle of North Gate Pass, which links Dun Morogh to Loch Modan.",
			full = "The northeasternmost settlement the dwarves have built in Dun Morogh stands in the middle of North Gate Pass, which links Dun Morogh to Loch Modan. Mountaineers are stationed here, and they are kept busy driving off the wildlife that presses in from the mountains. Some of them went hunting the fiercer beasts and have gone missing.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Outpost",
		},
		["north gate pass"] = {
			name = "North Gate Pass",
			short = "North Gate Pass carries the road from the high mountains of Dun Morogh down to the lower mountains of Loch Modan. Travelers heading to or from the Wetlands use it most, since it lies closest to the descent from the loch.",
			full = "North Gate Pass carries the road from the high mountains of Dun Morogh down to the lower mountains of Loch Modan. Travelers heading to or from the Wetlands use it most, since it lies closest to the descent from the loch. The guard station of North Gate Outpost stands here.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["shimmer ridge"] = {
			name = "Shimmer Ridge",
			short = "Frostmane trolls hold the high ground of Shimmer Ridge, west of the Gates of Ironforge. They live in two camps joined by a bridge, and they tame boars and grow shimmerweed.",
			full = "Frostmane trolls hold the high ground of Shimmer Ridge, west of the Gates of Ironforge. They live in two camps joined by a bridge, and they tame boars and grow shimmerweed. The dwarves use the weed in their beer, but it is the trolls who tend it.",
			source = "https://warcraft.wiki.gg/wiki/Shimmer_Ridge",
		},
		["south gate outpost"] = {
			name = "South Gate Outpost",
			short = "Dwarves keep South Gate Outpost in the middle of the pass that leads down into Loch Modan, with snow on the ground around it.",
			full = "Dwarves keep South Gate Outpost in the middle of the pass that leads down into Loch Modan, with snow on the ground around it. The mountaineers stationed here have cleared out most of the wildlife that pressed in on them, so they face less trouble than most garrisons in these mountains. Many travelers pass through on their way to or from Thelsamar.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Outpost",
		},
		["south gate pass"] = {
			name = "South Gate Pass",
			short = "Travelers bound for Thelsamar take South Gate Pass, which joins the high mountains of Dun Morogh to the lower mountains of Loch Modan.",
			full = "Travelers bound for Thelsamar take South Gate Pass, which joins the high mountains of Dun Morogh to the lower mountains of Loch Modan. It is the pass closest to the dwarven town. The guard station of South Gate Outpost stands here.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["steelgrills depot"] = {
			name = "Steelgrill's Depot",
			short = "Steelgrill's Depot sits east of Kharanos, a small camp of miners and engineers working the frozen ground of Dun Morogh.",
			full = "Steelgrill's Depot sits east of Kharanos, a small camp of miners and engineers working the frozen ground of Dun Morogh. It belongs to Beldin Steelgrill, and pilots of the Siege Brigade wait here while he works on their siege engines.",
			source = "https://warcraft.wiki.gg/wiki/Steelgrill's_Depot",
		},
		["thunderbrew distillery"] = {
			name = "Thunderbrew Distillery",
			short = "The ale of the Thunderbrew Distillery is known far and wide. The dwarven tavern in Kharanos was founded, so Ragnar Thunderbrew says, by his father, Arkilus Thunderbrew.",
			full = "The ale of the Thunderbrew Distillery is known far and wide. The dwarven tavern in Kharanos was founded, so Ragnar Thunderbrew says, by his father, Arkilus Thunderbrew. Ragnar has run it since his older brother Grimbooze disappeared. Innkeeper Belm keeps the inn.",
			source = "https://warcraft.wiki.gg/wiki/Thunderbrew_Distillery",
		},
		["tundrid hills"] = {
			name = "The Tundrid Hills",
			short = "Few travelers cross the Tundrid Hills without a weapon in hand. Several kinds of hostile wildlife roam these hills in the south of central Dun Morogh, west of Gol'Bolar Quarry.",
			full = "Few travelers cross the Tundrid Hills without a weapon in hand. Several kinds of hostile wildlife roam these hills in the south of central Dun Morogh, west of Gol'Bolar Quarry. A few still take them as a shortcut between Coldridge Valley and eastern Dun Morogh, though the road through Kharanos is far safer.",
			source = "https://warcraft.wiki.gg/wiki/Tundrid_Hills",
		},
	},
	-- Searing Gorge: 11 subzones
	[1427] = {
		["blackchar cave"] = {
			name = "Blackchar Cave",
			short = "Blackchar Cave, in the southwest of the gorge near Blackrock Mountain, is sealed off. What it holds is a mystery.",
			full = "Blackchar Cave, in the southwest of the gorge near Blackrock Mountain, is sealed off. What it holds is a mystery.",
			source = "https://warcraft.wiki.gg/wiki/Blackchar_Cave",
		},
		["blackrock mountain"] = {
			name = "Blackrock Mountain",
			short = "The Bronzebeard and Wildhammer armies were marching to purge the Dark Iron clan when the ridge burst upward into Blackrock Mountain.",
			full = "The Bronzebeard and Wildhammer armies were marching to purge the Dark Iron clan when the ridge burst upward into Blackrock Mountain. King Madoran and King Khardros turned their armies back rather than face the Firelord who had come with it. Where the Dark Iron kingdom had stood, a volcano rose, and Ragnaros withdrew into its core and set the surviving dwarves to carve a new city beneath it.\n\nTwo powers share the mountain now. Ragnaros rules from the molten core with his Dark Iron dwarves, golems and elementals. Nefarian watches from Blackwing Lair above, with the Dark Horde of Blackrock orcs at his command. Each means to raise an army and take Azeroth.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["cauldron"] = {
			name = "The Cauldron",
			short = "The Dark Irons dug the Cauldron into the middle of the gorge, a vast excavation rimmed by their great digging machines, and they fortified it after Ragnaros was summoned.",
			full = "The Dark Irons dug the Cauldron into the middle of the gorge, a vast excavation rimmed by their great digging machines, and they fortified it after Ragnaros was summoned. Fire and magma elementals move through the glowing crevices below. Slaves, mostly captured enemies, labor there without rest. The work, the heat and their masters have driven them mad, and they attack anyone who interferes, even those who come to free them.",
			source = "https://warcraft.wiki.gg/wiki/Cauldron",
		},
		["dustfire valley"] = {
			name = "Dustfire Valley",
			short = "Wind sweeps Dustfire Valley as it runs north through the gorge. At its end stand the gates of Stonewrought Pass, and beyond them lies the Valley of Kings in Loch Modan.",
			full = "Wind sweeps Dustfire Valley as it runs north through the gorge. At its end stand the gates of Stonewrought Pass, and beyond them lies the Valley of Kings in Loch Modan.",
			source = "https://warcraft.wiki.gg/wiki/Dustfire_Valley",
		},
		["firewatch ridge"] = {
			name = "Firewatch Ridge",
			short = "Firewatch Ridge is the main camp of the Dark Iron dwarves in Searing Gorge, overlooking the great excavation of the Cauldron.",
			full = "Firewatch Ridge is the main camp of the Dark Iron dwarves in Searing Gorge, overlooking the great excavation of the Cauldron. Dark Iron dwarves hold the slopes with mechanical golems and giant flame spiders, making the ridge a dangerous place to tread.",
			source = "https://warcraft.wiki.gg/wiki/Firewatch_Ridge",
		},
		["grimesilt dig site"] = {
			name = "Grimesilt Dig Site",
			short = "Dwarves from Ironforge once dug at the Grimesilt Dig Site. The Dark Iron dwarves took it over and hold it still. Dorius Stonetender, one of the original workers, lies injured at the bottom of the pit.",
			full = "Dwarves from Ironforge once dug at the Grimesilt Dig Site. The Dark Iron dwarves took it over and hold it still. Dorius Stonetender, one of the original workers, lies injured at the bottom of the pit.",
			source = "https://warcraft.wiki.gg/wiki/Grimesilt_Dig_Site",
		},
		["sea of cinders"] = {
			name = "The Sea of Cinders",
			short = "The Sea of Cinders lies flat and open in the southern reaches of Searing Gorge, just north of Blackrock Mountain. Nothing grows there.",
			full = "The Sea of Cinders lies flat and open in the southern reaches of Searing Gorge, just north of Blackrock Mountain. Nothing grows there. The ground still smolders, and ash rises constantly on the wind, drifting across the barren flats. Fire and wind left nothing behind but waste, and the burning has never stopped.",
			source = "https://warcraft.wiki.gg/wiki/Sea_of_Cinders",
		},
		["slag pit"] = {
			name = "The Slag Pit",
			short = "Deep inside the Cauldron lies the Slag Pit, an underground mine rich in ore. Cruel Dark Iron dwarves run it, and slave laborers do the digging while slavers and taskmasters drive them on.",
			full = "Deep inside the Cauldron lies the Slag Pit, an underground mine rich in ore. Cruel Dark Iron dwarves run it, and slave laborers do the digging while slavers and taskmasters drive them on. The Dark Irons answer anyone who interferes with their mining with open hostility, and ravenous incendosaurs prowl the depths.",
			source = "https://warcraft.wiki.gg/wiki/Slag_Pit",
		},
		["stonewrought pass"] = {
			name = "Stonewrought Pass",
			short = "Franclorn Forgewright, the Dark Iron architect who also oversaw the Stonewrought Dam, designed this tunnel through the mountains. It runs northeast from the head of Dustfire Valley to the Valley of Kings in Loch Modan.",
			full = "Franclorn Forgewright, the Dark Iron architect who also oversaw the Stonewrought Dam, designed this tunnel through the mountains. It runs northeast from the head of Dustfire Valley to the Valley of Kings in Loch Modan.\n\nWhen the Dark Irons overran the dwarven garrisons in the gorge, the dwarves fell back to Loch Modan and sealed the pass. Its gates are still locked, and Mountaineer Pebblebitty guards the one on the Loch Modan side, turning travelers away.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Pass",
		},
		["tanner camp"] = {
			name = "Tanner Camp",
			short = "Sarah Tanner, a master of elemental leatherworking, keeps a lone tent in this small camp. Behind it a long passage winds off to the lair of a great thunder lizard.",
			full = "Sarah Tanner, a master of elemental leatherworking, keeps a lone tent in this small camp. Behind it a long passage winds off to the lair of a great thunder lizard. Glassweb spiders and fire beetles crawl about the camp, and a lava spider called Rekk'tilac hunts among them.",
			source = "https://warcraft.wiki.gg/wiki/Tanner_Camp",
		},
		["thorium point"] = {
			name = "Thorium Point",
			short = "Overseer Oilfist leads the Thorium Brotherhood, Dark Iron dwarves who left their clan.",
			full = "Overseer Oilfist leads the Thorium Brotherhood, Dark Iron dwarves who left their clan. They built Thorium Point on the cliffs in the far north of the gorge, above the Cauldron, and from there they keep a close eye on what their former kin are doing. The town is neutral, with a forge and anvil ready for work. The Brotherhood's smiths are said to be among the finest Azeroth has seen, and rumor says they know how to make the arms of Ragnaros himself but lack the hands to gather what the work needs.",
			source = "https://warcraft.wiki.gg/wiki/Thorium_Point",
		},
	},
	-- Burning Steppes: 13 subzones
	[1428] = {
		["altar of storms"] = {
			name = "Altar of Storms",
			short = "In the Second War the altars of storms were carved from the runestone at Caer Darrow and crowned with bronze figures.",
			full = "In the Second War the altars of storms were carved from the runestone at Caer Darrow and crowned with bronze figures. Dark and arcane power ran through those figures and twisted the stone's elven magic, and on the altars the ogre magi were given their spells. Even the rest of the Horde kept away from the cold stone. The elves knew their sacred runestone had been defiled, and they swore to destroy every altar in the Eastern Kingdoms.\n\nOnly a few altars remain. This one lies in the shadow of Blackrock Mountain, where the Blackrock clan still holds its rituals, and Blackrock warlocks keep it.",
			source = "",
		},
		["blackrock mountain"] = {
			name = "Blackrock Mountain",
			short = "Blackrock Mountain bore its name centuries before the Blackrock orcs came to it. It rose out of the ruined Dark Iron kingdom when Ragnaros broke into the world.",
			full = "Blackrock Mountain bore its name centuries before the Blackrock orcs came to it. It rose out of the ruined Dark Iron kingdom when Ragnaros broke into the world. The Bronzebeard and Wildhammer armies had marched to purge the Dark Irons. Their kings, Madoran and Khardros, watched firestorms swallow the land and turned the armies back toward their kingdoms. Ragnaros withdrew into the blistering heart of the mountain and set the surviving Dark Irons to carve a fortress beneath it, Shadowforge City.\n\nIn the Second War the Horde took Blackrock Spire, the fortress in the mountain, and made it the base for its campaign against Lordaeron. Now Ragnaros and Nefarian fight over the whole mountain. The Firelord rules from the volcano's core with his Dark Irons and his elementals. Nefarian holds the heights with the Blackrock orcs and his black dragons.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["blackrock pass"] = {
			name = "Blackrock Pass",
			short = "Blackrock Pass is the threshold between two worlds. On one side lie the quiet green hills of the Redridge Mountains. On the other, the Burning Steppes wait, scorched and twisted beyond recognition.",
			full = "Blackrock Pass is the threshold between two worlds. On one side lie the quiet green hills of the Redridge Mountains. On the other, the Burning Steppes wait, scorched and twisted beyond recognition. A gate stands at the border and marks the line plainly. It is the main way into the Steppes from the south.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Pass",
		},
		["blackrock stronghold"] = {
			name = "Blackrock Stronghold",
			short = "Hard under the shadow of Blackrock Spire, a fortress of black stone, the Blackrock clan holds a massive stronghold in the north of the Burning Steppes.",
			full = "Hard under the shadow of Blackrock Spire, a fortress of black stone, the Blackrock clan holds a massive stronghold in the north of the Burning Steppes. These orcs keep out of sight of the road and always watch for an Alliance attack. They follow the old brutal ways of the First and Second Wars and mine the mountains around the Spire for the metal in their weapons and armor.\n\nBattlemasters, slayers, sorcerers and warlocks of the clan hold the stronghold, and sentries of the Scarshield Legion stand guard among them.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Stronghold",
		},
		["dracodar"] = {
			name = "Draco'dar",
			short = "Scorched hills fill the southwest of the Burning Steppes, blackened and given over to the black dragonflight. Its minions crawl across the ground in numbers.",
			full = "Scorched hills fill the southwest of the Burning Steppes, blackened and given over to the black dragonflight. Its minions crawl across the ground in numbers.",
			source = "https://warcraft.wiki.gg/wiki/Draco'dar",
		},
		["dreadmaul rock"] = {
			name = "Dreadmaul Rock",
			short = "The Firegut ogres make Dreadmaul Rock, also called Dreadmaul Peak, their base. Paths lead to the top of the rock, and a complicated cave system of ogre mounds runs within it.",
			full = "The Firegut ogres make Dreadmaul Rock, also called Dreadmaul Peak, their base. Paths lead to the top of the rock, and a complicated cave system of ogre mounds runs within it.\n\nThe Fireguts are castoffs of the Second War. Some study arcane magic, though their huge bodies still make them better fighters than casters. They mean to claim the Burning Steppes for ogres alone, and the Alliance, the Blackrock orcs, the Dark Iron dwarves and the black dragons will not let them.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Rock",
		},
		["flame crest"] = {
			name = "Flame Crest",
			short = "Only a crude bridge leads onto the bare outcropping of rock where Flame Crest stands. The outpost belongs to neither the Horde nor the Alliance.",
			full = "Only a crude bridge leads onto the bare outcropping of rock where Flame Crest stands. The outpost belongs to neither the Horde nor the Alliance. In a small cave at the back lives Kibler, who keeps a talkative parrot named Opus. Mathredis Firestar, hungry for magic, bargains for powerful arcane components.",
			source = "https://warcraft.wiki.gg/wiki/Flame_Crest",
		},
		["morgans vigil"] = {
			name = "Morgan's Vigil",
			short = "Fire has been through Morgan's Vigil, in the southeastern corner of the Burning Steppes. Its houses are burned to the ground and its one mage tower has crumbled.",
			full = "Fire has been through Morgan's Vigil, in the southeastern corner of the Burning Steppes. Its houses are burned to the ground and its one mage tower has crumbled. The Alliance holds what is left, and its people live in tents among the wreckage. Marshal Maxwell is here, seeking word of a high-ranking officer of Stormwind.",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Vigil",
		},
		["pillar of ash"] = {
			name = "The Pillar of Ash",
			short = "A tall tower of scorched stone rises at the eastern end of this camp, which the Blackrock orcs hold. Slayers, sorcerers and warlocks of the clan keep it, with their worgs beside them.",
			full = "A tall tower of scorched stone rises at the eastern end of this camp, which the Blackrock orcs hold. Slayers, sorcerers and warlocks of the clan keep it, with their worgs beside them.",
			source = "https://warcraft.wiki.gg/wiki/Pillar_of_Ash",
		},
		["poachers den"] = {
			pending = true,
			name = "Poacher's Den",
			short = "",
			full = "",
			source = "",
		},
		["ruins of thaurissan"] = {
			name = "Ruins of Thaurissan",
			short = "These ashen flats in the Burning Steppes were green once, when the city of Thaurissan stood here. The Dark Iron clan, exiled from Ironforge, founded it, and Sorcerer-Thane Thaurissan ruled it.",
			full = "These ashen flats in the Burning Steppes were green once, when the city of Thaurissan stood here. The Dark Iron clan, exiled from Ironforge, founded it, and Sorcerer-Thane Thaurissan ruled it.\n\nThe clan was losing the War of the Three Hammers. Their army had just been broken against the strongholds of the other two clans when Thaurissan gathered seven of his most trusted dwarves. Desperate to turn the tide, he called on the powers sleeping beneath the world for a servant to win the war back. Ragnaros, Elemental Lord of Fire, answered. A volcano split the mountains and burned the valley to ash, and the city was destroyed. The surviving Dark Irons, enslaved to the Firelord, left the ruins for a new home beneath the mountain that rose there.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Thaurissan",
		},
		["slither rock"] = {
			name = "Slither Rock",
			short = "Hidden beyond the Terror Wing Path, in the far northeastern corner of the Burning Steppes, a small cave holds one dweller. Cyrus Therepentous, a black dragonspawn, lives here alone.",
			full = "Hidden beyond the Terror Wing Path, in the far northeastern corner of the Burning Steppes, a small cave holds one dweller. Cyrus Therepentous, a black dragonspawn, lives here alone. He will help others against a common foe, though never without rude and derisive comments.",
			source = "https://warcraft.wiki.gg/wiki/Slither_Rock",
		},
		["terror wing path"] = {
			name = "Terror Wing Path",
			short = "Black drakes patrol the valley called Terror Wing Path, in the eastern Burning Steppes. Whelps and dragonkin of the black dragonflight nest among its rocks and ash.",
			full = "Black drakes patrol the valley called Terror Wing Path, in the eastern Burning Steppes. Whelps and dragonkin of the black dragonflight nest among its rocks and ash.",
			source = "https://warcraft.wiki.gg/wiki/Terror_Wing_Path",
		},
	},
	-- Elwynn Forest: 23 subzones
	[1429] = {
		["brackwell pumpkin patch"] = {
			name = "Brackwell Pumpkin Patch",
			short = "In southeast Elwynn Forest stands a farmstead that once belonged to the Brackwell family. The Defias Brotherhood holds it now, and no one can say what became of the Brackwells.",
			full = "In southeast Elwynn Forest stands a farmstead that once belonged to the Brackwell family. The Defias Brotherhood holds it now, and no one can say what became of the Brackwells. They simply vanished from its fields and fences.\n\nOne thing is still told of them. Their prize sow, Princess, grew enormous on vegetables she stole by creeping over to the neighboring Stonefield Farm.",
			source = "https://warcraft.wiki.gg/wiki/Brackwell_Pumpkin_Patch",
		},
		["crystal lake"] = {
			name = "Crystal Lake",
			short = "East of Goldshire, murlocs crawl over the shores of Crystal Lake and wade its shallows in numbers. The water is dangerous for anyone who comes to it unready.",
			full = "East of Goldshire, murlocs crawl over the shores of Crystal Lake and wade its shallows in numbers. The water is dangerous for anyone who comes to it unready.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Lake",
		},
		["eastvale logging camp"] = {
			name = "Eastvale Logging Camp",
			short = "Mill camps stand scattered through eastern Elwynn Forest, with living quarters between them. Together they make up Eastvale Logging Camp.",
			full = "Mill camps stand scattered through eastern Elwynn Forest, with living quarters between them. Together they make up Eastvale Logging Camp. Buyers send in orders for lumber without pause, and the lumberjacks work to strict deadlines.\n\nThe forest presses close. Wolves and bears attack the camps so often that workers are driven off and deliveries put at risk, and the Stormwind Guard has had to call for outside help to thin them.",
			source = "https://warcraft.wiki.gg/wiki/Eastvale_Logging_Camp",
		},
		["echo ridge mine"] = {
			name = "Echo Ridge Mine",
			short = "Marshal McBride keeps sending men into Echo Ridge Mine, in the northwest of Northshire Valley, to thin the kobolds that have taken over its tunnels.",
			full = "Marshal McBride keeps sending men into Echo Ridge Mine, in the northwest of Northshire Valley, to thin the kobolds that have taken over its tunnels. The humans living nearby are frustrated by them.",
			source = "https://warcraft.wiki.gg/wiki/Echo_Ridge_Mine",
		},
		["fargodeep mine"] = {
			name = "Fargodeep Mine",
			short = "Stormwind once took gold from Fargodeep Mine. The shafts stand abandoned now, and a clan of kobolds holds them, miners and tunnelers alike.",
			full = "Stormwind once took gold from Fargodeep Mine. The shafts stand abandoned now, and a clan of kobolds holds them, miners and tunnelers alike. The deepest workings are called the Lower Mines.",
			source = "https://warcraft.wiki.gg/wiki/Fargodeep_Mine",
		},
		["forests edge"] = {
			name = "Forest's Edge",
			short = "A swath of forest southwest of Stormwind reaches like a peninsula between the Nazferiti river and a smaller stream running toward Westfall.",
			full = "A swath of forest southwest of Stormwind reaches like a peninsula between the Nazferiti river and a smaller stream running toward Westfall. Boars root through the undergrowth, and copper veins show along the riverbanks.\n\nA band of Riverpaw gnolls holds the woods under their chieftain Hogger, who raids farms and villages across Elwynn Forest. The Stormwind army has put a bounty on him. Rumor ties the pack to the Defias Brotherhood, which is said to supply it with weapons.",
			source = "https://warcraft.wiki.gg/wiki/Forest's_Edge",
		},
		["goldshire"] = {
			name = "Goldshire",
			short = "Goldshire stands at the center of Elwynn Forest, one of the small towns that grew up around Stormwind. In the First War it and Moonbrook were the last two towns between the orcs and the capital.",
			full = "Goldshire stands at the center of Elwynn Forest, one of the small towns that grew up around Stormwind. In the First War it and Moonbrook were the last two towns between the orcs and the capital. Warchief Blackhand took both to cut King Llane Wrynn off from his people before the sack of Stormwind Keep. After the Second War the Alliance of Lordaeron rebuilt the town, and Supreme Commander Turalyon oversaw the return of the kingdom's scattered citizens.\n\nMarshal Dughan of the Stormwind Guard keeps order here now. The hearth and ale of the Lion's Pride Inn, one of the most respectable ale houses in Azeroth, draw travelers from every road that meets here. Murlocs from Stone Cairn Lake have killed townsfolk, two guards among them, and the guards fear that fighting will reach the town.",
			source = "https://warcraft.wiki.gg/wiki/Goldshire",
		},
		["heroes vigil"] = {
			name = "Heroes' Vigil",
			short = "On an island in Stone Cairn Lake, a ring of standing stones surrounds the Stone of Remembrance. It honors the dead of the First War, when the orcs sacked Goldshire and the lands around it.",
			full = "On an island in Stone Cairn Lake, a ring of standing stones surrounds the Stone of Remembrance. It honors the dead of the First War, when the orcs sacked Goldshire and the lands around it. Rogue wizards hold the island now.",
			source = "https://warcraft.wiki.gg/wiki/Heroes'_Vigil",
		},
		["jasperlode mine"] = {
			name = "Jasperlode Mine",
			short = "Kobolds have overrun the tunnels of Jasperlode Mine, which once gave Stormwind the raw ore it needed for its wars. The army, stretched thin by other threats, has no men to spare to drive them out.",
			full = "Kobolds have overrun the tunnels of Jasperlode Mine, which once gave Stormwind the raw ore it needed for its wars. The army, stretched thin by other threats, has no men to spare to drive them out.\n\nThe kobolds are not alone down there. A colony of mine spiders has settled in the deepest part, and to them the kobolds are a meal. Their queen, Mother Fang, does not welcome uninvited guests.",
			source = "https://warcraft.wiki.gg/wiki/Jasperlode_Mine",
		},
		["jerods landing"] = {
			name = "Jerod's Landing",
			short = "The Defias Brotherhood holds Jerod's Landing, a boat landing on the Elwynn Forest bank of the Nazferiti river.",
			full = "The Defias Brotherhood holds Jerod's Landing, a boat landing on the Elwynn Forest bank of the Nazferiti river. Its Dockmaster and his men use it to smuggle stolen goods from the Redridge Mountains to Klaven's Tower in Westfall.",
			source = "https://warcraft.wiki.gg/wiki/Jerod's_Landing",
		},
		["maclure vineyards"] = {
			name = "The Maclure Vineyards",
			short = "The Maclure family tends long rows of vine in southern Elwynn Forest. They are in a bitter rivalry with the Stonefield family nearby, and neither side hides its dislike.",
			full = "The Maclure family tends long rows of vine in southern Elwynn Forest. They are in a bitter rivalry with the Stonefield family nearby, and neither side hides its dislike. Yet a child of each family has fallen for the other's.",
			source = "https://warcraft.wiki.gg/wiki/Maclure_Vineyards",
		},
		["mirror lake"] = {
			name = "Mirror Lake",
			short = "Mirror Lake lies small and quiet in western Elwynn Forest, its waterfall spilling bright beside a nearby orchard, the kind of place that looks made for swimming or fishing.",
			full = "Mirror Lake lies small and quiet in western Elwynn Forest, its waterfall spilling bright beside a nearby orchard, the kind of place that looks made for swimming or fishing. Defias bandits have taken to the woods around it now, and what should be a place of rest has become one to cross carefully.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake",
		},
		["mirror lake orchard"] = {
			name = "Mirror Lake Orchard",
			short = "On the southern bank of Mirror Lake stands an orchard with a cottage beside it. Defias bandits have taken both for themselves.",
			full = "On the southern bank of Mirror Lake stands an orchard with a cottage beside it. Defias bandits have taken both for themselves.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake_Orchard",
		},
		["northshire abbey"] = {
			name = "Northshire Abbey",
			short = "Centuries ago, clerics of the Church of the Holy Light came south from Lordaeron and founded the Holy Order of Northshire Clerics at this abbey.",
			full = "Centuries ago, clerics of the Church of the Holy Light came south from Lordaeron and founded the Holy Order of Northshire Clerics at this abbey. They comforted Stormwind in hard times, and Medivh, the Guardian of Tirisfal, lay in a coma under their care for years.\n\nIn the First War the clerics stood with Stormwind's armies. When the ogre lord Turok stole the Tome of Divinity, Sir Anduin Lothar led an expedition to take it back, and the tome returned to the abbey. Shortly after the half-orc Garona Halforcen was brought there as a prisoner, the orcs overran the abbey and destroyed it. Refugees fled toward Lordaeron with sacred tomes pulled from the wreckage.\n\nIn the Second War, Cho'gall's Twilight's Hammer clan made the ruins its headquarters. After the Alliance of Lordaeron reclaimed Elwynn Forest, Archbishop Alonsus Faol helped rebuild the abbey and found the Brotherhood of Northshire, which holds it now. Its main hall, hall of arms and library wing stand in Northshire Valley.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Abbey",
		},
		["northshire valley"] = {
			name = "Northshire Valley",
			short = "Impenetrable mountains close in Northshire Valley on every side but one. A pass leads out to the south, protected by thick stone walls and a guarded gate.",
			full = "Impenetrable mountains close in Northshire Valley on every side but one. A pass leads out to the south, protected by thick stone walls and a guarded gate. A river runs through the valley and empties into Crystal Lake.\n\nMarshal Douglas McBride of the Stormwind Guard commands the abbey's garrison and answers for the defense of the valley. His guards still have trouble keeping the peace. Wolves that fled from Duskwood have grown in number in the woods, kobolds infest Echo Ridge Mine, and Defias thugs have taken the vineyards.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Valley",
		},
		["northshire valley camelot"] = {
			pending = true,
			name = "Northshire Valley - Camelot",
			short = "",
			full = "",
			source = "",
		},
		["northshire vineyards"] = {
			name = "Northshire Vineyards",
			short = "Defias bandits drove the farmers out of the Northshire Vineyards, which lie east of the abbey across the bridge. The Brotherhood's agents hold the rows now and keep a tent among the vines.",
			full = "Defias bandits drove the farmers out of the Northshire Vineyards, which lie east of the abbey across the bridge. The Brotherhood's agents hold the rows now and keep a tent among the vines. Garrick Padfoot, a cutthroat who has plagued the farmers and merchants for weeks, has gathered a gang of thugs around him there, and there is a bounty on his head.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Vineyards",
		},
		["ridgepoint tower"] = {
			name = "Ridgepoint Tower",
			short = "Ridgepoint Tower watches the border of Elwynn Forest, one of the Stormwind Guard's scout towers.",
			full = "Ridgepoint Tower watches the border of Elwynn Forest, one of the Stormwind Guard's scout towers. Its sentries turn their eyes toward Redridge, where gnolls and orcs gather, toward Duskwood, where the dead do not stay buried, and toward the nearby Defias camps. The garrison is well defended against all three.",
			source = "https://warcraft.wiki.gg/wiki/Ridgepoint_Tower",
		},
		["stone cairn lake"] = {
			name = "Stone Cairn Lake",
			short = "Stone Cairn Lake lies in northeastern Elwynn Forest and takes its name from Heroes' Vigil, the stone cairn on the large island at its heart.",
			full = "Stone Cairn Lake lies in northeastern Elwynn Forest and takes its name from Heroes' Vigil, the stone cairn on the large island at its heart. A ring of stones stands there with a monument called the Stone of Remembrance, raised for the dead of the First War against the orcs.\n\nPilgrims once came here in safety. Now Rogue Wizards hold the island, and a tribe of murlocs has raised crude dwellings on the southern bank, indifferent to the monument across the water.",
			source = "https://warcraft.wiki.gg/wiki/Stone_Cairn_Lake",
		},
		["stonefield farm"] = {
			name = "The Stonefield Farm",
			short = "Stonefield Farm lies in southern Elwynn Forest, worked by the Stonefield family, who share a bitter rivalry with the nearby Maclures.",
			full = "Stonefield Farm lies in southern Elwynn Forest, worked by the Stonefield family, who share a bitter rivalry with the nearby Maclures. Yet a child of each house has fallen in love, defying the old grudge between their families. Some hope that romance might succeed where years of quarreling never could, and mend what the feud has broken.",
			source = "https://warcraft.wiki.gg/wiki/Stonefield_Farm",
		},
		["thunder falls"] = {
			name = "Thunder Falls",
			short = "Thunder Falls is a narrow ravine in the mountains of northwestern Elwynn Forest, and an unusual one, with water falling at both of its ends.",
			full = "Thunder Falls is a narrow ravine in the mountains of northwestern Elwynn Forest, and an unusual one, with water falling at both of its ends. A third waterfall tumbles down from the northern cliffs and feeds it from above.\n\nThe path up from the waterfall at Mirror Lake climbs steep and narrow to a small rural cottage, its anvil and fire kept lit. A little pier and boat rest on the river beside the house. A few bandits linger near the cottage. The river runs on to another waterfall near the border of Westfall.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Falls",
		},
		["tower of azora"] = {
			name = "Tower of Azora",
			short = "The Tower of Azora rises amid the fields of central Elwynn Forest, a small mage tower kept by servants who all appear to be gnomes and who answer to the Archmage Theocritus.",
			full = "The Tower of Azora rises amid the fields of central Elwynn Forest, a small mage tower kept by servants who all appear to be gnomes and who answer to the Archmage Theocritus. Far off in the Redridge Mountains, the evil sorcerer Morganth rules the Tower of Ilgalar. The two towers are in constant feud, and each spies on the other through magic.\n\nThe tower's own aura works on whatever strays too near and turns it into something stranger. The servants have to battle living buckets and mutant butterflies.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Azora",
		},
		["westbrook garrison"] = {
			name = "Westbrook Garrison",
			short = "The Stormwind Guard keeps a barracks at Westbrook Garrison, on the western end of Elwynn Forest near the border of Westfall. Corruption and political instability have left the kingdom weak.",
			full = "The Stormwind Guard keeps a barracks at Westbrook Garrison, on the western end of Elwynn Forest near the border of Westfall. Corruption and political instability have left the kingdom weak. With the bulk of the Stormwind Army abroad, the garrison barely has enough men to keep the roads safe against growing numbers of gnolls and thieves from Westfall.\n\nDeputy Rainer commands the post. Wanted posters there name Hogger, chieftain of the Riverpaw gnolls, who has overpowered every attempt to capture him. His pack infests the woods south of the guard tower.",
			source = "https://warcraft.wiki.gg/wiki/Westbrook_Garrison",
		},
	},
	-- Deadwind Pass: 9 subzones
	[1430] = {
		["aridens camp"] = {
			name = "Ariden's Camp",
			short = "A deserted campsite lies just north of the main road through the pass. It is known as Ariden's Camp, and nobody is there now.",
			full = "A deserted campsite lies just north of the main road through the pass. It is known as Ariden's Camp, and nobody is there now.",
			source = "https://warcraft.wiki.gg/wiki/Ariden's_Camp",
		},
		["deadmans crossing"] = {
			name = "Deadman's Crossing",
			short = "A hangman's tree stands at the eastern crossroads of the pass, and a pair of corpses still hang from its branches. Beside it a signpost reads \"Turn Back!\" and \"Abandon hope, all ye who enter here.\"",
			full = "A hangman's tree stands at the eastern crossroads of the pass, and a pair of corpses still hang from its branches. Beside it a signpost reads \"Turn Back!\" and \"Abandon hope, all ye who enter here.\"\n\nFrom the crossing one road runs west to Duskwood, another east to the Swamp of Sorrows, and a third south toward Karazhan.",
			source = "https://warcraft.wiki.gg/wiki/Deadman's_Crossing",
		},
		["deadwind ravine"] = {
			name = "Deadwind Ravine",
			short = "A craggy cleft runs south through the mountains toward Karazhan. The western road follows its upper level. At the far end a bridge crosses to the south, and the ominous tower stands close by.",
			full = "A craggy cleft runs south through the mountains toward Karazhan. The western road follows its upper level. At the far end a bridge crosses to the south, and the ominous tower stands close by.",
			source = "https://warcraft.wiki.gg/wiki/Deadwind_Ravine",
		},
		["groshgok compound"] = {
			name = "Grosh'gok Compound",
			short = "Of all the Deadwind ogre caves in the Vice, the Grosh'gok Compound lies farthest south, and it is the largest. The Deadwind ogres live in it.",
			full = "Of all the Deadwind ogre caves in the Vice, the Grosh'gok Compound lies farthest south, and it is the largest. The Deadwind ogres live in it.",
			source = "https://warcraft.wiki.gg/wiki/Grosh'gok_Compound",
		},
		["karazhan"] = {
			name = "Karazhan",
			short = "The builders of the Ivory Tower of Karazhan are lost to time. It stands on a nexus of ley lines in southern Deadwind Pass, and it became the seat of Medivh, the last Guardian of Tirisfal.",
			full = "The builders of the Ivory Tower of Karazhan are lost to time. It stands on a nexus of ley lines in southern Deadwind Pass, and it became the seat of Medivh, the last Guardian of Tirisfal. Befitting his title, Medivh had amassed a vast collection of writings and artifacts, greater even than that of the Kirin Tor. He was killed inside the tower in the First War by Khadgar, Anduin Lothar and Garona.\n\nSince then the tower has stood abandoned, and a curse lies on it and the land around it. Ghosts fill its halls, and demons are said to walk among them.",
			source = "https://warcraft.wiki.gg/wiki/Karazhan",
		},
		["masters cellar"] = {
			name = "The Master's Cellar",
			short = "Below the ruins of a small village south of Karazhan, the ground opens into cellars full of ghosts. The villagers were probably servants of the tower.",
			full = "Below the ruins of a small village south of Karazhan, the ground opens into cellars full of ghosts. The villagers were probably servants of the tower. No one knows who killed them. Some blame Medivh, or something he summoned, and others the Dark Riders.\n\nTwo entrances lead down. One opens into a vast wine cellar, its racks and barrels long abandoned to the dead. The other leads to a cellar whose floor has collapsed into a cave system running deep underground. Unliving residents and caretakers, damned souls, restless shades and wailing spectres fill both.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Cellar",
		},
		["morgans plot"] = {
			name = "Morgan's Plot",
			short = "A small, decrepit church stands behind Karazhan, its graveyard and crypt sunk into the gloom of Deadwind Pass. Unliving residents haunt the chapel, and another patrols the hill just below.",
			full = "A small, decrepit church stands behind Karazhan, its graveyard and crypt sunk into the gloom of Deadwind Pass. Unliving residents haunt the chapel, and another patrols the hill just below.",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Plot",
		},
		["sleeping gorge"] = {
			name = "Sleeping Gorge",
			short = "A small chasm cuts through eastern Deadwind Pass. One of the paths south to Karazhan runs through it for a stretch before turning east into the Vice.",
			full = "A small chasm cuts through eastern Deadwind Pass. One of the paths south to Karazhan runs through it for a stretch before turning east into the Vice.",
			source = "https://warcraft.wiki.gg/wiki/Sleeping_Gorge",
		},
		["vice"] = {
			name = "The Vice",
			short = "Along the road to Karazhan, in the south of the pass, lies a desolate stretch of crags called the Vice. The Deadwind ogres live here in mounds and camps scattered beside the road.",
			full = "Along the road to Karazhan, in the south of the pass, lies a desolate stretch of crags called the Vice. The Deadwind ogres live here in mounds and camps scattered beside the road.\n\nNobody knows why they settled where only restless spirits and the vultures circling over them keep them company.",
			source = "https://warcraft.wiki.gg/wiki/Vice",
		},
	},
	-- Duskwood: 17 subzones
	[1431] = {
		["addles stead"] = {
			name = "Addle's Stead",
			short = "The Defias Brotherhood has taken Addle's Stead, one of the many farmsteads abandoned in southwestern Duskwood when the darkness crept in.",
			full = "The Defias Brotherhood has taken Addle's Stead, one of the many farmsteads abandoned in southwestern Duskwood when the darkness crept in. Its agents move through the field, hide in the barn and stalk the rooms of the small farmhouse.",
			source = "https://warcraft.wiki.gg/wiki/Addle's_Stead",
		},
		["beggars haunt"] = {
			name = "Beggar's Haunt",
			short = "Beggar's Haunt, an abandoned scout tower of the Stormwind Guard, stands in northeastern Duskwood, east of Manor Mistmantle and north of the road into Deadwind Pass.",
			full = "Beggar's Haunt, an abandoned scout tower of the Stormwind Guard, stands in northeastern Duskwood, east of Manor Mistmantle and north of the road into Deadwind Pass. The Forsaken hold it now, and Deathstalker Zraedus and Apothecary Faustin work experiments within its walls.\n\nA path winds down to a small pool fed by a waterfall, where an unmarked grave rests beneath two great statues carved like those at the Dark Portal. Near the tower lies another small cemetery, holding the grave of an Unknown Soldier.",
			source = "https://warcraft.wiki.gg/wiki/Beggar's_Haunt",
		},
		["brightwood grove"] = {
			name = "Brightwood Grove",
			short = "The few buildings that stood at the edge of Brightwood Grove lie in ruins, and Nightbane worgen prowl its dark fields. They raise crude camps among the wreckage and attack anyone who comes too close.",
			full = "The few buildings that stood at the edge of Brightwood Grove lie in ruins, and Nightbane worgen prowl its dark fields. They raise crude camps among the wreckage and attack anyone who comes too close. The grove lies just west of Darkshire. It keeps the old name of the whole forest, which was called Brightwood before the darkness.",
			source = "https://warcraft.wiki.gg/wiki/Brightwood_Grove",
		},
		["darkened bank"] = {
			name = "The Darkened Bank",
			short = "The Darkened Bank runs along the northern shore of Duskwood, from the far western edge east to the bridge that joins the wood to the Redridge Mountains.",
			full = "The Darkened Bank runs along the northern shore of Duskwood, from the far western edge east to the bridge that joins the wood to the Redridge Mountains. At its western end, refugees have made a small camp. Sven Yorgen lives there with Lars, and Sven has lost his wife and children to the Dark Riders of Deadwind Pass.",
			source = "https://warcraft.wiki.gg/wiki/Darkened_Bank",
		},
		["darkshire"] = {
			name = "Darkshire",
			short = "Darkshire was once a quaint little woodland village called Grand Hamlet, in the forest of Brightwood. Then the darkness came, and the woods turned into a dangerous, thorny blight.",
			full = "Darkshire was once a quaint little woodland village called Grand Hamlet, in the forest of Brightwood. Then the darkness came, and the woods turned into a dangerous, thorny blight. Brightwood became Duskwood, and Grand Hamlet became Darkshire. The walking dead choke the graveyards now, and worgen have overrun many of the farmsteads around the town.\n\nStormwind pulled all its troops out of Duskwood after King Varian Wrynn disappeared. The townsfolk armed themselves instead. Their militia, the Night Watch, was formed and trained entirely by the people of the forest, and Commander Althea Ebonlocke leads it. Its watchers keep the main road and the town against wolves and walking corpses.\n\nThe people of Darkshire are jumpy and suspicious, and they need whatever help they can get.",
			source = "https://warcraft.wiki.gg/wiki/Darkshire",
		},
		["dawning wood catacombs"] = {
			name = "Dawning Wood Catacombs",
			short = "Beneath Raven Hill Cemetery, twisting catacombs hold the most powerful undead in the region. There are two entrances. The eastern one leads into a den of ghouls, diseased and ferocious.",
			full = "Beneath Raven Hill Cemetery, twisting catacombs hold the most powerful undead in the region. There are two entrances. The eastern one leads into a den of ghouls, diseased and ferocious. The western one leads into a hall of skeletons, who guard the tombs of their former brethren.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Wood_Catacombs",
		},
		["forlorn rowe"] = {
			name = "Forlorn Rowe",
			short = "Forlorn Rowe is a hill on the northern edge of Raven Hill Cemetery, wrapped in a darkness heavier than the shadow of the forest around it.",
			full = "Forlorn Rowe is a hill on the northern edge of Raven Hill Cemetery, wrapped in a darkness heavier than the shadow of the forest around it. The necromancer Morbent Fel has his home in the dark house on its top, looking down over the graves. He rules the undead of Duskwood through evil arcane magic.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Rowe",
		},
		["hushed bank"] = {
			name = "The Hushed Bank",
			short = "The Hushed Bank follows the western river of Duskwood south from the point where Westfall, Elwynn Forest and Duskwood meet, down toward Stranglethorn Vale.",
			full = "The Hushed Bank follows the western river of Duskwood south from the point where Westfall, Elwynn Forest and Duskwood meet, down toward Stranglethorn Vale. A covered bridge crosses the river here and joins Duskwood to Westfall. Spiders and wolves range among the trees, and Sven Yorgen and Lars keep a camp at its northern end.",
			source = "https://warcraft.wiki.gg/wiki/Hushed_Bank",
		},
		["manor mistmantle"] = {
			name = "Manor Mistmantle",
			short = "Manor Mistmantle stands in northeastern Duskwood, north of Darkshire and west of Beggar's Haunt. Its grounds have rotted, and ghouls shamble through them.",
			full = "Manor Mistmantle stands in northeastern Duskwood, north of Darkshire and west of Beggar's Haunt. Its grounds have rotted, and ghouls shamble through them. The garden has gone to ruin. A single flower still grows in it, the Tear of Tilloa, the only sign of life on the property.",
			source = "https://warcraft.wiki.gg/wiki/Manor_Mistmantle",
		},
		["raven hill"] = {
			name = "Raven Hill",
			short = "The houses of Raven Hill stand empty in western Duskwood, given up to rot and dark. Almost nobody is left.",
			full = "The houses of Raven Hill stand empty in western Duskwood, given up to rot and dark. Almost nobody is left. Jitters, a frightened man, hides here from his dark past, and a goblin named Bliztik keeps out of sight on the top floor of one of the buildings. The Unseen haunt the rest of the town, moving through its empty rooms.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill",
		},
		["raven hill cemetery"] = {
			name = "Raven Hill Cemetery",
			short = "The cemetery grew far past its old bounds only after the darkness came to Duskwood. Undead walk among its stones, with massive spiders and gangs of grave robbers who attack anyone who interrupts their work.",
			full = "The cemetery grew far past its old bounds only after the darkness came to Duskwood. Undead walk among its stones, with massive spiders and gangs of grave robbers who attack anyone who interrupts their work. The undead Mor'Ladim wanders a strange, meandering path through the grounds, and death comes to the unwary who meet him.\n\nOn the hill in the cemetery's northwest corner stands Forlorn Rowe, home of the necromancer Morbent Fel, and in its northeast quarter lies the way down into the Dawning Wood Catacombs.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill_Cemetery",
		},
		["rolands doom"] = {
			name = "Roland's Doom",
			short = "Roland's Doom is a mine in southeastern Duskwood, due east of the Rotting Orchard. Worgen of the Nightbane pack fill its shafts, and it is home to Gutspill and Nefaru, who lead the worgen at the Rotting Orchard.",
			full = "Roland's Doom is a mine in southeastern Duskwood, due east of the Rotting Orchard. Worgen of the Nightbane pack fill its shafts, and it is home to Gutspill and Nefaru, who lead the worgen at the Rotting Orchard.",
			source = "https://warcraft.wiki.gg/wiki/Roland's_Doom",
		},
		["rotting orchard"] = {
			name = "The Rotting Orchard",
			short = "Worgen of the Nightbane pack have taken the Rotting Orchard in southern Duskwood. They make camps among its dilapidated buildings.",
			full = "Worgen of the Nightbane pack have taken the Rotting Orchard in southern Duskwood. They make camps among its dilapidated buildings. Nightbane Shadow Weavers practice their magic there, and Nightbane Stalkers keep watch in the shadows.",
			source = "https://warcraft.wiki.gg/wiki/Rotting_Orchard",
		},
		["tranquil gardens cemetery"] = {
			name = "Tranquil Gardens Cemetery",
			short = "Nothing about Tranquil Gardens Cemetery is tranquil anymore. It lies southeast of Darkshire, and its dead do not rest, though they are weaker than the undead elsewhere in Duskwood.",
			full = "Nothing about Tranquil Gardens Cemetery is tranquil anymore. It lies southeast of Darkshire, and its dead do not rest, though they are weaker than the undead elsewhere in Duskwood. They wander among the headstones and the ruined church. The Insane Ghoul haunts the ground, sometimes inside the church and sometimes outside. Blind Mary's house stands just north.",
			source = "https://warcraft.wiki.gg/wiki/Tranquil_Gardens_Cemetery",
		},
		["twilight grove"] = {
			name = "Twilight Grove",
			short = "An ancient volcano crater, long dead, lies at the center of Duskwood, and it teems with life. The twilight here is unlike the dark of the rest of the woods.",
			full = "An ancient volcano crater, long dead, lies at the center of Duskwood, and it teems with life. The twilight here is unlike the dark of the rest of the woods. A great tree with no name stands in its heart beside a moonwell and an old night elf gazebo. Beneath its boughs is one of only four portals into the Emerald Dream, and the influence of the sleeping druids shows on the land around it.\n\nFour great dragons guard the portal. They were once proud lieutenants of Ysera, Aspect of Dreams, and protectors of the Dream. The Emerald Nightmare has corrupted them, and now they seek only destruction and death.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Grove",
		},
		["vulgol ogre mound"] = {
			name = "Vul'Gol Ogre Mound",
			short = "Splinter Fist ogres have overrun a small basin in southern Duskwood, just southwest of the fork in the main road. The mound takes its name from their leader, Zzarc'Vul.",
			full = "Splinter Fist ogres have overrun a small basin in southern Duskwood, just southwest of the fork in the main road. The mound takes its name from their leader, Zzarc'Vul. Humans lived here once, as the ruined farmhouses show. In the cave the ogres feed on the carcasses of black bears.",
			source = "https://warcraft.wiki.gg/wiki/Vul'Gol_Ogre_Mound",
		},
		["yorgen farmstead"] = {
			name = "The Yorgen Farmstead",
			short = "Sven Yorgen once farmed this land in southern Duskwood, until Dark Riders from Deadwind Pass came and killed his family.",
			full = "Sven Yorgen once farmed this land in southern Duskwood, until Dark Riders from Deadwind Pass came and killed his family. The farm is abandoned now, its fields gone to rot, and Sven keeps to a small camp on the Darkened Bank.\n\nThe Defias Brotherhood holds the farmstead. Its assassins move through the fields unseen.",
			source = "https://warcraft.wiki.gg/wiki/Yorgen_Farmstead",
		},
	},
	-- Loch Modan: 15 subzones
	[1432] = {
		["algaz station"] = {
			name = "Algaz Station",
			short = "Many dwarven mountaineers are stationed at this outpost, just east of North Gate Pass. It lies south of Dun Algaz, the stronghold in the pass, and takes its name from it.",
			full = "Many dwarven mountaineers are stationed at this outpost, just east of North Gate Pass. It lies south of Dun Algaz, the stronghold in the pass, and takes its name from it.",
			source = "https://warcraft.wiki.gg/wiki/Algaz_Station",
		},
		["dun algaz"] = {
			name = "Dun Algaz",
			short = "The tunnel through Dun Algaz is older than the War of the Three Hammers. When that war drove the Wildhammer dwarves out of Ironforge, they passed through here.",
			full = "The tunnel through Dun Algaz is older than the War of the Three Hammers. When that war drove the Wildhammer dwarves out of Ironforge, they passed through here.\n\nThe Horde retreated this way too. Beaten back from Dun Modr in the Second War, the orcs fell south across the Thandol Valley and dug in at the outpost here. Anduin Lothar, wanting them pushed clear out of Khaz Modan, sent his forces to tear the stronghold down. The assault failed. The orcs held on, and Dun Algaz became the last ground the Horde kept in the region.\n\nThe dwarven mountaineers who watch this pass kept mostly to the hills above it, but the Dragonmaw clan has overrun their post and driven them back to the upper tunnel. With the lower pass lost, the road between the dwarven homelands and Menethil Harbor has grown far more dangerous.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["farstrider lodge"] = {
			name = "The Farstrider Lodge",
			short = "The Farstrider Lodge stands in the southeastern hills of Loch Modan, a hunters' lodge whose stonework is plainly high elven. Only one high elf is known to live there now.",
			full = "The Farstrider Lodge stands in the southeastern hills of Loch Modan, a hunters' lodge whose stonework is plainly high elven. Only one high elf is known to live there now. Humans and dwarves, hunters among them, have since taken up residence within its elven walls.",
			source = "https://warcraft.wiki.gg/wiki/Farstrider_Lodge",
		},
		["grizzlepaw ridge"] = {
			name = "Grizzlepaw Ridge",
			short = "Grizzlepaw Ridge rises south of Thelsamar, thick with bears that have made the heights their own. The most ferocious of them, a large black bear called Ol' Sooty, keeps a lair on the slopes.",
			full = "Grizzlepaw Ridge rises south of Thelsamar, thick with bears that have made the heights their own. The most ferocious of them, a large black bear called Ol' Sooty, keeps a lair on the slopes. Now and then he wanders down to the base of the valley and pounces on anyone unlucky enough to irritate him.",
			source = "https://warcraft.wiki.gg/wiki/Grizzlepaw_Ridge",
		},
		["ironbands excavation site"] = {
			name = "Ironband's Excavation Site",
			short = "Prospector Ironband leads an excavation of ancient ruins here, in the southeastern corner of Loch Modan. Like the other dwarven digs, it has been invaded, and the prospectors and miners have been driven out.",
			full = "Prospector Ironband leads an excavation of ancient ruins here, in the southeastern corner of Loch Modan. Like the other dwarven digs, it has been invaded, and the prospectors and miners have been driven out. The invaders are troggs of an especially large and volatile breed.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Excavation_Site",
		},
		["loch"] = {
			name = "The Loch",
			short = "No other lake on Khaz Modan comes close to the Loch. Only Lordamere Lake and Darrowmere Lake are larger anywhere in the known world.",
			full = "No other lake on Khaz Modan comes close to the Loch. Only Lordamere Lake and Darrowmere Lake are larger anywhere in the known world.\n\nThe Stonewrought Dam on its northern edge holds the water in, and the lake is more than twice the size it was before the dam was built. Threshadons and frenzies swim in it, and the broken catapults and ballistae of the Second War still lie on its bottom and on its islands.",
			source = "https://warcraft.wiki.gg/wiki/The_Loch",
		},
		["mogrosh stronghold"] = {
			name = "Mo'grosh Stronghold",
			short = "A tribe of ogres, the Mo'grosh, holds the caves of the northeastern hills.",
			full = "A tribe of ogres, the Mo'grosh, holds the caves of the northeastern hills. Chok'sul, thought to be their leader, has coordinated attacks on Thelsamar, the Stonewrought Dam and the dwarven digs, and the magistrate of Thelsamar has put a price on his head. One band ambushed a dwarven caravan coming from the Wetlands and left no one alive but a mortally wounded guard.",
			source = "https://warcraft.wiki.gg/wiki/Mo'grosh_Stronghold",
		},
		["north gate pass"] = {
			name = "North Gate Pass",
			short = "The pass runs between the high mountains of Dun Morogh to the west and the lower mountains of Loch Modan to the east.",
			full = "The pass runs between the high mountains of Dun Morogh to the west and the lower mountains of Loch Modan to the east. In its middle stands North Gate Outpost, the northeasternmost settlement the dwarves have built in Dun Morogh.\n\nThe mountaineers here are kept busy driving the wildlife back from the walls. Some dwarves have gone missing in the mountains while searching for the fiercer beasts.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["silver stream mine"] = {
			name = "Silver Stream Mine",
			short = "Silver once came out of this mine in plenty, and it went to the dwarves of Ironforge. The vein ran dry long ago, and the Miners' League turned the tunnels into a storage depot.",
			full = "Silver once came out of this mine in plenty, and it went to the dwarves of Ironforge. The vein ran dry long ago, and the Miners' League turned the tunnels into a storage depot.\n\nNow Tunnel Rat kobolds have overrun it, hungry for what the mine still holds. Behind the mine lie the wrecked wagons and catapults of the orcs.",
			source = "https://warcraft.wiki.gg/wiki/Silver_Stream_Mine",
		},
		["south gate pass"] = {
			name = "South Gate Pass",
			short = "Halfway through the pass stands a dwarven outpost, and its mountaineers have cleared out most of the wildlife that once pressed in on it.",
			full = "Halfway through the pass stands a dwarven outpost, and its mountaineers have cleared out most of the wildlife that once pressed in on it. Snow lies on the ground here, as it does in the mountains to the west.\n\nThe pass is the closest way down to the dwarven town of Thelsamar.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["stonesplinter valley"] = {
			name = "Stonesplinter Valley",
			short = "Stonesplinter Valley was a pristine place once, carved among the mountains of southwestern Loch Modan. Now it crawls with hostile Stonesplinter troggs.",
			full = "Stonesplinter Valley was a pristine place once, carved among the mountains of southwestern Loch Modan. Now it crawls with hostile Stonesplinter troggs.\n\nThe dwarves hold that the tribe's push into their lands is led by a trogg named Grawmug, who lives in the innermost cave. Two elite guards, Gnasher and Brawler, never leave his side. Captain Rugelfuss wants him dead.",
			source = "https://warcraft.wiki.gg/wiki/Stonesplinter_Valley",
		},
		["stonewrought dam"] = {
			name = "Stonewrought Dam",
			short = "Few who cross the Stonewrought Dam know that a Dark Iron dwarf built it. Franclorn Forgewright, the great architect of that clan, oversaw the work and invented the stonewrought method that the dam is named for.",
			full = "Few who cross the Stonewrought Dam know that a Dark Iron dwarf built it. Franclorn Forgewright, the great architect of that clan, oversaw the work and invented the stonewrought method that the dam is named for.\n\nThe dam rises east of Dun Algaz along the northern edge of Loch Modan, and the water it holds back more than doubled the size of the loch. The Dark Iron clan has lately attacked it, and the dwarves of Ironforge have tightened their guard. Chief Engineer Hinderweir VII now oversees it.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Dam",
		},
		["stoutlager inn"] = {
			name = "Stoutlager Inn",
			short = "The Stoutlager Inn stands in Thelsamar. Dwarves and travelers gather here to drink and talk. Innkeeper Hearthstove keeps it, and Lina Hearthstove tends the stable.",
			full = "The Stoutlager Inn stands in Thelsamar. Dwarves and travelers gather here to drink and talk. Innkeeper Hearthstove keeps it, and Lina Hearthstove tends the stable.",
			source = "https://warcraft.wiki.gg/wiki/Stoutlager_Inn",
		},
		["thelsamar"] = {
			name = "Thelsamar",
			short = "A dwarven town stands on the west shore of Loch Modan, north of Grizzlepaw Ridge and northeast of Stonesplinter Valley. Mountaineers keep watch over its houses, and Magistrate Bluntnose presides over the town.",
			full = "A dwarven town stands on the west shore of Loch Modan, north of Grizzlepaw Ridge and northeast of Stonesplinter Valley. Mountaineers keep watch over its houses, and Magistrate Bluntnose presides over the town. It has an inn, the Stoutlager, and a forge and anvil near its southwesternmost house. The Explorers' League keeps a house here too, and fishermen work the shore of the loch below the town.\n\nA north-south road runs just west of the town, leading to the passes into Dun Morogh and the Wetlands.",
			source = "https://warcraft.wiki.gg/wiki/Thelsamar",
		},
		["valley of kings"] = {
			name = "Valley of Kings",
			short = "The Valley of Kings lies in the southwestern reach of Loch Modan, where the green land narrows toward the gate leading down into the blackened Searing Gorge.",
			full = "The Valley of Kings lies in the southwestern reach of Loch Modan, where the green land narrows toward the gate leading down into the blackened Searing Gorge. The gate stays locked and guarded, and Mountaineer Pebblebitty holds it.\n\nTwo great statues rise over the pass, King Madoran Bronzebeard and King Khardros Wildhammer. When the two kings died, their sons commissioned the statues together in honor of their fathers. The land to the south had turned volcanic in the wake of Ragnaros, and the statues stand guard over the road into it. They are a warning to anyone who would attack the dwarven kingdoms, and a reminder of the price the Dark Irons paid for their crimes.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Kings",
		},
	},
	-- Redridge Mountains: 16 subzones
	[1433] = {
		["althers mill"] = {
			name = "Alther's Mill",
			short = "The lumber mill northeast of Lakeshire is abandoned. It was always a backwater, a place folk passed through on the way to Stonewatch Keep, and spiders, buzzards and the odd stray orc have overrun it.",
			full = "The lumber mill northeast of Lakeshire is abandoned. It was always a backwater, a place folk passed through on the way to Stonewatch Keep, and spiders, buzzards and the odd stray orc have overrun it.",
			source = "https://warcraft.wiki.gg/wiki/Alther's_Mill",
		},
		["galardell valley"] = {
			name = "Galardell Valley",
			short = "The Tower of Ilgalar stands in Galardell Valley, in the northeastern Redridge Mountains. Morganth, a dark mage cast out of Stormwind, lives there.",
			full = "The Tower of Ilgalar stands in Galardell Valley, in the northeastern Redridge Mountains. Morganth, a dark mage cast out of Stormwind, lives there.\n\nThe valley below crawls with the Shadowhide gnolls that serve him. The strongest is their leader, Lieutenant Fangore, who calls the nearby gnolls to his side at the first sign of trespass, and Magistrate Solomon has put a price on his head.",
			source = "https://warcraft.wiki.gg/wiki/Galardell_Valley",
		},
		["lake everstill"] = {
			name = "Lake Everstill",
			short = "Wide, clear and azure, Lake Everstill fills the middle of the Redridge Mountains and gives the sleepy town of Lakeshire its setting.",
			full = "Wide, clear and azure, Lake Everstill fills the middle of the Redridge Mountains and gives the sleepy town of Lakeshire its setting. Its eastern river runs out past the dark walls of Stonewatch Keep.\n\nThe lake was once known for its fishing. Murloc tribes have overrun it since, and a great thresher called the Lake Thresher patrols the deeps. The Everstill Bridge carries the road across the water, but the Blackrock clan damaged it, and Foreman Oslow and his workers are still at the repairs.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Everstill",
		},
		["lakeridge highway"] = {
			name = "Lakeridge Highway",
			short = "Traffic once moved steadily along the Lakeridge Highway, on the southern edge of Lake Everstill, in the days before the First War. Since the orcs took Stonewatch Keep the old road has fallen into disuse.",
			full = "Traffic once moved steadily along the Lakeridge Highway, on the southern edge of Lake Everstill, in the days before the First War. Since the orcs took Stonewatch Keep the old road has fallen into disuse. Gnolls patrol most of its length, and few travelers risk it.",
			source = "https://warcraft.wiki.gg/wiki/Lakeridge_Highway",
		},
		["lakeshire"] = {
			name = "Lakeshire",
			short = "Lakeshire sits on the northern bank of Lake Everstill, and the town has bled for that ground more than once. In the First War, Warchief Blackhand led a raiding party into these mountains to take it for the Horde.",
			full = "Lakeshire sits on the northern bank of Lake Everstill, and the town has bled for that ground more than once. In the First War, Warchief Blackhand led a raiding party into these mountains to take it for the Horde. Anduin Lothar and the Knights of Stormwind ambushed the orcs from the slopes and nearly beat them. Two Shadow Council warlocks turned the fight and drove Lothar back. Blackhand returned weeks later with a larger force and took the town. After the Second War, the Alliance of Lordaeron retook and rebuilt it, and Supreme Commander Turalyon oversaw the return of its people.\n\nMagistrate Solomon now leads Lakeshire through its own court, and Marshal Marris commands the guard. Gnolls and Blackrock orcs press on the town, and little help comes from Stormwind. One of the Blackrock assaults damaged the Everstill Bridge, and Foreman Oslow and his crew are still repairing it, slowed by the supplies they lose to the raids.",
			source = "https://warcraft.wiki.gg/wiki/Lakeshire",
		},
		["redridge canyons"] = {
			name = "Redridge Canyons",
			short = "The canyons run through the northwestern Redridge Mountains. Yowler, who leads the local gnolls, has his den here.",
			full = "The canyons run through the northwestern Redridge Mountains. Yowler, who leads the local gnolls, has his den here.",
			source = "https://warcraft.wiki.gg/wiki/Redridge_Canyons",
		},
		["renders camp"] = {
			name = "Render's Camp",
			short = "Blackrock orcs hold an outpost in the northwestern Redridge Mountains, near the entrance to the Burning Steppes.",
			full = "Blackrock orcs hold an outpost in the northwestern Redridge Mountains, near the entrance to the Burning Steppes.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Camp",
		},
		["renders rock"] = {
			name = "Render's Rock",
			short = "Powerful Blackrock orcs hold a large cave here, in the northwestern Redridge Mountains, close to the way into the Burning Steppes.",
			full = "Powerful Blackrock orcs hold a large cave here, in the northwestern Redridge Mountains, close to the way into the Burning Steppes.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Rock",
		},
		["renders valley"] = {
			name = "Render's Valley",
			short = "The orcs of this valley in the southeastern Redridge Mountains are not as strong as their kin farther northwest. The camp is theirs all the same, an outpost of the Blackrock clan.",
			full = "The orcs of this valley in the southeastern Redridge Mountains are not as strong as their kin farther northwest. The camp is theirs all the same, an outpost of the Blackrock clan.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Valley",
		},
		["rethban caverns"] = {
			name = "Rethban Caverns",
			short = "Gnolls hold the deep tunnels of the Rethban Caverns, in the northwestern Redridge Mountains. Their leader, Ardo Dirtpaw, is a cunning one.",
			full = "Gnolls hold the deep tunnels of the Rethban Caverns, in the northwestern Redridge Mountains. Their leader, Ardo Dirtpaw, is a cunning one. The gnolls carry Rethban ore, which takes its name from Bart Rethban, the first man to find it. The caverns were probably named for him too.",
			source = "https://warcraft.wiki.gg/wiki/Rethban_Caverns",
		},
		["stonewatch"] = {
			name = "Stonewatch",
			short = "The humans of Lakeshire held Stonewatch as a fortress against the orc raids that come down from the Burning Steppes.",
			full = "The humans of Lakeshire held Stonewatch as a fortress against the orc raids that come down from the Burning Steppes. It has an easily defended keep, an armored tower beside it, and falls that pour down the cliff face below.\n\nThe warlock Morganth struck a bargain with the Blackrock warlord Gath'Ilzogg. With Morganth's dark magic behind them, the orcs fell on the keep with horrific savagery, beat the 12th Sabre Regiment and took the fortress.\n\nThe alliance did not last. Morganth turned on the orcs and raised a tower of his own, where he built an army of Shadowhide gnolls. Left to fend for themselves, the Blackrock orcs hold Stonewatch still.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch",
		},
		["stonewatch falls"] = {
			name = "Stonewatch Falls",
			short = "Lake Everstill's eastern river ends here, spilling down the hillside below Stonewatch into a deep lake in the nook of the eastern mountains.",
			full = "Lake Everstill's eastern river ends here, spilling down the hillside below Stonewatch into a deep lake in the nook of the eastern mountains. A small tribe of murlocs lives along its banks. They catch fish from the water and build crude shelters to sleep in.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Falls",
		},
		["stonewatch keep"] = {
			name = "Stonewatch Keep",
			short = "Gath'Ilzogg, a warlord of the Blackrock clan, holds Stonewatch Keep with his trusted lieutenant Tharil'zun. The orcs took the keep from the humans of Lakeshire, and Gath'Ilzogg leads raids against the town from it.",
			full = "Gath'Ilzogg, a warlord of the Blackrock clan, holds Stonewatch Keep with his trusted lieutenant Tharil'zun. The orcs took the keep from the humans of Lakeshire, and Gath'Ilzogg leads raids against the town from it.\n\nIn the fighting the orcs took Corporal Keeshan of the Stormwind Army prisoner and dragged him off to their camps farther north. Magistrate Solomon has put a bounty on Gath'Ilzogg, and Marshal Marris of Lakeshire wants Tharil'zun to answer for his misdeeds.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Keep",
		},
		["stonewatch tower"] = {
			name = "Stonewatch Tower",
			short = "Beside the keep stands the armored scout tower of Stonewatch. It once belonged to the humans of Lakeshire, like the keep.",
			full = "Beside the keep stands the armored scout tower of Stonewatch. It once belonged to the humans of Lakeshire, like the keep. Now it is held by underlings of Gath'Ilzogg, Blackrock orcs who watch from it over the stronghold their clan took.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Tower",
		},
		["three corners"] = {
			name = "Three Corners",
			short = "At Three Corners the road splits three ways, toward the Three Shires. One road goes to Goldshire in Elwynn Forest, one to Lakeshire, and one to Darkshire in Duskwood.",
			full = "At Three Corners the road splits three ways, toward the Three Shires. One road goes to Goldshire in Elwynn Forest, one to Lakeshire, and one to Darkshire in Duskwood. Only the crossroads marks the seam between the three lands. A lone Stormwind guard, Guard Parker, watches it, and gnolls roam the roads nearby.",
			source = "https://warcraft.wiki.gg/wiki/Three_Corners",
		},
		["tower of ilgalar"] = {
			name = "Tower of Ilgalar",
			short = "Morganth once studied in the mage tower of Stormwind with two other mages, until he fell to the dark arts. He was urged to turn away from that magic and could not, and he was banished from the Mage Quarter.",
			full = "Morganth once studied in the mage tower of Stormwind with two other mages, until he fell to the dark arts. He was urged to turn away from that magic and could not, and he was banished from the Mage Quarter.\n\nNow he lives in the Tower of Ilgalar, in the northeastern Redridge Mountains, and goes on with his dark studies. Dragon bones hang on display through the tower, and a dragon skull and a human skull sit on the alchemy table at the top. He commands the Shadowhide gnolls, who have brought down orc and man alike.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Ilgalar",
		},
	},
	-- Stranglethorn Vale: 40 subzones
	[1434] = {
		["baliamah ruins"] = {
			name = "Balia'mah Ruins",
			short = "Ancient troll stonework stands on the east bank of the river here, and the Skullsplitter trolls have made their home in it. The ogre mound of Mosh'Ogg lies to the northeast.",
			full = "Ancient troll stonework stands on the east bank of the river here, and the Skullsplitter trolls have made their home in it. The ogre mound of Mosh'Ogg lies to the northeast.",
			source = "https://warcraft.wiki.gg/wiki/Balia'mah_Ruins",
		},
		["ballal ruins"] = {
			name = "Bal'lal Ruins",
			short = "All that is left of Bal'lal is a line of broken columns on the northwestern coast, facing the Vile Reef. The trolls who raised it are long gone, and Bloodscalp trolls now live among the fallen stone.",
			full = "All that is left of Bal'lal is a line of broken columns on the northwestern coast, facing the Vile Reef. The trolls who raised it are long gone, and Bloodscalp trolls now live among the fallen stone.",
			source = "https://warcraft.wiki.gg/wiki/Bal'lal_Ruins",
		},
		["battle ring"] = {
			name = "Battle Ring",
			short = "The fighting ring lies at the center of the Gurubashi Arena, an old relic of the Gurubashi Empire that once ruled great stretches of the southern Eastern Kingdoms.",
			full = "The fighting ring lies at the center of the Gurubashi Arena, an old relic of the Gurubashi Empire that once ruled great stretches of the southern Eastern Kingdoms. In ancient times the fights here were to the death, and the sand ran muddy with troll blood. The empire fell long ago, but the arena endured, and Short John Mithril now oversees matches that are less deadly.\n\nOld stories say that whoever finds a blood-red amulet here at midnight will have a demon devour their soul by daybreak.",
			source = "",
		},
		["bloodsail compound"] = {
			name = "Bloodsail Compound",
			short = "The Bloodsail Buccaneers, a renegade band of sailors, keep a loose camp on the western coast of Stranglethorn Vale, toward the middle of the shore.",
			full = "The Bloodsail Buccaneers, a renegade band of sailors, keep a loose camp on the western coast of Stranglethorn Vale, toward the middle of the shore. Swashbucklers and warlocks gather among the pirates.",
			source = "https://warcraft.wiki.gg/wiki/Bloodsail_Compound",
		},
		["booty bay"] = {
			name = "Booty Bay",
			short = "Visitors on foot enter Booty Bay through the bleached jaws of a giant shark. Beyond them a port city climbs the cliffs around a blue lagoon at the southern tip of Stranglethorn Vale.",
			full = "Visitors on foot enter Booty Bay through the bleached jaws of a giant shark. Beyond them a port city climbs the cliffs around a blue lagoon at the southern tip of Stranglethorn Vale. Life is cheap here and no one is to be trusted. It is a rogue's paradise, full of informants.\n\nThe place was Blackwater Cove once, a small human port, until jungle trolls overran it. Goblins of the Steamwheedle Cartel drove the trolls back from the shore and made the cove their center of operations in the Eastern Kingdoms. That was before the First War.\n\nThe Blackwater Raiders run the port now, in close company with the Cartel, and it serves any traveler whatever banner they follow. Baron Revilgaz rules from the top of the inn, alongside Fleet Master Seahorn of the Raiders, and hires every sword he can against the Bloodsail Buccaneers, who threaten the bay.",
			source = "https://warcraft.wiki.gg/wiki/Booty_Bay",
		},
		["cape of stranglethorn"] = {
			name = "The Cape of Stranglethorn",
			short = "The southern reaches of Stranglethorn Vale lie thick with troll ruins, half-swallowed by jungle, and long stretches of sandy shore where the trees give way to sea.",
			full = "The southern reaches of Stranglethorn Vale lie thick with troll ruins, half-swallowed by jungle, and long stretches of sandy shore where the trees give way to sea. This is the ground of a long quarrel between the goblin pirates of Booty Bay and their rivals, the Bloodsail Buccaneers.",
			source = "https://warcraft.wiki.gg/wiki/Cape_of_Stranglethorn",
		},
		["crystal shore"] = {
			name = "The Crystal Shore",
			short = "The South Seas break on a long sandy shore here, across from the eastern beaches of Jaguero Isle.",
			full = "The South Seas break on a long sandy shore here, across from the eastern beaches of Jaguero Isle. A steep ridge walls the beach off from the land behind it, and only two paths cut through, one of them climbing toward Mistvale Valley. At the north end of the shore stand the Ruins of Aboraz.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Shore",
		},
		["crystalvein mine"] = {
			name = "Crystalvein Mine",
			short = "The rock of Crystalvein Mine, near Zul'Mamwe, holds strange crystals that Crank Fizzlebub called Singing Crystals. They are found nowhere but Stranglethorn and are worth a good deal.",
			full = "The rock of Crystalvein Mine, near Zul'Mamwe, holds strange crystals that Crank Fizzlebub called Singing Crystals. They are found nowhere but Stranglethorn and are worth a good deal. The basilisks that nest here eat them, and that is what hardens their hides. The Venture Company came hoping to harvest the mine, but the basilisks have stopped them so far. Outside the entrance, trolls and humans stand crystallized where they were caught.",
			source = "https://warcraft.wiki.gg/wiki/Crystalvein_Mine",
		},
		["gromgol base camp"] = {
			name = "Grom'gol Base Camp",
			short = "Commander Aggro'gosh holds Grom'gol Base Camp, an orc fort on the western coast. It is heavily fortified against jungle trolls, naga from the surf, and the Alliance men who come in along the shore.",
			full = "Commander Aggro'gosh holds Grom'gol Base Camp, an orc fort on the western coast. It is heavily fortified against jungle trolls, naga from the surf, and the Alliance men who come in along the shore. The camp keeps a safe chain of supply open to Stonard in the Swamp of Sorrows.",
			source = "https://warcraft.wiki.gg/wiki/Grom'gol_Base_Camp",
		},
		["gurubashi arena"] = {
			name = "Gurubashi Arena",
			short = "In ancient times the fights in the Gurubashi Arena were to the death, and the sand turned to mud with troll blood. The Gurubashi Empire raised it when it ruled vast tracts of the south of the Eastern Kingdoms.",
			full = "In ancient times the fights in the Gurubashi Arena were to the death, and the sand turned to mud with troll blood. The Gurubashi Empire raised it when it ruled vast tracts of the south of the Eastern Kingdoms. It stands in the northwest of the Cape of Stranglethorn, just north of Booty Bay, and it has outlasted the empire.\n\nShort John Mithril now oversees matches that are less deadly, with fame and treasure as the prize. Old stories say that anyone who finds a blood-red amulet at midnight will have their soul devoured by a demon before daybreak.",
			source = "https://warcraft.wiki.gg/wiki/Gurubashi_Arena",
		},
		["jaguero isle"] = {
			name = "Jaguero Isle",
			short = "Jaguero Isle lies off the coast of Stranglethorn Vale, a jungle island of panthers and gorillas. King Mukla, an enormous ape, rules there and keeps a tauren, Princess Poobah, captive.",
			full = "Jaguero Isle lies off the coast of Stranglethorn Vale, a jungle island of panthers and gorillas. King Mukla, an enormous ape, rules there and keeps a tauren, Princess Poobah, captive.",
			source = "https://warcraft.wiki.gg/wiki/Jaguero_Isle",
		},
		["janeiros point"] = {
			name = "Janeiro's Point",
			short = "A giant statue of a goblin stands on this small island outside Booty Bay, its arms flung wide. No one knows whose likeness it is. It was built as a beacon to welcome ships to the port.",
			full = "A giant statue of a goblin stands on this small island outside Booty Bay, its arms flung wide. No one knows whose likeness it is. It was built as a beacon to welcome ships to the port. The sea giant Mok'rash has made the island his home.\n\nHe bellows across the water at Captain Smotts, boasting that he has the captain's belt tied around his finger, asking whether Smotts has run out of ships to send, and grumbling that the statue is poor company.",
			source = "https://warcraft.wiki.gg/wiki/Janeiro's_Point",
		},
		["kalai ruins"] = {
			name = "Kal'ai Ruins",
			short = "The Kal'ai Ruins lie half-swallowed by the sea in Stranglethorn Vale, ancient troll stonework worn by tide and age.",
			full = "The Kal'ai Ruins lie half-swallowed by the sea in Stranglethorn Vale, ancient troll stonework worn by tide and age. The Murkgill tribe of murlocs now nests among the fallen columns, having claimed the drowned halls for its own.",
			source = "https://warcraft.wiki.gg/wiki/Kal'ai_Ruins",
		},
		["kurzens compound"] = {
			name = "Kurzen's Compound",
			short = "Colonel Conrad Kurzen's expedition raised this unusual human settlement, east of the Rebel Camp, and it has a lumber mill. Madness has taken Kurzen.",
			full = "Colonel Conrad Kurzen's expedition raised this unusual human settlement, east of the Rebel Camp, and it has a lumber mill. Madness has taken Kurzen. The men who would not follow him broke away and founded the Rebel Camp, and the two sides are locked in a deadly fight, men once of one command killing each other among the trees.\n\nNear the stables, panthers and Stranglethorn tigers sit in cages while the men train them into war beasts.",
			source = "https://warcraft.wiki.gg/wiki/Kurzen's_Compound",
		},
		["lake nazferiti"] = {
			name = "Lake Nazferiti",
			short = "A large base of the goblin Venture Company stands on the shore of Lake Nazferiti. Frenzies and crocolisks fill the water.",
			full = "A large base of the goblin Venture Company stands on the shore of Lake Nazferiti. Frenzies and crocolisks fill the water.\n\nThe Nazferiti river runs through the lake, and it may be the longest river in the southern Eastern Kingdoms. Its source is a waterfall in the Redridge Mountains, though some place its headwaters farther off, in Deadwind Pass.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Nazferiti",
		},
		["mistvale valley"] = {
			name = "Mistvale Valley",
			short = "Mistvale Valley lies in the southern reaches of Stranglethorn Vale, and the great Mistvale gorillas make their home among its trees.",
			full = "Mistvale Valley lies in the southern reaches of Stranglethorn Vale, and the great Mistvale gorillas make their home among its trees.",
			source = "https://warcraft.wiki.gg/wiki/Mistvale_Valley",
		},
		["mizjah ruins"] = {
			name = "Mizjah Ruins",
			short = "The Mizjah Ruins lie southeast of Grom'gol Base Camp, held by Mosh'Ogg Brutes and their witch doctors. From these broken stones the ogres ambush the supply caravans bound for Stonard.",
			full = "The Mizjah Ruins lie southeast of Grom'gol Base Camp, held by Mosh'Ogg Brutes and their witch doctors. From these broken stones the ogres ambush the supply caravans bound for Stonard.",
			source = "https://warcraft.wiki.gg/wiki/Mizjah_Ruins",
		},
		["moshogg ogre mound"] = {
			name = "Mosh'Ogg Ogre Mound",
			short = "The Mosh'Ogg Ogre Mound lies south of Zul'Gurub, its dark hollows home to the Mosh'Ogg tribe of ogres. Deep within, their leader, the ogre mage Mai'Zoth, rules the mound.",
			full = "The Mosh'Ogg Ogre Mound lies south of Zul'Gurub, its dark hollows home to the Mosh'Ogg tribe of ogres. Deep within, their leader, the ogre mage Mai'Zoth, rules the mound.",
			source = "https://warcraft.wiki.gg/wiki/Mosh'Ogg_Ogre_Mound",
		},
		["nekmani wellspring"] = {
			name = "Nek'mani Wellspring",
			short = "On the western edge of Stranglethorn, high in the cliffs above the Southern Savage Coast, a holy spring rises. Its water is the only clean fresh water south of Duskwood.",
			full = "On the western edge of Stranglethorn, high in the cliffs above the Southern Savage Coast, a holy spring rises. Its water is the only clean fresh water south of Duskwood.\n\nScholars quarrel over it, because every race claims the waters were made divine for its own people, and none has settled the matter. An expedition of naga explorers has lately advanced on the spring, and they guard it fiercely.",
			source = "https://warcraft.wiki.gg/wiki/Nek'mani_Wellspring",
		},
		["nesingwarys expedition"] = {
			name = "Nesingwary's Expedition",
			short = "The dwarf Hemet Nesingwary, a master hunter, led an expedition into Stranglethorn to hunt the wild game that crosses the jungle. His camp sits just below the river, north of Lake Nazferiti.",
			full = "The dwarf Hemet Nesingwary, a master hunter, led an expedition into Stranglethorn to hunt the wild game that crosses the jungle. His camp sits just below the river, north of Lake Nazferiti.\n\nHired guns keep watch over it. His servant, Barnil Stonepot, calls him a war hero of the Alliance.",
			source = "https://warcraft.wiki.gg/wiki/Nesingwary's_Expedition",
		},
		["rebel camp"] = {
			name = "Rebel Camp",
			short = "Soldiers of Stormwind who broke with their own colonel built this camp. It stands in the northernmost part of Stranglethorn Vale, west of the road that runs south from Duskwood.",
			full = "Soldiers of Stormwind who broke with their own colonel built this camp. It stands in the northernmost part of Stranglethorn Vale, west of the road that runs south from Duskwood.\n\nColonel Conrad Kurzen led an expedition out of Stormwind, and madness fell on it. Most of his men still follow him. Lieutenant Doren and a small band escaped from Kurzen's Compound, fled west and set up here. Their loyalty is still to Stormwind, and Doren wants Kurzen's head to end the madness.",
			source = "https://warcraft.wiki.gg/wiki/Rebel_Camp",
		},
		["ruins of aboraz"] = {
			name = "Ruins of Aboraz",
			short = "Zanzil the Outcast keeps these ancient troll ruins on the southeastern coast of Stranglethorn Vale. The Skullsplitter tribe exiled him for poisoning his own people.",
			full = "Zanzil the Outcast keeps these ancient troll ruins on the southeastern coast of Stranglethorn Vale. The Skullsplitter tribe exiled him for poisoning his own people.\n\nHere he brews a mixture that leaves whoever drinks it strong and feeble-minded. It has bent ghouls, naga and troll minions to his will, and they wander the ruins.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Aboraz",
		},
		["ruins of jubuwal"] = {
			name = "Ruins of Jubuwal",
			short = "Old troll ruins stand just east of the Gurubashi Arena, beside the main road that runs the length of Stranglethorn Vale. Ghouls, naga and trolls in the service of Zanzil the Outcast have taken them over.",
			full = "Old troll ruins stand just east of the Gurubashi Arena, beside the main road that runs the length of Stranglethorn Vale. Ghouls, naga and trolls in the service of Zanzil the Outcast have taken them over.\n\nTwo men are among them, Jon-Jon the Crow and Maury \"Club Foot\" Wilkins, who owe money to the ruthless \"Sea Wolf\" MacKinley.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Jubuwal",
		},
		["ruins of zulkunda"] = {
			name = "Ruins of Zul'Kunda",
			short = "The Bloodscalp tribe holds the vast jungle troll ruins of Zul'Kunda, in the northwest of Stranglethorn Vale. Nezzliok the Dire and Gan'zulah command here.",
			full = "The Bloodscalp tribe holds the vast jungle troll ruins of Zul'Kunda, in the northwest of Stranglethorn Vale. Nezzliok the Dire and Gan'zulah command here.\n\nThe Bloodscalps broke from the Gurubashi Empire in its civil war. They fight off every intruder, the Skullsplitters included, to keep the land they took. They have only contempt for the Darkspear tribe, the first jungle trolls to join the Horde.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Zul'Kunda",
		},
		["ruins of zulmamwe"] = {
			name = "Ruins of Zul'Mamwe",
			short = "Mountains close in the ruins of Zul'Mamwe on every side except the north. The Skullsplitter tribe lives here, the second great troll tribe of Stranglethorn Vale, under its vicious chieftain, Ana'thek the Cruel.",
			full = "Mountains close in the ruins of Zul'Mamwe on every side except the north. The Skullsplitter tribe lives here, the second great troll tribe of Stranglethorn Vale, under its vicious chieftain, Ana'thek the Cruel.\n\nLike the Bloodscalps, the Skullsplitters broke from the Gurubashi Empire in its civil war. They hold the Darkspear tribe in contempt and fight off every intruder, the nearby Bloodscalps most of all. Their witch doctor, Mogh the Undying, has bent several men of Colonel Conrad Kurzen's expedition to his will and keeps them at his side.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Zul'Mamwe",
		},
		["savage coast"] = {
			name = "The Savage Coast",
			short = "Crocolisks fill the shallows of the Savage Coast, and basilisks live along its shore. Several troll settlements stand beside it.",
			full = "Crocolisks fill the shallows of the Savage Coast, and basilisks live along its shore. Several troll settlements stand beside it.\n\nIt takes up the northern shore of Stranglethorn Vale, from the Westfall border south to Grom'gol Base Camp, on the shore east of the Vile Reef.",
			source = "https://warcraft.wiki.gg/wiki/Savage_Coast",
		},
		["south seas"] = {
			name = "South Seas",
			short = "Between the continents, the South Seas wash the southern shores of the Eastern Kingdoms and Kalimdor. They are a part of the Great Sea, and Zandalar lies out among their islands.",
			full = "Between the continents, the South Seas wash the southern shores of the Eastern Kingdoms and Kalimdor. They are a part of the Great Sea, and Zandalar lies out among their islands. Nearer Stranglethorn Vale, the sea grows treacherous with reefs and small islands, some no more than a sandbar.\n\nIn the Second War the Stormreaver clan caught giant turtles in these waters and used them as submarines for the Horde.",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southern savage coast"] = {
			name = "Southern Savage Coast",
			short = "Beaches and shallow water line the west side of the Cape of Stranglethorn, where the South Seas meet the shore. The coast runs south past Booty Bay and Janeiro's Point to the Wild Shore.",
			full = "Beaches and shallow water line the west side of the Cape of Stranglethorn, where the South Seas meet the shore. The coast runs south past Booty Bay and Janeiro's Point to the Wild Shore.\n\nThe Vile Reef divides it from the Savage Coast to the north. There the Great Sea gives way to the South Seas.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Savage_Coast",
		},
		["spirit den"] = {
			name = "Spirit Den",
			short = "A jungle troll witch doctor named Unbagwa keeps to a hidden cave at the northern end of Mistvale Valley. The valley around the Spirit Den is the range of the great Mistvale gorillas.",
			full = "A jungle troll witch doctor named Unbagwa keeps to a hidden cave at the northern end of Mistvale Valley. The valley around the Spirit Den is the range of the great Mistvale gorillas.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Den",
		},
		["stockpile"] = {
			name = "The Stockpile",
			short = "A cave at the back of Kurzen's Compound serves as the arsenal of Colonel Conrad Kurzen's jungle fighters, who keep their arms and equipment here.",
			full = "A cave at the back of Kurzen's Compound serves as the arsenal of Colonel Conrad Kurzen's jungle fighters, who keep their arms and equipment here. Whatever has gone wrong in the colonel's mind, most of his men still follow him.",
			source = "https://warcraft.wiki.gg/wiki/Stockpile",
		},
		["sunken hollow"] = {
			pending = true,
			name = "Sunken Hollow",
			short = "",
			full = "",
			source = "",
		},
		["tkashi ruins"] = {
			name = "Tkashi Ruins",
			short = "Broken troll walls stand in the jungle southwest of Nesingwary's Expedition. A large band of Bloodscalp trolls lives among them, warriors, axe throwers and shamans.",
			full = "Broken troll walls stand in the jungle southwest of Nesingwary's Expedition. A large band of Bloodscalp trolls lives among them, warriors, axe throwers and shamans. The hunter Hemet Nesingwary wrote that he and his followers passed through the ruins without incident.",
			source = "https://warcraft.wiki.gg/wiki/Tkashi_Ruins",
		},
		["venture co base camp"] = {
			name = "Venture Co. Base Camp",
			short = "Goblins of the Venture Company have cleared a camp beside Lake Nazferiti.",
			full = "Goblins of the Venture Company have cleared a camp beside Lake Nazferiti. Lumberjacks and shredders work the jungle timber while geologists dig the hills for crystals found only in Stranglethorn, which certain buyers value highly.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Base_Camp",
		},
		["venture co operations center"] = {
			name = "Venture Co. Operations Center",
			short = "An oil platform stands on a lake in the northern jungle, built by goblins of the Venture Company. Mechanics and geologists crowd the rig, and the crews press from here deeper into the jungle.",
			full = "An oil platform stands on a lake in the northern jungle, built by goblins of the Venture Company. Mechanics and geologists crowd the rig, and the crews press from here deeper into the jungle. Their hold on these remote works is thin. The jungle trolls are bent on purging their old lands of every foreign invader.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Operations_Center",
		},
		["vile reef"] = {
			name = "The Vile Reef",
			short = "Off the western coast of Stranglethorn Vale, near Grom'gol Base Camp, the sea breaks bright over coral.",
			full = "Off the western coast of Stranglethorn Vale, near Grom'gol Base Camp, the sea breaks bright over coral. Beneath it lie sunken troll ruins, and among that drowned stone the murlocs make their home, moving through halls that once belonged to someone else. The Altar of the Tides still stands there. Giant clams litter the reef floor, and rumor says they hold blue pearls. Wreckage from ships washes in along the shore.",
			source = "https://warcraft.wiki.gg/wiki/Vile_Reef",
		},
		["wild shore"] = {
			name = "Wild Shore",
			short = "The southernmost shore of the Eastern Kingdoms is where the land gives way to the South Seas. The Bloodsail Buccaneers have anchored their fleet off the beach, and a sea giant wanders the sand.",
			full = "The southernmost shore of the Eastern Kingdoms is where the land gives way to the South Seas. The Bloodsail Buccaneers have anchored their fleet off the beach, and a sea giant wanders the sand.\n\nThe land ends in a rocky point at its western edge, with Booty Bay on the north side of it.",
			source = "https://warcraft.wiki.gg/wiki/Wild_Shore",
		},
		["yojamba isle"] = {
			name = "Yojamba Isle",
			short = "Small islands lie off the northwestern coast of Stranglethorn, near the border with Westfall, and the Zandalar tribe has made camp on them.",
			full = "Small islands lie off the northwestern coast of Stranglethorn, near the border with Westfall, and the Zandalar tribe has made camp on them. Hakkar the Soulflayer, an ancient blood god, holds Zul'Gurub and has made it a place of blood and madness. The tribe cannot bring him down alone, and the troll tribes are splintered. So they send word to the Alliance and the Horde, and ask champions of every race to set their war aside long enough to help.",
			source = "https://warcraft.wiki.gg/wiki/Yojamba_Isle",
		},
		["ziatajai ruins"] = {
			name = "Ziata'jai Ruins",
			short = "Troll ruins lie in the jungle here, and the Skullsplitter tribe holds them against every interloper that comes near.",
			full = "Troll ruins lie in the jungle here, and the Skullsplitter tribe holds them against every interloper that comes near.",
			source = "https://warcraft.wiki.gg/wiki/Ziata'jai_Ruins",
		},
		["zulgurub"] = {
			name = "Zul'Gurub",
			short = "Zul'Gurub rises out of the jungle in the northeast of Stranglethorn Vale, a temple city of vine-covered ziggurats and overgrown idols.",
			full = "Zul'Gurub rises out of the jungle in the northeast of Stranglethorn Vale, a temple city of vine-covered ziggurats and overgrown idols. It was the capital of the Gurubashi Empire, and every jungle troll tribe answered to it. Now only the Gurubashi tribe holds it.\n\nLong before the Dark Portal opened, civil war tore the empire apart. A circle of priests called the Atal'ai summoned the avatar of Hakkar the Soulflayer, an ancient blood god, and were driven into exile. The exiles had learned that Hakkar could take physical form only in the old capital.\n\nNow Hakkar dwells in its deepest part. Jin'do the Hexxer has enslaved several Gurubashi high priests to serve him. Champions of the Primal Gods went in to quell the blood god and fell under his sway, and their power feeds him.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Gurub",
		},
		["zuuldaia ruins"] = {
			name = "Zuuldaia Ruins",
			short = "Bloodscalp trolls in numbers live among the ancient ruins on the northern stretch of Stranglethorn's western coast. They drive off every interloper.",
			full = "Bloodscalp trolls in numbers live among the ancient ruins on the northern stretch of Stranglethorn's western coast. They drive off every interloper.",
			source = "https://warcraft.wiki.gg/wiki/Zuuldaia_Ruins",
		},
	},
	-- Swamp of Sorrows: 14 subzones
	[1435] = {
		["fallow sanctuary"] = {
			name = "Fallow Sanctuary",
			short = "A tribe known simply as the Lost Ones lives in this village. They are draenei who came through the Dark Portal, and homesickness has driven them mad and feral.",
			full = "A tribe known simply as the Lost Ones lives in this village. They are draenei who came through the Dark Portal, and homesickness has driven them mad and feral. They attack on sight, and they send assassins and saboteurs against the orcs.",
			source = "https://warcraft.wiki.gg/wiki/Fallow_Sanctuary",
		},
		["harborage"] = {
			name = "The Harborage",
			short = "Magtoor leads a handful of draenei here, in the northern reaches of the swamp. Unlike most of their kind they kept their minds, and they remember their noble roots and live apart from their mad kin.",
			full = "Magtoor leads a handful of draenei here, in the northern reaches of the swamp. Unlike most of their kind they kept their minds, and they remember their noble roots and live apart from their mad kin. Magtoor has had the grim task of killing those who were once his own brethren.\n\nThe village deals with both the Horde and the Alliance. The Lost Ones of the Fallow Sanctuary are at open war with it, and Noboru and his gang wander the swamp killing any who cross their path.",
			source = "https://warcraft.wiki.gg/wiki/Harborage",
		},
		["ithariuss cave"] = {
			name = "Itharius's Cave",
			short = "A mysterious high elf named Itharius lives in this cave, in the far southwestern corner of the swamp.",
			full = "A mysterious high elf named Itharius lives in this cave, in the far southwestern corner of the swamp. Unruly green whelps scrap and stumble on the ground outside, and Itharius has taken it upon himself to watch over them while they grow.",
			source = "https://warcraft.wiki.gg/wiki/Itharius's_Cave",
		},
		["misty reed post"] = {
			name = "Misty Reed Post",
			short = "Tok'Kar holds this small outpost for Stonard, with Katar, a few hunters and a shaman from the town. It sits between the Stagalbog and the Misty Reed Strand.",
			full = "Tok'Kar holds this small outpost for Stonard, with Katar, a few hunters and a shaman from the town. It sits between the Stagalbog and the Misty Reed Strand. It is a camp with no burrow and no tower, and Tok'Kar dreams of a burrow here, or at least a tower.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Post",
		},
		["misty reed strand"] = {
			name = "Misty Reed Strand",
			short = "Driftwood and debris line this gloomy stretch of coast, with little else along its vast beach. Crocolisks and crabs share the shore with murlocs.",
			full = "Driftwood and debris line this gloomy stretch of coast, with little else along its vast beach. Crocolisks and crabs share the shore with murlocs.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Strand",
		},
		["misty valley"] = {
			name = "Misty Valley",
			short = "Mist hangs low in this valley in the northwestern corner of the swamp, north of the way into Deadwind Pass, and swampwalkers and tangled horrors crowd it.",
			full = "Mist hangs low in this valley in the northwestern corner of the swamp, north of the way into Deadwind Pass, and swampwalkers and tangled horrors crowd it. The Mire Lord, an elemental, keeps to a cave deep at the back.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Valley",
		},
		["pool of tears"] = {
			name = "Pool of Tears",
			short = "The Pool of Tears lies broad and still on the eastern edge of the Swamp of Sorrows.",
			full = "The Pool of Tears lies broad and still on the eastern edge of the Swamp of Sorrows. Beneath its calm surface sits the drowned troll temple of Atal'Hakkar, and members of the green dragonflight keep watch over the ground nearby and over the ruin below.\n\nBloodthirsty frenzies swim in the water. Broken Atal'ai stonework lies along the shore and under the surface.",
			source = "https://warcraft.wiki.gg/wiki/Pool_of_Tears",
		},
		["shifting mire"] = {
			name = "The Shifting Mire",
			short = "The fine silt of the Shifting Mire never lies still. A mysterious force gathers it into drifts and drags it across the ground, curling and pooling as though it were alive.",
			full = "The fine silt of the Shifting Mire never lies still. A mysterious force gathers it into drifts and drags it across the ground, curling and pooling as though it were alive. The Mire makes up the central bulk of the swamp, west of the Pool of Tears. Crocolisks and swamp jaguars hunt in it, and Lost Ones wander through.",
			source = "https://warcraft.wiki.gg/wiki/Shifting_Mire",
		},
		["sorrowmurk"] = {
			name = "Sorrowmurk",
			short = "Green dragonspawn crawl through the mire here, just east of the Pool of Tears and the Temple of Atal'Hakkar. A large green drake patrols the region.",
			full = "Green dragonspawn crawl through the mire here, just east of the Pool of Tears and the Temple of Atal'Hakkar. A large green drake patrols the region. Only the boldest travelers go in.",
			source = "https://warcraft.wiki.gg/wiki/Sorrowmurk",
		},
		["splinterspear junction"] = {
			name = "Splinterspear Junction",
			short = "The road into the swamp forks here. One branch runs north and the other runs south toward Stonard. An old orcish watch tower stands at the fork, and Horde guards patrol the crossing.",
			full = "The road into the swamp forks here. One branch runs north and the other runs south toward Stonard. An old orcish watch tower stands at the fork, and Horde guards patrol the crossing.",
			source = "https://warcraft.wiki.gg/wiki/Splinterspear_Junction",
		},
		["stagalbog"] = {
			name = "Stagalbog",
			short = "Dense marshland lies south of the Pool of Tears, where the swamp runs up against the mountains that close it in on the south. A cave opens into the rock at the mountains' edge.",
			full = "Dense marshland lies south of the Pool of Tears, where the swamp runs up against the mountains that close it in on the south. A cave opens into the rock at the mountains' edge.",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog",
		},
		["stagalbog cave"] = {
			name = "Stagalbog Cave",
			short = "Many murlocs of the Marsh tribe live in this large cave in the eastern marsh, under their leader, the Swamp Talker.",
			full = "Many murlocs of the Marsh tribe live in this large cave in the eastern marsh, under their leader, the Swamp Talker.",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog_Cave",
		},
		["stonard"] = {
			name = "Stonard",
			short = "Orcs of the Old Horde raised Stonard in the Black Morass soon after the Dark Portal first opened. It is one of the oldest orcish settlements on Azeroth, and the First War left it badly damaged.",
			full = "Orcs of the Old Horde raised Stonard in the Black Morass soon after the Dark Portal first opened. It is one of the oldest orcish settlements on Azeroth, and the First War left it badly damaged. After Thrall took command of the Horde, the orcs rebuilt it.\n\nIt is the Horde's only town in the Swamp of Sorrows. A great hall still stands in its midst, a rare thing among orcish communities, and two burrows guard the approach. Patrols range out from it, and small encampments nearby strengthen the Horde's hold on the region. The swamp is still largely unmapped to the orcs, and they send wayfinders and cartographers from here to chart it. Researchers have come to study its ancient magical artifacts and its plants and beasts.",
			source = "https://warcraft.wiki.gg/wiki/Stonard",
		},
		["temple of atalhakkar"] = {
			name = "The Temple of Atal'Hakkar",
			short = "More than a thousand years ago, the Gurubashi Empire was torn apart by civil war. At its heart were the Atal'ai, troll priests who sought to bring the blood god Hakkar the Soulflayer back into the world.",
			full = "More than a thousand years ago, the Gurubashi Empire was torn apart by civil war. At its heart were the Atal'ai, troll priests who sought to bring the blood god Hakkar the Soulflayer back into the world. They were defeated and driven out, and they fled north into the Swamp of Sorrows. There they raised a great temple to prepare for his coming.\n\nYsera the Dreamer, Aspect of the green dragonflight, learned of their plan and smashed the temple down beneath the marsh. Green dragons guard the drowned ruins, and they let no one in or out. It is believed that some of the fanatical Atal'ai lived through her wrath and went back to the dark service of Hakkar. Their master, Jammal'an the Prophet, leads them in the temple.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Atal'Hakkar",
		},
	},
	-- Westfall: 17 subzones
	[1436] = {
		["alexston farmstead"] = {
			name = "Alexston Farmstead",
			short = "The fields at Alexston Farmstead once fed families, before the Defias Brotherhood took the land.",
			full = "The fields at Alexston Farmstead once fed families, before the Defias Brotherhood took the land. It is one of many farms in northern and central Westfall that the Brotherhood now holds, and mechanical harvest golems roam its furrows, guarding rows that no one plants anymore.\n\nBaros Alexston, an architect in the service of Stormwind, worked these fields as a boy, before the land that shaped him passed into other hands.",
			source = "https://warcraft.wiki.gg/wiki/Alexston_Farmstead",
		},
		["dagger hills"] = {
			name = "The Dagger Hills",
			short = "Behind Moonbrook, a long ridge of hills runs through the south of Westfall. Little lives there. Defias knuckledusters, pathstalkers and highwaymen watch the ground.",
			full = "Behind Moonbrook, a long ridge of hills runs through the south of Westfall. Little lives there. Defias knuckledusters, pathstalkers and highwaymen watch the ground. A jovial dwarf brewer named Grimbooze Thunderbrew keeps to the hills and speaks in rhymes, and the ghoul Leprithus is known to rise out of the earth nearby.",
			source = "https://warcraft.wiki.gg/wiki/Dagger_Hills",
		},
		["dead acre"] = {
			name = "The Dead Acre",
			short = "A farm once stood here in the southeast of Westfall, close to the bridge into Duskwood. The Defias Brotherhood burned it and the fields around it.",
			full = "A farm once stood here in the southeast of Westfall, close to the bridge into Duskwood. The Defias Brotherhood burned it and the fields around it. No farmer walks the ground now. Smoking ruins remain, and harvest golems roam the smoldering acres.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Acre",
		},
		["deadmines"] = {
			name = "The Deadmines",
			short = "Before the First War, the tunnels beneath Moonbrook were the greatest gold mine in human lands. The First War emptied them of miners, and afterward they were left alone and thought haunted.",
			full = "Before the First War, the tunnels beneath Moonbrook were the greatest gold mine in human lands. The First War emptied them of miners, and afterward they were left alone and thought haunted. Later a crew from the Miners' League worked part of the tunnels under Foreman Thistlenettle. The Defias Brotherhood attacked them at their work, a tunnel fell in, and the miners who died there walk the dark as restless undead.\n\nThe Brotherhood has made the mines its headquarters. Edwin VanCleef is building a juggernaut at the bottom of them with the help of goblins, a ship meant to destroy Stormwind from the sea.",
			source = "https://warcraft.wiki.gg/wiki/Deadmines",
		},
		["demonts place"] = {
			name = "Demont's Place",
			short = "Little remains of the old farmstead at Demont's Place, west of Moonbrook. Defias agents occupy it now and hold it as their own.",
			full = "Little remains of the old farmstead at Demont's Place, west of Moonbrook. Defias agents occupy it now and hold it as their own.",
			source = "https://warcraft.wiki.gg/wiki/Demont's_Place",
		},
		["dust plains"] = {
			name = "The Dust Plains",
			short = "The southern end of Westfall is dry, open ground. Gnolls hold a few camps there and threaten anyone who crosses it.",
			full = "The southern end of Westfall is dry, open ground. Gnolls hold a few camps there and threaten anyone who crosses it. On the eastern edge stands an old mage tower, now a Defias stronghold called Klaven's Tower after its master, the Defias rogue Klaven Mortwake. It is a well known launching point for the Brotherhood's activity.",
			source = "https://warcraft.wiki.gg/wiki/Dust_Plains",
		},
		["furlbrows pumpkin farm"] = {
			name = "Furlbrow's Pumpkin Farm",
			short = "Farmer Furlbrow and his wife Verna kept a pumpkin farm here until the Defias Brotherhood swept through Westfall with their mechanical harvest golems and took it.",
			full = "Farmer Furlbrow and his wife Verna kept a pumpkin farm here until the Defias Brotherhood swept through Westfall with their mechanical harvest golems and took it. Defias now hold the farm buildings. The Furlbrows fled to the road in the north of Westfall, leaving their pumpkins behind.",
			source = "https://warcraft.wiki.gg/wiki/Furlbrow's_Pumpkin_Farm",
		},
		["gold coast quarry"] = {
			name = "Gold Coast Quarry",
			short = "For a long time the pits of Gold Coast Quarry gave Stormwind gold and ore, before Westfall fell into ruin. The Defias Brotherhood owns the quarry now and patrols its stone.",
			full = "For a long time the pits of Gold Coast Quarry gave Stormwind gold and ore, before Westfall fell into ruin. The Defias Brotherhood owns the quarry now and patrols its stone.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Coast_Quarry",
		},
		["jangolode mine"] = {
			name = "Jangolode Mine",
			short = "Kobolds occupy the shafts of the Jangolode Mine now, and it is rumored that the Defias Brotherhood has dealings with them. The mine was one of the main ore sources in Westfall, and its ore went to Stormwind.",
			full = "Kobolds occupy the shafts of the Jangolode Mine now, and it is rumored that the Defias Brotherhood has dealings with them. The mine was one of the main ore sources in Westfall, and its ore went to Stormwind.",
			source = "https://warcraft.wiki.gg/wiki/Jangolode_Mine",
		},
		["jansen stead"] = {
			name = "The Jansen Stead",
			short = "The northernmost farm in Westfall, the Jansen Stead, stands close to the bridge into Elwynn Forest. Its owners were driven off by the Defias Brotherhood, whose agents and harvest golems control it now.",
			full = "The northernmost farm in Westfall, the Jansen Stead, stands close to the bridge into Elwynn Forest. Its owners were driven off by the Defias Brotherhood, whose agents and harvest golems control it now.",
			source = "https://warcraft.wiki.gg/wiki/Jansen_Stead",
		},
		["longshore"] = {
			name = "Longshore",
			short = "Westfall's coast runs long and wide, one of the biggest beaches in Azeroth. Murlocs roam it in swarms, and Old Murk-Eye roams among them.",
			full = "Westfall's coast runs long and wide, one of the biggest beaches in Azeroth. Murlocs roam it in swarms, and Old Murk-Eye roams among them. Off the coast lie the wrecks of many ships, elven destroyers among them.\n\nOn the far southwestern coast stands the farm of Daphne Stilwell. The Defias Brotherhood has all but taken over the land around it.",
			source = "https://warcraft.wiki.gg/wiki/Longshore",
		},
		["molsen farm"] = {
			name = "The Molsen Farm",
			short = "The Molsen Farm lies among the many farmsteads of Westfall held by the Defias Brotherhood. The Brotherhood's harvest golems patrol its fields, striking down anyone who wanders too close.",
			full = "The Molsen Farm lies among the many farmsteads of Westfall held by the Defias Brotherhood. The Brotherhood's harvest golems patrol its fields, striking down anyone who wanders too close.",
			source = "https://warcraft.wiki.gg/wiki/Molsen_Farm",
		},
		["moonbrook"] = {
			name = "Moonbrook",
			short = "Moonbrook was a mining town and the center of Westfall's farmland, the breadbasket of the kingdom. Before the orcs came, the gold deposits beneath it made up a third of Stormwind's treasury.",
			full = "Moonbrook was a mining town and the center of Westfall's farmland, the breadbasket of the kingdom. Before the orcs came, the gold deposits beneath it made up a third of Stormwind's treasury. The orcs razed it in the First War, among the last towns to fall before they destroyed Stormwind Keep, and it was rebuilt after the Second War.\n\nThe Defias Brotherhood holds it now. They drove out the townsfolk, and only a few Defias stay on above ground as sentries. The rest live below, in the old mining tunnels beneath the town.",
			source = "https://warcraft.wiki.gg/wiki/Moonbrook",
		},
		["saldeans farm"] = {
			name = "Saldean's Farm",
			short = "Farmer Saldean and his wife Salma have refused to leave. This is the one farm in Westfall the Defias Brotherhood never overran, though harvest golems of the Brotherhood roam its fields.",
			full = "Farmer Saldean and his wife Salma have refused to leave. This is the one farm in Westfall the Defias Brotherhood never overran, though harvest golems of the Brotherhood roam its fields. The farmhouse has been a halfway house for years, and the couple do what they can to keep their guests alive.",
			source = "https://warcraft.wiki.gg/wiki/Saldean's_Farm",
		},
		["sentinel hill"] = {
			name = "Sentinel Hill",
			short = "Sentinel Hill stands on high ground in eastern Westfall. A tower watches from the top, and below it on the slope are cottages, a forge, an inn and a lumber mill.",
			full = "Sentinel Hill stands on high ground in eastern Westfall. A tower watches from the top, and below it on the slope are cottages, a forge, an inn and a lumber mill. Gryan Stoutmantle's People's Militia holds the hill as the last military bastion in the region and calls on anyone willing to fight the Defias. Stormwind gives it little help.",
			source = "https://warcraft.wiki.gg/wiki/Sentinel_Hill",
		},
		["stendels pond"] = {
			name = "Stendel's Pond",
			short = "A small pond lies southwest of Sentinel Hill. Gnolls ring it, and a few old bones and two graves lie at its edge, which hints that the water is no longer fit to drink.",
			full = "A small pond lies southwest of Sentinel Hill. Gnolls ring it, and a few old bones and two graves lie at its edge, which hints that the water is no longer fit to drink.",
			source = "https://warcraft.wiki.gg/wiki/Stendel's_Pond",
		},
		["westfall lighthouse"] = {
			name = "Westfall Lighthouse",
			short = "The lighthouse stands off the far southern coast of Westfall, and at night its beam still circles out over the water, though the hand that keeps it belongs to a dead man.",
			full = "The lighthouse stands off the far southern coast of Westfall, and at night its beam still circles out over the water, though the hand that keeps it belongs to a dead man. The ghost of Captain Grayson keeps the light. In life he was a pirate captain whose ship broke on the rocks one night when the lighthouse was dark. After he died he came to the tower and watched Old Murk-Eye drive the keeper's family away.\n\nThe family returned and relit the flame. Old Murk-Eye came back with the murlocs of the coast, and this time the family died before Grayson's eyes. No one is left to tend the light but him, and he stands guard outside the tower.",
			source = "https://warcraft.wiki.gg/wiki/Westfall_Lighthouse",
		},
	},
	-- Wetlands: 29 subzones
	[1437] = {
		["angerfang encampment"] = {
			name = "Angerfang Encampment",
			short = "Angerfang Encampment sprawls across the central Wetlands, the largest camp the Dragonmaw clan holds in the region, home to the Angerfang orcs.",
			full = "Angerfang Encampment sprawls across the central Wetlands, the largest camp the Dragonmaw clan holds in the region, home to the Angerfang orcs. Nek'rosh Skullcrusher, son of Nekros Skullcrusher, commands them and means to make the camp the gathering place for an attack on Menethil Harbor. He has ordered catapults built for the assault.",
			source = "https://warcraft.wiki.gg/wiki/Angerfang_Encampment",
		},
		["baradin bay"] = {
			name = "Baradin Bay",
			short = "The waters of Baradin Bay wash the coast where Khaz Modan meets Lordaeron. The bay's history lies broken along its bottom.",
			full = "The waters of Baradin Bay wash the coast where Khaz Modan meets Lordaeron. The bay's history lies broken along its bottom. The Kul Tiran navy patrolled it regularly during and after the Second War, and its Third Fleet was destroyed in that war. Some of the wrecks lie shattered along the coast of the Wetlands, and others went down to the dark bottom of the sea.\n\nMurlocs and crocolisks drift in the shallows. Crabs and sharks hold the deeper water.",
			source = "https://warcraft.wiki.gg/wiki/Baradin_Bay",
		},
		["black channel marsh"] = {
			name = "Black Channel Marsh",
			short = "Raptors have their lairs all through Black Channel Marsh, in the southwestern Wetlands. The road to Menethil Harbor skirts the marsh, and the hungrier raptors wander close to the roadside.",
			full = "Raptors have their lairs all through Black Channel Marsh, in the southwestern Wetlands. The road to Menethil Harbor skirts the marsh, and the hungrier raptors wander close to the roadside.",
			source = "https://warcraft.wiki.gg/wiki/Black_Channel_Marsh",
		},
		["bluegill marsh"] = {
			name = "Bluegill Marsh",
			short = "Several camps of Bluegill murlocs stand in the marshes of the western Wetlands. The murlocs here move in groups of two or three, and Gobbler, the fiercest of them, leads them.",
			full = "Several camps of Bluegill murlocs stand in the marshes of the western Wetlands. The murlocs here move in groups of two or three, and Gobbler, the fiercest of them, leads them.",
			source = "https://warcraft.wiki.gg/wiki/Bluegill_Marsh",
		},
		["deepwater tavern"] = {
			name = "Deepwater Tavern",
			short = "Fights break out often in the Deepwater Tavern, and Tapoke \"Slim\" Jahn starts many of them. It is a busy gathering place in Menethil Harbor.",
			full = "Fights break out often in the Deepwater Tavern, and Tapoke \"Slim\" Jahn starts many of them. It is a busy gathering place in Menethil Harbor.",
			source = "https://warcraft.wiki.gg/wiki/Deepwater_Tavern",
		},
		["direforge hill"] = {
			name = "Direforge Hill",
			short = "Dark Iron dwarves keep a major campsite on Direforge Hill, in the northeastern Wetlands. The warlock Balgaras the Foul leads them.",
			full = "Dark Iron dwarves keep a major campsite on Direforge Hill, in the northeastern Wetlands. The warlock Balgaras the Foul leads them.",
			source = "https://warcraft.wiki.gg/wiki/Direforge_Hill",
		},
		["dragonmaw gates"] = {
			name = "Dragonmaw Gates",
			short = "Four grand gates block the winding path that climbs from the Wetlands to Grim Batol. The red dragonflight guards them under the mighty drake Axtroz and holds the way against anyone who comes near.",
			full = "Four grand gates block the winding path that climbs from the Wetlands to Grim Batol. The red dragonflight guards them under the mighty drake Axtroz and holds the way against anyone who comes near. Outside the gates, along the road, lie the ruins of an orc caravan that tried to flee the fortress.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmaw_Gates",
		},
		["dragonmaw retreat"] = {
			name = "Dragonmaw Retreat",
			short = "Dragonmaw orcs hold a camp along the road here. Soulbinders, infiltrators and reclaimers stand among them, and they swear that Grim Batol will be theirs once more.",
			full = "Dragonmaw orcs hold a camp along the road here. Soulbinders, infiltrators and reclaimers stand among them, and they swear that Grim Batol will be theirs once more.",
			source = "",
		},
		["drunken dwarf"] = {
			name = "The Drunken Dwarf",
			short = "The dwarf Agriel Firebrew and the others who run this tavern turned an old outlook that their kingdom was tired of maintaining into a tavern, and they have kept it for well over a year.",
			full = "The dwarf Agriel Firebrew and the others who run this tavern turned an old outlook that their kingdom was tired of maintaining into a tavern, and they have kept it for well over a year. Word has spread, and traders and merchants want their brews on its shelves and their jerky on its plates. The dwarves mind their own business and let folk come as they may.",
			source = "",
		},
		["dun algaz"] = {
			name = "Dun Algaz",
			short = "The tunnel through Dun Algaz is older than the War of the Three Hammers. When that war drove the Wildhammer dwarves out of Ironforge, they passed through here.",
			full = "The tunnel through Dun Algaz is older than the War of the Three Hammers. When that war drove the Wildhammer dwarves out of Ironforge, they passed through here.\n\nThe Horde retreated this way too. Beaten back from Dun Modr in the Second War, the orcs fell south across the Thandol Valley and dug in at the outpost here. Anduin Lothar, wanting them pushed clear out of Khaz Modan, sent his forces to tear the stronghold down. The assault failed. The orcs held on, and Dun Algaz became the last ground the Horde kept in the region.\n\nThe dwarven mountaineers who watch this pass kept mostly to the hills above it, but the Dragonmaw clan has overrun their post and driven them back to the upper tunnel. With the lower pass lost, the road between the dwarven homelands and Menethil Harbor has grown far more dangerous.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["dun modr"] = {
			name = "Dun Modr",
			short = "Whoever holds the old dwarven city of Dun Modr commands the country around it, and it has changed hands often.",
			full = "Whoever holds the old dwarven city of Dun Modr commands the country around it, and it has changed hands often. In the Second War the Horde built an outpost beside its ruins and used it as a staging ground, beating back Alliance troops and raiding the farmlands nearby. Warriors from Stromgarde laid siege and drove the orcs south, but the Horde struck back and took the place again. When Anduin Lothar pushed the Horde back through Thandol Span, the city came back into Alliance hands and stayed there after the war.\n\nNow the Dark Iron dwarves have it. While Ironforge's soldiers died in wars far from home, the Dark Irons under the warlock Balgaras the Foul laid waste to the Span, and southern Dun Modr fell soon after. A blacksmith's shop and an inn with a brewery still stand among the wreckage.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Modr",
		},
		["excavation site wetlands"] = {
			name = "Excavation Site: Wetlands",
			short = "A dwarven dig site stands here, and Dragonmaw orcs have taken over its workings. Their thaumaturgists summon fire elementals and their saboteurs carry bombs.",
			full = "A dwarven dig site stands here, and Dragonmaw orcs have taken over its workings. Their thaumaturgists summon fire elementals and their saboteurs carry bombs. Cave stalkers and leech stalkers, great spiders, crawl through the diggings.",
			source = "",
		},
		["green belt"] = {
			name = "The Green Belt",
			short = "Crocolisks, bog beasts and oozes fill the Green Belt in the eastern Wetlands. Rethiel the Greenwarden, a bog beast himself, watches over the land here.",
			full = "Crocolisks, bog beasts and oozes fill the Green Belt in the eastern Wetlands. Rethiel the Greenwarden, a bog beast himself, watches over the land here. Gnolls have pushed into the marsh, and some of his lesser bog beast kin have been corrupted.\n\nA wrecked Dragonmaw caravan lies in the Belt, red whelps denning among its ruin. It seems to have been broken when the freed dragons turned on the clan.",
			source = "https://warcraft.wiki.gg/wiki/Green_Belt",
		},
		["grim batol"] = {
			name = "Grim Batol",
			short = "The walls and spires of Grim Batol rise in the eastern Wetlands toward a steel-gray sky, but most of the fortress lies underground.",
			full = "The walls and spires of Grim Batol rise in the eastern Wetlands toward a steel-gray sky, but most of the fortress lies underground. The Wildhammer dwarves founded it and lived there until a curse fell on it in the War of the Three Hammers. They left it empty.\n\nIn the Second War, Orgrim Doomhammer sent the Dragonmaw clan to take the empty fortress. They held the dragon queen Alexstrasza prisoner in its depths and forced the red dragons to serve the Horde. Their hold broke when the dragons were freed and burned the orcs who had enslaved them.\n\nMost thought the fortress's evil had died with the clan. The dwarves sensed a darkness still in the mountain and left. Now Alexstrasza has set red dragonkin around it, and they let no one enter.",
			source = "https://warcraft.wiki.gg/wiki/Grim_Batol",
		},
		["ironbeards tomb"] = {
			name = "Ironbeard's Tomb",
			short = "Over the graveyard at Ironbeard's Tomb stands a statue of a dwarf, carved, it seems, in the likeness of Ironbeard himself. The crypt lies just west of the road to Dun Modr, in the north-central Wetlands.",
			full = "Over the graveyard at Ironbeard's Tomb stands a statue of a dwarf, carved, it seems, in the likeness of Ironbeard himself. The crypt lies just west of the road to Dun Modr, in the north-central Wetlands. Oozes of black, crimson and monstrous kinds have defiled it, and no one who wishes to bury their dead comes here any longer.",
			source = "https://warcraft.wiki.gg/wiki/Ironbeard's_Tomb",
		},
		["lost fleet"] = {
			name = "The Lost Fleet",
			short = "The Wave Mistress and the Intrepid lie on the seabed of Baradin Bay, off the coast of northern Bluegill Marsh.",
			full = "The Wave Mistress and the Intrepid lie on the seabed of Baradin Bay, off the coast of northern Bluegill Marsh. They belonged to the Kul Tiran Third Fleet, commanded in the Second War by Derek Proudmoore, elder son of Lord Admiral Daelin Proudmoore. At the Battle of Crestfall, red dragons enslaved by the Dragonmaw clan fell on the fleet and set it ablaze. Derek climbed the crow's nest to warn his father, and a dragon killed him there. His ship went down soon after. Only First Mate Fitzsimmons of the Wave Mistress lived.\n\nThe dead did not rest. A curse has bound the sunken crews into undeath. Only First Mate Snellig kept his mind, and his ghost walks the nearby shore.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Fleet",
		},
		["lost marsh"] = {
			name = "Lost Marsh",
			short = "A great crocolisk called Saltspine patrols the Lost Marsh, past the diggings of the Wetlands excavation site.",
			full = "A great crocolisk called Saltspine patrols the Lost Marsh, past the diggings of the Wetlands excavation site.",
			source = "",
		},
		["menethil bay"] = {
			name = "Menethil Bay",
			short = "Crocolisks of every age and size crowd Menethil Bay, and hunters take them for their fine leather. The bay is an inlet of Baradin Bay, lying between Menethil Harbor and the northern cliffs of Dun Morogh.",
			full = "Crocolisks of every age and size crowd Menethil Bay, and hunters take them for their fine leather. The bay is an inlet of Baradin Bay, lying between Menethil Harbor and the northern cliffs of Dun Morogh. At its entrance rests the wreck of the Flying Osprey, a ship of the Kul Tiran Third Fleet.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Bay",
		},
		["menethil harbor"] = {
			name = "Menethil Harbor",
			short = "The wall is the first thing anyone notices, thick stone thrown up around a harbor town on a small island off the western shore.",
			full = "The wall is the first thing anyone notices, thick stone thrown up around a harbor town on a small island off the western shore. Four towers rise above it, and there is no way in but the bridge, the sea, or a secret path running underground to the mainland. Sailors, travelers, smugglers and pirates fill its streets.\n\nThe Horde built the first shipyard here. After the First War, Warchief Orgrim Doomhammer chose this shore as the place to build the fleet that would carry his army past Lordaeron's ground defenses, and the orcs stripped iron and timber from the dwarven mines of Khaz Modan to make it. When the Second War ended, the Alliance took the place and rebuilt it as a harbor town. Grand Admiral Daelin Proudmoore named it Menethil Harbor, for King Terenas Menethil II of Lordaeron. Raptors out of the hills strike at the town now and then, never in great numbers.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Harbor",
		},
		["menethil keep"] = {
			name = "Menethil Keep",
			short = "Captain Stoutfist commands the Menethil militia from Menethil Keep, whose four towers watch over the harbor town below like stern guardians.",
			full = "Captain Stoutfist commands the Menethil militia from Menethil Keep, whose four towers watch over the harbor town below like stern guardians.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Keep",
		},
		["mosshide fen"] = {
			name = "Mosshide Fen",
			short = "The Mosshide gnolls hold this waterlogged fen in the eastern Wetlands, and their camps dot the ground. Their vicious leader Gnawbone orders the tribe to seize any stranger seen in the marsh and eat them.",
			full = "The Mosshide gnolls hold this waterlogged fen in the eastern Wetlands, and their camps dot the ground. Their vicious leader Gnawbone orders the tribe to seize any stranger seen in the marsh and eat them.",
			source = "https://warcraft.wiki.gg/wiki/Mosshide_Fen",
		},
		["raptor ridge"] = {
			name = "Raptor Ridge",
			short = "Raptors lair in large numbers along Raptor Ridge, in the eastern Wetlands, just northwest of the dangerous Dragonmaw Gates. A cavern in the ridge shelters the fierce Razormaw Matriarch, who watches over her brood.",
			full = "Raptors lair in large numbers along Raptor Ridge, in the eastern Wetlands, just northwest of the dangerous Dragonmaw Gates. A cavern in the ridge shelters the fierce Razormaw Matriarch, who watches over her brood.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Ridge",
		},
		["saltspray glen"] = {
			name = "Saltspray Glen",
			short = "When a strong wind blows off the bay, the ocean throws its spray far inland at Saltspray Glen. That is how the glen got its name.",
			full = "When a strong wind blows off the bay, the ocean throws its spray far inland at Saltspray Glen. That is how the glen got its name. It is a small stretch of the northwestern Wetlands, open to Baradin Bay on the north and west. Raptors nest thickly here.",
			source = "https://warcraft.wiki.gg/wiki/Saltspray_Glen",
		},
		["site of the guardian"] = {
			name = "Site of the Guardian",
			short = "An elemental golem called the Relic Guardian stands at the Site of the Guardian, inside the Wetlands excavation site.",
			full = "An elemental golem called the Relic Guardian stands at the Site of the Guardian, inside the Wetlands excavation site.",
			source = "",
		},
		["stalkers thicket"] = {
			name = "Stalker's Thicket",
			short = "Raptors hold Stalker's Thicket, in the excavation site in the Wetlands.",
			full = "Raptors hold Stalker's Thicket, in the excavation site in the Wetlands. Hunters, lurkers and stalkers that slip out of sight move through it with their young and a matriarch, and a raptor called Shadetooth walks its path with two of the hunters beside it.",
			source = "",
		},
		["sundown marsh"] = {
			name = "Sundown Marsh",
			short = "The deepest part of the Wetlands lies in the northwest, in Sundown Marsh.",
			full = "The deepest part of the Wetlands lies in the northwest, in Sundown Marsh. Here stands Swiftgear Station, a small stone dwelling with a windmill, where an odd couple named Fradd Swiftgear and Wenna Silkbeard make their home. They sell peculiar things they find in the marsh. All around them the swamp is full of aggressive crocolisks, gnolls, raptors, bog beasts and oozes.",
			source = "https://warcraft.wiki.gg/wiki/Sundown_Marsh",
		},
		["thandol span"] = {
			name = "Thandol Span",
			short = "Two great stone arches carry the road over the gap between the Wetlands and the Arathi Highlands, one of the greatest engineering works the dwarves ever finished.",
			full = "Two great stone arches carry the road over the gap between the Wetlands and the Arathi Highlands, one of the greatest engineering works the dwarves ever finished. Dwarves raised them after the War of the Three Hammers, when Ironforge wanted to keep trade and ties with its Wildhammer cousins in Aerie Peak. The bridges served as both road and symbol between the two dwarven kingdoms, and the trade enriched both. The Anvilmar family has guarded the Span for at least three generations.\n\nNow the bridges are scarred. The Dark Iron dwarves struck, and one arch was all but destroyed. Dwarven forces fought fiercely to defend the other and to retake the nearby town of Dun Modr, and many of them died.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thelgen rock"] = {
			name = "Thelgen Rock",
			short = "A great cavern runs deep into the mountains of the southern Wetlands, and the place takes its name, Thelgen Rock, from it.",
			full = "A great cavern runs deep into the mountains of the southern Wetlands, and the place takes its name, Thelgen Rock, from it. Poisonous spiders crawl through the caves, and veins of incendicite ore lie somewhere in the deeper tunnels.",
			source = "https://warcraft.wiki.gg/wiki/Thelgen_Rock",
		},
		["whelgars excavation site"] = {
			name = "Whelgar's Excavation Site",
			short = "Dwarves came to dig here in peace, east of Menethil Harbor. Then mottled raptors overran the site.",
			full = "Dwarves came to dig here in peace, east of Menethil Harbor. Then mottled raptors overran the site. A small group of dwarves, Prospector Whelgar and his crew among them, is trapped on a ridge above their own excavation, with raptors roaming the pits below.",
			source = "https://warcraft.wiki.gg/wiki/Whelgar's_Excavation_Site",
		},
	},
	-- Teldrassil: 16 subzones
	[1438] = {
		["aldrassil"] = {
			name = "Aldrassil",
			short = "Aldrassil rises at the heart of Shadowglen, a giant tree with a village in its boughs.",
			full = "Aldrassil rises at the heart of Shadowglen, a giant tree with a village in its boughs. Tenaron Stormgrip, the leader of Shadowglen, makes his home inside the very top, above the reach of the settlement below, and watches over the glen from there. From the crown he sends promising young night elves out into the world.",
			source = "https://warcraft.wiki.gg/wiki/Aldrassil",
		},
		["banethil barrow den"] = {
			name = "Ban'ethil Barrow Den",
			short = "The night elves built Ban'ethil Barrow Den as one of their sacred places, a barrow where sleeping druids of the Talon could rest. It has two parts, the Lower Den and the Upper Den.",
			full = "The night elves built Ban'ethil Barrow Den as one of their sacred places, a barrow where sleeping druids of the Talon could rest. It has two parts, the Lower Den and the Upper Den. The corrupted furbolgs of the Gnarlpine tribe have taken it over, and it is a dangerous place for a lone night elf to enter.",
			source = "https://warcraft.wiki.gg/wiki/Ban'ethil_Barrow_Den",
		},
		["banethil hollow"] = {
			name = "Ban'ethil Hollow",
			short = "A small ravine cuts into the land south of the road from Dolanaar to Darnassus. Hostile furbolgs hold its slopes and ambush travelers on the road now and then.",
			full = "A small ravine cuts into the land south of the road from Dolanaar to Darnassus. Hostile furbolgs hold its slopes and ambush travelers on the road now and then. At the back of the hollow lies Ban'ethil Barrow Den, sunk into the earth.",
			source = "https://warcraft.wiki.gg/wiki/Ban'ethil_Hollow",
		},
		["cleft"] = {
			name = "The Cleft",
			short = "The Cleft lies northwest of Dolanaar, close to the corrupted cave of Fel Rock, and nothing makes its home there.",
			full = "The Cleft lies northwest of Dolanaar, close to the corrupted cave of Fel Rock, and nothing makes its home there.",
			source = "https://warcraft.wiki.gg/wiki/Cleft",
		},
		["dolanaar"] = {
			name = "Dolanaar",
			short = "Young night elves leaving Shadowglen come to Dolanaar first. The village stands in the central-eastern part of Teldrassil, just southwest of the glen, and its central position draws it into much of the island's business.",
			full = "Young night elves leaving Shadowglen come to Dolanaar first. The village stands in the central-eastern part of Teldrassil, just southwest of the glen, and its central position draws it into much of the island's business. Tallonkai Swiftroot leads the effort here to fight back the corrupted furbolgs and satyrs of the Great Tree.",
			source = "https://warcraft.wiki.gg/wiki/Dolanaar",
		},
		["fel rock"] = {
			name = "Fel Rock",
			short = "A cave lies just north of Dolanaar that was once beautiful and is now corrupted. Grells infest its dark hollows, and the vicious satyr Lord Melenas makes his home within.",
			full = "A cave lies just north of Dolanaar that was once beautiful and is now corrupted. Grells infest its dark hollows, and the vicious satyr Lord Melenas makes his home within. He has gathered a small army of grells to guard his lair, led by one called Threggil.",
			source = "https://warcraft.wiki.gg/wiki/Fel_Rock",
		},
		["gnarlpine hold"] = {
			name = "Gnarlpine Hold",
			short = "In the far southwest corner of Teldrassil, Gnarlpine Hold is the home of the Gnarlpine furbolgs and the seat of their chieftain, Ursal the Mauler.",
			full = "In the far southwest corner of Teldrassil, Gnarlpine Hold is the home of the Gnarlpine furbolgs and the seat of their chieftain, Ursal the Mauler.\n\nThe tribe was once peaceful and counted the night elves as allies. Now its furbolgs have turned berserk and attack them, and the madness has carried them out of their old villages in the south and west of the island into Starbreeze Village and Ban'ethil Barrow Den.",
			source = "https://warcraft.wiki.gg/wiki/Gnarlpine_Hold",
		},
		["lake alameth"] = {
			name = "Lake Al'Ameth",
			short = "South of Dolanaar, Lake Al'Ameth spreads out as one of the largest waters on Teldrassil. Little stands on its shores beyond a small jetty.",
			full = "South of Dolanaar, Lake Al'Ameth spreads out as one of the largest waters on Teldrassil. Little stands on its shores beyond a small jetty. Lately many enraged timberlings have been seen along the banks, and the lake is no longer safe. Denalan keeps a small tent near the water, where he tries to understand the strange affliction seeping into the island.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Al'Ameth",
		},
		["oracle glade"] = {
			name = "The Oracle Glade",
			short = "The first and most powerful of Teldrassil's moonwells lies in the Oracle Glade, a shrine in the northwest of the island. Beside it stands the Oracle Tree.",
			full = "The first and most powerful of Teldrassil's moonwells lies in the Oracle Glade, a shrine in the northwest of the island. Beside it stands the Oracle Tree. Its trunk is wide, and its boughs take the shape of a great eagle perched atop a mighty bear. Many believe nature magic grew it that way. The tree has watched over Teldrassil's growth alongside the druids, and it can shed pieces of inscribed bark to send reports to Archdruid Fandral Staghelm in Darnassus.\n\nBloodfeather harpies have built nests nearby and threaten the tree. A small group of Sentinels has been sent to push them back.",
			source = "https://warcraft.wiki.gg/wiki/Oracle_Glade",
		},
		["pools of arlithrien"] = {
			name = "Pools of Arlithrien",
			short = "Small pools gather in the west of Teldrassil, south of the entrance to Darnassus. The place was peaceful once, and a lone moonwell still stands among the pools.",
			full = "Small pools gather in the west of Teldrassil, south of the entrance to Darnassus. The place was peaceful once, and a lone moonwell still stands among the pools. The night elves abandoned it when the Gnarlpine furbolgs became a threat, and hostile wildlife now roams the water's edge.",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Arlithrien",
		},
		["ruttheran village"] = {
			name = "Rut'theran Village",
			short = "Rut'theran Village sits at the very foot of the World Tree, the port for the night elf city of Darnassus far above. A portal here leads straight up into the capital, and hippogryphs roost at the village.",
			full = "Rut'theran Village sits at the very foot of the World Tree, the port for the night elf city of Darnassus far above. A portal here leads straight up into the capital, and hippogryphs roost at the village. A single dock serves The Moonspray, the boat that crosses to Auberdine on the Darkshore coast. When the Midsummer Fire Festival comes, the braziers in the village are lit.",
			source = "https://warcraft.wiki.gg/wiki/Rut'theran_Village",
		},
		["shadowglen"] = {
			name = "Shadowglen",
			short = "A perpetual dusk lies over Shadowglen, a small glade in the northeast of Teldrassil that never quite sees full daylight. Mountains ring it on every side.",
			full = "A perpetual dusk lies over Shadowglen, a small glade in the northeast of Teldrassil that never quite sees full daylight. Mountains ring it on every side. The only gap is to the south, where a path parts the range and heads toward Dolanaar. At the center of the clearing stands the great tree Aldrassil, as though the whole glen were arranged around it.",
			source = "https://warcraft.wiki.gg/wiki/Shadowglen",
		},
		["shadowthread cave"] = {
			name = "Shadowthread Cave",
			short = "Great spiders have always lived in Shadowthread Cave, in the northwest corner of Shadowglen. Lately they have grown more hostile, and the cave is far more dangerous.",
			full = "Great spiders have always lived in Shadowthread Cave, in the northwest corner of Shadowglen. Lately they have grown more hostile, and the cave is far more dangerous. The largest of them, Githyiss the Vile, has been the bane of more than one inexperienced night elf.",
			source = "https://warcraft.wiki.gg/wiki/Shadowthread_Cave",
		},
		["starbreeze village"] = {
			name = "Starbreeze Village",
			short = "Southeast of Shadowglen stand the few small houses of Starbreeze Village, once a night elf settlement. Corrupted furbolgs of the Gnarlpine tribe have overrun it.",
			full = "Southeast of Shadowglen stand the few small houses of Starbreeze Village, once a night elf settlement. Corrupted furbolgs of the Gnarlpine tribe have overrun it. Uruson patrols the village, and Ferocitas the Dream Eater is found on its outskirts.",
			source = "https://warcraft.wiki.gg/wiki/Starbreeze_Village",
		},
		["wellspring lake"] = {
			name = "Wellspring Lake",
			short = "Night elf fishermen once favored Wellspring Lake, a small lake northeast of Darnassus. A natural spring deep within the land of the World Tree feeds it, and the Wellspring River drains it.",
			full = "Night elf fishermen once favored Wellspring Lake, a small lake northeast of Darnassus. A natural spring deep within the land of the World Tree feeds it, and the Wellspring River drains it. Corrupted timberlings now make their home here, and nightsabers and spiders infest the land around it.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_Lake",
		},
		["wellspring river"] = {
			name = "Wellspring River",
			short = "The Wellspring River rises from a spring deep within the great tree. It flows north from Wellspring Lake and cascades over the edge of Teldrassil in a great waterfall, falling to the sea far below.",
			full = "The Wellspring River rises from a spring deep within the great tree. It flows north from Wellspring Lake and cascades over the edge of Teldrassil in a great waterfall, falling to the sea far below. Crazed timberlings patrol its banks and attack anyone who wanders near.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_River",
		},
	},
	-- Darkshore: 16 subzones
	[1439] = {
		["ametharan"] = {
			name = "Ameth'Aran",
			short = "The ruins of Ameth'Aran lie southeast of Auberdine. Queen Azshara raised it and its twin Bashal'Aran for her favored Highborne, with bazaars and temples to Elune, and Athrikus Narassin governed it for her.",
			full = "The ruins of Ameth'Aran lie southeast of Auberdine. Queen Azshara raised it and its twin Bashal'Aran for her favored Highborne, with bazaars and temples to Elune, and Athrikus Narassin governed it for her. In the last days of the old empire the town was already in ruins, and its people clung to the ground as though that might spare them from the destruction. Athrikus came to them and said a spell would keep them safe. As he spoke, the elves around him died, and their souls went into his soul gems, which he said would give them eternal life.\n\nTheir restless spirits still fill the ruins. Two large tablets stand among the stones, carved with the story of the town and its fall. A sentinel who tried to read them was driven off by the Highborne.",
			source = "https://warcraft.wiki.gg/wiki/Ameth'Aran",
		},
		["auberdine"] = {
			name = "Auberdine",
			short = "Auberdine stands on a coast the Sundering made, where the sea ruined the great cities of the old night elf empire.",
			full = "Auberdine stands on a coast the Sundering made, where the sea ruined the great cities of the old night elf empire. Darkshore stayed empty after that, and every attempt to settle it failed except this one town on the Veiled Sea.\n\nDwarves, gnomes, humans and even high elves walk its streets, which is unusual for a night elf town. Its port draws traders from the Eastern Kingdoms, and to help them the town is lit more brightly than most night elf places, with some signposts written in both Darnassian and Common. The elder Thundris Windweaver runs the town's daily affairs, and Sentinels guard it. Murlocs sink boats along this coast, and the townsfolk make armor from the scales of the ones they kill.\n\nBy the lighthouse, the wreck of a ship commanded by an elf named Elura lies on the rocks. Her cargo of elunite ore went down with her.",
			source = "https://warcraft.wiki.gg/wiki/Auberdine",
		},
		["bashalaran"] = {
			name = "Bashal'Aran",
			short = "Asterion was a mage as skilled with a blade as with the arcane arts, and he served as second to Athrikus Narassin in Bashal'Aran. He lived among its people and often traveled to Ameth'Aran to tend to its folk.",
			full = "Asterion was a mage as skilled with a blade as with the arcane arts, and he served as second to Athrikus Narassin in Bashal'Aran. He lived among its people and often traveled to Ameth'Aran to tend to its folk. Then Athrikus used his craft to make a moonstone seal and bound Asterion in the ruins. No one knows why he turned on his second. Asterion lived on in pain, and when he died he found that his spirit was held as surely as his body had been.\n\nThe town itself fell when the first Well of Eternity was shattered. Satyrs and grells have since made their home in the ruins and grow stronger on the magic left in the stones. They never go near the shrine where Asterion is imprisoned.",
			source = "https://warcraft.wiki.gg/wiki/Bashal'Aran",
		},
		["blackwood den"] = {
			name = "Blackwood Den",
			short = "In the far south of Darkshore, near the border of Ashenvale, a few furbolg camps and a small cave make up Blackwood Den, also called Blackwood Hold.",
			full = "In the far south of Darkshore, near the border of Ashenvale, a few furbolg camps and a small cave make up Blackwood Den, also called Blackwood Hold. The Blackwood furbolgs who live here have been corrupted by fel moss. Their warriors, shamans and great ursas hold the camps and the cave.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Den",
		},
		["cliffspring falls"] = {
			name = "Cliffspring Falls",
			short = "Cliffspring Falls feed the Cliffspring River and are the main supply of drinking water in Darkshore. The water was once pure. Now the cave it flows from has become corrupted, like much of the land around it.",
			full = "Cliffspring Falls feed the Cliffspring River and are the main supply of drinking water in Darkshore. The water was once pure. Now the cave it flows from has become corrupted, like much of the land around it.\n\nPeople disagree about the cause. Some say the corruption seeps in from Felwood. Others blame the Twilight's Hammer, whose cultists have been found deep in the caves where the water begins. Naga crawl through the cave as well.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_Falls",
		},
		["cliffspring river"] = {
			name = "Cliffspring River",
			short = "The Cliffspring River runs from Cliffspring Falls out to the sea in northern Darkshore. The Stormscale naga have tainted it, and the wildlife that drinks from it often falls sick.",
			full = "The Cliffspring River runs from Cliffspring Falls out to the sea in northern Darkshore. The Stormscale naga have tainted it, and the wildlife that drinks from it often falls sick.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_River",
		},
		["grove of the ancients"] = {
			name = "Grove of the Ancients",
			short = "Onu, an Ancient of Lore, makes his home among the stones of the Grove of the Ancients, the sacred ruin of an old night elf temple in the mountains of southeastern Darkshore.",
			full = "Onu, an Ancient of Lore, makes his home among the stones of the Grove of the Ancients, the sacred ruin of an old night elf temple in the mountains of southeastern Darkshore. It was built around the surging Wildbend River, and the Circle of Ancients meets here. Onu is patient and wise, with a sleeping druid for company, and he is troubled by the naga and by the Twilight's Hammer cult at work in the region.",
			source = "https://warcraft.wiki.gg/wiki/Grove_of_the_Ancients",
		},
		["long wash"] = {
			name = "The Long Wash",
			short = "Despite its name, the Long Wash is the shortest stretch of coast in Darkshore. Gray sand runs south from Auberdine to the water west of Ameth'Aran, under an overcast sky that never lifts.",
			full = "Despite its name, the Long Wash is the shortest stretch of coast in Darkshore. Gray sand runs south from Auberdine to the water west of Ameth'Aran, under an overcast sky that never lifts. Debris strews the beach, and murlocs have been showing up on it more often.",
			source = "https://warcraft.wiki.gg/wiki/Long_Wash",
		},
		["masters glaive"] = {
			name = "The Master's Glaive",
			short = "A colossal skull lies in the southwest of Darkshore with an adamantine glaive driven through the bone. It is what remains of Soggoth the Slitherer, a herald of the Old Gods, and the blade is the Master's Glaive.",
			full = "A colossal skull lies in the southwest of Darkshore with an adamantine glaive driven through the bone. It is what remains of Soggoth the Slitherer, a herald of the Old Gods, and the blade is the Master's Glaive. The night elves once held the place holy.\n\nTablets found by Explorers' League diggers tell what happened here. The titans sent twenty stone giants against Soggoth, and the battle was so terrible that only the largest, Kronn, lived to see its end. He let Soggoth's tendrils wrap around him, just long enough to be lifted within reach of the skull and his great sword. The sword stayed where it struck.\n\nThe Twilight's Hammer now controls the site. Its cultists dig into Soggoth's remains, meaning to bring him back to life.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Glaive",
		},
		["mists edge"] = {
			name = "Mist's Edge",
			short = "Gray beaches and gloomy bays make up Mist's Edge, the longest shoreline in Darkshore, running from near Auberdine to the region's northern tip.",
			full = "Gray beaches and gloomy bays make up Mist's Edge, the longest shoreline in Darkshore, running from near Auberdine to the region's northern tip. Huge carcasses of sea animals lie on the sand, and the wrecks of sunken ships dot the water. Crabs scuttle along the entire shore, and murlocs in the bays are an ever-present threat.",
			source = "https://warcraft.wiki.gg/wiki/Mist's_Edge",
		},
		["remtravels excavation"] = {
			name = "Remtravel's Excavation",
			short = "Prospector Remtravel of the Explorers' League, a famed archaeologist, gave this dig its name.",
			full = "Prospector Remtravel of the Explorers' League, a famed archaeologist, gave this dig its name. His team uncovered evidence of a great society here, and he found a fossil of unusual mystic properties, then forgot where he put it. Then huge golems sprang up out of the ground and overran the site, and Remtravel never seemed to notice.",
			source = "https://warcraft.wiki.gg/wiki/Remtravel's_Excavation",
		},
		["ruins of mathystra"] = {
			name = "Ruins of Mathystra",
			short = "Past the Tower of Althalaxx, in the north of Darkshore, lie the ruins of Mathystra. Before the Great Sundering, it stood as a city of the night elves, raised in the age of the Highborne.",
			full = "Past the Tower of Althalaxx, in the north of Darkshore, lie the ruins of Mathystra. Before the Great Sundering, it stood as a city of the night elves, raised in the age of the Highborne. When the Well of Eternity tore itself apart and the world broke beneath it, Mathystra was ruined along with so much else, and the night elves who survived did not return to rebuild it. They withdrew instead to smaller villages along the coast further south, leaving the ruins behind.\n\nStormscale naga have since taken the ruins for their own and guard them fiercely against anyone who comes near. Scattered relics of the old Highborne still lie among the fallen stones, and young night elves sometimes come searching through Mathystra for them, wary of the naga and of the ghost sabers that prowl among the ruins of what their people once built.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Mathystra",
		},
		["tower of althalaxx"] = {
			name = "Tower of Althalaxx",
			short = "Athrikus Narassin governed the twin towns for Queen Azshara, but he grew bored with the post and spent his days in a tower of his own, Althalaxx, some way from them.",
			full = "Athrikus Narassin governed the twin towns for Queen Azshara, but he grew bored with the post and spent his days in a tower of his own, Althalaxx, some way from them. The explosion of the Well of Eternity threw him far off and left him immortal, with the power to drain other mages to feed his own.\n\nNow the tower holds a cult that calls itself the Cult of the Dark Strand. Warlocks gather there, a satyr among them, and Athrikus leads them.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Althalaxx",
		},
		["twilight shore"] = {
			name = "Twilight Shore",
			short = "Gray beaches run along the southern coast of Darkshore, from the end of the Long Wash, due west of Ameth'Aran, all the way to Ashenvale.",
			full = "Gray beaches run along the southern coast of Darkshore, from the end of the Long Wash, due west of Ameth'Aran, all the way to Ashenvale. This is the most rugged part of the shore, and in the south jutting cliffs and small islands break up the sand. Greymist murlocs crowd the beaches, threshers hunt the water close in, and Blackfathom naga gather on this coast as well. Reef crawlers and tide crawlers pick along the sand, and a murloc called Flagglemurk the Cruel roams among the Greymist.",
			source = "",
		},
		["twilight vale"] = {
			name = "Twilight Vale",
			short = "Twilight Vale takes in the forests south of Ameth'Aran, running to the border of Ashenvale.",
			full = "Twilight Vale takes in the forests south of Ameth'Aran, running to the border of Ashenvale. Corrupted furbolgs, feral nightsabers and rabid bears haunt these woods, and travelers are counseled to keep to the roads rather than wander beneath the trees.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Vale",
		},
		["wildbend river"] = {
			name = "Wildbend River",
			short = "The Wildbend River carries its sickness down from the mountains, a continuation of the Bloodvenom River spilling out of Felwood into southern Darkshore, near the Grove of the Ancients.",
			full = "The Wildbend River carries its sickness down from the mountains, a continuation of the Bloodvenom River spilling out of Felwood into southern Darkshore, near the Grove of the Ancients. Its waters run tainted, the corruption of Felwood following the current down into these lower lands.",
			source = "https://warcraft.wiki.gg/wiki/Wildbend_River",
		},
	},
	-- Ashenvale: 41 subzones
	[1440] = {
		["astranaar"] = {
			name = "Astranaar",
			short = "Astranaar stands on an island in the middle of a lake, joined to the shore by two bridges, with the main road running through it. It is the largest settlement in Ashenvale, and a cemetery lies by the lake.",
			full = "Astranaar stands on an island in the middle of a lake, joined to the shore by two bridges, with the main road running through it. It is the largest settlement in Ashenvale, and a cemetery lies by the lake.\n\nRaene Wolfrunner commands the Sentinels and scouts here and works to ease the corruption in the ancient forest. To the north the Thistlefur furbolgs have grown in number, and she fears they will find the courage to attack Astranaar itself.",
			source = "https://warcraft.wiki.gg/wiki/Astranaar",
		},
		["bathrans haunt"] = {
			name = "Bathran's Haunt",
			short = "Broken pillars and fallen marble mark a night elf ruin that the elves abandoned long ago. Agents of the Forsaken have moved in, mostly herbalists and the thugs who guard them.",
			full = "Broken pillars and fallen marble mark a night elf ruin that the elves abandoned long ago. Agents of the Forsaken have moved in, mostly herbalists and the thugs who guard them. Where they work the grass has turned brown and the flowers have withered. Among the stones they have built a makeshift laboratory and use the local herbs for malicious ends.\n\nA remedial herb called Bathran's Hair grows in this one spot and nowhere else.",
			source = "https://warcraft.wiki.gg/wiki/Bathran's_Haunt",
		},
		["blackfathom deeps"] = {
			name = "Blackfathom Deeps",
			short = "A temple to Elune, the night elves' moon goddess, once stood on the Zoram Strand. The Great Sundering shattered it and sank it beneath the waves of the Veiled Sea, and for thousands of years it lay untouched.",
			full = "A temple to Elune, the night elves' moon goddess, once stood on the Zoram Strand. The Great Sundering shattered it and sank it beneath the waves of the Veiled Sea, and for thousands of years it lay untouched.\n\nThen the Twilight's Hammer came, called by whispers and foul dreams. The cult sacrificed countless innocents, and was rewarded with a charge. It must guard and feed Aku'mai the Devourer, a three-headed hydra and a favored pet of the Old Gods, until she is ready to loose her dark power on the world. Twilight Lord Kelris leads the cultists in the flooded caverns, and the corruption of an Old God has tainted the temple's moonwell. Naga and satyrs, drawn by the ruins' ancient power, have come as well to search its secrets. The place is called Blackfathom now, and the name fits.",
			source = "https://warcraft.wiki.gg/wiki/Blackfathom_Deeps",
		},
		["bloodtooth camp"] = {
			name = "Bloodtooth Camp",
			short = "Ran Bloodtooth, the king of all the furbolgs in Ashenvale, holds this camp just west of the Falfarren River and southwest of the southern moonwell.",
			full = "Ran Bloodtooth, the king of all the furbolgs in Ashenvale, holds this camp just west of the Falfarren River and southwest of the southern moonwell. The camp takes its name from him. Every furbolg in it has been corrupted, and they attack any outsider who comes near.",
			source = "https://warcraft.wiki.gg/wiki/Bloodtooth_Camp",
		},
		["bough shadow"] = {
			name = "Bough Shadow",
			short = "A Great Tree grows here, and it is a gate into the Emerald Dream. The green drakes Phantim and Dreamstalker guard the portal. Cursed green dragonspawn have slipped out of it into the woods, where they patrol in groups.",
			full = "A Great Tree grows here, and it is a gate into the Emerald Dream. The green drakes Phantim and Dreamstalker guard the portal. Cursed green dragonspawn have slipped out of it into the woods, where they patrol in groups.",
			source = "https://warcraft.wiki.gg/wiki/Bough_Shadow",
		},
		["demon fall canyon"] = {
			name = "Demon Fall Canyon",
			short = "The pit lord Mannoroth fought Thrall and Grommash Hellscream here. He knocked Thrall senseless, but he was not quick enough to dodge Grommash's axe, which cleaved into his chest.",
			full = "The pit lord Mannoroth fought Thrall and Grommash Hellscream here. He knocked Thrall senseless, but he was not quick enough to dodge Grommash's axe, which cleaved into his chest. His death burst in fire and light, and it tore the life from Grommash as well. With Mannoroth gone, the Burning Legion's curse on the orcs was broken. The canyon takes its name from that fight.\n\nA monument to Grommash stands here, and many orcs make the pilgrimage to honor the warrior who freed them. The ground is still fel-corrupted, and lesser demons now fill the canyon.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Canyon",
		},
		["demon fall ridge"] = {
			name = "Demon Fall Ridge",
			short = "Lesser demons haunt the slopes of this ridge and the abandoned barrow den cut into its side. In the deepest part of the den waits Diathorus the Seeker, a dreadlord who rules the demonic conclave in Ashenvale.",
			full = "Lesser demons haunt the slopes of this ridge and the abandoned barrow den cut into its side. In the deepest part of the den waits Diathorus the Seeker, a dreadlord who rules the demonic conclave in Ashenvale.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Ridge",
		},
		["dordanil barrow den"] = {
			name = "The Dor'Danil Barrow Den",
			short = "Night elf druids have long come to the Dor'Danil Barrow Den to rest. The Horde's advance into Ashenvale left the den behind its lines, and the orcs cared little for sleeping elves.",
			full = "Night elf druids have long come to the Dor'Danil Barrow Den to rest. The Horde's advance into Ashenvale left the den behind its lines, and the orcs cared little for sleeping elves. The Forsaken, who joined the Horde later, cared a great deal. They experimented on the sleeping druids, severing them from their spirits, and drove them insane.\n\nForsaken assassins now skulk through the den among the enraged souls of the severed druids. Three of the spirits are stronger than the rest: Uthil Mooncall, Mavoris Cloudsbreak and Taneel Darkwood.",
			source = "https://warcraft.wiki.gg/wiki/Dor'Danil_Barrow_Den",
		},
		["falfarren river"] = {
			name = "Falfarren River",
			short = "The Falfarren runs across Ashenvale from northeast to southwest. It roughly divides the night elf land under Astranaar in the west from the orc land under Splintertree Post in the east.",
			full = "The Falfarren runs across Ashenvale from northeast to southwest. It roughly divides the night elf land under Astranaar in the west from the orc land under Splintertree Post in the east. The river is neither deep nor wide, though heavy rain makes it swell.\n\nIt rises on the slopes of Mount Hyjal, falls through a series of waterfalls into a lake, and in the end slips underground beneath the mountains of the northern Barrens. Aggressive bog beasts roam beneath the water near Felfire Hill.",
			source = "https://warcraft.wiki.gg/wiki/Falfarren_River",
		},
		["fallen sky lake"] = {
			name = "Fallen Sky Lake",
			short = "A small lake lies south of Silverwing Outpost, with a single island at its center. Shadethickets, bog beasts of the forest, ring the shore, and the strongest of them, the Shadethicket Oracle, keeps to the island.",
			full = "A small lake lies south of Silverwing Outpost, with a single island at its center. Shadethickets, bog beasts of the forest, ring the shore, and the strongest of them, the Shadethicket Oracle, keeps to the island.",
			source = "https://warcraft.wiki.gg/wiki/Fallen_Sky_Lake",
		},
		["felfire hill"] = {
			name = "Felfire Hill",
			short = "Felfire Hill still bears the scars of the Third War, when infernals fell burning from the sky and struck the earth here. Foul demons have lived among its stones ever since.",
			full = "Felfire Hill still bears the scars of the Third War, when infernals fell burning from the sky and struck the earth here. Foul demons have lived among its stones ever since. The Horde has fortified both bridges onto the hill to keep attacks from reaching its settlements nearby.",
			source = "https://warcraft.wiki.gg/wiki/Felfire_Hill",
		},
		["fire scar shrine"] = {
			name = "Fire Scar Shrine",
			short = "The demonic influence of the Shadow Council has corrupted Fire Scar Shrine, in southwestern Ashenvale, until it became a place of great evil.",
			full = "The demonic influence of the Shadow Council has corrupted Fire Scar Shrine, in southwestern Ashenvale, until it became a place of great evil. An orcish warlock of the Cult of the Dark Strand, Ilkrud Magthrull, lives here.\n\nDemons infest the shrine now. A rare doomguard named Akkrilus appears in the area from time to time.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Scar_Shrine",
		},
		["forest song"] = {
			name = "Forest Song",
			short = "The druid Kayneth Stillwind is the lone inhabitant of Forest Song, an old night elf ruin in the northeast of Ashenvale. From its stones he directs the fight against the Forsaken in the region.",
			full = "The druid Kayneth Stillwind is the lone inhabitant of Forest Song, an old night elf ruin in the northeast of Ashenvale. From its stones he directs the fight against the Forsaken in the region.\n\nThe Forsaken have crept into Ashenvale and lurk at the night elves' ruins and barrows, and the elves believe they mean to spread disease through the forest.",
			source = "https://warcraft.wiki.gg/wiki/Forest_Song",
		},
		["greenpaw village"] = {
			name = "Greenpaw Village",
			short = "Corrupted furbolgs of the Foulweald tribe have made Greenpaw Village their home, in central Ashenvale south of Raynewood Retreat. The shaman Oakpaw is among them.",
			full = "Corrupted furbolgs of the Foulweald tribe have made Greenpaw Village their home, in central Ashenvale south of Raynewood Retreat. The shaman Oakpaw is among them.",
			source = "https://warcraft.wiki.gg/wiki/Greenpaw_Village",
		},
		["howling vale"] = {
			name = "The Howling Vale",
			short = "In a cave near the Felwood border stands the Shrine of Mel'Thandris. In front of it is carved an ancient inscription praising Elune, and the shrine bears another, in Darnassian, that reads \"The truth is a guiding light.\"",
			full = "In a cave near the Felwood border stands the Shrine of Mel'Thandris. In front of it is carved an ancient inscription praising Elune, and the shrine bears another, in Darnassian, that reads \"The truth is a guiding light.\"\n\nThe shrine lies in ruins. A pack of worgen called the Terrowulf has taken it over, and their chilling howls give the vale its name.",
			source = "https://warcraft.wiki.gg/wiki/Howling_Vale",
		},
		["iris lake"] = {
			name = "Iris Lake",
			short = "The corruption of Felwood has crept into Iris Lake, in north-central Ashenvale, one of the many parts of the night elf forest to fall to it.",
			full = "The corruption of Felwood has crept into Iris Lake, in north-central Ashenvale, one of the many parts of the night elf forest to fall to it. The water has turned a sickly yellowish green. Twisted bog beasts roam its shores and attack anyone who comes near.",
			source = "https://warcraft.wiki.gg/wiki/Iris_Lake",
		},
		["kargathia keep"] = {
			name = "Kargathia Keep",
			short = "The officers of the Warsong clan make their base at Kargathia Keep, in the eastern part of the Warsong Lumber Camp, just west of the Southfury River.",
			full = "The officers of the Warsong clan make their base at Kargathia Keep, in the eastern part of the Warsong Lumber Camp, just west of the Southfury River. Spiked barricades ring the stronghold. Its position lets reinforcements come down from Orgrimmar if the Alliance moves against the camp in force.\n\nThe keep is named for the legendary orc hero Kargath Bladefist.",
			source = "https://warcraft.wiki.gg/wiki/Kargathia_Keep",
		},
		["lake falathim"] = {
			name = "Lake Falathim",
			short = "Elune's moonlight touches down on Lake Falathim at every hour, day or night. Night elves once came here to swim and fish. Ferocious murlocs have since overrun the lake.",
			full = "Elune's moonlight touches down on Lake Falathim at every hour, day or night. Night elves once came here to swim and fish. Ferocious murlocs have since overrun the lake. A scholar named Teronis was last seen near its shore and never returned.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Falathim",
		},
		["maestras post"] = {
			name = "Maestra's Post",
			short = "A tower and one large night elf hall make up Maestra's Post, and only a few people live here. Two of them are humans, the only ones in Ashenvale.",
			full = "A tower and one large night elf hall make up Maestra's Post, and only a few people live here. Two of them are humans, the only ones in Ashenvale. Delgren the Purifier and Feero Ironhand came from the Argent Dawn to help the night elves clear their forest of demons and the undead. They work from the post to undermine the Cult of the Dark Strand.",
			source = "https://warcraft.wiki.gg/wiki/Maestra's_Post",
		},
		["moonwell"] = {
			name = "Moonwell",
			short = "Night elves fill their moonwells with the sacred water of the Well of Eternity, poured in from a well already purified, and Elune's moonlight keeps it pure.",
			full = "Night elves fill their moonwells with the sacred water of the Well of Eternity, poured in from a well already purified, and Elune's moonlight keeps it pure. The stone pools glow with silver water and heal both the land around them and anyone who drinks. Priestesses wash the night elf dead in such waters before burial, and the Sentinels honor the wells as shrines to Elune.\n\nThis moonwell lies east of Iris Lake, and a dryad named Shael'dryn keeps to it.",
			source = "",
		},
		["mystral lake"] = {
			name = "Mystral Lake",
			short = "The water elementals of Mystral Lake were once loyal to the night elves. A Forsaken mage corrupted them.",
			full = "The water elementals of Mystral Lake were once loyal to the night elves. A Forsaken mage corrupted them. It is the largest lake in the forest, and its tainted elementals make it dangerous to anyone who comes to the shore.",
			source = "https://warcraft.wiki.gg/wiki/Mystral_Lake",
		},
		["night run"] = {
			name = "Night Run",
			short = "A few broken pillars and pieces of ruined stonework shelter the Felmusk satyrs at Night Run, the smallest of the satyr holdings in Ashenvale.",
			full = "A few broken pillars and pieces of ruined stonework shelter the Felmusk satyrs at Night Run, the smallest of the satyr holdings in Ashenvale. The ruins stand on a spur of land that juts out into the forest. Cliffs too steep to climb guard its sides.\n\nThe Felmusk are allied with the Cult of the Dark Strand.",
			source = "https://warcraft.wiki.gg/wiki/Night_Run",
		},
		["nightsong woods"] = {
			name = "Nightsong Woods",
			short = "Most of the heavy fighting between the Horde and the Alliance happens in Nightsong Woods, the eastern part of Ashenvale, where the Warsong clan and the Silverwing Sentinels both hold ground.",
			full = "Most of the heavy fighting between the Horde and the Alliance happens in Nightsong Woods, the eastern part of Ashenvale, where the Warsong clan and the Silverwing Sentinels both hold ground. The Sentinels keep the west for the Alliance, and the Warsong clan keeps the east for the Horde.\n\nThe far east is the most contested ground of all. Satyrs, Warsong orcs and demons of the Burning Legion each hold a piece of it. In the south, the Warsong orcs have cut down much of the ancient forest and use the thick timber to build their settlements, leaving open, wounded ground where the old trees once stood unbroken.",
			source = "https://warcraft.wiki.gg/wiki/Nightsong_Woods",
		},
		["raynewood retreat"] = {
			name = "Raynewood Retreat",
			short = "At the top of the Great Tree Raynewood hides Ordanus, a keeper of the grove and one of the eldest sons of the forest god Cenarius.",
			full = "At the top of the Great Tree Raynewood hides Ordanus, a keeper of the grove and one of the eldest sons of the forest god Cenarius.\n\nBelow him, Cenarion Protectors, Blink Dragons and the Laughing Sisters hold the Alliance outpost and watch the path that leads north into corrupted Felwood.",
			source = "https://warcraft.wiki.gg/wiki/Raynewood_Retreat",
		},
		["ruins of ordilaran"] = {
			name = "The Ruins of Ordil'Aran",
			short = "Not much remains of the ancient city that once stood at Ordil'Aran. Among the broken stone grows a tree called the Heartswood.",
			full = "Not much remains of the ancient city that once stood at Ordil'Aran. Among the broken stone grows a tree called the Heartswood.\n\nThe Cult of the Dark Strand has made the ruins its own. Its members wait among the stones, ready to strike at anyone who comes near.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ordil'Aran",
		},
		["ruins of stardust"] = {
			name = "The Ruins of Stardust",
			short = "The Ruins of Stardust stand on an island in a lake, and they were once held holy. The demonic rot of Felwood has since reached them.",
			full = "The Ruins of Stardust stand on an island in a lake, and they were once held holy. The demonic rot of Felwood has since reached them. Water and stone carry the same stain, and large bog beasts, corrupted by the tainted lake, roam among the ruins.\n\nOnly the stardust shrubs scattered about have escaped the taint. They are known to hold powerful healing properties if drunk.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Stardust",
		},
		["satyrnaar"] = {
			name = "Satyrnaar",
			short = "Tents stand among the ruined buildings of Satyrnaar, where the Bleakheart satyrs shelter. Of the satyr ruins in the forest, it is the most intact.",
			full = "Tents stand among the ruined buildings of Satyrnaar, where the Bleakheart satyrs shelter. Of the satyr ruins in the forest, it is the most intact. Their hellcallers summon imps and voidwalkers. They are allied with the Cult of the Dark Strand.\n\nThe ruins lie just off the main road from Splintertree toward Azshara, which makes them the most contested of the satyr holdings.",
			source = "https://warcraft.wiki.gg/wiki/Satyrnaar",
		},
		["shady nook"] = {
			name = "The Shady Nook",
			short = "A family of bears lives in the Shady Nook, a small valley in Ashenvale. A cave opens in the hillside, and the bears likely den there.",
			full = "A family of bears lives in the Shady Nook, a small valley in Ashenvale. A cave opens in the hillside, and the bears likely den there.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Nook",
		},
		["shrine of aessina"] = {
			name = "The Shrine of Aessina",
			short = "A shrine to Aessina, the spirit of the wilderness, stands in the forest west of Astranaar. The night elves have raised shrines to her across Kalimdor, though few mortals know much about her.",
			full = "A shrine to Aessina, the spirit of the wilderness, stands in the forest west of Astranaar. The night elves have raised shrines to her across Kalimdor, though few mortals know much about her.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Aessina",
		},
		["silverwind refuge"] = {
			name = "Silverwind Refuge",
			short = "Sentinels guard Silverwind Refuge, and an army of water elementals serves beside them. The night elves count it with Astranaar as one of the major outposts of Ashenvale.",
			full = "Sentinels guard Silverwind Refuge, and an army of water elementals serves beside them. The night elves count it with Astranaar as one of the major outposts of Ashenvale. It lies just north of Mystral Lake and is a welcoming place, with an inn more luxurious than most in these woods.",
			source = "https://warcraft.wiki.gg/wiki/Silverwind_Refuge",
		},
		["silverwing grove"] = {
			name = "Silverwing Grove",
			short = "The Silverwing Sentinels keep their base in this grove in south-central Ashenvale, west of Fallen Sky Lake. Sentinel Farsong keeps watch here.",
			full = "The Silverwing Sentinels keep their base in this grove in south-central Ashenvale, west of Fallen Sky Lake. Sentinel Farsong keeps watch here. Four years after the Third War, the night elves began a great push to win back the forests of Ashenvale and rid their land of the Warsong Outriders. The Silverwings answered the call and swore not to rest until every last orc was beaten and cast out of Warsong Gulch.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Grove",
		},
		["silverwing outpost"] = {
			name = "Silverwing Outpost",
			short = "On the Horde side of the Falfarren River stands the eastern bastion of the Alliance's defense against the Horde in Ashenvale.",
			full = "On the Horde side of the Falfarren River stands the eastern bastion of the Alliance's defense against the Horde in Ashenvale. The Sentinels posted at Silverwing Outpost fight off constant attacks from the orcs nearby, who are set on ridding the woods of the Silverwings once and for all.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Outpost",
		},
		["southfury river"] = {
			name = "Southfury River",
			short = "The Southfury begins as a lake in Mount Hyjal. From there it drops in a run of spectacular waterfalls and comes down wide and swift, likely the most prominent river in Kalimdor.",
			full = "The Southfury begins as a lake in Mount Hyjal. From there it drops in a run of spectacular waterfalls and comes down wide and swift, likely the most prominent river in Kalimdor. It marks the border between Ashenvale and Azshara, and farther south it divides the Barrens from Durotar.\n\nJust north of the western bridge to Orgrimmar, one spot on the water touches four lands at once. Ashenvale, Azshara, Durotar and the Barrens all meet there. At its mouth the river empties into the Great Sea in a last cascade, northeast of the goblin port of Ratchet.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["splintertree post"] = {
			name = "Splintertree Post",
			short = "Grommash Hellscream and his Warsong clan raised Splintertree Post during the Third War, when the orcs first ventured into Ashenvale.",
			full = "Grommash Hellscream and his Warsong clan raised Splintertree Post during the Third War, when the orcs first ventured into Ashenvale. It is one of the oldest Horde settlements on Kalimdor.\n\nThe night elves have not forgotten Grommash. Tricked by the Burning Legion, he killed the demigod Cenarius in these woods. With that and the strain on the peace between Horde and Alliance, Splintertree draws a great deal of retaliation, especially since raids on Astranaar are frequent.\n\nOrcs and tauren hold the post now, mostly scouts and guards.",
			source = "https://warcraft.wiki.gg/wiki/Splintertree_Post",
		},
		["talondeep path"] = {
			name = "The Talondeep Path",
			short = "A winding tunnel runs through the rock between Ashenvale and the Stonetalon Mountains. It opens west of Mystral Lake on one side and in the northwest of Windshear Crag on the other.",
			full = "A winding tunnel runs through the rock between Ashenvale and the Stonetalon Mountains. It opens west of Mystral Lake on one side and in the northwest of Windshear Crag on the other. Small dead ends branch off it, and odd holes are worn into its walls. Nothing lives inside, and the remains of an old road can be found on the rock above.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["thistlefur village"] = {
			name = "Thistlefur Village",
			short = "Furbolgs of the Thistlefur tribe make their home in this village north of Astranaar. They are corrupted and hostile, and they attack anyone who wanders too close.",
			full = "Furbolgs of the Thistlefur tribe make their home in this village north of Astranaar. They are corrupted and hostile, and they attack anyone who wanders too close. Two ferocious warriors, Dal Bloodclaw and Rorgish Jowl, lead them.",
			source = "https://warcraft.wiki.gg/wiki/Thistlefur_Village",
		},
		["warsong labor camp"] = {
			name = "Warsong Labor Camp",
			short = "Orc guards watch over loggers and harvesters at the Warsong Labor Camp in southeastern Ashenvale, east of Fallen Sky Lake.",
			full = "Orc guards watch over loggers and harvesters at the Warsong Labor Camp in southeastern Ashenvale, east of Fallen Sky Lake. The camp sits far from help, so Alliance raiders now and then strike the guards without fear of retribution.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Labor_Camp",
		},
		["warsong lumber camp"] = {
			name = "Warsong Lumber Camp",
			short = "The forests of Ashenvale ring with axes at the Warsong Lumber Camp, where the Warsong clan strips the ancient trees for timber.",
			full = "The forests of Ashenvale ring with axes at the Warsong Lumber Camp, where the Warsong clan strips the ancient trees for timber. Peons and deforesters do the cutting with a shredder beside them, while Horde grunts, scouts and shamans stand guard. The camp keeps a kennel, and its stronghold is Kargathia Keep, named for the orc hero Kargath Bladefist. The keep stands just west of the Southfury River, close enough for reinforcements to come from Orgrimmar.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Lumber_Camp",
		},
		["xavian"] = {
			name = "Xavian",
			short = "Satyrs have made their home in the ruins of an ancient night elf temple in northeastern Ashenvale.",
			full = "Satyrs have made their home in the ruins of an ancient night elf temple in northeastern Ashenvale. Of the three satyr settlements in the forest, Xavian seems to be the center of their power, for Prince Raze and Geltharis both live here. Rogues, hellcallers, felsworn and betrayers of the sect fill the ruins.",
			source = "https://warcraft.wiki.gg/wiki/Xavian",
		},
		["zoram strand"] = {
			name = "The Zoram Strand",
			short = "Before the Great Sundering, a night elf settlement named Zoram stood near this beach. The Sundering destroyed it, and the Veiled Sea took what was left.",
			full = "Before the Great Sundering, a night elf settlement named Zoram stood near this beach. The Sundering destroyed it, and the Veiled Sea took what was left.\n\nToday the naga hold the shore. Wrecked ships and stranded sea creatures lie along the sand, and the naga are many. The Horde keeps a small outpost here and fights the Wrathtail naga who contest the coast. Blackfathom Deeps lies on the strand as well.",
			source = "https://warcraft.wiki.gg/wiki/Zoram_Strand",
		},
		["zoramgar outpost"] = {
			name = "Zoram'gar Outpost",
			short = "Docks reach out over the water at Zoram'gar Outpost, a Horde port on the Zoram Strand. The Horde set it up here and fights the Wrathtail naga from it.",
			full = "Docks reach out over the water at Zoram'gar Outpost, a Horde port on the Zoram Strand. The Horde set it up here and fights the Wrathtail naga from it.",
			source = "https://warcraft.wiki.gg/wiki/Zoram'gar_Outpost",
		},
	},
	-- Thousand Needles: 20 subzones
	[1441] = {
		["camp ethok"] = {
			name = "Camp E'thok",
			short = "Galak centaur keep a camp here in northwestern Thousand Needles. It is the smaller of the tribe's two holdings, and most of the Galak live at Splithoof Crag.",
			full = "Galak centaur keep a camp here in northwestern Thousand Needles. It is the smaller of the tribe's two holdings, and most of the Galak live at Splithoof Crag. The camp lies close to the road and to the Horde's Whitereach Post, and from it the centaur send raids against caravans and traveling merchants. The Galak hold no alliance with any other centaur tribe.",
			source = "https://warcraft.wiki.gg/wiki/Camp_E'thok",
		},
		["darkcloud pinnacle"] = {
			name = "Darkcloud Pinnacle",
			short = "Three small mesas here are home to the Grimtotem tauren, with several smaller empty ones around them. Rope bridges join the mesas.",
			full = "Three small mesas here are home to the Grimtotem tauren, with several smaller empty ones around them. Rope bridges join the mesas. Only two ways lead up, a natural slope that climbs a fourth mesa and ends in a bridge, and a second bridge. Both are well guarded.\n\nArnak Grimtotem and Harb Foulmountain lead the Grimtotem here.",
			source = "https://warcraft.wiki.gg/wiki/Darkcloud_Pinnacle",
		},
		["freewind post"] = {
			name = "Freewind Post",
			short = "Freewind Post stands on top of a mesa, out of reach of the Galak centaur war bands that camp below.",
			full = "Freewind Post stands on top of a mesa, out of reach of the Galak centaur war bands that camp below. Its people ride wooden lifts up from the canyon floor, and rope bridges climb from pinnacle to pinnacle until they reach the village. Screeching harpies are a lesser threat.\n\nThe tauren of Freewind grew wary of the Grimtotem on Darkcloud Pinnacle. Tauren were kidnapped, agents of dark and unknown origin came and went, and murder was laid at the Grimtotems' door, most of all at that of their chieftain, Arnak Grimtotem.",
			source = "https://warcraft.wiki.gg/wiki/Freewind_Post",
		},
		["great lift"] = {
			name = "The Great Lift",
			short = "Built by the tauren, this elevator carries travelers between the Barrens and Thousand Needles. Grish Longrunner and Brave Moonhorn keep watch over it.",
			full = "Built by the tauren, this elevator carries travelers between the Barrens and Thousand Needles. Grish Longrunner and Brave Moonhorn keep watch over it.",
			source = "https://warcraft.wiki.gg/wiki/Great_Lift",
		},
		["highperch"] = {
			name = "Highperch",
			short = "On this elevated ground in the west, the proud Highperch wyverns keep their nests.",
			full = "On this elevated ground in the west, the proud Highperch wyverns keep their nests. Young tauren come from Freewind Post to study them and to take eggs from the ancestral nesting grounds, which are raised as mounts for the Horde. The wyverns are wild, and they attack anyone who comes among the nests.",
			source = "https://warcraft.wiki.gg/wiki/Highperch",
		},
		["ironstone camp"] = {
			name = "Ironstone Camp",
			short = "A small band of the Horde camps at the border of the Shimmering Flats.",
			full = "A small band of the Horde camps at the border of the Shimmering Flats. They were sent to drive the dwarven diggers out of the Rustmaul Dig Site and got more than they bargained for, when silithid erupted from a nearby cave and attacked them. Moktar Krin leads them, and the silithid still infest the dig site.",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Camp",
		},
		["mirage raceway"] = {
			name = "Mirage Raceway",
			short = "A goblin named Pozzik and a gnome named Fizzle Brassbolts each held that their own people were the better engineers. To prove it, they built a raceway and rocket cars to run on it, and enlisted teams to drive them.",
			full = "A goblin named Pozzik and a gnome named Fizzle Brassbolts each held that their own people were the better engineers. To prove it, they built a raceway and rocket cars to run on it, and enlisted teams to drive them.\n\nGoblin and gnome drag cars race here daily. Supporters from both the Horde and the Alliance come to cheer their favorites, and seedy types come to gamble on the winner. After each race the two teams scramble to find improvements that will give their side an edge.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Raceway",
		},
		["razorfen downs"] = {
			name = "Razorfen Downs",
			short = "Legend says that where the demigod Agamaggan fell, his blood raised great masses of thorny vines. The quilboar revere the largest tangle of them as his resting place, and Razorfen Downs is their ancestral burial ground.",
			full = "Legend says that where the demigod Agamaggan fell, his blood raised great masses of thorny vines. The quilboar revere the largest tangle of them as his resting place, and Razorfen Downs is their ancestral burial ground. The entrance is said to be Agamaggan's own maw, an arched gap in the outer dome so hidden that only someone who knows where to look will find it.\n\nThe Downs are the traditional capital of the quilboar. The high priests of the Death's Head tribe live in the thorny maze among a great army of loyal warriors. After the Third War, the lich Amnennar the Coldbringer and agents of the Scourge took control of the quilboar and made the maze a bastion of undead might. The quilboar are fighting to win their city back before he can spread his hold across the Barrens.",
			source = "https://warcraft.wiki.gg/wiki/Razorfen_Downs",
		},
		["roguefeather den"] = {
			name = "Roguefeather Den",
			short = "Harpies crowd this small cavern in south central Thousand Needles. They screech at anyone who comes near, and at the back of the den they hoard the food they have gathered and guard it zealously.",
			full = "Harpies crowd this small cavern in south central Thousand Needles. They screech at anyone who comes near, and at the back of the den they hoard the food they have gathered and guard it zealously.",
			source = "https://warcraft.wiki.gg/wiki/Roguefeather_Den",
		},
		["rustmaul dig site"] = {
			name = "The Rustmaul Dig Site",
			short = "Dwarves of the Explorers' League were uncovering some old ruins here when a Horde war party led by Moktar Krin attacked and killed them all.",
			full = "Dwarves of the Explorers' League were uncovering some old ruins here when a Horde war party led by Moktar Krin attacked and killed them all. The fighting stirred up a nest of silithid in a cave at the dig site. The swarm that poured out drove off the war party, which was already weakened. The dig site is abandoned now, and the silithid hold the ground.",
			source = "https://warcraft.wiki.gg/wiki/Rustmaul_Dig_Site",
		},
		["scalding ridge"] = {
			pending = true,
			name = "Scalding Ridge",
			short = "",
			full = "",
			source = "",
		},
		["screeching canyon"] = {
			name = "The Screeching Canyon",
			short = "Screeching harpies infest this canyon in southern Thousand Needles, aggressive and loud. At its back lies Roguefeather Den.",
			full = "Screeching harpies infest this canyon in southern Thousand Needles, aggressive and loud. At its back lies Roguefeather Den.",
			source = "https://warcraft.wiki.gg/wiki/Screeching_Canyon",
		},
		["shimmering flats"] = {
			name = "The Shimmering Flats",
			short = "A sailing ship lies wrecked in the northern part of the Shimmering Flats, far from any water. It shows what this place once was, the bed of a lake that has dried away.",
			full = "A sailing ship lies wrecked in the northern part of the Shimmering Flats, far from any water. It shows what this place once was, the bed of a lake that has dried away. Nothing grows on the flat salt here, at the southeastern end of Thousand Needles. Basilisks, scorpids, turtles and vultures live here.\n\nThe flatness drew goblins and gnomes, who race their machines here, and their inventions are often unstable. Craters pock the ground, and the wreckage of countless failed gizmos lies scattered across the salt.",
			source = "https://warcraft.wiki.gg/wiki/Shimmering_Flats",
		},
		["splithoof crag"] = {
			name = "Splithoof Crag",
			short = "The Galak centaur keep their village against the northern wall of Thousand Needles, just east of Darkcloud Pinnacle. In a cavern in the mountainside at its center lies Splithoof Hold, their stronghold.",
			full = "The Galak centaur keep their village against the northern wall of Thousand Needles, just east of Darkcloud Pinnacle. In a cavern in the mountainside at its center lies Splithoof Hold, their stronghold.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Crag",
		},
		["splithoof hold"] = {
			name = "Splithoof Hold",
			short = "This cave in Splithoof Crag is the stronghold of the Galak centaur. The Ancient Brazier stands inside, and the Sacred Flame upon it burns forever.",
			full = "This cave in Splithoof Crag is the stronghold of the Galak centaur. The Ancient Brazier stands inside, and the Sacred Flame upon it burns forever.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Hold",
		},
		["tahonda ruins"] = {
			name = "Tahonda Ruins",
			short = "Long ago a tauren village here fell to ruin and sank beneath the sands of the Shimmering Flats. Little is known about it. Saltstone basilisks live among the ruins, and they may be the reason the village was abandoned.",
			full = "Long ago a tauren village here fell to ruin and sank beneath the sands of the Shimmering Flats. Little is known about it. Saltstone basilisks live among the ruins, and they may be the reason the village was abandoned.\n\nOther signs point to an attack by hostile forces. On one of the leather buildings are two sets of three parallel tears. The ruins lie in the southern reaches of the flats, near the path through the mountains to Tanaris.",
			source = "https://warcraft.wiki.gg/wiki/Tahonda_Ruins",
		},
		["weathered nook"] = {
			name = "The Weathered Nook",
			short = "Dorn Plainstalker and Prate Cloudseer live in a small, well-hidden cave in the northern wall of Thousand Needles. Dorn teaches the ways of faith, endurance and strength.",
			full = "Dorn Plainstalker and Prate Cloudseer live in a small, well-hidden cave in the northern wall of Thousand Needles. Dorn teaches the ways of faith, endurance and strength.",
			source = "https://warcraft.wiki.gg/wiki/Weathered_Nook",
		},
		["weazels crater"] = {
			name = "Weazel's Crater",
			short = "A large, deep crater opens in the northern part of the Shimmering Flats. Where it came from is a mystery. Its name suggests either who found it or who made it.",
			full = "A large, deep crater opens in the northern part of the Shimmering Flats. Where it came from is a mystery. Its name suggests either who found it or who made it. Rubble and smaller craters lie scattered about, and goblins and gnomes race dangerous cars in these parts, so it may be the work of an unstable invention. Saltstone basilisks live in it now.",
			source = "https://warcraft.wiki.gg/wiki/Weazel's_Crater",
		},
		["whitereach post"] = {
			name = "Whitereach Post",
			short = "Along the road near Camp E'thok stands a small Horde camp. Kanati Greycloud and the goblin Wizlo Bearingshiner are among those who stay here.",
			full = "Along the road near Camp E'thok stands a small Horde camp. Kanati Greycloud and the goblin Wizlo Bearingshiner are among those who stay here.",
			source = "https://warcraft.wiki.gg/wiki/Whitereach_Post",
		},
		["windbreak canyon"] = {
			name = "Windbreak Canyon",
			short = "Wind serpents fill this canyon with their nests. It covers most of the ground between Freewind Post and the Shimmering Flats, on the north side of the road.",
			full = "Wind serpents fill this canyon with their nests. It covers most of the ground between Freewind Post and the Shimmering Flats, on the north side of the road.",
			source = "https://warcraft.wiki.gg/wiki/Windbreak_Canyon",
		},
	},
	-- Stonetalon Mountains: 18 subzones
	[1442] = {
		["blackwolf river"] = {
			name = "Blackwolf River",
			short = "The Blackwolf River runs out of Cragpool Lake and through the valley of Windshear Crag. It is a small river, and a foul one. The Venture Company's logging of the valley has poisoned its water.",
			full = "The Blackwolf River runs out of Cragpool Lake and through the valley of Windshear Crag. It is a small river, and a foul one. The Venture Company's logging of the valley has poisoned its water.",
			source = "https://warcraft.wiki.gg/wiki/Blackwolf_River",
		},
		["boulderslide cavern"] = {
			name = "Boulderslide Cavern",
			short = "Boulderslide kobolds nest in this cave at the end of the ravine. They mine without rest for Resonite, a rare purple crystal that glows and carries a trace of earthen magic, and they guard it with their lives.",
			full = "Boulderslide kobolds nest in this cave at the end of the ravine. They mine without rest for Resonite, a rare purple crystal that glows and carries a trace of earthen magic, and they guard it with their lives.",
			source = "https://warcraft.wiki.gg/wiki/Boulderslide_Cavern",
		},
		["boulderslide ravine"] = {
			name = "Boulderslide Ravine",
			short = "Rams graze the slopes of this small ravine, and the occasional cliff stormer wheels overhead. It leads in to the cavern where the Boulderslide kobolds nest.",
			full = "Rams graze the slopes of this small ravine, and the occasional cliff stormer wheels overhead. It leads in to the cavern where the Boulderslide kobolds nest.\n\nAcross from that cavern stands a small abandoned cave. Barrels sit inside, crude torches light it, and the walls carry tribal art that may be tauren work.",
			source = "https://warcraft.wiki.gg/wiki/Boulderslide_Ravine",
		},
		["camp aparaje"] = {
			name = "Camp Aparaje",
			short = "Grimtotem forces from Grimtotem Post, led by Grundig Darkcloud, fell upon Camp Aparaje, a tauren village in the eastern Stonetalon Mountains.",
			full = "Grimtotem forces from Grimtotem Post, led by Grundig Darkcloud, fell upon Camp Aparaje, a tauren village in the eastern Stonetalon Mountains. Makaba Flathoof made his home here.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Aparaje",
		},
		["charred vale"] = {
			name = "The Charred Vale",
			short = "The Charred Vale was a green valley once. Bloodfury harpies called it home, and treants walked its forest as guardians.",
			full = "The Charred Vale was a green valley once. Bloodfury harpies called it home, and treants walked its forest as guardians.\n\nThen goblins of the Venture Company came and decimated it. The vale's spirits were enraged, and numerous elementals broke loose when the treants drove the goblins back. The goblins' weapons probably tainted the treants as the goblins left.\n\nThe valley now lies mostly in flames and lava, in the southwest of the Stonetalon Mountains. Blackened ancients and scorched basilisks live among the burning ground.",
			source = "https://warcraft.wiki.gg/wiki/Charred_Vale",
		},
		["cragpool lake"] = {
			name = "Cragpool Lake",
			short = "An enormous structure built by the Venture Company runs above this small lake. Gerenzo Wrenchwhistle oversees the logging of Windshear Crag from its platform.",
			full = "An enormous structure built by the Venture Company runs above this small lake. Gerenzo Wrenchwhistle oversees the logging of Windshear Crag from its platform.",
			source = "https://warcraft.wiki.gg/wiki/Cragpool_Lake",
		},
		["greatwood vale"] = {
			name = "Greatwood Vale",
			short = "Wooded foothills hold this valley, and sparse evergreens grow here even where the mountains further south are less forested. The Webwinder Path leads into it.",
			full = "Wooded foothills hold this valley, and sparse evergreens grow here even where the mountains further south are less forested. The Webwinder Path leads into it.\n\nThe Grimtotem who fell upon Camp Aparaje are in the vale now, their ruffians and mercenaries spread through the trees.",
			source = "https://warcraft.wiki.gg/wiki/Greatwood_Vale",
		},
		["grimtotem post"] = {
			name = "Grimtotem Post",
			short = "Grimtotem warriors of many kinds, from brutes and ruffians to sorcerers and mercenaries, patrol the post and the slopes around it. It is the base of the Grimtotem tribe's operations in the Stonetalon Mountains.",
			full = "Grimtotem warriors of many kinds, from brutes and ruffians to sorcerers and mercenaries, patrol the post and the slopes around it. It is the base of the Grimtotem tribe's operations in the Stonetalon Mountains. The fierce chieftain Grundig Darkcloud leads them.",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Post",
		},
		["malakajin"] = {
			name = "Malaka'jin",
			short = "Darkspear trolls live in Malaka'jin, a small Horde village just south of Grimtotem Post. The hunters make a modest living selling their catches to Horde travelers who pass through.",
			full = "Darkspear trolls live in Malaka'jin, a small Horde village just south of Grimtotem Post. The hunters make a modest living selling their catches to Horde travelers who pass through.",
			source = "https://warcraft.wiki.gg/wiki/Malaka'jin",
		},
		["mirkfallon lake"] = {
			name = "Mirkfallon Lake",
			short = "Mirkfallon Lake fills a basin at the center of the Stonetalon Mountains, with a hill rising out of the water in the middle. Wyverns nest around the lake, and slimes and thunder lizards roam its shores.",
			full = "Mirkfallon Lake fills a basin at the center of the Stonetalon Mountains, with a hill rising out of the water in the middle. Wyverns nest around the lake, and slimes and thunder lizards roam its shores.",
			source = "https://warcraft.wiki.gg/wiki/Mirkfallon_Lake",
		},
		["sishir canyon"] = {
			name = "Sishir Canyon",
			short = "Deepmoss spiders have taken Sishir Canyon entirely. Their eggs and webbing cover the ledges and hollows of the stone, and deep inside waits Besseleth, the most powerful of the brood.",
			full = "Deepmoss spiders have taken Sishir Canyon entirely. Their eggs and webbing cover the ledges and hollows of the stone, and deep inside waits Besseleth, the most powerful of the brood.",
			source = "https://warcraft.wiki.gg/wiki/Sishir_Canyon",
		},
		["stonetalon peak"] = {
			name = "Stonetalon Peak",
			short = "At the far northwestern end of the range, in a green mountain valley, stands Stonetalon Peak. The mountain is held sacred, and magic runs through its stone.",
			full = "At the far northwestern end of the range, in a green mountain valley, stands Stonetalon Peak. The mountain is held sacred, and magic runs through its stone.\n\nDuring the Third War, Jaina Proudmoore and her expedition made a base near the entrance to the caverns beneath the peak. Thrall and his Horde came later, searching for the Oracle, and in those caverns the Alliance and the Horde stood together against the Burning Legion for a time.\n\nNow the night elves and the Alliance keep the peak, and the druids of the Talon Den tend the valley.",
			source = "https://warcraft.wiki.gg/wiki/Stonetalon_Peak",
		},
		["sun rock retreat"] = {
			name = "Sun Rock Retreat",
			short = "In ages past, tauren made pilgrimages to Sun Rock Retreat to perform the rites that cross into the spirit world, for the place has a strong bond with that realm.",
			full = "In ages past, tauren made pilgrimages to Sun Rock Retreat to perform the rites that cross into the spirit world, for the place has a strong bond with that realm. It is said that An'she himself once kissed the mountain where the retreat now stands.\n\nOrcs and tauren hold it together now, hidden among the peaks south of Mirkfallon Lake. It is the busiest settlement in the mountains, and its people work to repair what the Venture Company and other malignant forces have torn from the land.",
			source = "https://warcraft.wiki.gg/wiki/Sun_Rock_Retreat",
		},
		["talon den"] = {
			name = "The Talon Den",
			short = "On Stonetalon Peak the earth opens into the Talon Den, a barrow den. Mirkfallon dryads and keepers make their home there, together with night elf Cenarion Caretakers.",
			full = "On Stonetalon Peak the earth opens into the Talon Den, a barrow den. Mirkfallon dryads and keepers make their home there, together with night elf Cenarion Caretakers.",
			source = "https://warcraft.wiki.gg/wiki/Talon_Den",
		},
		["talondeep path"] = {
			name = "The Talondeep Path",
			short = "The Talondeep Path winds through the mountains from Ashenvale to Windshear Crag. Small dead ends and odd holes break its walls, and nothing lives inside.",
			full = "The Talondeep Path winds through the mountains from Ashenvale to Windshear Crag. Small dead ends and odd holes break its walls, and nothing lives inside.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["webwinder path"] = {
			name = "Webwinder Path",
			short = "Spiders, rams and thunder lizards live along the Webwinder Path, the main road between Malaka'jin and Mirkfallon Lake.",
			full = "Spiders, rams and thunder lizards live along the Webwinder Path, the main road between Malaka'jin and Mirkfallon Lake.",
			source = "https://warcraft.wiki.gg/wiki/Webwinder_Path",
		},
		["windshear crag"] = {
			name = "Windshear Crag",
			short = "Windshear Crag was a massive old-growth forest, green and thick in its valley. Now it is stumps, fouled water, and machinery that creaks without end.",
			full = "Windshear Crag was a massive old-growth forest, green and thick in its valley. Now it is stumps, fouled water, and machinery that creaks without end. The goblin-run Venture Company logged it, and the whole operation answers to a leper gnome, Gerenzo Wrenchwhistle. His flesh looks to be rotting away, and he has grafted metal and gears onto his body. He built the Super Reaper 6000, a machine that can turn the largest trees to sawdust, and he watches the crag from a platform above Cragpool Lake.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Crag",
		},
		["windshear mine"] = {
			name = "Windshear Mine",
			short = "Windshear kobolds occupy Windshear Mine, a tin mine at the end of the Blackwolf River in the southeast corner of Windshear Crag. They dig its tin for the Venture Company.",
			full = "Windshear kobolds occupy Windshear Mine, a tin mine at the end of the Blackwolf River in the southeast corner of Windshear Crag. They dig its tin for the Venture Company.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Mine",
		},
	},
	-- Desolace: 20 subzones
	[1443] = {
		["bolgans hole"] = {
			name = "Bolgan's Hole",
			short = "Khan Shaka and the most prominent members of the Gelkis clan live in this cave. Blue crystals grow inside it, called the tears of Theradras.",
			full = "Khan Shaka and the most prominent members of the Gelkis clan live in this cave. Blue crystals grow inside it, called the tears of Theradras. The clan's shaman hoard them and believe the stones carry the protection of Princess Theradras.",
			source = "https://warcraft.wiki.gg/wiki/Bolgan's_Hole",
		},
		["ethel rethor"] = {
			name = "Ethel Rethor",
			short = "Far in the northwest of Desolace, a night elf ruin lies mostly underwater. Only a lone tower rises above the surface, joined to the shore by a small bridge that ends at a closed entrance.",
			full = "Far in the northwest of Desolace, a night elf ruin lies mostly underwater. Only a lone tower rises above the surface, joined to the shore by a small bridge that ends at a closed entrance. Naga, who inhabit many of the coastal elven ruins, have taken this one as well.\n\nAzore Aldamort, who speaks for the Argent Dawn, stays among the ruins.",
			source = "https://warcraft.wiki.gg/wiki/Ethel_Rethor",
		},
		["gelkis village"] = {
			name = "Gelkis Village",
			short = "The Gelkis clan keeps its principal village in a ring around a wide ravine in southwestern Desolace.",
			full = "The Gelkis clan keeps its principal village in a ring around a wide ravine in southwestern Desolace. Bridges join the cliffs and bluffs inside the ravine and lead to a cave in the southern mountain face, where the Gelkis khan lives.\n\nThe village sits hard against the main north-south road, which makes the road dangerous for anyone who travels it. Lately the centaur have spread, building huts on the east side of the road, near the lake.",
			source = "https://warcraft.wiki.gg/wiki/Gelkis_Village",
		},
		["ghost walker post"] = {
			name = "Ghost Walker Post",
			short = "Gurda Wildmane leads the tauren shaman who keep this small outpost beside the Kodo Graveyard. The shaman ease the nearby kodo into their next lives and sometimes speak with the spirits of the dead ones.",
			full = "Gurda Wildmane leads the tauren shaman who keep this small outpost beside the Kodo Graveyard. The shaman ease the nearby kodo into their next lives and sometimes speak with the spirits of the dead ones. A band of orcs sent by Warchief Thrall holds the post with them.\n\nThe outpost is exposed and bare. It has no inn and little beyond the necessities. From here the Horde wages war on the Burning Blade, its servants and the centaur tribes.",
			source = "https://warcraft.wiki.gg/wiki/Ghost_Walker_Post",
		},
		["kodo graveyard"] = {
			name = "Kodo Graveyard",
			short = "Here lies the final resting place of the kodo. Their bones are scattered across the ground, and many seem to come from beasts far larger than the kodo that roam the land now.",
			full = "Here lies the final resting place of the kodo. Their bones are scattered across the ground, and many seem to come from beasts far larger than the kodo that roam the land now. Dying kodo still make their way here to end their days, and vultures called carrion horrors gather over the bones.",
			source = "https://warcraft.wiki.gg/wiki/Kodo_Graveyard",
		},
		["kolkar village"] = {
			name = "Kolkar Village",
			short = "The Kolkar clan holds the eastern margin of Desolace, where its ancestral grounds lie along the mountains. This village is the center of its power.",
			full = "The Kolkar clan holds the eastern margin of Desolace, where its ancestral grounds lie along the mountains. This village is the center of its power. Here the Kolkar are the smallest and least influential of the tribes, yet no other centaur clan has spread as far across Kalimdor. They keep villages and outposts in the Barrens and in Durotar.",
			source = "https://warcraft.wiki.gg/wiki/Kolkar_Village",
		},
		["kormeks hut"] = {
			name = "Kormek's Hut",
			short = "A small hovel stands on the barren flats of north-central Desolace. Inside lives Willow, a friendly member of the Twilight's Hammer.",
			full = "A small hovel stands on the barren flats of north-central Desolace. Inside lives Willow, a friendly member of the Twilight's Hammer. In the pen outside, kodo bones lie scattered, and Bibbly F'utzbuckle dances among them, excited at the money the bones might fetch. No one knows where Kormek, the hut's namesake, has gone.",
			source = "https://warcraft.wiki.gg/wiki/Kormek's_Hut",
		},
		["magram village"] = {
			name = "Magram Village",
			short = "The Magram clan lives on the shores and islands of a chain of polluted yellow pools in southeastern Desolace.",
			full = "The Magram clan lives on the shores and islands of a chain of polluted yellow pools in southeastern Desolace. Crude bridges join the islands to each other and to the shore, and the clan's yurts and pavilions stand scattered among the pools. The Magram are at war with the Gelkis clan.",
			source = "https://warcraft.wiki.gg/wiki/Magram_Village",
		},
		["mannoroc coven"] = {
			name = "Mannoroc Coven",
			short = "The night elf ruins here take their name from Mannoroth, the dreaded pit lord. The earth was dead already, and the demons that live here have blasted it further with fel magic.",
			full = "The night elf ruins here take their name from Mannoroth, the dreaded pit lord. The earth was dead already, and the demons that live here have blasted it further with fel magic. It hangs thick in the air, and a deadly pall falls over anyone who crosses into the coven.\n\nBurning Blade cultists summoned these demons through a number of magical portals. Infernals, succubi, felhounds and felguards now stalk the ruins, and the orc warlock Jugkar Grim'rod stands here for the Burning Blade. It is the largest gathering of demons in central Kalimdor, and new portals keep opening.",
			source = "https://warcraft.wiki.gg/wiki/Mannoroc_Coven",
		},
		["nijels point"] = {
			name = "Nijel's Point",
			short = "The Alliance and the Cenarion Circle hold an outpost among night elf ruins in the northern mountains. No one there can say who Nijel was.",
			full = "The Alliance and the Cenarion Circle hold an outpost among night elf ruins in the northern mountains. No one there can say who Nijel was.\n\nKeeper Marandis and his dryad sisters use the outpost as a base, on a mission for the Cenarion Circle: to kill Princess Theradras and to bring the body of Zaetar out of Maraudon and home to the Stonetalon Mountains. The Stormwind Army keeps a guard here under Captain Pentigast, against the centaur clans. He is sure that whichever of the Gelkis and the Magram wins their war will grow bold enough to threaten the Alliance holdings, and he wants to learn how the centaur can be beaten.",
			source = "https://warcraft.wiki.gg/wiki/Nijel's_Point",
		},
		["ranazjar isle"] = {
			name = "Ranazjar Isle",
			short = "Naga live on this small, rocky island off the northwest coast of Desolace. Night elf ruins stand among the stones, and they seem to belong to the same ancient city as Ethel Rethor.",
			full = "Naga live on this small, rocky island off the northwest coast of Desolace. Night elf ruins stand among the stones, and they seem to belong to the same ancient city as Ethel Rethor. A statue of Queen Azshara is there too.",
			source = "https://warcraft.wiki.gg/wiki/Ranazjar_Isle",
		},
		["sargeron"] = {
			name = "Sargeron",
			short = "Satyrs of the Hatefury have taken over the ruins of a night elf city. The city has lain broken since the War of the Ancients, and its first name is lost.",
			full = "Satyrs of the Hatefury have taken over the ruins of a night elf city. The city has lain broken since the War of the Ancients, and its first name is lost. The satyrs renamed it Sargeron, after their demon master Sargeras.",
			source = "https://warcraft.wiki.gg/wiki/Sargeron",
		},
		["sartheris strand"] = {
			name = "Sar'theris Strand",
			short = "The coast is the one part of Desolace with color. The interior is gray and gloomy, but here the grass is green and the sun comes out.",
			full = "The coast is the one part of Desolace with color. The interior is gray and gloomy, but here the grass is green and the sun comes out. Sea giants and naga crowd the water, and makrura share the beach. A small boat lies smashed on the sand below Ethel Rethor.",
			source = "https://warcraft.wiki.gg/wiki/Sar'theris_Strand",
		},
		["scrabblescrews camp"] = {
			name = "Scrabblescrew's Camp",
			short = "Smeed Scrabblescrew lives in a small goblin camp not far from the Kodo Graveyard. He is an enterprising goblin who keeps a caravan of kodo.",
			full = "Smeed Scrabblescrew lives in a small goblin camp not far from the Kodo Graveyard. He is an enterprising goblin who keeps a caravan of kodo.",
			source = "https://warcraft.wiki.gg/wiki/Scrabblescrew's_Camp",
		},
		["shadowbreak ravine"] = {
			name = "Shadowbreak Ravine",
			short = "The Burning Blade cultists have made a well-hidden haven of this ravine in the mountains. Huge mushrooms grow among its rocks. A summoning circle hung with giant chains lies in the middle of it.",
			full = "The Burning Blade cultists have made a well-hidden haven of this ravine in the mountains. Huge mushrooms grow among its rocks. A summoning circle hung with giant chains lies in the middle of it.\n\nCaptured stallions are held here, and the cult's nightmares stand among them.",
			source = "https://warcraft.wiki.gg/wiki/Shadowbreak_Ravine",
		},
		["shadowprey village"] = {
			name = "Shadowprey Village",
			short = "Darkspear trolls built this fishing village at the southern end of Desolace's coast, and they live by what the sea gives them. Their catches are always in demand, and they feed the tauren outpost inland.",
			full = "Darkspear trolls built this fishing village at the southern end of Desolace's coast, and they live by what the sea gives them. Their catches are always in demand, and they feed the tauren outpost inland.\n\nSelendra, a dryad of the Cenarion Circle, stays nearby, searching for the remains of Zaetar. The inn is airy, and guests wake to a view of the water.",
			source = "https://warcraft.wiki.gg/wiki/Shadowprey_Village",
		},
		["tethris aran"] = {
			name = "Tethris Aran",
			short = "North of Thunder Axe Fortress lie the ruins of a night elf settlement, presumably destroyed in the Great Sundering. Only the wild creatures of Desolace live among the broken stones.",
			full = "North of Thunder Axe Fortress lie the ruins of a night elf settlement, presumably destroyed in the Great Sundering. Only the wild creatures of Desolace live among the broken stones.",
			source = "https://warcraft.wiki.gg/wiki/Tethris_Aran",
		},
		["thunder axe fortress"] = {
			name = "Thunder Axe Fortress",
			short = "The Burning Blade cult holds this stronghold in northwestern Desolace, and its reavers, felsworn, augurs, adepts and shadowmages crowd the walls.",
			full = "The Burning Blade cult holds this stronghold in northwestern Desolace, and its reavers, felsworn, augurs, adepts and shadowmages crowd the walls. Inside them stand a barracks, a cave and several watch towers.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Axe_Fortress",
		},
		["valley of bones"] = {
			name = "Valley of Bones",
			short = "Skeletons crowd this crag on the southern border of Desolace, the way on foot into Shen'dralas, and centaur necromancers walk among them.",
			full = "Skeletons crowd this crag on the southern border of Desolace, the way on foot into Shen'dralas, and centaur necromancers walk among them. Two enormous skeletons lie collapsed against the cliff walls, the Dead Goliaths, and no one knows where they came from.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Bones",
		},
		["valley of spears"] = {
			name = "Valley of Spears",
			short = "The Maraudine clan of centaur lives in this valley in western Desolace. On foot it can be entered only through narrow mountain passes to the south and the east.",
			full = "The Maraudine clan of centaur lives in this valley in western Desolace. On foot it can be entered only through narrow mountain passes to the south and the east. At its southwestern end lies the entrance to Maraudon, the foul place where the centaur race was born.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Spears",
		},
	},
	-- Feralas: 29 subzones
	[1444] = {
		["camp mojache"] = {
			name = "Camp Mojache",
			short = "The tauren of Camp Mojache have built their village above Wildwind Lake, straddling a swift stream that runs down into it.",
			full = "The tauren of Camp Mojache have built their village above Wildwind Lake, straddling a swift stream that runs down into it. They are known for their thick hides, and their braves guard travelers against the dangers of Feralas with great courage.\n\nWoodpaw gnolls raid the camp, and their attacks have grown more fevered of late.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Mojache",
		},
		["dire maul"] = {
			name = "Dire Maul",
			short = "Twelve thousand years ago a covert sect of night elf sorcerers raised Eldre'Thalas to guard Queen Azshara's most prized arcane secrets.",
			full = "Twelve thousand years ago a covert sect of night elf sorcerers raised Eldre'Thalas to guard Queen Azshara's most prized arcane secrets. Among its Highborne were the arcanists of the Shen'dralar.\n\nThe Great Sundering cut the Highborne off from the Well of Eternity. When Prince Tortheldrin set out to bind a demon, Immol'thar, the Highborne who warned that it would give the Burning Legion a foothold again died in a single bloody night. Other Shen'dralar rose in secret under a masked leader called the Shal'nan. After a last raid on Tortheldrin's sanctum, the Shal'nan led his people west out of the city, and they sailed into the unknown. Those who stayed lived on the demon's power for thousands of years, until holding him cost more than he gave. Tortheldrin then killed many of his own people so the rest could draw more from him, and the survivors drew back into the heart of the city, leaving the rest to whatever came.\n\nOgres, satyrs and ghosts hold the ruins now, and the stone still stands.",
			source = "https://warcraft.wiki.gg/wiki/Dire_Maul",
		},
		["dream bough"] = {
			name = "Dream Bough",
			short = "The largest tree in Feralas stands on a small island in the middle of Jademir Lake. It is one of the four Great Trees, and its roots and branches hold a portal into the Emerald Dream.",
			full = "The largest tree in Feralas stands on a small island in the middle of Jademir Lake. It is one of the four Great Trees, and its roots and branches hold a portal into the Emerald Dream. The green dragonflight guards it.\n\nDragons of the green flight corrupted by the Emerald Nightmare have come into Azeroth through the Great Trees, and they appear here at times.",
			source = "https://warcraft.wiki.gg/wiki/Dream_Bough",
		},
		["feathermoon stronghold"] = {
			name = "Feathermoon Stronghold",
			short = "General Shandris Feathermoon raised this fortress on Sardor Isle, off the western coast of Feralas, and it carries her name.",
			full = "General Shandris Feathermoon raised this fortress on Sardor Isle, off the western coast of Feralas, and it carries her name. For ten thousand years she has stood at the right hand of Tyrande Whisperwind among the Sentinels. The stronghold holds this stretch of Kalimdor's coast for the night elves still.\n\nThe naga trouble the island, and Shandris works to cleanse the land of the Hatecrest and their leader, Lord Shalzaru. Only the sea joins the island to the mainland, and a boat crosses to its dock from the coast.",
			source = "https://warcraft.wiki.gg/wiki/Feathermoon_Stronghold_(Classic)",
		},
		["feral scar vale"] = {
			name = "Feral Scar Vale",
			short = "The Feral Scar yetis hold this vale in the High Wilderness of western Feralas, and it carries their name.",
			full = "The Feral Scar yetis hold this vale in the High Wilderness of western Feralas, and it carries their name.",
			source = "https://warcraft.wiki.gg/wiki/Feral_Scar_Vale",
		},
		["forgotten coast"] = {
			name = "The Forgotten Coast",
			short = "Water elementals rise out of the surf along the Forgotten Coast, the whole western edge of Feralas where the land meets the Veiled Sea, and sea giants roam the shore.",
			full = "Water elementals rise out of the surf along the Forgotten Coast, the whole western edge of Feralas where the land meets the Veiled Sea, and sea giants roam the shore.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Coast",
		},
		["frayfeather highlands"] = {
			name = "Frayfeather Highlands",
			short = "The Frayfeather hippogryphs hold these highlands and give them their name. Deep among the crags their nests lie hidden, each with its eggs.",
			full = "The Frayfeather hippogryphs hold these highlands and give them their name. Deep among the crags their nests lie hidden, each with its eggs.",
			source = "https://warcraft.wiki.gg/wiki/Frayfeather_Highlands",
		},
		["gordunni outpost"] = {
			name = "Gordunni Outpost",
			short = "In the mountains north of Lariss Pavilion, the Gordunni ogres have taken the land, and the plant life that is green everywhere else in Feralas has withered to brown.",
			full = "In the mountains north of Lariss Pavilion, the Gordunni ogres have taken the land, and the plant life that is green everywhere else in Feralas has withered to brown. Two caves open in the hills, a small one near the entrance and an ogre mound at the back. Gordunni brutes and ogre mages roam the slopes.",
			source = "https://warcraft.wiki.gg/wiki/Gordunni_Outpost",
		},
		["grimtotem compound"] = {
			name = "Grimtotem Compound",
			short = "East of Dire Maul, the Grimtotem tauren have built a large village in two parts. In the southern part a big cage holds sprite darters prisoner.",
			full = "East of Dire Maul, the Grimtotem tauren have built a large village in two parts. In the southern part a big cage holds sprite darters prisoner. East of the northern part, gnolls have set up a few camps of their own.",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Compound",
		},
		["high wilderness"] = {
			name = "High Wilderness",
			short = "Ancient trees fill the High Wilderness, a vast forest stretching across western Feralas from the Forgotten Coast to the Verdantis River.",
			full = "Ancient trees fill the High Wilderness, a vast forest stretching across western Feralas from the Forgotten Coast to the Verdantis River. Bears, wolves and hippogryphs roam among them, and treants, yetis and ogres share the forest with them.",
			source = "https://warcraft.wiki.gg/wiki/High_Wilderness",
		},
		["isle of dread"] = {
			name = "Isle of Dread",
			short = "The Isle of Dread lies off the coast of Feralas, south of Sardor Isle. Its middle is a valley walled in by unyielding cliffs, and the only way in is from the southeast.",
			full = "The Isle of Dread lies off the coast of Feralas, south of Sardor Isle. Its middle is a valley walled in by unyielding cliffs, and the only way in is from the southeast. The chimaerok live in that valley, among them arcane-touched beasts and devourers, led by Lord Lakmaeran.\n\nAt the northern end of the isle a cave sinks deep into the rock, unlike anything else there. The Hatecrest naga hold it under Lord Shalzaru.",
			source = "https://warcraft.wiki.gg/wiki/Isle_of_Dread",
		},
		["jademir lake"] = {
			name = "Jademir Lake",
			short = "Jademir Lake lies in northern Feralas, with a small island at its center. A portal into the Emerald Dream stands there, and Lethlas and a number of green dragonspawn guard it.",
			full = "Jademir Lake lies in northern Feralas, with a small island at its center. A portal into the Emerald Dream stands there, and Lethlas and a number of green dragonspawn guard it.",
			source = "https://warcraft.wiki.gg/wiki/Jademir_Lake",
		},
		["lariss pavilion"] = {
			name = "Lariss Pavilion",
			short = "Azj'Tordin, a Highborne who disagreed with Prince Tortheldrin, lives here. He left Dire Maul by a back way that comes out at the bottom of Lariss Pavilion.",
			full = "Azj'Tordin, a Highborne who disagreed with Prince Tortheldrin, lives here. He left Dire Maul by a back way that comes out at the bottom of Lariss Pavilion.\n\nThe pavilion is a large open building in the night elf style, just north of Camp Mojache.",
			source = "https://warcraft.wiki.gg/wiki/Lariss_Pavilion",
		},
		["lower wilds"] = {
			name = "Lower Wilds",
			short = "The Lower Wilds is the eastern end of Feralas, where the forest leads on into Thousand Needles. Ironfur bears and Longtooth wolves roam among the trees, and now and then a treant wanders through.",
			full = "The Lower Wilds is the eastern end of Feralas, where the forest leads on into Thousand Needles. Ironfur bears and Longtooth wolves roam among the trees, and now and then a treant wanders through.",
			source = "https://warcraft.wiki.gg/wiki/Lower_Wilds",
		},
		["maul"] = {
			name = "The Maul",
			short = "A great pit called the Maul lies at the heart of the ruins of Dire Maul, and it serves as the ruined city's arena.",
			full = "A great pit called the Maul lies at the heart of the ruins of Dire Maul, and it serves as the ruined city's arena. The only way out of it is a tunnel that starts at a doorway on the west side and runs past packs of sleeping Gordok hyenas. A Gordok mauler and an ogre-mage stand in the pit, and Griniblix the Spectator, a goblin, watches the fights there.",
			source = "",
		},
		["oneiros"] = {
			name = "Oneiros",
			short = "The ruins of Oneiros lie south of Jademir Lake in northern Feralas. Many night elf ruins stand here, and green dragonspawn patrol them.",
			full = "The ruins of Oneiros lie south of Jademir Lake in northern Feralas. Many night elf ruins stand here, and green dragonspawn patrol them.",
			source = "https://warcraft.wiki.gg/wiki/Oneiros",
		},
		["rage scar hold"] = {
			name = "Rage Scar Hold",
			short = "The fiercest yetis in the area live in Rage Scar Hold, a cave dug into the ground. Books and strange symbols lie scattered inside.",
			full = "The fiercest yetis in the area live in Rage Scar Hold, a cave dug into the ground. Books and strange symbols lie scattered inside. Either the yetis are studying magic, or the books belonged to some unlucky magus who met his end here.",
			source = "https://warcraft.wiki.gg/wiki/Rage_Scar_Hold",
		},
		["ruins of isildien"] = {
			name = "Ruins of Isildien",
			short = "Ten thousand years ago a great night elf city in southwestern Feralas was destroyed. The Gordunni ogres have made their home in its ruins, ruling over stones raised by hands far older than their own.",
			full = "Ten thousand years ago a great night elf city in southwestern Feralas was destroyed. The Gordunni ogres have made their home in its ruins, ruling over stones raised by hands far older than their own. A cave opens on the eastern side, and at the top of a stair stands a large round building that may once have been a temple of Elune, since it looks much like the Temple of the Moon in Darnassus.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Isildien",
		},
		["ruins of ravenwind"] = {
			name = "Ruins of Ravenwind",
			short = "Northern Feralas holds the broken stones of Ravenwind, raised long ago by the Highborne of the night elves, much as Dire Maul was raised elsewhere.",
			full = "Northern Feralas holds the broken stones of Ravenwind, raised long ago by the Highborne of the night elves, much as Dire Maul was raised elsewhere. Little of that glory remains standing now. Northspring harpies have taken the ruins for their own, nesting among the fallen columns and empty halls.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ravenwind",
		},
		["ruins of solarsal"] = {
			name = "Ruins of Solarsal",
			short = "Southwest of Feathermoon Stronghold, on Sardor Isle, lie old night elf ruins, long since abandoned.",
			full = "Southwest of Feathermoon Stronghold, on Sardor Isle, lie old night elf ruins, long since abandoned. Hatecrest naga have moved in among the broken columns in such numbers that the night elves of the stronghold take it for the first move of an attack.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Solarsal",
		},
		["sardor isle"] = {
			name = "Sardor Isle",
			short = "Sardor Isle lies off the west coast of Feralas, north of the Isle of Dread. The night elves hold it as a small refuge, from Feathermoon Stronghold under General Shandris Feathermoon.",
			full = "Sardor Isle lies off the west coast of Feralas, north of the Isle of Dread. The night elves hold it as a small refuge, from Feathermoon Stronghold under General Shandris Feathermoon. Naga live along its shores and a pack of wolves ranges through what wild places remain, so the stronghold's watch is never idle.",
			source = "https://warcraft.wiki.gg/wiki/Sardor_Isle",
		},
		["shalzarus lair"] = {
			name = "Shalzaru's Lair",
			short = "Lord Shalzaru, master of the Hatecrest, lives deep inside this twisting cave at the northern end of the Isle of Dread.",
			full = "Lord Shalzaru, master of the Hatecrest, lives deep inside this twisting cave at the northern end of the Isle of Dread. It has a main cave and a smaller one joined by a waterway, and a hidden passage under the water leads to an inner chamber where Lady Szallah lives. Hatecrest sorceresses and serpent guards fill its length.",
			source = "https://warcraft.wiki.gg/wiki/Shalzaru's_Lair",
		},
		["thalanaar"] = {
			name = "Thalanaar",
			short = "Where Feralas meets Thousand Needles stands Thalanaar, a tiny night elf camp held by the Alliance. Falfindel Waywarder is here, and he fights the Death's Head cult.",
			full = "Where Feralas meets Thousand Needles stands Thalanaar, a tiny night elf camp held by the Alliance. Falfindel Waywarder is here, and he fights the Death's Head cult.",
			source = "https://warcraft.wiki.gg/wiki/Thalanaar",
		},
		["twin colossals"] = {
			name = "The Twin Colossals",
			short = "Two sheer mountains, the Twin Colossals, rise on the western edge of Feralas, higher than anything else in the region.",
			full = "Two sheer mountains, the Twin Colossals, rise on the western edge of Feralas, higher than anything else in the region. The road to Desolace runs through the gap between them, and the pair are among the most striking sights in the land.\n\nOn top of the eastern peak lies a small, deep pond. From the summit the whole region opens out below.",
			source = "https://warcraft.wiki.gg/wiki/Twin_Colossals",
		},
		["verdantis river"] = {
			name = "Verdantis River",
			short = "The Verdantis River winds through central Feralas, southeast of the ruins of Dire Maul, cutting a quiet green thread through the tangled forest.",
			full = "The Verdantis River winds through central Feralas, southeast of the ruins of Dire Maul, cutting a quiet green thread through the tangled forest. Its waters hold Feralas ahi, found nowhere else in the world.",
			source = "https://warcraft.wiki.gg/wiki/Verdantis_River",
		},
		["wildwind lake"] = {
			name = "Wildwind Lake",
			short = "Wildwind Lake lies beside Camp Mojache and is fed by the swift stream that runs through the tauren village.",
			full = "Wildwind Lake lies beside Camp Mojache and is fed by the swift stream that runs through the tauren village.",
			source = "https://warcraft.wiki.gg/wiki/Wildwind_Lake",
		},
		["woodpaw den"] = {
			name = "Woodpaw Den",
			short = "The Woodpaw Alphas, the leaders of the Woodpaw gnolls, crowd this den in Feralas, with mystics and reavers of the clan among them.",
			full = "The Woodpaw Alphas, the leaders of the Woodpaw gnolls, crowd this den in Feralas, with mystics and reavers of the clan among them.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Den",
		},
		["woodpaw hills"] = {
			name = "Woodpaw Hills",
			short = "The gnolls of the Woodpaw clan make their home in these forested hills in southeastern Feralas.",
			full = "The gnolls of the Woodpaw clan make their home in these forested hills in southeastern Feralas. In the far southeast the ground has split open, in the place now called the Writhing Deep, and silithid have burst up from it.\n\nThe Woodpaw Alphas who lead the tribe walk the camps as well as the Woodpaw Den.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Hills",
		},
		["writhing deep"] = {
			name = "The Writhing Deep",
			short = "Hive Zukk'ash lies in the southeastern corner of Feralas, where silithid swarm up out of the ground. Its workers, tunnelers, stingers and wasps fill the hive, and a silithid wasp called Qirot flies among them.",
			full = "Hive Zukk'ash lies in the southeastern corner of Feralas, where silithid swarm up out of the ground. Its workers, tunnelers, stingers and wasps fill the hive, and a silithid wasp called Qirot flies among them.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Deep",
		},
	},
	-- Dustwallow Marsh: 24 subzones
	[1445] = {
		["alcaz island"] = {
			name = "Alcaz Island",
			short = "Tropical green covers Alcaz Island, off the northeast coast of Dustwallow Marsh, unlike anything on the mainland.",
			full = "Tropical green covers Alcaz Island, off the northeast coast of Dustwallow Marsh, unlike anything on the mainland. The Strashaz naga hold its shores, myrmidons and sirens thick among them, and hydras prowl the water around it.\n\nA flying machine has landed on the island, and the minions of its mad inventor keep watch around it.",
			source = "https://warcraft.wiki.gg/wiki/Alcaz_Island",
		},
		["beezils wreck"] = {
			name = "Beezil's Wreck",
			short = "A goblin zeppelin bound south with supplies went down in the deepest reaches of Dustwallow Marsh, east of Tabetha's Farm. Its hull lies broken in the mud, cargo scattered among the wreckage.",
			full = "A goblin zeppelin bound south with supplies went down in the deepest reaches of Dustwallow Marsh, east of Tabetha's Farm. Its hull lies broken in the mud, cargo scattered among the wreckage.",
			source = "https://warcraft.wiki.gg/wiki/Beezil's_Wreck",
		},
		["bloodfen burrow"] = {
			name = "Bloodfen Burrow",
			short = "Bloodfen raptors nest in great numbers in a cave in the south-west of Dustwallow Marsh. Outside the entrance lie the remains of some settlement, torn apart by the ravenous raptors.",
			full = "Bloodfen raptors nest in great numbers in a cave in the south-west of Dustwallow Marsh. Outside the entrance lie the remains of some settlement, torn apart by the ravenous raptors.",
			source = "https://warcraft.wiki.gg/wiki/Bloodfen_Burrow",
		},
		["bluefen"] = {
			name = "Bluefen",
			short = "Bluefen is low marshland in the north of Dustwallow Marsh, near Brackenwall Village. Spiders, marsh birds, raptors and crocolisks overrun it, and Theramore infiltrators have been seen among them.",
			full = "Bluefen is low marshland in the north of Dustwallow Marsh, near Brackenwall Village. Spiders, marsh birds, raptors and crocolisks overrun it, and Theramore infiltrators have been seen among them.",
			source = "https://warcraft.wiki.gg/wiki/Bluefen",
		},
		["brackenwall village"] = {
			name = "Brackenwall Village",
			short = "The Stonemaul ogres came to Brackenwall as refugees. Black dragons fell on their old village in the south and ruined it, and Overlord Mok'Morokk led the survivors north to this cluster of a few huts and an ogre mound.",
			full = "The Stonemaul ogres came to Brackenwall as refugees. Black dragons fell on their old village in the south and ruined it, and Overlord Mok'Morokk led the survivors north to this cluster of a few huts and an ogre mound. No black dragon lives here, and Mok'Morokk is content to leave it that way.\n\nOthers will not. Tharg and Draz'Zilb refuse to call Brackenwall home and want the old village back.",
			source = "https://warcraft.wiki.gg/wiki/Brackenwall_Village",
		},
		["darkmist cavern"] = {
			name = "Darkmist Cavern",
			short = "A small mine in the northwest of Dustwallow Marsh has been given over to spiders grown terrifyingly large in the dark.",
			full = "A small mine in the northwest of Dustwallow Marsh has been given over to spiders grown terrifyingly large in the dark. The marsh folk call them the Darkmist Spiders, and the cavern Darkmist in turn, though none can say which name came first.\n\nRuins of small houses stand outside the mine, half-sunk in the wet ground. They suggest a settlement was here once.",
			source = "https://warcraft.wiki.gg/wiki/Darkmist_Cavern",
		},
		["den of flame"] = {
			name = "The Den of Flame",
			short = "The Den of Flame began as an ogre mound raised by the Stonemaul, and the stonework still bears their craft. It lies just west of the Stonemaul Ruins.",
			full = "The Den of Flame began as an ogre mound raised by the Stonemaul, and the stonework still bears their craft. It lies just west of the Stonemaul Ruins. Black dragonkin have overrun it, probably on the orders of Onyxia, who lives nearby, and hold it as a nest of the black dragonflight.",
			source = "https://warcraft.wiki.gg/wiki/Den_of_Flame",
		},
		["dragonmurk"] = {
			name = "The Dragonmurk",
			short = "Dragon whelps and dragonspawn of the black dragonflight breed thickly in the Dragonmurk, the fetid ground of the southern marsh. The Den of Flame and the Stonemaul Ruins stand inside it, and black dragonspawn hold both.",
			full = "Dragon whelps and dragonspawn of the black dragonflight breed thickly in the Dragonmurk, the fetid ground of the southern marsh. The Den of Flame and the Stonemaul Ruins stand inside it, and black dragonspawn hold both.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmurk",
		},
		["dreadmurk shore"] = {
			name = "Dreadmurk Shore",
			short = "The Mirefin murlocs claim this coastline and the scattered islands along it, and they infest it. Sea turtles and other sea creatures share the water.",
			full = "The Mirefin murlocs claim this coastline and the scattered islands along it, and they infest it. Sea turtles and other sea creatures share the water.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmurk_Shore",
		},
		["dustwallow bay"] = {
			name = "Dustwallow Bay",
			short = "Dustwallow Bay is where the Great Sea reaches the eastern coast of the marsh, west of Theramore Isle. Salt water mixes with swamp water here and turns a wide band of the coast brackish.",
			full = "Dustwallow Bay is where the Great Sea reaches the eastern coast of the marsh, west of Theramore Isle. Salt water mixes with swamp water here and turns a wide band of the coast brackish. Makrura and turtles crowd its shallows, and young threshers swim the deeper water.",
			source = "https://warcraft.wiki.gg/wiki/Dustwallow_Bay",
		},
		["emberstrifes den"] = {
			name = "Emberstrife's Den",
			short = "A wide cave opens into the reeking Wyrmbog, home to the black drake Emberstrife. He puts young black dragonlings through vigorous tests, and only those he finds worthy go on to Onyxia's Lair.",
			full = "A wide cave opens into the reeking Wyrmbog, home to the black drake Emberstrife. He puts young black dragonlings through vigorous tests, and only those he finds worthy go on to Onyxia's Lair.",
			source = "https://warcraft.wiki.gg/wiki/Emberstrife's_Den",
		},
		["foothold citadel"] = {
			name = "Foothold Citadel",
			short = "At the doors of Foothold Citadel, the guards of Theramore drill against practice dummies and young recruits spar with each other. Priests watch close by, ready to call on the Light the instant anyone is hurt.",
			full = "At the doors of Foothold Citadel, the guards of Theramore drill against practice dummies and young recruits spar with each other. Priests watch close by, ready to call on the Light the instant anyone is hurt. The keep is the headquarters of the Theramore Guard.\n\nGrand Admiral Daelin Proudmoore died in battle inside it. He had taken Theramore, and Warchief Thrall asked Lady Jaina Proudmoore to let the Horde in so that they could kill her father. Thrall's forces stormed the city, led by Rexxar and his companions, and Rexxar faced the admiral himself in his keep.",
			source = "https://warcraft.wiki.gg/wiki/Foothold_Citadel",
		},
		["lost point"] = {
			name = "Lost Point",
			short = "Theramore built Lost Point as a scout tower in the west of the marsh. It is run-down and decrepit now, and no longer serves its builders.",
			full = "Theramore built Lost Point as a scout tower in the west of the marsh. It is run-down and decrepit now, and no longer serves its builders. Theramore deserters live in it under their leader, Balos Jacken.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Point",
		},
		["north point tower"] = {
			name = "North Point Tower",
			short = "A sizable contingent of Theramore guards holds North Point Tower beside a well-traveled stretch of road in the north of the marsh. Since deserters took over Lost Point, it is the most distant of Theramore's outposts.",
			full = "A sizable contingent of Theramore guards holds North Point Tower beside a well-traveled stretch of road in the north of the marsh. Since deserters took over Lost Point, it is the most distant of Theramore's outposts.",
			source = "https://warcraft.wiki.gg/wiki/North_Point_Tower",
		},
		["onyxias lair"] = {
			name = "Onyxia's Lair",
			short = "The entrance to Onyxia's Lair is carved to look like the maw of the broodmother herself. Inside, the path is lined with magma, and the ground is cracked and glowing with fire from below.",
			full = "The entrance to Onyxia's Lair is carved to look like the maw of the broodmother herself. Inside, the path is lined with magma, and the ground is cracked and glowing with fire from below. The stone ceiling groans and shifts, and rock falls without end. Lava spills from the walls where the heat cannot be held.\n\nOnyxia built it, and her kin, the black dragonflight, guard her here. She is the daughter of Deathwing and the sister of Nefarian, lord of Blackrock Spire. Where her father rules by force and her brother breeds twisted abominations, she works through charm. She delights in meddling in the politics of mortals and bending them to her own ends.",
			source = "https://warcraft.wiki.gg/wiki/Onyxia's_Lair",
		},
		["quagmire"] = {
			name = "The Quagmire",
			short = "The Quagmire fills the sodden heart of Dustwallow Marsh, reaching from Lost Point in the west to Dustwallow Bay in the east.",
			full = "The Quagmire fills the sodden heart of Dustwallow Marsh, reaching from Lost Point in the west to Dustwallow Bay in the east. Crocolisks lurk in its black water, spiders and oozes crawl through it, and Grimtotem tauren have made their home here.",
			source = "https://warcraft.wiki.gg/wiki/Quagmire",
		},
		["sentry point"] = {
			name = "Sentry Point",
			short = "A scout tower built by Theramore stands just across the bridge from the city, watching the comings and goings on the road.",
			full = "A scout tower built by Theramore stands just across the bridge from the city, watching the comings and goings on the road.",
			source = "https://warcraft.wiki.gg/wiki/Sentry_Point",
		},
		["shady rest inn"] = {
			name = "Shady Rest Inn",
			short = "The Shady Rest Inn, a human-built waystop near the border of Dustwallow Marsh and the Barrens, burned to the ground without explanation.",
			full = "The Shady Rest Inn, a human-built waystop near the border of Dustwallow Marsh and the Barrens, burned to the ground without explanation. James Hyal ran the inn, and his wife and child died in the blaze. Little of it still stands but a crumbling chimney, and the blackened ruin is still smoking.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Rest_Inn",
		},
		["stonemaul ruins"] = {
			name = "Stonemaul Ruins",
			short = "Kor'gall seized the Stonemaul clan with an ancient orcish axe, Serathil, and ruled its village by cruelty. Crol'ka, whose brothers Kor'gall had killed, barely escaped with his life.",
			full = "Kor'gall seized the Stonemaul clan with an ancient orcish axe, Serathil, and ruled its village by cruelty. Crol'ka, whose brothers Kor'gall had killed, barely escaped with his life. A Darkspear patrol found him, and Vol'jin and Rexxar agreed to help, hoping to win the Stonemaul for the Horde's war against Kul Tiras.\n\nBarred at the gates, Rexxar fought his way in. Kor'gall let him join the clan if he survived the Gauntlet, a valley full of deadly beasts, and Rexxar did. When Kor'gall then refused to lend the clan to the war, Rexxar challenged him for the leadership and killed him, and the Stonemaul went to war under Rexxar. Afterward he left the clan to Mok'Morokk, who took from his people instead of serving them.\n\nBlack dragons later raided the village and claimed it. Mok'Morokk led the survivors away, and Firemane dragonspawn infest the ruins now.",
			source = "https://warcraft.wiki.gg/wiki/Stonemaul_Ruins",
		},
		["swamplight manor"] = {
			name = "Swamplight Manor",
			short = "\"Swamp Eye\" Jarl, a famous cook, lives in Swamplight Manor, a modest house on Witch Hill with a small garden outside.",
			full = "\"Swamp Eye\" Jarl, a famous cook, lives in Swamplight Manor, a modest house on Witch Hill with a small garden outside. He favors good swamp cooking, fried green frog legs and frog leg stew, and he counts the eyes of Darkmist spiders a delicacy.",
			source = "https://warcraft.wiki.gg/wiki/Swamplight_Manor",
		},
		["theramore isle"] = {
			name = "Theramore Isle",
			short = "During the Third War, Lady Jaina Proudmoore led the survivors of Lordaeron across the sea to Kalimdor.",
			full = "During the Third War, Lady Jaina Proudmoore led the survivors of Lordaeron across the sea to Kalimdor. After the Burning Legion's defeat at Mount Hyjal, they raised Theramore on a rocky island off Dustwallow Marsh, a walled port meant to safeguard the ragged remnants of the failing Alliance. A rectangular wall studded with cannon towers rings most of the isle. Only the harbor is open, and two scout towers guard it. At the center, behind an inner wall, rises Jaina's Tower, the tallest building in the city. Its many stories are linked by long winding stairs, and its walls are warded against attack. It holds her private rooms, her library and the small throne room.\n\nThe marsh gives poor timber, and the city's shipwrights call the local trees marshy garbage. They envy the orcs, who cut good oaks above Orgrimmar. Even so, humans trade fish to the orcs for surplus Durotar crops. Most people know each other, and crime is rare.",
			source = "https://warcraft.wiki.gg/wiki/Theramore_Isle",
		},
		["tidefury cove"] = {
			name = "Tidefury Cove",
			short = "Treacherous water lies at the end of Dustwallow Bay, south of Theramore Isle. Small islands and hidden reefs dot the cove, and two ships lie broken on its shallows, given over now to roaming makrura.",
			full = "Treacherous water lies at the end of Dustwallow Bay, south of Theramore Isle. Small islands and hidden reefs dot the cove, and two ships lie broken on its shallows, given over now to roaming makrura. The famous fisherman Nat Pagle makes his home on one of the islets.",
			source = "https://warcraft.wiki.gg/wiki/Tidefury_Cove",
		},
		["witch hill"] = {
			name = "Witch Hill",
			short = "Mirefin murloc camps stand in the mire of Witch Hill, and crocolisks, spiders and raptors hunt across it. Swamplight Manor sits near its center, and \"Swamp Eye\" Jarl lives there.",
			full = "Mirefin murloc camps stand in the mire of Witch Hill, and crocolisks, spiders and raptors hunt across it. Swamplight Manor sits near its center, and \"Swamp Eye\" Jarl lives there.",
			source = "https://warcraft.wiki.gg/wiki/Witch_Hill",
		},
		["wyrmbog"] = {
			name = "Wyrmbog",
			short = "South of the Dragonmurk lies the Wyrmbog. Black dragons make their home here, Onyxia, the daughter of Deathwing, and Emberstrife among them, and the entrances to Emberstrife's Den and Onyxia's Lair lie within the bog.",
			full = "South of the Dragonmurk lies the Wyrmbog. Black dragons make their home here, Onyxia, the daughter of Deathwing, and Emberstrife among them, and the entrances to Emberstrife's Den and Onyxia's Lair lie within the bog.",
			source = "https://warcraft.wiki.gg/wiki/Wyrmbog",
		},
	},
	-- Tanaris: 23 subzones
	[1446] = {
		["abyssal sands"] = {
			name = "Abyssal Sands",
			short = "The sands here lie within Tanaris, a desert reaching in every direction.",
			full = "The sands here lie within Tanaris, a desert reaching in every direction.",
			source = "https://warcraft.wiki.gg/wiki/Abyssal_Sands",
		},
		["broken pillar"] = {
			name = "Broken Pillar",
			short = "The goblin scientist Marvon Rivetseeker has made his camp among a small group of troll ruins south of Gadgetzan.",
			full = "The goblin scientist Marvon Rivetseeker has made his camp among a small group of troll ruins south of Gadgetzan. His home is in Ratchet, but after his zeppelin crashed here he decided to start the research he had come to do among these stones.",
			source = "https://warcraft.wiki.gg/wiki/Broken_Pillar",
		},
		["caverns of time"] = {
			name = "Caverns of Time",
			short = "The bronze dragonflight has guarded the Caverns of Time since the world was young. The titans gave them the task, and they keep it still.",
			full = "The bronze dragonflight has guarded the Caverns of Time since the world was young. The titans gave them the task, and they keep it still. Beneath the eastern sands the caverns wind like a labyrinth, and the paths through them follow the shifting timeways. Mortals are kept out, because their meddling could upset the flow of time.\n\nNozdormu, the Aspect of Time, makes his home here. The dragon Anachronos sits outside the gate. It was here that he first learned how great a threat the silithid were, with their hives spreading through the remote parts of the desert.",
			source = "https://warcraft.wiki.gg/wiki/Caverns_of_Time",
		},
		["dunemaul compound"] = {
			name = "Dunemaul Compound",
			short = "The Dunemaul are nomadic ogres who have taken over a wide stretch of Tanaris, and this mound is their compound. Brutes and enforcers hold it alongside ogre mages and warlocks.",
			full = "The Dunemaul are nomadic ogres who have taken over a wide stretch of Tanaris, and this mound is their compound. Brutes and enforcers hold it alongside ogre mages and warlocks. Gor'marok the Ravager leads them.",
			source = "https://warcraft.wiki.gg/wiki/Dunemaul_Compound",
		},
		["eastmoon ruins"] = {
			name = "Eastmoon Ruins",
			short = "Dunemaul ogres have taken over the Eastmoon Ruins, the crumbling stonework of an ancient troll settlement just west of the Gaping Chasm.",
			full = "Dunemaul ogres have taken over the Eastmoon Ruins, the crumbling stonework of an ancient troll settlement just west of the Gaping Chasm. The trolls are long gone from it.",
			source = "https://warcraft.wiki.gg/wiki/Eastmoon_Ruins",
		},
		["gadgetzan"] = {
			name = "Gadgetzan",
			short = "Profit above loyalty is the creed of Gadgetzan, capital of the Steamwheedle Cartel, the largest of the goblin cartels. That makes the city neutral ground in the quarrel between the Horde and the Alliance.",
			full = "Profit above loyalty is the creed of Gadgetzan, capital of the Steamwheedle Cartel, the largest of the goblin cartels. That makes the city neutral ground in the quarrel between the Horde and the Alliance. Both governments recognize this, and goblin bruisers patrol the streets, ready to pound to a pulp anyone who brings war into a place built on trade. Wallets, not banners, decide who is welcome.\n\nSome of the best goblin engineers, miners and alchemists work here. In the auction house humans trade kittens to the Horde and tauren trade prairie dogs to the Alliance, and some say the pet trade may bring the two sides to terms.",
			source = "https://warcraft.wiki.gg/wiki/Gadgetzan",
		},
		["gaping chasm"] = {
			name = "The Gaping Chasm",
			short = "Hazzali silithid swarm through the Gaping Chasm, and several large hive complexes lie within it. It is one of the minor hives in southeastern Tanaris, just east of the Eastmoon Ruins.",
			full = "Hazzali silithid swarm through the Gaping Chasm, and several large hive complexes lie within it. It is one of the minor hives in southeastern Tanaris, just east of the Eastmoon Ruins. Workers and tunnelers, stingers, wasps, swarmers and sandreavers fill it, and a silithid reaver called Haarka the Ravenous hunts among them.\n\nSenior Surveyor Fizzledowser of the Gadgetzan Water Company once sent his junior, Scrimshank, down to survey it. Nothing has been heard from him since.",
			source = "https://warcraft.wiki.gg/wiki/Gaping_Chasm",
		},
		["lands end beach"] = {
			name = "Land's End Beach",
			short = "Land's End Beach lies at the southernmost point of Tanaris, in the far southeastern corner of Kalimdor, one of the remotest places in the world.",
			full = "Land's End Beach lies at the southernmost point of Tanaris, in the far southeastern corner of Kalimdor, one of the remotest places in the world. Two islands lie off the shore. Surf gliders roam the eastern stretch of sand, and a mermaid named Meridith lives in the water off the eastern shore.",
			source = "https://warcraft.wiki.gg/wiki/Land's_End_Beach",
		},
		["lost rigger cove"] = {
			name = "Lost Rigger Cove",
			short = "Mountains close in on three sides of Lost Rigger Cove, which hides the port of the Southsea Pirates on the Tanaris coast. A shipyard here is busy building a new vessel.",
			full = "Mountains close in on three sides of Lost Rigger Cove, which hides the port of the Southsea Pirates on the Tanaris coast. A shipyard here is busy building a new vessel.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Rigger_Cove",
		},
		["noonshade ruins"] = {
			name = "Noonshade Ruins",
			short = "Wastewander bandits have overrun the Noonshade Ruins, worn stone left behind by trolls long gone, east of Gadgetzan in northeastern Tanaris.",
			full = "Wastewander bandits have overrun the Noonshade Ruins, worn stone left behind by trolls long gone, east of Gadgetzan in northeastern Tanaris.",
			source = "https://warcraft.wiki.gg/wiki/Noonshade_Ruins",
		},
		["noxious lair"] = {
			name = "The Noxious Lair",
			short = "The ground in southwestern Tanaris sinks a little here, overlooking Un'Goro Crater, as if something broad and shallow, a river or a lake, once lay across it.",
			full = "The ground in southwestern Tanaris sinks a little here, overlooking Un'Goro Crater, as if something broad and shallow, a river or a lake, once lay across it. The Centipaar silithid hold it now, and they have drained the water pools that used to lie here. Large claws stand twitching in the sand, seemingly from huge silithid buried beneath, and the soil around each is drenched in silithid goo, the only moisture left in a place that used to hold a lake.\n\nBelow the surface the hive is humid, warm and eerie. Tunnels join its two entrances to the breeding rooms, and the walls are coated with silithid acid and hung with unborn insects.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Lair",
		},
		["sandsorrow watch"] = {
			name = "Sandsorrow Watch",
			short = "From a chain of watchtowers called Sandsorrow Watch, the Sandfury trolls keep an eye on their holdings across a wide area west of Gadgetzan.",
			full = "From a chain of watchtowers called Sandsorrow Watch, the Sandfury trolls keep an eye on their holdings across a wide area west of Gadgetzan. They have had to give up most of Tanaris to outsiders over the years, and they guard what is left fiercely. The Sandfury need every troll to pitch in just to get by, so they learned to raise the dead with voodoo, and a troll can go on working even after death.",
			source = "https://warcraft.wiki.gg/wiki/Sandsorrow_Watch",
		},
		["south seas"] = {
			name = "South Seas",
			short = "During the Second War the Stormreaver clan captured giant sea turtles in these waters for the Horde to use as submarines, and daring goblins of the Steamwheedle Cartel steered them against enemy ships.",
			full = "During the Second War the Stormreaver clan captured giant sea turtles in these waters for the Horde to use as submarines, and daring goblins of the Steamwheedle Cartel steered them against enemy ships. The South Seas are the stretch of the Great Sea that washes the southern shores of the Eastern Kingdoms and Kalimdor. Zandalar and Tel'Abim rise among its islands. The flesh-eating bloodwing bat rules the night sky over the misty jungle islands, and giant squids live in the deep.",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southbreak shore"] = {
			name = "Southbreak Shore",
			short = "A flat stretch of beach runs along the southern edge of Tanaris, south of Lost Rigger Cove, quiet and almost deserted. Turtles and sea giants roam the surf.",
			full = "A flat stretch of beach runs along the southern edge of Tanaris, south of Lost Rigger Cove, quiet and almost deserted. Turtles and sea giants roam the surf. Just off the coast, on a small island, lives a lone gnome named Winkey.",
			source = "https://warcraft.wiki.gg/wiki/Southbreak_Shore",
		},
		["southmoon ruins"] = {
			name = "Southmoon Ruins",
			short = "Old troll ruins lie in southern Tanaris, just north of the Valley of the Watchers, their stones weathered and half-buried in the desert sand.",
			full = "Old troll ruins lie in southern Tanaris, just north of the Valley of the Watchers, their stones weathered and half-buried in the desert sand. Dunemaul ogres hold them.",
			source = "https://warcraft.wiki.gg/wiki/Southmoon_Ruins",
		},
		["steamwheedle port"] = {
			name = "Steamwheedle Port",
			short = "Steamwheedle Port sits on the eastern coast of Tanaris, with a road running west to Gadgetzan, its mother city. A dock reaches out toward the outer islands, and the goblins keep their ships to themselves.",
			full = "Steamwheedle Port sits on the eastern coast of Tanaris, with a road running west to Gadgetzan, its mother city. A dock reaches out toward the outer islands, and the goblins keep their ships to themselves. The port belongs to the Steamwheedle Cartel, who deal with anyone so long as the gold is good.\n\nAmong its residents is Yeh'kinya, who is trying to learn more about the essence of an ancient god.",
			source = "https://warcraft.wiki.gg/wiki/Steamwheedle_Port",
		},
		["thistleshrub valley"] = {
			name = "Thistleshrub Valley",
			short = "Giant cacti stand thick in Thistleshrub Valley, strange for such barren desert to keep alive. Desert-dwelling thistleshrubs crowd the valley too.",
			full = "Giant cacti stand thick in Thistleshrub Valley, strange for such barren desert to keep alive. Desert-dwelling thistleshrubs crowd the valley too.",
			source = "https://warcraft.wiki.gg/wiki/Thistleshrub_Valley",
		},
		["uldum"] = {
			name = "Uldum",
			short = "The titans left a holding in the southern part of the desert, the ancient city of Uldum, rich in their lore. It is a research facility, where they work to improve the living world of Azeroth.",
			full = "The titans left a holding in the southern part of the desert, the ancient city of Uldum, rich in their lore. It is a research facility, where they work to improve the living world of Azeroth.",
			source = "https://warcraft.wiki.gg/wiki/Uldum",
		},
		["valley of the watchers"] = {
			name = "Valley of the Watchers",
			short = "A great gate stands in the Valley of the Watchers, impenetrable against Uldum behind it. Mountain giants called Dune Smashers roam the valley.",
			full = "A great gate stands in the Valley of the Watchers, impenetrable against Uldum behind it. Mountain giants called Dune Smashers roam the valley.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_the_Watchers",
		},
		["waterspring field"] = {
			name = "Waterspring Field",
			short = "Water towers rise across Waterspring Field, pumping water up from reserves deep underground. The goblins of Gadgetzan built them to supply their desert operations.",
			full = "Water towers rise across Waterspring Field, pumping water up from reserves deep underground. The goblins of Gadgetzan built them to supply their desert operations. Then the Wastewanders arrived, a nomadic gang of bandits, and claimed the field and the towers for themselves.\n\nThey squat on the land under their leader, Caliph Scorpidsting, hoping it will be kinder than the ogre camp they once lived in. They still shiver at the memory. The Gadgetzan Water Company wants its towers back, and it has put a high bounty on the Caliph's head for murdering its workers and seizing its property.",
			source = "https://warcraft.wiki.gg/wiki/Waterspring_Field",
		},
		["wavestrider beach"] = {
			name = "Wavestrider Beach",
			short = "Two ships burn off the coast of Wavestrider Beach, and they seem to be fighting each other. The beach runs along the eastern shore of Tanaris, near Steamwheedle Port.",
			full = "Two ships burn off the coast of Wavestrider Beach, and they seem to be fighting each other. The beach runs along the eastern shore of Tanaris, near Steamwheedle Port. Steeljaw snappers crawl across the sand, and Wastewander bandits roam the beach.",
			source = "https://warcraft.wiki.gg/wiki/Wavestrider_Beach",
		},
		["zalashjis den"] = {
			name = "Zalashji's Den",
			short = "A naga named Zalashji makes his home in this small cave in eastern Tanaris.",
			full = "A naga named Zalashji makes his home in this small cave in eastern Tanaris.",
			source = "https://warcraft.wiki.gg/wiki/Zalashji's_Den",
		},
		["zulfarrak"] = {
			name = "Zul'Farrak",
			short = "Chief Ukorz Sandscalp rules Zul'Farrak, the Sandfury city in northwestern Tanaris. The Sandfury are known for their particular ruthlessness and dark mysticism.",
			full = "Chief Ukorz Sandscalp rules Zul'Farrak, the Sandfury city in northwestern Tanaris. The Sandfury are known for their particular ruthlessness and dark mysticism. Ukorz was raised on stories of a time when trolls lorded over these lands with no outsiders in the way, and he wants that time back. The Sandfury are raising an army of undead trolls to win it.\n\nZul'Farrak was once the shining jewel of Tanaris, and its trolls have had to give up much of their territory since. Troll legends tell of Sul'thraze the Lasher, a sword that fills even the strongest foe with fear and weakness. It was split in half long ago, and rumor puts both halves inside these sun-blasted walls. Others say a demigod sleeps in a sacred pool at the city's heart.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Farrak",
		},
	},
	-- Azshara: 29 subzones
	[1447] = {
		["bay of storms"] = {
			name = "Bay of Storms",
			short = "The Bay of Storms is a stretch of the Great Sea off the eastern coast of Azshara, and travelers know it for the storms that gather over it.",
			full = "The Bay of Storms is a stretch of the Great Sea off the eastern coast of Azshara, and travelers know it for the storms that gather over it. When the world broke, much of the night elf city of Eldarath sank into its water, and the drowned stones still lie below the surface.\n\nIslands in the bay have residents of their own. Loramus Thalipedes, a demon hunter, watches the horizon from his island refuge with his guardians beside him. On a small island far to the east, Duke Hydraxis of the Waterlords keeps his honor guard, and his war with the other elemental lords still rages.",
			source = "https://warcraft.wiki.gg/wiki/Bay_of_Storms",
		},
		["bears head"] = {
			name = "Bear's Head",
			short = "Furbolg villages dot the land at Bear's Head, small outposts of the Timbermaw tribe that serve the larger Timbermaw settlements to the north.",
			full = "Furbolg villages dot the land at Bear's Head, small outposts of the Timbermaw tribe that serve the larger Timbermaw settlements to the north. The place takes its name from them.\n\nOn a cliff above them stands the tower of Archmage Xylem, who lives there with several apprentices and associates.",
			source = "https://warcraft.wiki.gg/wiki/Bear's_Head",
		},
		["bitter reaches"] = {
			name = "Bitter Reaches",
			short = "The northeast of Azshara is called the Bitter Reaches. Hippogryphs, oozes and chimaerae fill the land.",
			full = "The northeast of Azshara is called the Bitter Reaches. Hippogryphs, oozes and chimaerae fill the land. Along its northern edge mountain giants have driven off most of the other wildlife and hold the ground for themselves.",
			source = "https://warcraft.wiki.gg/wiki/Bitter_Reaches",
		},
		["blackmaw hold"] = {
			name = "Blackmaw Hold",
			short = "High in the mountains of Azshara, narrow corridors lead into Blackmaw Hold, a grotto of rusted reds and golds.",
			full = "High in the mountains of Azshara, narrow corridors lead into Blackmaw Hold, a grotto of rusted reds and golds. A sect of the Blackmaw furbolgs has fallen to an insidious corruption, though others of their clan have kept their minds. Ritualists chant at the heart of a twisted ritual, and boars patrol the passages.\n\nAcross a lake lies a cavern where a rotting bear stalks, and ravenous larvae burst from the infested scars on its back.",
			source = "",
		},
		["forlorn ridge"] = {
			name = "Forlorn Ridge",
			short = "A mountain called Forlorn Ridge rises over southwestern Azshara and commands the land around it. Both the Alliance and the Horde have built fortifications on its slopes.",
			full = "A mountain called Forlorn Ridge rises over southwestern Azshara and commands the land around it. Both the Alliance and the Horde have built fortifications on its slopes.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Ridge",
		},
		["haldarr encampment"] = {
			name = "Haldarr Encampment",
			short = "The Haldarr clan of satyrs has made its camp in western Azshara, northeast of Shadowsong Shrine and southwest of Valormok. The encampment is thick with vicious satyrs, a corrupted host of goat-legged fiends.",
			full = "The Haldarr clan of satyrs has made its camp in western Azshara, northeast of Shadowsong Shrine and southwest of Valormok. The encampment is thick with vicious satyrs, a corrupted host of goat-legged fiends.",
			source = "https://warcraft.wiki.gg/wiki/Haldarr_Encampment",
		},
		["hetaeras clutch"] = {
			name = "Hetaera's Clutch",
			short = "Beneath the waters of the Bay of Storms lies Hetaera's Clutch, a large temple of Elune now home to hydras, the children of Hetaera.",
			full = "Beneath the waters of the Bay of Storms lies Hetaera's Clutch, a large temple of Elune now home to hydras, the children of Hetaera. Hetaera herself swims the sea just north of it, sometimes resting on a tiny island there, and calls herself the ruler of these waters. Sons of the sea giant Lord Arkkoroc patrol here too. She has killed many of them, and Arkkoroc names her a false god.",
			source = "https://warcraft.wiki.gg/wiki/Hetaera's_Clutch",
		},
		["jagged reef"] = {
			name = "Jagged Reef",
			short = "Jets of stone break the sandy beach of Azshara's northern coast again and again, and small inlets of the sea cut into the shore. Rocks and shallows hide beneath the surface, so travel along the coast is hazardous.",
			full = "Jets of stone break the sandy beach of Azshara's northern coast again and again, and small inlets of the sea cut into the shore. Rocks and shallows hide beneath the surface, so travel along the coast is hazardous. Murlocs, hydras and makrura hold this shore, swimming the shallows or plodding across the sand in search of food.",
			source = "https://warcraft.wiki.gg/wiki/Jagged_Reef",
		},
		["lake mennar"] = {
			name = "Lake Mennar",
			short = "The waters of Lake Mennar lie still at their center, though dragonspawn hold the ground on every side.",
			full = "The waters of Lake Mennar lie still at their center, though dragonspawn hold the ground on every side. Anyone who crosses that ring finds the lake itself free of danger, a place of quiet and refreshment inside the guarded shores.\n\nFew places in the world hold so many of the blue dragonflight, and the only one like it is Mazthoril in Winterspring.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mennar",
		},
		["legash encampment"] = {
			name = "Legash Encampment",
			short = "Legashi satyrs hold this camp in northern Azshara, east of Ursolan and north of the Thalassian Base Camp.",
			full = "Legashi satyrs hold this camp in northern Azshara, east of Ursolan and north of the Thalassian Base Camp. Their rogues and hellcallers crowd it under Master Feardred, and Thunderhead hippogryphs range over the land around them.",
			source = "https://warcraft.wiki.gg/wiki/Legash_Encampment",
		},
		["legashi stronghold"] = {
			name = "Legashi Stronghold",
			short = "Legashi satyrs crowd the Legashi Stronghold in Azshara, the same sect that camps at the Legash Encampment.",
			full = "Legashi satyrs crowd the Legashi Stronghold in Azshara, the same sect that camps at the Legash Encampment.",
			source = "",
		},
		["ravencrest monument"] = {
			name = "Ravencrest Monument",
			short = "Two broken legs stand on the cliffs at the southern tip of Azshara, all that is left of an ancient night elf colossus.",
			full = "Two broken legs stand on the cliffs at the southern tip of Azshara, all that is left of an ancient night elf colossus. The rest of the figure lies scattered on the stone around them, or has slipped beneath the waves below. Who it honored is not known.\n\nThe Spitelash naga hold the ruins now.",
			source = "https://warcraft.wiki.gg/wiki/Ravencrest_Monument",
		},
		["rethress sanctum"] = {
			name = "Rethress Sanctum",
			short = "Rethress Sanctum, a ruined shrine on the southern coast, stands broken among the Ruined Reaches. No one keeps it now. Murlocs and makrura wander through its fallen stones, the only ones who come here at all.",
			full = "Rethress Sanctum, a ruined shrine on the southern coast, stands broken among the Ruined Reaches. No one keeps it now. Murlocs and makrura wander through its fallen stones, the only ones who come here at all.",
			source = "https://warcraft.wiki.gg/wiki/Rethress_Sanctum",
		},
		["ruined reaches"] = {
			name = "The Ruined Reaches",
			short = "The Ruined Reaches run along the southern coast of Azshara, near the border with Durotar. Cliffs and beaches break into inlets, and ruins and shipwrecks lie scattered across them.",
			full = "The Ruined Reaches run along the southern coast of Azshara, near the border with Durotar. Cliffs and beaches break into inlets, and ruins and shipwrecks lie scattered across them. Shallows just under the water make the coast treacherous, and murlocs, hydras and makrura hold the shore.\n\nOn a hill above the western beach stands a gnomish house where Blimo and Jubie Gadgetspring live and trade. Upstairs in their bedroom is a third bed, and no one knows who, if anyone, sleeps in it.",
			source = "https://warcraft.wiki.gg/wiki/Ruined_Reaches",
		},
		["ruins of eldarath"] = {
			name = "Ruins of Eldarath",
			short = "Eldarath was a mighty stronghold of the Highborne before the world broke.",
			full = "Eldarath was a mighty stronghold of the Highborne before the world broke. Their greatest mages carved runes and tablets setting out the rules of the arcane and their insights into it, and left them in public places for anyone to ponder. Then the Great Sundering came, and most of the city crumbled into the Bay of Storms.\n\nWhat is left clings to the eastern cliffs, a cluster of ruins the night elves have long shunned. Fierce bands of naga have claimed it, and Warlord Krellian rules them from the Temple of Zin-Malor. Many of the old tablets still stand among the wreckage.\n\nThe blue dragonflight has taken it on itself to guard the magic left in these ruins, and the blue dragon Azuregos will fight to the death to defend Azshara's magical treasures. Some say his coming means that something of great worth, perhaps the fabled Vials of Eternity, lies hidden in this land.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Eldarath",
		},
		["scalebeards cave"] = {
			name = "Scalebeard's Cave",
			short = "A cave on a tiny island in the western Bay of Storms is the den of Scalebeard, a rare turtle. He is seldom at home, since he prefers to hunt far out in the Great Sea.",
			full = "A cave on a tiny island in the western Bay of Storms is the den of Scalebeard, a rare turtle. He is seldom at home, since he prefers to hunt far out in the Great Sea.",
			source = "https://warcraft.wiki.gg/wiki/Scalebeard's_Cave",
		},
		["shadowsong shrine"] = {
			name = "Shadowsong Shrine",
			short = "A hill covered in ruins in western Azshara bears the name Shadowsong.",
			full = "A hill covered in ruins in western Azshara bears the name Shadowsong. It shares that name with Jarod Shadowsong, who commanded the resistance in the War of the Ancients, and with his older sister Maiev, the warden who held Illidan Stormrage captive after his betrayal at Mount Hyjal. What either has to do with the hill, no one knows.\n\nThe ghosts of the Highborne haunt the stones and roam the land around, bent on snuffing out any life that comes near. Among them walks the ghost of Varo'then, who once led Queen Azshara's personal guard.",
			source = "https://warcraft.wiki.gg/wiki/Shadowsong_Shrine",
		},
		["shattered strand"] = {
			name = "The Shattered Strand",
			short = "The north shore of the Bay of Storms is crowded. Spitelash naga, hydras, sea giants, makrura and murlocs each hold a stretch of the sand, and an old temple and a tower rise from the shore among them.",
			full = "The north shore of the Bay of Storms is crowded. Spitelash naga, hydras, sea giants, makrura and murlocs each hold a stretch of the sand, and an old temple and a tower rise from the shore among them.",
			source = "https://warcraft.wiki.gg/wiki/Shattered_Strand",
		},
		["southfury river"] = {
			name = "Southfury River",
			short = "The Southfury rises in a lake on Mount Hyjal and drops into the lowlands in a set of spectacular waterfalls.",
			full = "The Southfury rises in a lake on Mount Hyjal and drops into the lowlands in a set of spectacular waterfalls. From there it runs wide and swift, and it is the border between the forest of Ashenvale and Azshara, and farther south between the Barrens and Durotar. Near its mouth it tumbles over a last cascade into the Great Sea, northeast of the goblin port of Ratchet.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["southridge beach"] = {
			name = "Southridge Beach",
			short = "Southridge Beach lines the southern edge of the Bay of Storms, its sands strewn with ruins of the once-great city of Eldarath.",
			full = "Southridge Beach lines the southern edge of the Bay of Storms, its sands strewn with ruins of the once-great city of Eldarath. Naga now hold the shore, sharing it with makrura, hydras, murlocs, and the occasional sea giant risen from deeper water.",
			source = "https://warcraft.wiki.gg/wiki/Southridge_Beach",
		},
		["storm cliffs"] = {
			name = "Storm Cliffs",
			short = "The Spitelash naga have made their home among the rock of the Storm Cliffs. At the far eastern edge of the cliffs stands the Ravencrest Monument.",
			full = "The Spitelash naga have made their home among the rock of the Storm Cliffs. At the far eastern edge of the cliffs stands the Ravencrest Monument.",
			source = "https://warcraft.wiki.gg/wiki/Storm_Cliffs",
		},
		["talrendis point"] = {
			name = "Talrendis Point",
			short = "Night elves keep a small encampment at Talrendis Point, in southwestern Azshara on the border with Ashenvale. It began as a watch kept at the edge of the forest.",
			full = "Night elves keep a small encampment at Talrendis Point, in southwestern Azshara on the border with Ashenvale. It began as a watch kept at the edge of the forest.\n\nA tauren, Loh'atu, lives among them. The Sentinels let him stay so long as he makes no trouble, and he says he has come to look into disturbances to the land.",
			source = "https://warcraft.wiki.gg/wiki/Talrendis_Point",
		},
		["temple of arkkoran"] = {
			name = "Temple of Arkkoran",
			short = "This temple on the northeastern shore of Azshara once belonged to the worship of Elune. Now Lord Arkkoroc, a sea giant revered as a demigod, lives at the top.",
			full = "This temple on the northeastern shore of Azshara once belonged to the worship of Elune. Now Lord Arkkoroc, a sea giant revered as a demigod, lives at the top. Murlocs and makrura guard the temple and attack on sight, and his sons patrol around it. Hydras and fierce sea giants watch the shore beyond.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Arkkoran",
		},
		["temple of zin malor"] = {
			name = "Temple of Zin-Malor",
			short = "Among the stones of Eldarath stands a temple to Elune, raised by night elves. Its design is strikingly close to the Temple of Arkkoran and to the Temple of the Moon in Darnassus.",
			full = "Among the stones of Eldarath stands a temple to Elune, raised by night elves. Its design is strikingly close to the Temple of Arkkoran and to the Temple of the Moon in Darnassus. The Spitelash naga hold it now, and their cruel leader, Warlord Krellian, sits in the place of honor.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Zin-Malor",
		},
		["thalassian base camp"] = {
			name = "Thalassian Base Camp",
			short = "Blood elves hold the hill above the Legash camps, a scatter of small fortified camps on its slopes. Their expedition searches Azshara for Highborne relics under Magus Rimtori.",
			full = "Blood elves hold the hill above the Legash camps, a scatter of small fortified camps on its slopes. Their expedition searches Azshara for Highborne relics under Magus Rimtori. She promised the Horde a share of the riches she found in return for warriors to guard her, then turned on them. Rimtori spends most of her time searching Azshara with her bodyguards, and Magister Hawkhelm watches over the camp.",
			source = "https://warcraft.wiki.gg/wiki/Thalassian_Base_Camp",
		},
		["thalassian vanguard camp"] = {
			pending = true,
			name = "Thalassian Vanguard Camp",
			short = "",
			full = "",
			source = "",
		},
		["tower of eldara"] = {
			name = "Tower of Eldara",
			short = "The Tower of Eldara stands on the far northeastern tip of land above the Bay of Storms, its sandy shore patrolled by murlocs, makrura, and hydras.",
			full = "The Tower of Eldara stands on the far northeastern tip of land above the Bay of Storms, its sandy shore patrolled by murlocs, makrura, and hydras. It once belonged to the night elf civilization that spread across this coast, but the tower stands closed and abandoned now.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Eldara",
		},
		["ursolan"] = {
			name = "Ursolan",
			short = "The furbolgs revere Ursol, a bear demigod, and Ursolan takes its name from him. The area is now a large Timbermaw furbolg settlement, which runs south through Timbermaw Hold to Bear's Head.",
			full = "The furbolgs revere Ursol, a bear demigod, and Ursolan takes its name from him. The area is now a large Timbermaw furbolg settlement, which runs south through Timbermaw Hold to Bear's Head.",
			source = "https://warcraft.wiki.gg/wiki/Ursolan",
		},
		["valormok"] = {
			name = "Valormok",
			short = "Valormok, a Horde outpost of orc warriors in northwestern Azshara, stands bare and lightly guarded. The Horde took little interest in this hostile land at first.",
			full = "Valormok, a Horde outpost of orc warriors in northwestern Azshara, stands bare and lightly guarded. The Horde took little interest in this hostile land at first. Its warriors endure hard times and keep their hope.\n\nBelgrom Rockmaul trusted the blood elf Magus Rimtori, who promised him riches and powerful relics from Azshara, and sent warriors to guard her. She killed them all. The camp was once a dozen warriors strong.\n\nAg'tor Bloodfist leads what is left and wants vengeance for his dead. He admits that the days here are not the Horde's best or most glorious, but his warriors are young, with blood still in their veins, and he says victory is only a matter of time.",
			source = "https://warcraft.wiki.gg/wiki/Valormok",
		},
	},
	-- Felwood: 18 subzones
	[1448] = {
		["bloodvenom falls"] = {
			name = "Bloodvenom Falls",
			short = "Poisoned water spills from the heights at Bloodvenom Falls and feeds the Bloodvenom River. Furbolgs are hardy enough to survive drinking it, but the water only deepens their madness.",
			full = "Poisoned water spills from the heights at Bloodvenom Falls and feeds the Bloodvenom River. Furbolgs are hardy enough to survive drinking it, but the water only deepens their madness.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Falls",
		},
		["bloodvenom post"] = {
			name = "Bloodvenom Post",
			short = "A small Horde outpost stands on the high cliffs above Darkshore, near the Bloodvenom River where it cuts through Felwood. Its old architecture and the tauren who guard it suggest that tauren founded it.",
			full = "A small Horde outpost stands on the high cliffs above Darkshore, near the Bloodvenom River where it cuts through Felwood. Its old architecture and the tauren who guard it suggest that tauren founded it.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Post",
		},
		["bloodvenom river"] = {
			name = "Bloodvenom River",
			short = "The Bloodvenom River runs through the middle of Felwood, and its banks crawl with noxious oozes and corrupted beasts. The water is not fit to drink or to swim in.",
			full = "The Bloodvenom River runs through the middle of Felwood, and its banks crawl with noxious oozes and corrupted beasts. The water is not fit to drink or to swim in. Its taint does not stop at the edge of the forest. Farther on, the river comes down the mountains and becomes the sickened Wildbend River in Darkshore.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_River",
		},
		["deadwood village"] = {
			name = "Deadwood Village",
			short = "The furbolgs of the Deadwood tribe hold this village in southern Felwood. Like most of their kin they have been corrupted by the forest's taint, and they attack outsiders on sight.",
			full = "The furbolgs of the Deadwood tribe hold this village in southern Felwood. Like most of their kin they have been corrupted by the forest's taint, and they attack outsiders on sight.",
			source = "https://warcraft.wiki.gg/wiki/Deadwood_Village",
		},
		["emerald sanctuary"] = {
			name = "Emerald Sanctuary",
			short = "Druids of the Emerald Circle keep a camp in southeastern Felwood. They work to snuff out the demonic corruption that spreads from Jaedenar.",
			full = "Druids of the Emerald Circle keep a camp in southeastern Felwood. They work to snuff out the demonic corruption that spreads from Jaedenar. The tauren Greta Mosshoof is among them, and Grazle, a furbolg of the uncorrupted Timbermaw tribe, stays here with the druids.",
			source = "https://warcraft.wiki.gg/wiki/Emerald_Sanctuary",
		},
		["felpaw village"] = {
			name = "Felpaw Village",
			short = "Felpaw Village stands at the far north of Felwood, near the entrance to Timbermaw Hold.",
			full = "Felpaw Village stands at the far north of Felwood, near the entrance to Timbermaw Hold. It belongs to the Deadwood, furbolgs whose corruption has turned them from their kin, and their taint still marks the ground they hold.\n\nChieftain Bloodmaw lives here among his shamans, avengers and den watchers.",
			source = "https://warcraft.wiki.gg/wiki/Felpaw_Village",
		},
		["irontree cavern"] = {
			name = "Irontree Cavern",
			short = "Warpwood Shredders and Warpwood Moss Flayers stalk the dark of this deep cave.",
			full = "Warpwood Shredders and Warpwood Moss Flayers stalk the dark of this deep cave.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Cavern",
		},
		["irontree woods"] = {
			name = "Irontree Woods",
			short = "The Irontree Woods once stood as a peaceful glade in northern Felwood, before the corruption of the Burning Legion twisted it into something else.",
			full = "The Irontree Woods once stood as a peaceful glade in northern Felwood, before the corruption of the Burning Legion twisted it into something else. Crazed treants, twisted bog beasts, ferocious wildlife and corrupted water elementals roam the woods and attack anyone who comes near.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Woods",
		},
		["jadefire glen"] = {
			name = "Jadefire Glen",
			short = "In the corrupted woods of southern Felwood, Jadefire Glen shelters a camp of Jadefire satyrs, demonic creatures who have made the tainted hollow their own, thriving amid its rot and spreading the corruption further through the trees around them.",
			full = "In the corrupted woods of southern Felwood, Jadefire Glen shelters a camp of Jadefire satyrs, demonic creatures who have made the tainted hollow their own, thriving amid its rot and spreading the corruption further through the trees around them.",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Glen",
		},
		["jadefire run"] = {
			name = "Jadefire Run",
			short = "The most powerful satyrs in Felwood make their home in this encampment in the north of the forest.",
			full = "The most powerful satyrs in Felwood make their home in this encampment in the north of the forest.",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Run",
		},
		["jaedenar"] = {
			name = "Jaedenar",
			short = "Jaedenar rises out of ground that once belonged to the night elves, its ruins older than the corruption that now claims them.",
			full = "Jaedenar rises out of ground that once belonged to the night elves, its ruins older than the corruption that now claims them. Beneath it lie two druidic barrow dens, sacred once, and its name was given in worship of Kil'jaeden, the Deceiver.\n\nAfter the Third War the ruins fell to the Shadow Council, led by Lord Banehollow. Its cultists are mostly orc and Forsaken warlocks, and demons serve beside them, among them succubi, felhunters, felguards and satyrs. At its heart stands Shadow Hold, and beside it the Shrine of the Deceiver.",
			source = "https://warcraft.wiki.gg/wiki/Jaedenar",
		},
		["morlosaran"] = {
			name = "Morlos'Aran",
			short = "Morlos'Aran was once a great night elf settlement, raised long before the Great Sundering. Now it lies in ruin at the southern edge of Felwood.",
			full = "Morlos'Aran was once a great night elf settlement, raised long before the Great Sundering. Now it lies in ruin at the southern edge of Felwood.\n\nNight elf ruins of the same kind lie across Darkshore, Ashenvale and Desolace. Once thriving cities, they are now only stone and a reminder of a golden age lost long ago.",
			source = "https://warcraft.wiki.gg/wiki/Morlos'Aran",
		},
		["ruins of constellas"] = {
			name = "Ruins of Constellas",
			short = "Broken columns mark what appears to have been one of the night elf settlements near Mount Hyjal. A moonwell still rests among them, but it no longer holds clean light.",
			full = "Broken columns mark what appears to have been one of the night elf settlements near Mount Hyjal. A moonwell still rests among them, but it no longer holds clean light. Fel energy has soaked into its waters, and Jadefire satyrs hold the ruins. A particularly cruel satyr named Xavathras leads them, and they spread the corruption to any creature they meet.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Constellas",
		},
		["shadow hold"] = {
			name = "Shadow Hold",
			short = "A gigantic labyrinth that was once a night elf barrow den lies within Jaedenar, in western Felwood. It is now the Shadow Council's stronghold on Azeroth, and warlocks and their demonic familiars roam its tunnels.",
			full = "A gigantic labyrinth that was once a night elf barrow den lies within Jaedenar, in western Felwood. It is now the Shadow Council's stronghold on Azeroth, and warlocks and their demonic familiars roam its tunnels. The satyr Prince Xavalis and the dreadlord Lord Banehollow both dwell here.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Hold",
		},
		["shatter scar vale"] = {
			name = "Shatter Scar Vale",
			short = "Many infernals fell here when the Burning Legion invaded during the Third War. The craters they left still smolder, and demons still wander the scarred ground.",
			full = "Many infernals fell here when the Burning Legion invaded during the Third War. The craters they left still smolder, and demons still wander the scarred ground.",
			source = "https://warcraft.wiki.gg/wiki/Shatter_Scar_Vale",
		},
		["shrine of the deceiver"] = {
			name = "Shrine of the Deceiver",
			short = "Warlocks of the Shadow Council fill this corrupted barrow den at Jaedenar, in Felwood. It takes its name from Kil'jaeden, the Deceiver, lord of the Burning Legion.",
			full = "Warlocks of the Shadow Council fill this corrupted barrow den at Jaedenar, in Felwood. It takes its name from Kil'jaeden, the Deceiver, lord of the Burning Legion.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Deceiver",
		},
		["talonbranch glade"] = {
			name = "Talonbranch Glade",
			short = "This small night elf post in northern Felwood is the Alliance's only outpost in the forest. It lies south of Timbermaw Hold, along the path that leads on to Moonglade and Winterspring.",
			full = "This small night elf post in northern Felwood is the Alliance's only outpost in the forest. It lies south of Timbermaw Hold, along the path that leads on to Moonglade and Winterspring. It is a night elf house, a moonwell and a few other pieces of elven building.",
			source = "https://warcraft.wiki.gg/wiki/Talonbranch_Glade",
		},
		["timbermaw hold"] = {
			name = "Timbermaw Hold",
			short = "When the corruption of the Burning Legion crept into the sacred forests of Kalimdor, most furbolgs fell under its influence and were twisted into madness.",
			full = "When the corruption of the Burning Legion crept into the sacred forests of Kalimdor, most furbolgs fell under its influence and were twisted into madness. The Timbermaw tribe escaped it. They sheltered in their hold in the northeast of Felwood, and they watched the forest they loved turn into a festering ruin of itself. Even after the demons' leader fell, the taint on the woods remained. Its tunnels open a passage through to Moonglade and Winterspring.\n\nThe Timbermaw are one of the last two tribes of pure furbolgs. They are wary of strangers, fearing they will be mistaken for their corrupted kin and attacked, but they value friends above all else. Their wish is to end the suffering of their corrupted brethren and to find a cure for the wound that Felwood has become, so that the ancient forest might ring again with peaceful chants and soft laughter.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- Un'Goro Crater: 12 subzones
	[1449] = {
		["fire plume ridge"] = {
			name = "Fire Plume Ridge",
			short = "Fire Plume Ridge rises at the heart of Un'Goro Crater, a mountain of scorched rock where lava creeps down the slopes and fire elementals stir in the heat.",
			full = "Fire Plume Ridge rises at the heart of Un'Goro Crater, a mountain of scorched rock where lava creeps down the slopes and fire elementals stir in the heat. Here the jungle ends, scorched away by the lava. The strongest of the fire elementals, Blazerunner, lives in a cave at the peak, master of the mountain's burning heart.\n\nShallow veins of magma run beneath the floor of the crater and heat the steam pools and geysers that hiss throughout Un'Goro, so that the whole basin seems to breathe from the mountain's fire.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Plume_Ridge",
		},
		["fungal rock"] = {
			name = "Fungal Rock",
			short = "A large cavern opens in the northeastern wall of Un'Goro Crater. Gorillas have made their home inside, among the ghost mushrooms.",
			full = "A large cavern opens in the northeastern wall of Un'Goro Crater. Gorillas have made their home inside, among the ghost mushrooms. Outside the entrance is a small pool with a waterfall, and there stands A-Me 01, the mechanical ape of Karna Remtravel.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Rock",
		},
		["golakka hot springs"] = {
			name = "Golakka Hot Springs",
			short = "Steam rises constantly from Golakka Hot Springs, a stretch of the western crater filled with pools and geysers heated by the nearby volcano.",
			full = "Steam rises constantly from Golakka Hot Springs, a stretch of the western crater filled with pools and geysers heated by the nearby volcano. Elder diemetradons and frenzied pterrordax roam around the pools.\n\nA goblin named Krakle has made camp by the springs to study how they are tied to the fires of Fire Plume Ridge.",
			source = "https://warcraft.wiki.gg/wiki/Golakka_Hot_Springs",
		},
		["ironstone plateau"] = {
			name = "Ironstone Plateau",
			short = "Bare rock breaks through the green of Un'Goro in several stretches along the northeastern edge of the crater, tucked against the crater wall.",
			full = "Bare rock breaks through the green of Un'Goro in several stretches along the northeastern edge of the crater, tucked against the crater wall. Ironstone Plateau lies quiet compared to the rest of the crater, and no monsters hunt here. Fledgling pterrordax live on it, and its stillness sets it apart from Un'Goro's restless growth.",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Plateau",
		},
		["lakkari tar pits"] = {
			name = "Lakkari Tar Pits",
			short = "Lakes of thick, foul-smelling black tar lie in the northern part of Un'Goro Crater. The tar traps creatures in its grip, and the bones of hundreds of beasts jut from its surface.",
			full = "Lakes of thick, foul-smelling black tar lie in the northern part of Un'Goro Crater. The tar traps creatures in its grip, and the bones of hundreds of beasts jut from its surface. Scavengers loiter nearby looking for easy prey, and tar beasts live in the pits.\n\nRare tarblossom flowers grow at the bottom. They are prized for their beauty and durability, but they lie deep in the tar and are hard to harvest.",
			source = "https://warcraft.wiki.gg/wiki/Lakkari_Tar_Pits",
		},
		["marshals refuge"] = {
			name = "Marshal's Refuge",
			short = "Marshal's Refuge sits at the northern edge of Un'Goro Crater, raised by the Marshal Expeditions under Williden Marshal and Hol'anyee Marshal.",
			full = "Marshal's Refuge sits at the northern edge of Un'Goro Crater, raised by the Marshal Expeditions under Williden Marshal and Hol'anyee Marshal. Their venture into the crater was not ready for what it found. Un'Goro's beasts proved too savage, and the expedition's base camps were overrun one by one. The survivors fled to higher ground and made camp here, at the crater's edge.\n\nThe refuge is what came of that retreat, a foothold barely kept. It is neutral ground.",
			source = "https://warcraft.wiki.gg/wiki/Marshal's_Refuge",
		},
		["marshlands"] = {
			name = "The Marshlands",
			short = "Standing water and rank growth sprawl across much of the southeastern crater in a vast marsh. Raptors move through the reeds in large numbers, and some of them are poisonous.",
			full = "Standing water and rank growth sprawl across much of the southeastern crater in a vast marsh. Raptors move through the reeds in large numbers, and some of them are poisonous. Blue power crystals are found here and nowhere else in the crater.\n\nOn a large mound stands Torwa Pathfinder, who seems to have come here by canoe from elsewhere in the crater.",
			source = "https://warcraft.wiki.gg/wiki/Marshlands",
		},
		["pillar of assimilation"] = {
			pending = true,
			name = "Pillar of Assimilation",
			short = "",
			full = "",
			source = "",
		},
		["shapers terrace"] = {
			name = "The Shaper's Terrace",
			short = "In the hills of Un'Goro Crater stands the Shaper's Terrace, an abandoned titan facility left seemingly undisturbed for ages. Its name recalls Khaz'goroth, the titan called the Shaper.",
			full = "In the hills of Un'Goro Crater stands the Shaper's Terrace, an abandoned titan facility left seemingly undisturbed for ages. Its name recalls Khaz'goroth, the titan called the Shaper. The crater's great predators have claimed it for longer than anyone knows. Wildlife and coiling vines wrap the ancient fixtures, and pulsing power crystals line its halls beside consoles that wait for fuel. Crimson devilsaurs roam within.",
			source = "",
		},
		["slithering scar"] = {
			name = "The Slithering Scar",
			short = "The Gorishi, a sect of the silithid, hold most of the southern part of Un'Goro Crater with their hive. Wasps and workers swarm through it, guarded by reavers, stingers and tunnelers.",
			full = "The Gorishi, a sect of the silithid, hold most of the southern part of Un'Goro Crater with their hive. Wasps and workers swarm through it, guarded by reavers, stingers and tunnelers. One of the reavers is known as Clutchmother Zavas.",
			source = "https://warcraft.wiki.gg/wiki/Slithering_Scar",
		},
		["stomping grounds"] = {
			pending = true,
			name = "Stomping Grounds",
			short = "",
			full = "",
			source = "",
		},
		["terror run"] = {
			name = "Terror Run",
			short = "In the southwest of Un'Goro Crater, just west of the Slithering Scar, stegodons, diemetradons, pterrordax and devilsaurs gather in great numbers, and all of them are hostile.",
			full = "In the southwest of Un'Goro Crater, just west of the Slithering Scar, stegodons, diemetradons, pterrordax and devilsaurs gather in great numbers, and all of them are hostile. Red crystals grow here and nowhere else in the crater.\n\nAlong the eastern edge lies an abandoned research camp that the Marshal Expeditions left behind.",
			source = "https://warcraft.wiki.gg/wiki/Terror_Run",
		},
	},
	-- Moonglade: 5 subzones
	[1450] = {
		["lake eluneara"] = {
			name = "Lake Elune'ara",
			short = "Crystal water fills the heart of Moonglade, still as glass beneath the trees. The lake is named for Elune herself.",
			full = "Crystal water fills the heart of Moonglade, still as glass beneath the trees. The lake is named for Elune herself.\n\nCenturies ago heroes gathered in Nighthaven to face the maddened demigod Omen. They blinded him and drove him into the lake, and he rests in its depths still, stirring each year around the time of the Lunar Festival.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Elune'ara",
		},
		["nighthaven"] = {
			name = "Nighthaven",
			short = "On the shore of Lake Elune'ara stands Nighthaven, a village of night elf stonework and a pair of moonwells, home to the druids of the Cenarion Circle.",
			full = "On the shore of Lake Elune'ara stands Nighthaven, a village of night elf stonework and a pair of moonwells, home to the druids of the Cenarion Circle. It is a quiet, remote place, usually closed to outsiders, its people given over to druidism and the tending of the wild.",
			source = "https://warcraft.wiki.gg/wiki/Nighthaven",
		},
		["shrine of remulos"] = {
			name = "Shrine of Remulos",
			short = "Western Moonglade holds a shrine dedicated to Keeper Remulos, son of the demigod Cenarius and guardian of the valley. Remulos himself keeps his place at the shrine, and the night elf Tajarri lives within.",
			full = "Western Moonglade holds a shrine dedicated to Keeper Remulos, son of the demigod Cenarius and guardian of the valley. Remulos himself keeps his place at the shrine, and the night elf Tajarri lives within.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Remulos",
		},
		["stormrage barrow dens"] = {
			name = "Stormrage Barrow Dens",
			short = "Beneath the quiet turf of Moonglade lie the barrow dens, sunk into earth that many night elf druids never truly leave, their bodies resting while their spirits wander the Emerald Dream.",
			full = "Beneath the quiet turf of Moonglade lie the barrow dens, sunk into earth that many night elf druids never truly leave, their bodies resting while their spirits wander the Emerald Dream.\n\nIt was here that Malfurion Stormrage once slept, and the dens bear his name for it. When Tichondrius and his Dreadlords came in the Third War, they struck at Malfurion where he lay, nearly tearing his den apart. It was Tyrande Whisperwind who woke him to stand against Archimonde and the Burning Legion.\n\nAfterward, when the Cenarion Circle spoke of raising a second World Tree, Malfurion returned to the barrow dens to meditate. Tyrande later came seeking him and found his body fallen still, as though asleep, with no waking it. The Circle judged it wiser not to move him, because if his spirit still wandered the Dream searching for its way home, it would need to find the body where it had left it. So he remains there, watched over by the Cenarion Circle and the Sisterhood of Elune.",
			source = "https://warcraft.wiki.gg/wiki/Stormrage_Barrow_Dens",
		},
		["timbermaw hold"] = {
			name = "Timbermaw Hold",
			short = "The Timbermaw tribe of furbolgs keeps its capital in northeastern Felwood, and a tunnel through the hold leads out to Moonglade and Winterspring.",
			full = "The Timbermaw tribe of furbolgs keeps its capital in northeastern Felwood, and a tunnel through the hold leads out to Moonglade and Winterspring. When the corruption of the Burning Legion crept into the sacred forests of Kalimdor, most furbolgs fell under its influence. The Timbermaw escaped it and sheltered in the hold, and they have watched the forest they loved twisted into a festering ruin of itself. Even after the source of that corruption was destroyed, the taint on the woods remained.\n\nThe Timbermaw want an end to the suffering of their corrupted kin, and a cure for the land, so that the ancient forest might one day ring again with chants and laughter.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- Silithus: 20 subzones
	[1451] = {
		["bones of grakkarond"] = {
			name = "Bones of Grakkarond",
			short = "The huge bones of the bronze dragon Grakkarond lie in central Silithus. Ossirian the Unscarred slew Grakkarond in the War of the Shifting Sands.",
			full = "The huge bones of the bronze dragon Grakkarond lie in central Silithus. Ossirian the Unscarred slew Grakkarond in the War of the Shifting Sands. The Anubisath hold the bones sacred.",
			source = "https://warcraft.wiki.gg/wiki/Bones_of_Grakkarond",
		},
		["bronzebeard encampment"] = {
			name = "Bronzebeard Encampment",
			short = "Rutgar Glyphshaper works at a camp in southern Silithus, east of the Scarab Wall, and asks after the whereabouts of the famous explorer Brann Bronzebeard.",
			full = "Rutgar Glyphshaper works at a camp in southern Silithus, east of the Scarab Wall, and asks after the whereabouts of the famous explorer Brann Bronzebeard.",
			source = "https://warcraft.wiki.gg/wiki/Bronzebeard_Encampment",
		},
		["cenarion hold"] = {
			name = "Cenarion Hold",
			short = "Cenarion Hold stands in Silithus on the ground of an ancient night elf settlement. It is one of the biggest druid strongholds in Kalimdor, almost as large as Moonglade itself.",
			full = "Cenarion Hold stands in Silithus on the ground of an ancient night elf settlement. It is one of the biggest druid strongholds in Kalimdor, almost as large as Moonglade itself. After the War of the Shifting Sands the Cenarion Circle took on the duty of defending it against the silithid and the other forces that grow more hostile in this region, and of guarding the imprisoned Old God C'Thun and its armies.\n\nIt is a hard, embattled place to live, and the silithid press constantly against its walls.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Hold",
		},
		["crystal vale"] = {
			name = "The Crystal Vale",
			short = "In the far northwestern corner of Silithus lies the Crystal Vale, a valley held by earth and air elementals, desert rumblers and dust stormers.",
			full = "In the far northwestern corner of Silithus lies the Crystal Vale, a valley held by earth and air elementals, desert rumblers and dust stormers. Thorium lies thick in its stone. An air elemental called Huricanian patrols the mountain at its southeastern edge.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Vale",
		},
		["gates of ahnqiraj"] = {
			name = "Gates of Ahn'Qiraj",
			short = "The ancient, brooding city of Ahn'Qiraj lies in Silithus, home to an insect menace that threatens Horde and Alliance alike.",
			full = "The ancient, brooding city of Ahn'Qiraj lies in Silithus, home to an insect menace that threatens Horde and Alliance alike. Its gates were shut during the War of the Shifting Sands and sealed behind the enchanted Scarab Wall. This ground lies just beyond the wall, in the southwest of Silithus.",
			source = "",
		},
		["hiveashi"] = {
			name = "Hive'Ashi",
			short = "A silithid hive lies in northern Silithus, and its brood has spread out to infest the Swarming Pillar.",
			full = "A silithid hive lies in northern Silithus, and its brood has spread out to infest the Swarming Pillar. Defenders, sandstalkers, stingers, swarmers and workers fill it, and a scout of the Cenarion Circle watches it from nearby.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Ashi",
		},
		["hiveregal"] = {
			name = "Hive'Regal",
			short = "In southern Silithus, the mounds of Hive'Regal rise from the sand, tunnels and chitin thick amid the dust. Ambushers, burrowers, slavemakers, spitfires and hive lords crowd the nest.",
			full = "In southern Silithus, the mounds of Hive'Regal rise from the sand, tunnels and chitin thick amid the dust. Ambushers, burrowers, slavemakers, spitfires and hive lords crowd the nest.\n\nBefore the hive camps the Orgrimmar Legion, a battalion of orcs and jungle trolls sent from Orgrimmar to aid Cenarion Hold against the silithid. Krug Skullsplit leads it.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Regal",
		},
		["hivezora"] = {
			name = "Hive'Zora",
			short = "Out in western Silithus, a silithid nest lies burrowed into the sand, swarming with wasps, reavers, hive sisters, tunnelers and waywatchers.",
			full = "Out in western Silithus, a silithid nest lies burrowed into the sand, swarming with wasps, reavers, hive sisters, tunnelers and waywatchers.\n\nThe Ironforge Brigade guards against the hive from an outpost nearby. It is an Alliance force, mostly dwarves of Ironforge with gnomes and humans in its ranks, sent to support Cenarion Hold, and Captain Blackanvil leads it.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Zora",
		},
		["ortells hideout"] = {
			name = "Ortell's Hideout",
			short = "Ortell, a hermit, makes his home in a small cave in southeastern Silithus.",
			full = "Ortell, a hermit, makes his home in a small cave in southeastern Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Ortell's_Hideout",
		},
		["ravaged twilight camp"] = {
			name = "Ravaged Twilight Camp",
			short = "Highlord Demitrian makes his home in the Ravaged Twilight Camp, set in the Crystal Vale in northwestern Silithus.",
			full = "Highlord Demitrian makes his home in the Ravaged Twilight Camp, set in the Crystal Vale in northwestern Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Twilight_Camp",
		},
		["scarab dais"] = {
			name = "The Scarab Dais",
			short = "The Scarab Gong stands on a dais in southern Silithus, northwest of the Scarab Wall, outside Ahn'Qiraj.",
			full = "The Scarab Gong stands on a dais in southern Silithus, northwest of the Scarab Wall, outside Ahn'Qiraj.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Dais",
		},
		["scarab wall"] = {
			name = "The Scarab Wall",
			short = "Along the southern edge of Silithus, between the silithid-held desert and the ruined city of Ahn'Qiraj, runs the Scarab Wall.",
			full = "Along the southern edge of Silithus, between the silithid-held desert and the ruined city of Ahn'Qiraj, runs the Scarab Wall. It was molded from the sand itself at the end of the War of the Shifting Sands, and its sandstone bulk climbs high above the desert. Where the stone could rise no further, the magic of the bronze dragonflight took over and formed a barrier many times taller still.\n\nThe night elves and bronze dragons who made it named their creation Irana'ethil, Shield against the Shadow. It keeps C'Thun and its crawling minions sealed within.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Wall",
		},
		["southwind village"] = {
			name = "Southwind Village",
			short = "Southwind Village was a night elf base until the Qiraji swarmed over it in the War of the Shifting Sands. Valstann Staghelm, son of Archdruid Fandral Staghelm, led a detachment of the night elf army to defend it.",
			full = "Southwind Village was a night elf base until the Qiraji swarmed over it in the War of the Shifting Sands. Valstann Staghelm, son of Archdruid Fandral Staghelm, led a detachment of the night elf army to defend it. The Qiraji slaughtered his troops, and General Rajaxx took Valstann captive while the village was torn apart behind him.\n\nThe silithid have since overrun the ruins. The spirits of druids and Sentinels who fell in the slaughter linger among the wreckage, wandering without purpose, bound to the place of their deaths.",
			source = "https://warcraft.wiki.gg/wiki/Southwind_Village",
		},
		["staghelm point"] = {
			name = "Staghelm Point",
			short = "A night elf tower crowns a peak in northeastern Silithus. Ralo'shan the Eternal Watcher keeps the post, and a bronze drake of Nozdormu's brood circles the sky above.",
			full = "A night elf tower crowns a peak in northeastern Silithus. Ralo'shan the Eternal Watcher keeps the post, and a bronze drake of Nozdormu's brood circles the sky above.",
			source = "https://warcraft.wiki.gg/wiki/Staghelm_Point",
		},
		["swarming pillar"] = {
			name = "The Swarming Pillar",
			short = "A large peak in the middle of Silithus, just south of Cenarion Hold, is riddled through with silithid tunnels and filled by a hive.",
			full = "A large peak in the middle of Silithus, just south of Cenarion Hold, is riddled through with silithid tunnels and filled by a hive. A haze of small silithid circles the stone at all hours, a living cloud that gave the pillar its name. Of the many hives built beneath the sands of Silithus, this is the largest.",
			source = "https://warcraft.wiki.gg/wiki/Swarming_Pillar",
		},
		["twilight base camp"] = {
			name = "Twilight Base Camp",
			short = "The Twilight's Hammer cult keeps four camps across the wastes of Silithus, and this is one of them, a foothold amid the dust and ruin of that scoured land.",
			full = "The Twilight's Hammer cult keeps four camps across the wastes of Silithus, and this is one of them, a foothold amid the dust and ruin of that scoured land. Twilight Keeper Havunth is stationed here, and wind stones stand in the camp.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Base_Camp",
		},
		["twilight outpost"] = {
			name = "Twilight Outpost",
			short = "Twilight Keeper Exeter is stationed at an outpost of the Twilight's Hammer cult in the far southwestern corner of Silithus, just northwest of the Scarab Wall and west of the Bronzebeard Encampment.",
			full = "Twilight Keeper Exeter is stationed at an outpost of the Twilight's Hammer cult in the far southwestern corner of Silithus, just northwest of the Scarab Wall and west of the Bronzebeard Encampment. Wind stones stand in the camp.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Outpost",
		},
		["twilight post"] = {
			name = "Twilight Post",
			short = "Wind stones stand in a camp the Twilight's Hammer cult holds in the northwest of Silithus, far west of Cenarion Hold and northwest of Twilight Base Camp.",
			full = "Wind stones stand in a camp the Twilight's Hammer cult holds in the northwest of Silithus, far west of Cenarion Hold and northwest of Twilight Base Camp. Twilight Keeper Mayna is stationed here.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Post",
		},
		["twilights run"] = {
			name = "Twilight's Run",
			short = "Twilight's Run lies hidden in the rock at the base of Staghelm Point, in northern Silithus.",
			full = "Twilight's Run lies hidden in the rock at the base of Staghelm Point, in northern Silithus. A cave there is filled with members of the Twilight's Hammer cult, who have made the hollow in the mountain their own while the desert wind scours the stone above them.",
			source = "https://warcraft.wiki.gg/wiki/Twilight's_Run",
		},
		["valors rest"] = {
			name = "Valor's Rest",
			short = "Alliance and Horde alike shelter at Valor's Rest, a small camp at the edge of Silithus where the path out of Un'Goro Crater reaches the desert.",
			full = "Alliance and Horde alike shelter at Valor's Rest, a small camp at the edge of Silithus where the path out of Un'Goro Crater reaches the desert. Members of the Cenarion Circle tend it, and graves stand quiet at its edge.",
			source = "https://warcraft.wiki.gg/wiki/Valor's_Rest",
		},
	},
	-- Winterspring: 18 subzones
	[1452] = {
		["banthallow barrow den"] = {
			name = "Ban'Thallow Barrow Den",
			short = "The Ban'Thallow Barrow Den lies in the hillside behind Starfall Village. It stands unused and empty.",
			full = "The Ban'Thallow Barrow Den lies in the hillside behind Starfall Village. It stands unused and empty.",
			source = "https://warcraft.wiki.gg/wiki/Ban'Thallow_Barrow_Den",
		},
		["darkwhisper gorge"] = {
			name = "Darkwhisper Gorge",
			short = "When Archimonde fell at the Battle of Mount Hyjal, the demons of the Burning Legion who survived did not vanish.",
			full = "When Archimonde fell at the Battle of Mount Hyjal, the demons of the Burning Legion who survived did not vanish. They fled into Darkwhisper Gorge, a network of tunnels and chasms in the far south of Winterspring, and took refuge there. Hederine demons hold it now, seemingly led by Lady Hederine.",
			source = "https://warcraft.wiki.gg/wiki/Darkwhisper_Gorge",
		},
		["dun mandarr"] = {
			name = "Dun Mandarr",
			short = "Dun Mandarr is a small camp beside an icy cavern in southeastern Winterspring.",
			full = "Dun Mandarr is a small camp beside an icy cavern in southeastern Winterspring. Jaron Stoneshaper, a dwarf of the Explorers' League, set it up while he hunted for artifacts in the region, until bloodthirsty moonkin chased him out and wrecked it. Ferocious moonkin overrun it now, alongside Winterspring screechers.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Mandarr",
		},
		["everlook"] = {
			name = "Everlook",
			short = "Goblins of the Steamwheedle Cartel run Everlook, a trading post where Winterspring's main trade routes cross. It has a goblin laboratory among its buildings, and Everlook Bruisers keep the peace.",
			full = "Goblins of the Steamwheedle Cartel run Everlook, a trading post where Winterspring's main trade routes cross. It has a goblin laboratory among its buildings, and Everlook Bruisers keep the peace. The Argent Dawn sent Gregor Greystone here to speak for their interests to the Cartel's local governance.\n\nMalyfous Darkhammer of the Thorium Brotherhood, the Dark Iron smiths of Thorium Point, also keeps his trade in the town.",
			source = "https://warcraft.wiki.gg/wiki/Everlook",
		},
		["frostfire hot springs"] = {
			name = "Frostfire Hot Springs",
			short = "A chain of steaming pools lies at the far western end of Winterspring, warm water in a land of ice. No one has explained why the springs burn hot beneath the snow and ice.",
			full = "A chain of steaming pools lies at the far western end of Winterspring, warm water in a land of ice. No one has explained why the springs burn hot beneath the snow and ice. Donova Snowden has made camp nearby. She wants to know why the springs appeared and what power they hold, and she suspects demonic interference reaching them from Darkwhisper Gorge in the far south. Furbolgs of the Winterfall tribe live around the pools.",
			source = "https://warcraft.wiki.gg/wiki/Frostfire_Hot_Springs",
		},
		["frostsaber rock"] = {
			name = "Frostsaber Rock",
			short = "At the very top of a large tor in the north of Winterspring stands Rivern Frostwind of the Wintersaber Trainers, keeper of the bond between the frostsabers and those who would ride them.",
			full = "At the very top of a large tor in the north of Winterspring stands Rivern Frostwind of the Wintersaber Trainers, keeper of the bond between the frostsabers and those who would ride them. He works with the Alliance, and the beautiful white cats prowl the icy stone below.",
			source = "https://warcraft.wiki.gg/wiki/Frostsaber_Rock",
		},
		["frostwhisper gorge"] = {
			name = "Frostwhisper Gorge",
			short = "Night elf ruins lie scattered across the floor and ridges of Frostwhisper Gorge, a canyon in southern Winterspring. A great bridge spans the chasm toward Darkwhisper Gorge, just to the south.",
			full = "Night elf ruins lie scattered across the floor and ridges of Frostwhisper Gorge, a canyon in southern Winterspring. A great bridge spans the chasm toward Darkwhisper Gorge, just to the south. Huge Frostmaul giants and their Preservers live among the old stones.",
			source = "https://warcraft.wiki.gg/wiki/Frostwhisper_Gorge",
		},
		["hidden grove"] = {
			name = "The Hidden Grove",
			short = "The Hidden Grove lies sunk in a forested crater in northeastern Winterspring, walled in on every side by high cliffs. A single cave cut into the southeastern ridge is the one way in.",
			full = "The Hidden Grove lies sunk in a forested crater in northeastern Winterspring, walled in on every side by high cliffs. A single cave cut into the southeastern ridge is the one way in. A drop from the heights above is possible in places, and very dangerous.\n\nMoonkin hold the grove, berserk and crazed, and they are hostile to any who enter.",
			source = "https://warcraft.wiki.gg/wiki/Hidden_Grove",
		},
		["ice thistle hills"] = {
			name = "Ice Thistle Hills",
			short = "The Ice Thistle Hills rise southeast of Everlook, home to the Ice Thistle yeti, who live in and around a cave high on the slopes.",
			full = "The Ice Thistle Hills rise southeast of Everlook, home to the Ice Thistle yeti, who live in and around a cave high on the slopes. Icecap grows across the open slopes outside, and veins of thorium run through the rock inside.",
			source = "https://warcraft.wiki.gg/wiki/Ice_Thistle_Hills",
		},
		["lake keltheril"] = {
			name = "Lake Kel'Theril",
			short = "The frozen waters of Lake Kel'Theril lie still in the middle of Winterspring, ringed by old Highborne ruins that carry its name. The tormented spirits that haunt the ruins drift out across the ice as well.",
			full = "The frozen waters of Lake Kel'Theril lie still in the middle of Winterspring, ringed by old Highborne ruins that carry its name. The tormented spirits that haunt the ruins drift out across the ice as well.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Kel'Theril",
		},
		["mazthoril"] = {
			name = "Mazthoril",
			short = "Deep in the ice of Winterspring, near the middle of the valley, the cavern of Mazthoril opens beneath the earth, vast and thick with magic.",
			full = "Deep in the ice of Winterspring, near the middle of the valley, the cavern of Mazthoril opens beneath the earth, vast and thick with magic. Here the blue dragons, sworn to Malygos, keep their lair, and here their matriarch Haleh keeps her solitary watch. She shows herself only as a high elf, at the very top of the cavern, and a portal rune in the floor far below is the way up.\n\nFour powerful drakes guard the lair. Spellmaw patrols a slow path around a third of the lower valley, while Manaclaw and Scryer watch over the runes at the back of the cavern. Azurous ranges through the nearby lands for threats to the forces of Malygos, and a sizable army of sorcerous spawn and young whelps stands behind them.",
			source = "https://warcraft.wiki.gg/wiki/Mazthoril",
		},
		["moon horror den"] = {
			name = "Moon Horror Den",
			short = "Raging owlbeasts live in the Moon Horror Den, a small cave a short walk northeast of Everlook's gates. Winterfall Village lies close by, but a mountain stands between the two.",
			full = "Raging owlbeasts live in the Moon Horror Den, a small cave a short walk northeast of Everlook's gates. Winterfall Village lies close by, but a mountain stands between the two.",
			source = "https://warcraft.wiki.gg/wiki/Moon_Horror_Den",
		},
		["owl wing thicket"] = {
			name = "Owl Wing Thicket",
			short = "In the south of Winterspring, a series of caves cuts through the rock, home to owlbeasts gone berserk, moontouched and crazed. Ranshalla stands at the entrance.",
			full = "In the south of Winterspring, a series of caves cuts through the rock, home to owlbeasts gone berserk, moontouched and crazed. Ranshalla stands at the entrance.",
			source = "https://warcraft.wiki.gg/wiki/Owl_Wing_Thicket",
		},
		["ruins of keltheril"] = {
			name = "The Ruins of Kel'Theril",
			short = "The Ruins of Kel'Theril lie broken on the shore of the lake that bears their name. Ten thousand years ago a great city of the Highborne stood here.",
			full = "The Ruins of Kel'Theril lie broken on the shore of the lake that bears their name. Ten thousand years ago a great city of the Highborne stood here. The Great Sundering destroyed it, and it has never been rebuilt.\n\nThe Highborne who died there did not pass on. Their tormented spirits still wander among the fallen columns and stones.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Kel'Theril",
		},
		["starfall village"] = {
			name = "Starfall Village",
			short = "The Alliance holds one settlement in Winterspring, Starfall Village, which stands beside the main road. A night elf lodge and a smaller house make up the village.",
			full = "The Alliance holds one settlement in Winterspring, Starfall Village, which stands beside the main road. A night elf lodge and a smaller house make up the village. Jaron Stoneshaper, a dwarf of the Explorers' League, stays here while he hunts the region for artifacts. Winterspring holds powerful relics, he says, most of them heavily guarded.",
			source = "https://warcraft.wiki.gg/wiki/Starfall_Village",
		},
		["timbermaw hold"] = {
			name = "Timbermaw Hold",
			short = "Timbermaw Hold, the capital of the Timbermaw furbolgs, lies in northeastern Felwood, and its tunnel comes out here in Winterspring as well as in Moonglade.",
			full = "Timbermaw Hold, the capital of the Timbermaw furbolgs, lies in northeastern Felwood, and its tunnel comes out here in Winterspring as well as in Moonglade.\n\nThe furbolgs are wary of all strangers, fearing they will be mistaken for their corrupted brethren and attacked. A stranger who proves a friend finds that they value friends above all else. They own no fine jewels or worldly riches, but their shamanistic tradition is strong, and they know much about crafting armor from animal hides.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
		["timbermaw post"] = {
			name = "Timbermaw Post",
			short = "The name says Timbermaw, but the small furbolg camp at Timbermaw Post belongs to the corrupted Winterfall tribe, who hold it completely.",
			full = "The name says Timbermaw, but the small furbolg camp at Timbermaw Post belongs to the corrupted Winterfall tribe, who hold it completely. It stands southeast across the road from the Frostfire Hot Springs and west of Lake Kel'Theril.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Post",
		},
		["winterfall village"] = {
			name = "Winterfall Village",
			short = "High Chief Winterfall rules the corrupted furbolgs of Winterfall Village from a small cave at the top of the settlement. The village climbs the slopes of far eastern Winterspring, near Everlook.",
			full = "High Chief Winterfall rules the corrupted furbolgs of Winterfall Village from a small cave at the top of the settlement. The village climbs the slopes of far eastern Winterspring, near Everlook.",
			source = "https://warcraft.wiki.gg/wiki/Winterfall_Village",
		},
	},
	-- Stormwind City: 4 subzones
	[1453] = {
		["champions hall"] = {
			name = "Champions' Hall",
			short = "In the south of Old Town, the officers of the Alliance keep their barracks in the Champions' Hall.",
			full = "In the south of Old Town, the officers of the Alliance keep their barracks in the Champions' Hall. At the back they gather around a table spread with maps of Azeroth, among them Archmage Gaiman of Stormwind and Sergeant Major Skyshadow of Darnassus.",
			source = "https://warcraft.wiki.gg/wiki/Champions'_Hall",
		},
		["deeprun tram"] = {
			name = "Deeprun Tram",
			short = "After the Second War the dwarves of Ironforge hurried to help their human allies rebuild Stormwind, but King Magni Bronzebeard thought the aid came too slowly.",
			full = "After the Second War the dwarves of Ironforge hurried to help their human allies rebuild Stormwind, but King Magni Bronzebeard thought the aid came too slowly. He also wanted a way to send dwarven soldiers to the humans quickly if war returned. He turned to High Tinker Gelbin Mekkatorque, the finest engineer on Azeroth, who drew up a railway under the earth to link the two capitals.\n\nThe builders ran into a subterranean lake and then a plague of rats. The tram was finished anyway. Gnomes work on the line every day, and the rats have never quite gone.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["stormwind harbor"] = {
			name = "Stormwind Harbor",
			short = "When the Horde sacked Stormwind, Sir Anduin Lothar covered the retreat of the survivors to the quays. They sailed for Lordaeron, and most of the ships left behind were destroyed so that the orcs could not follow.",
			full = "When the Horde sacked Stormwind, Sir Anduin Lothar covered the retreat of the survivors to the quays. They sailed for Lordaeron, and most of the ships left behind were destroyed so that the orcs could not follow. The harbor lies in the northwest of the city, on the Great Sea.",
			source = "",
		},
		["valley of heroes"] = {
			name = "Valley of Heroes",
			short = "A stone bridge crosses the moat before Stormwind's gate and leads into a lush green valley. Five great statues stand along the road.",
			full = "A stone bridge crosses the moat before Stormwind's gate and leads into a lush green valley. Five great statues stand along the road. Stormwind raised them after the Second War, as the city was rebuilt, for the leaders of the Alliance expedition that passed through the Dark Portal to seal it from the far side.\n\nKurdran Wildhammer, Thane of Aerie Peak, and the Archmage Khadgar of the Kirin Tor stand on the left. Force Commander Danath Trollbane and Ranger-Captain Alleria Windrunner stand on the right. At the end of the road, where it splits to enter the city, is General Turalyon, who led them all. None of the five came back.\n\nGeneral Marcus Jonathan, High Commander of Stormwind's defense, keeps his post in the valley.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Heroes",
		},
	},
	-- Orgrimmar: 2 subzones
	[1454] = {
		["hall of legends"] = {
			name = "Hall of Legends",
			short = "The Horde's officers keep their barracks in the Hall of Legends.",
			full = "The Horde's officers keep their barracks in the Hall of Legends. Around a table in the middle, spread with maps of Azeroth, stand Chieftain Earthbind of Thunder Bluff, Advisor Willington of the Undercity and Blood Guard Hini'wana of the Darkspear trolls.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_Legends",
		},
		["ragefire chasm"] = {
			name = "Ragefire Chasm",
			short = "Beneath Orgrimmar the earth opens into a chasm of lava and smoke. Troggs have begun to climb out of the deep tunnels, a clan the Horde calls the Ragefire troggs.",
			full = "Beneath Orgrimmar the earth opens into a chasm of lava and smoke. Troggs have begun to climb out of the deep tunnels, a clan the Horde calls the Ragefire troggs. Magatha the Seer, of the tauren, tried to make peace with them and met only hostility. These creatures have no interest in talking, and left alone they could overwhelm the whole Horde.\n\nA sect of the Shadow Council, the Searing Blade, has also taken refuge in the chasm. Taragaman the Hungerer, a felguard, leads it alongside the warlock Jergosh the Invoker and the satyr Bazzalan. From their hiding place they plot to overthrow all that the Horde has built in these lands.",
			source = "https://warcraft.wiki.gg/wiki/Ragefire_Chasm",
		},
	},
	-- Ironforge: 3 subzones
	[1455] = {
		["deeprun tram"] = {
			name = "Deeprun Tram",
			short = "Two sets of three wagons run on double tracks between Ironforge and Stormwind, passing partly under the water of a subterranean lake.",
			full = "Two sets of three wagons run on double tracks between Ironforge and Stormwind, passing partly under the water of a subterranean lake. High Tinker Gelbin Mekkatorque, the most esteemed engineer in Azeroth, drew up the line for King Magni Bronzebeard, who wanted a way to send dwarven soldiers to the humans if they were ever needed. Rats overran the tunnels while it was dug, and gnomes work on it every day to keep it safe.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["gates of ironforge"] = {
			name = "Gates of Ironforge",
			short = "The Gates of Ironforge rise where the great ramp of central Dun Morogh climbs to meet the mountain, a grand sight visible for miles across the snow.",
			full = "The Gates of Ironforge rise where the great ramp of central Dun Morogh climbs to meet the mountain, a grand sight visible for miles across the snow. They stand as the threshold between the open dwarven lands and Ironforge proper.\n\nInside stands a huge statue of High King Modimus Anvilmar, set to guard the entrance so that none enter the city without passing beneath his gaze.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
		["hall of thanes"] = {
			name = "The Hall of Thanes",
			short = "The spirit of an old thane cannot rest in this hall, consumed by an ancient grudge. His ghostly attendant keeps to the hall, speaking in broken words and asking only that his thane be allowed to sleep.",
			full = "The spirit of an old thane cannot rest in this hall, consumed by an ancient grudge. His ghostly attendant keeps to the hall, speaking in broken words and asking only that his thane be allowed to sleep.\n\nThe hall keeps a tablet from just after the War of the Three Hammers, setting out the terms of peace between the Bronzebeard and Wildhammer clans. Madoran, the first Bronzebeard king of Ironforge after the civil war, had it drawn up once the Bronzebeards won the mountain. The Wildhammers and the Bronzebeards signed it. The Dark Irons did not.",
			source = "",
		},
	},
	-- Thunder Bluff: 4 subzones
	[1456] = {
		["elder rise"] = {
			name = "Elder Rise",
			short = "The Council of Elders governs from Elder Rise, which lies directly east of the central bluff, and the Cenarion Circle makes its home here among the tauren druids and priests.",
			full = "The Council of Elders governs from Elder Rise, which lies directly east of the central bluff, and the Cenarion Circle makes its home here among the tauren druids and priests. Arch Druid Hamuul Runetotem lives on the rise, a childhood friend of Cairne Bloodhoof. The hut between the two bridges belongs to Magatha Grimtotem, who leads the Grimtotem tribe.",
			source = "https://warcraft.wiki.gg/wiki/Elder_Rise",
		},
		["hunter rise"] = {
			name = "Hunter Rise",
			short = "The southern rise of Thunder Bluff belongs to those who hunt and fight.",
			full = "The southern rise of Thunder Bluff belongs to those who hunt and fight. Trappers, trackers and tanners work beside the renowned Hunter's Hall, where the tauren train their warriors and hunters, and training dummies stand outside for warriors to practice on.",
			source = "https://warcraft.wiki.gg/wiki/Hunter_Rise",
		},
		["pools of vision"] = {
			name = "The Pools of Vision",
			short = "In a tunnel system just below the cap of Spirit Rise, the Forsaken keep a foothold deep in tauren country. Their mages and priests gather around the Pools of Vision, which steam beneath the mesa.",
			full = "In a tunnel system just below the cap of Spirit Rise, the Forsaken keep a foothold deep in tauren country. Their mages and priests gather around the Pools of Vision, which steam beneath the mesa.",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Vision",
		},
		["spirit rise"] = {
			name = "Spirit Rise",
			short = "Shamans study on Spirit Rise, northwest of the central bluff, and the Skychaser tribe holds great influence here. The steamy Pools of Vision lie below the surface of the mesa.",
			full = "Shamans study on Spirit Rise, northwest of the central bluff, and the Skychaser tribe holds great influence here. The steamy Pools of Vision lie below the surface of the mesa.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Rise",
		},
	},
	-- Darnassus: 5 subzones
	[1457] = {
		["cenarion enclave"] = {
			name = "Cenarion Enclave",
			short = "In the northwest of Darnassus, the Cenarion Enclave rings a grove where oaks and ashes stand taller than the halls of stone elsewhere in the city.",
			full = "In the northwest of Darnassus, the Cenarion Enclave rings a grove where oaks and ashes stand taller than the halls of stone elsewhere in the city. Every tree bears mystic runes shaped from its own bark. Within the circle, the druids gather in structures molded from living wood and carefully shaped stone, and the largest, at the heart of the grove, is the home of Archdruid Fandral Staghelm. The Enclave takes its name from Cenarius, the ancient demigod, and treants called Darnassian Protectors guard it in place of Sentinels.\n\nThis is the seat of the city's druids, just as the Temple of the Moon is the seat of its priests. Druids learn the old ways here, hunters train in its easternmost tree, and a secretive guild of rogues keeps its quarters below ground, known only to those who already know where to look.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Enclave",
		},
		["craftsmens terrace"] = {
			name = "Craftsmen's Terrace",
			short = "The Craftsmen's Terrace lies in the north of Darnassus.",
			full = "The Craftsmen's Terrace lies in the north of Darnassus. Most of the city's craftspeople keep their halls and workshops here, alchemists and tailors, leatherworkers and enchanters, cooks and healers, and travelers find a room at Innkeeper Saelienne's inn, one of the city's main inns. An embassy of the Argent Dawn also stands here, a foreign presence within the elven city.\n\nTelonis, the master leatherworker, says the grass is soft and the air full of light and song, and that everything he has seen tells him Teldrassil is a dream come true. He cannot say why his heart is full of foreboding.",
			source = "https://warcraft.wiki.gg/wiki/Craftsmen's_Terrace",
		},
		["temple gardens"] = {
			name = "The Temple Gardens",
			short = "At the heart of Darnassus lie the Temple Gardens, an expanse of water, walkways and small islands named for the Temple of the Moon that rises just to the south.",
			full = "At the heart of Darnassus lie the Temple Gardens, an expanse of water, walkways and small islands named for the Temple of the Moon that rises just to the south. Bridges lead out in every direction, so that all roads through the city seem to gather here. The islets hold some of the finest plants in the city, and the night elves tend the waters to keep them so. Tyrande Whisperwind has meditated here.\n\nIn the far west of the gardens a portal leads down to Rut'theran Village at the foot of the World Tree.",
			source = "https://warcraft.wiki.gg/wiki/Temple_Gardens",
		},
		["tradesmens terrace"] = {
			name = "Tradesmen's Terrace",
			short = "Most of the shopkeepers and merchants of Darnassus keep to the Tradesmen's Terrace in the south of the city. It is the center of commerce for the night elves, and the city's auction house is here.",
			full = "Most of the shopkeepers and merchants of Darnassus keep to the Tradesmen's Terrace in the south of the city. It is the center of commerce for the night elves, and the city's auction house is here. Its buildings are grown of wood, in the manner of the night elves, light and graceful things.",
			source = "https://warcraft.wiki.gg/wiki/Tradesmen's_Terrace",
		},
		["warriors terrace"] = {
			name = "Warrior's Terrace",
			short = "The eastern gate of Darnassus, where the city opens onto the wilds of Teldrassil, stands on the Warrior's Terrace, also called the Hall of Justice.",
			full = "The eastern gate of Darnassus, where the city opens onto the wilds of Teldrassil, stands on the Warrior's Terrace, also called the Hall of Justice. The Sentinels keep their ground here, and patrols on nightsabers guard the gates. Night elves of military rank train on its target ranges and dueling grounds, and the terrace is the city's shield against whatever comes up the road from the forest.",
			source = "https://warcraft.wiki.gg/wiki/Warrior's_Terrace",
		},
	},
	-- Undercity: 1 subzones
	[1458] = {
		["ruins of lordaeron"] = {
			name = "Ruins of Lordaeron",
			short = "Above the buried city the palace of Lordaeron still stands, its halls open to the sky and its gardens gone to ruin.",
			full = "Above the buried city the palace of Lordaeron still stands, its halls open to the sky and its gardens gone to ruin. Prince Arthas Menethil came home to it at the head of an army, welcomed through the gates by bells and cheering before anyone understood what he had become. In the throne room he killed his father, King Terenas, and the Scourge destroyed the capital. The kingdom fell.\n\nThe ruins have kept the sound of that day. Bells clang in the entryway, a faint cheer welcomes the prince, and voices murmur in the throne room, where Arthas is heard declaring that the kingdom will fall and a new order will rise from its ashes. The ghosts of Lordaeron's citizens still haunt the courtyard, and darkhounds and duskbats prowl beyond the walls.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
	},
