	-- Zephras Isle: 27 subzones
	[2521] = {
		["bandit hideout"] = {
			name = "Bandit Hideout",
			short = "Bandits hide here and steal windstones from the village stores to get by. Some of them are refugees from settlements that fell apart, and they turned to crime when they had nowhere else to go.",
			full = "Bandits hide here and steal windstones from the village stores to get by. Some of them are refugees from settlements that fell apart, and they turned to crime when they had nowhere else to go.",
			source = "",
		},
		["east pylon watchtower"] = {
			name = "East Pylon Watchtower",
			short = "Al'Aketh cultists have laid siege to the East Pylon Watchtower, and Peacekeepers hold it against them. The pylons it is named for are ancient anchors, gifts of the wind spirits, that keep the island aloft.",
			full = "Al'Aketh cultists have laid siege to the East Pylon Watchtower, and Peacekeepers hold it against them. The pylons it is named for are ancient anchors, gifts of the wind spirits, that keep the island aloft.",
			source = "",
		},
		["fairweather stables"] = {
			name = "Fairweather Stables",
			short = "Genn Fairweather keeps galestriders at the Fairweather Stables and trains riders for them.",
			full = "Genn Fairweather keeps galestriders at the Fairweather Stables and trains riders for them. The great birds are temperamental and toss a new rider who handles them badly, so he teaches only those with some experience and the coin to pay. In the pens the galestriders, umber, stormy and empyrean, preen, warble and peer at visitors, and one almost bounces with excitement.",
			source = "",
		},
		["falaath village"] = {
			name = "Falaath Village",
			short = "The Al'Aketh cult occupies Falaath Village. A tailor named Zendraas lived here, and when the cultists took over his home he put on their robes and professed their faith.",
			full = "The Al'Aketh cult occupies Falaath Village. A tailor named Zendraas lived here, and when the cultists took over his home he put on their robes and professed their faith. He went on to design much of their clothing. Some in the cult joined to stay alive and hold none of its beliefs.",
			source = "",
		},
		["gustberry lowlands"] = {
			name = "Gustberry Lowlands",
			short = "A river runs through the Gustberry Lowlands. Frogs live along it, butterflies fly over the land, and cloudrunner matriarchs roam with their young.",
			full = "A river runs through the Gustberry Lowlands. Frogs live along it, butterflies fly over the land, and cloudrunner matriarchs roam with their young. Al'Aketh cultists have also moved in, led by Commander Belguilos, whom they call the Breaker. She was once a Peacekeeper.",
			source = "",
		},
		["nightclaw cavern"] = {
			name = "Nightclaw Cavern",
			short = "The Nightclaw, a circle of shen'dorei druids, keeps a den in a cave in the northeast of Shadowgale Forest. Shen'dorei druids are rare these days, and the Nightclaw keep apart from every other faction on the island.",
			full = "The Nightclaw, a circle of shen'dorei druids, keeps a den in a cave in the northeast of Shadowgale Forest. Shen'dorei druids are rare these days, and the Nightclaw keep apart from every other faction on the island.",
			source = "",
		},
		["overlook standing stones"] = {
			name = "Overlook Standing Stones",
			short = "Wind sprites, tiny air elementals, flit among the Overlook Standing Stones. They squeak and vanish when startled. Guardians and elementalists of the Windshapers keep watch over the stones.",
			full = "Wind sprites, tiny air elementals, flit among the Overlook Standing Stones. They squeak and vanish when startled. Guardians and elementalists of the Windshapers keep watch over the stones.",
			source = "",
		},
		["rise of spirits"] = {
			pending = true,
			name = "Rise of Spirits",
			short = "",
			full = "",
			source = "",
		},
		["rohashi spires"] = {
			name = "Rohashi Spires",
			short = "The Rohashi Spires stand in the sky above the Shrine of Akir. Skypriests and honor guards of the Al'Aketh cult keep to them.",
			full = "The Rohashi Spires stand in the sky above the Shrine of Akir. Skypriests and honor guards of the Al'Aketh cult keep to them.",
			source = "",
		},
		["ruins of banaethal"] = {
			name = "Ruins of Ban'aethal",
			short = "The magesmiths of Ban'aethal were the finest artisans in the Skyborne Isles. When the magic that held the settlement failed, its people fled in the night as it began to fall into the sky.",
			full = "The magesmiths of Ban'aethal were the finest artisans in the Skyborne Isles. When the magic that held the settlement failed, its people fled in the night as it began to fall into the sky. Wind Hollows, ghostly air elementals, now drift among the ruins.",
			source = "",
		},
		["sanctum of storms"] = {
			name = "Sanctum of Storms",
			short = "Skypriests and honor guards of the Al'Aketh cult fill the Sanctum of Storms.",
			full = "Skypriests and honor guards of the Al'Aketh cult fill the Sanctum of Storms.",
			source = "",
		},
		["shadowgale forest"] = {
			name = "Shadowgale Forest",
			short = "The Nightclaw Druids, a secretive circle, live in Shadowgale Forest and keep apart from every other faction on the island.",
			full = "The Nightclaw Druids, a secretive circle, live in Shadowgale Forest and keep apart from every other faction on the island. Since the wind spirits vanished, ghostly wind sprites called Wind Hollows have been appearing among the trees. Some nights a sorrowful singing is heard near them.",
			source = "",
		},
		["shendar highlands"] = {
			name = "Shen'dar Highlands",
			short = "The Windshapers, shaman who commune with the elemental spirits, protect the standing stones in the Shen'dar Highlands, a sacred site of elemental magic.",
			full = "The Windshapers, shaman who commune with the elemental spirits, protect the standing stones in the Shen'dar Highlands, a sacred site of elemental magic. Bandits roam the highlands as well.",
			source = "",
		},
		["shendar village"] = {
			name = "Shen'dar Village",
			short = "The Calmbreeze Inn stands in Shen'dar Village.",
			full = "The Calmbreeze Inn stands in Shen'dar Village. An elder of the Windshapers and an elder of the High Order both live here, Constable Aonda keeps watch with a few Peacekeepers, and a missionary of the Al'Aketh cult walks among the villagers.",
			source = "",
		},
		["shriekling den"] = {
			name = "Shriekling Den",
			short = "Shrieklings nest in this cave, a short way from Valanaar, with their fledglings and their matriarch.",
			full = "Shrieklings nest in this cave, a short way from Valanaar, with their fledglings and their matriarch.",
			source = "",
		},
		["shrine of akir"] = {
			name = "Shrine of Akir",
			short = "The Shrine of Akir is held by the Al'Aketh cult.",
			full = "The Shrine of Akir is held by the Al'Aketh cult. Guardians, blademasters, honor guards, spiritcallers and skypriests stand watch over it, among them Zaal Stormshield and Tel'daeor the Stormspeaker, and Brother Zendraas serves there as well.",
			source = "",
		},
		["skywall"] = {
			name = "Skywall",
			short = "Skywall is the elemental plane of air, a realm ruled by ancient spirits of wind, and Zephras Isle hangs within it.",
			full = "Skywall is the elemental plane of air, a realm ruled by ancient spirits of wind, and Zephras Isle hangs within it. Two other Skyborne islands, Anvilas and Siroccas, float somewhere in it too, but contact with them was lost when the wind spirits disappeared.\n\nThe Al'Aketh cult holds that the true ruler of Skywall is Al'Akir the Windlord, and worships him. The skycutters of the Skyborne can be steered through the plane toward Azeroth only by reckoning how its elemental energy flows.",
			source = "",
		},
		["thendal cave"] = {
			name = "Thendal Cave",
			short = "Ursera scavengers den in Thendal Cave, west of Thendal Village, under a matriarch the rangers of Thendal Grove call Urs'anah.",
			full = "Ursera scavengers den in Thendal Cave, west of Thendal Village, under a matriarch the rangers of Thendal Grove call Urs'anah.",
			source = "",
		},
		["thendal grove"] = {
			name = "Thendal Grove",
			short = "Rangers watch over Thendal Grove, which looks across to one of the island's ancient pylons. Its magic has grown unstable and uneven.",
			full = "Rangers watch over Thendal Grove, which looks across to one of the island's ancient pylons. Its magic has grown unstable and uneven.",
			source = "",
		},
		["thendal standing stones"] = {
			name = "Thendal Standing Stones",
			short = "A ley line has broken through the ground at the Thendal Standing Stones, as several have lately across Zephras, bringing arcane energy close to the surface.",
			full = "A ley line has broken through the ground at the Thendal Standing Stones, as several have lately across Zephras, bringing arcane energy close to the surface. Simple wind sprites drift here, answering to the moods and intentions of anyone near them, and the Al'Aketh have been agitating them. Roiling Winds elementals and cult converts roam the stones.",
			source = "",
		},
		["thendal village"] = {
			name = "Thendal Village",
			short = "The Rangers of Thendal Grove patrol the woods around Thendal Village, their home, and Rorian the Dayseeker leads the village.",
			full = "The Rangers of Thendal Grove patrol the woods around Thendal Village, their home, and Rorian the Dayseeker leads the village. Windshapers and the High Order, who distrust each other elsewhere on the island, live here in relative harmony. The villagers have known of the Al'Aketh for some time and have been content to watch the cult from afar.",
			source = "",
		},
		["valanaar"] = {
			name = "Valanaar",
			short = "Talaanis Shadowsong, High Elder of Zephras Isle, lives in Valanaar.",
			full = "Talaanis Shadowsong, High Elder of Zephras Isle, lives in Valanaar. The High Order and the Windshapers each keep a lodge in the town, and Peacekeepers, the island's militia, keep watch over its streets under their captain, Valennia Stormfist. It has its own Calmbreeze Inn.",
			source = "",
		},
		["valanaar skydocks"] = {
			name = "Valanaar Skydocks",
			short = "Skycutters, the airships of the Skyborne, dock here. They once ran between the islands, until the crossings grew unsafe.",
			full = "Skycutters, the airships of the Skyborne, dock here. They once ran between the islands, until the crossings grew unsafe.",
			source = "",
		},
		["west pylon watchtower"] = {
			name = "West Pylon Watchtower",
			short = "Al'Aketh warriors hold the West Pylon Watchtower, and a skypriest of the cult stands at its top.",
			full = "Al'Aketh warriors hold the West Pylon Watchtower, and a skypriest of the cult stands at its top.",
			source = "",
		},
		["windfield orchard"] = {
			name = "Windfield Orchard",
			short = "The Windfield family keep an orchard here and grow stormapples. A huge construct from the days of the wind spirits has wandered the fields for decades, and a faint buzzing comes from beneath its armor plates.",
			full = "The Windfield family keep an orchard here and grow stormapples. A huge construct from the days of the wind spirits has wandered the fields for decades, and a faint buzzing comes from beneath its armor plates. The family mostly ignore it.",
			source = "",
		},
		["windsong lake"] = {
			name = "Windsong Lake",
			short = "Some of the constructs the wind spirits gave the Skyborne fell into Windsong Lake when the pylons failed. A threshadon known as the Lost One lives in its waters.",
			full = "Some of the constructs the wind spirits gave the Skyborne fell into Windsong Lake when the pylons failed. A threshadon known as the Lost One lives in its waters.",
			source = "",
		},
		["windsong standing stones"] = {
			name = "Windsong Standing Stones",
			short = "Small air elementals called wind sprites live among the Windsong Standing Stones.",
			full = "Small air elementals called wind sprites live among the Windsong Standing Stones.",
			source = "",
		},
	},
