	-- Riverglades: 18 subzones
	[2548] = {
		["ashwoods fall"] = {
			name = "Ashwood's Fall",
			short = "Wrecked wagons lie around a ruined watchtower, and rubble and wooden barricades fill its broken walls.",
			full = "Wrecked wagons lie around a ruined watchtower, and rubble and wooden barricades fill its broken walls. Rosalind Ashwood, a scout of the Brotherhood, rode to Windstead to warn the families there of a coming Horde attack and led a convoy of them toward Farholde. The Horde overtook the convoy at a watchtower, and no one survived. The wagons and the name suggest that this is that tower.",
			source = "",
		},
		["bolderok"] = {
			name = "Bolder'ok",
			short = "Ogres hold Bolder'ok, a settlement northwest of Windstead. They once stood with the Twilight's Hammer but have left it and allied themselves with the Horde.",
			full = "Ogres hold Bolder'ok, a settlement northwest of Windstead. They once stood with the Twilight's Hammer but have left it and allied themselves with the Horde.",
			source = "",
		},
		["bristle hills"] = {
