			name = "Bristle Hills",
			short = "",
			full = "",
			source = "",
		},
		["eastwind shore"] = {
			pending = true,
			name = "Eastwind Shore",
			short = "",
			full = "",
			source = "",
		},
		["elbrims farm"] = {
			pending = true,
			name = "Elbrim's Farm",
			short = "",
			full = "",
			source = "",
		},
		["farholde keep"] = {
			name = "Farholde Keep",
			short = "Farholde stands on a coastal island that knights chose for its natural defenses. They fortified it with the survivors they had rescued in the First War, because the Horde had closed the road home.",
			full = "Farholde stands on a coastal island that knights chose for its natural defenses. They fortified it with the survivors they had rescued in the First War, because the Horde had closed the road home.\n\nYears after the Second War a Horde army laid siege to the keep. Raiders came by water and sabotaged the seaworthy ships moored there, so no one could escape or send for help. Families crowded inside, rations ran thin and morale sank. In the night a Brotherhood agent named Fern Crimsonleaf slipped into the enemy camp and killed the Horde's leaders. At dawn Sir Howard Armstrong led a charge from the gate. The Horde's soldiers waited for orders that never came, and they broke and ran. Howard and several of his companions died in the charge. Their memorials stand in the keep, and Demar Brant, the knight commander, still holds it.",
			source = "",
		},
		["forlorn pit"] = {
			pending = true,
			name = "Forlorn Pit",
			short = "",
			full = "",
			source = "",
		},
		["kroldok stronghold"] = {
			name = "Krol'dok Stronghold",
			short = "Krol'dok Stronghold is an ogre fortress. The Horde army that besieged Farholde fell back to it when the siege broke.",
			full = "Krol'dok Stronghold is an ogre fortress. The Horde army that besieged Farholde fell back to it when the siege broke.",
			source = "",
		},
		["meadowsbrook"] = {
			name = "Meadowsbrook",
			short = "Knights who had rescued the captives of Sunnyglade found the road home cut off by the Horde, and they settled here with the survivors.",
			full = "Knights who had rescued the captives of Sunnyglade found the road home cut off by the Horde, and they settled here with the survivors. After some time a Brotherhood detachment, retreating from the Horde, came upon the village, and its help gave the Brotherhood a foothold in the Riverglades.",
			source = "",
		},
		["powderfuse port"] = {
			name = "Powderfuse Port",
			short = "Melbin Powderfuse, a goblin engineer, claims he built everything in this port on the eastern coast and owns all of it. He says the site was an empty lot when he arrived.",
			full = "Melbin Powderfuse, a goblin engineer, claims he built everything in this port on the eastern coast and owns all of it. He says the site was an empty lot when he arrived. Jazzle Cheapshot is setting up an arena here that is not yet running, and he complains that the Horde and the Alliance fight each other in the fields instead of paying to fight in his.",
			source = "",
		},
		["rogmar"] = {
			name = "Rog'mar",
			short = "The Horde keeps one of its main settlements in the Riverglades at Rog'mar.",
			full = "The Horde keeps one of its main settlements in the Riverglades at Rog'mar.",
			source = "",
		},
		["southern watch"] = {
			pending = true,
			name = "Southern Watch",
			short = "",
			full = "",
			source = "",
		},
		["sunnyglade"] = {
			name = "Sunnyglade",
			short = "Sunnyglade was a rich and prosperous town of the Kingdom of Stormwind.",
			full = "Sunnyglade was a rich and prosperous town of the Kingdom of Stormwind. In the First War the Old Horde destroyed most of it and took the survivors as slaves, but spared one mage tower so the orcs could learn how human magic worked. Later the Brotherhood of the Horse held the ruins. When the Horde came again, Roderick the Unbroken, a captain of the Brotherhood, held a bridge here while a scout carried word to Farholde. He lost an arm and lived. The Twilight's Hammer holds the ruins now, and the mage tower still stands.",
			source = "",
		},
		["terrals watch"] = {
			name = "Terral's Watch",
			short = "A banner with a horse emblem hangs above the barred entrance of Terral's Watch, a stone watchtower whose upper walls have partly collapsed.",
			full = "A banner with a horse emblem hangs above the barred entrance of Terral's Watch, a stone watchtower whose upper walls have partly collapsed. A broad stone stairway leads up to the door, with a lit lamp on either side.",
			source = "",
		},
		["turners logging camp"] = {
			pending = true,
			name = "Turner's Logging Camp",
			short = "",
			full = "",
			source = "",
		},
		["twilights shroud"] = {
			name = "Twilight's Shroud",
			short = "Twilight's Shroud is one of the bases the Twilight's Hammer holds in the Riverglades, along with Krol'dok Stronghold. The Badlands lie to the north of it.",
			full = "Twilight's Shroud is one of the bases the Twilight's Hammer holds in the Riverglades, along with Krol'dok Stronghold. The Badlands lie to the north of it.",
			source = "",
		},
		["wheelers grange"] = {
			name = "Wheeler's Grange",
			short = "Benjy Wheeler stands outside the farmhouse of this farmstead near Farholde Keep, and hostile harvest reapers crowd its fields.",
			full = "Benjy Wheeler stands outside the farmhouse of this farmstead near Farholde Keep, and hostile harvest reapers crowd its fields.",
			source = "",
		},
		["windstead"] = {
			name = "Windstead",
			short = "Families who escaped the destruction of Sunnyglade found a lake hidden in the mountains and founded Windstead beside it, afraid the Horde would one day find them.",
			full = "Families who escaped the destruction of Sunnyglade found a lake hidden in the mountains and founded Windstead beside it, afraid the Horde would one day find them. After years of seclusion the villagers brushed off Farholde's warning that it could not protect them in a major battle. Some left by the coast and some by the road when the danger came close. The village stands empty now, and Eastsea pirates occupy its ruins.",
			source = "",
		},
	},
