	[2652] = {
		["bristleback retreat"] = {
			name = "Bristleback Retreat",
			short = "Blue-skinned gnolls of the Palemane tribe have made a camp at Bristleback Retreat, poachers, skinners and tanners among them.",
			full = "Blue-skinned gnolls of the Palemane tribe have made a camp at Bristleback Retreat, poachers, skinners and tanners among them.",
			source = "",
		},
		["evenshades overlook"] = {
			name = "Evenshade's Overlook",
			short = "Archmage Mordent Evenshade is found here, outside the ruins north of the city. He is a Highborne of the Shen'dralar and still calls the city by its true name, Eldre'Thalas.",
			full = "Archmage Mordent Evenshade is found here, outside the ruins north of the city. He is a Highborne of the Shen'dralar and still calls the city by its true name, Eldre'Thalas. He says the temple and its grounds are in a sorry state after thousands of years, and that Shen'dralas is a haunted shell of its former self. The city survived the Great Sundering, yet so many of his people died that he cannot forget it. He looks out toward a mass grave of his kin. He has met no other survivors, apart from those of his order who stay cloistered with Prince Tortheldrin deep inside the city, and he spends little time in the library he once called home.",
			source = "",
		},
